-- ----------------------------------------------------------------------------
-- vw_rulebook_releases: Version ledger for the canonical ERB-PKO rulebook itself. This is distinct from PKO Procedure versioning.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_rulebook_releases: Version ledger for the canonical ERB-PKO rulebook itself. This is distinct from PKO Procedure versioning.
-- SELF-REFERENTIAL SETTLE: RulebookReleases has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: cq_coverage_percent, cq_run_count. Drivers: previous_release.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_releases CASCADE;
CREATE VIEW vw_rulebook_releases WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.rulebook_release_id, jsonb_build_object(
      'cq_coverage_percent', CASE WHEN COALESCE(((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,''))))::NUMERIC, 0) = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')) AND was_answerable = TRUE)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, (1)::INTEGER))::text END,
      'cq_run_count', (SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')))
    ))
    FROM rulebook_releases t WHERE NULLIF(t.previous_release,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.rulebook_release_id, jsonb_build_object(
      'cq_coverage_percent', CASE WHEN COALESCE(((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,''))))::NUMERIC, 0) = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')) AND was_answerable = TRUE)) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0), 0))) AS v OFFSET 0) __safe_numeric), 0)))::NUMERIC, (1)::INTEGER))::text END,
      'cq_run_count', (SELECT COUNT(*) FROM competency_question_runs WHERE rulebook_release = (SELECT NULLIF(t.rulebook_release_id::text,'')))
    ))
    FROM rulebook_releases t
    WHERE NOT (a.settled ? t.rulebook_release_id) AND NOT (NULLIF(t.previous_release,'') IS NULL) AND (NULLIF(t.previous_release,'') IS NULL OR a.settled ? t.previous_release)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM rulebook_releases t
    WHERE NOT (a.settled ? t.rulebook_release_id) AND NOT (NULLIF(t.previous_release,'') IS NULL) AND (NULLIF(t.previous_release,'') IS NULL OR a.settled ? t.previous_release))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.rulebook_release_id,                                                        -- Stored logical identifier for one RulebookReleases row.
  calc_rulebook_releases_name(t.rulebook_release_id) AS name,                   -- Human-readable calculated display alias for the RulebookReleases row.
  t.rulebook_version,                                                           -- Semantic version of this canonical rulebook release.
  t.profile_version,                                                            -- Version of the ERB-PKO profile schema.
  t.profile_schema_path,                                                        -- Repository-relative path to the ERB-PKO JSON profile schema.
  t.pko_core_version_iri,                                                       -- Exact version IRI of the PKO core ontology used by this release.
  t.pko_industry_version_iri,                                                   -- Exact version IRI of the PKO industry module used by this release.
  t.issued_at,                                                                  -- Timestamp at which this rulebook release was issued.
  t.status,                                                                     -- Release status such as Draft, Candidate, or Published.
  t.changelog,                                                                  -- Human-readable semantic changelog for this release.
  t.is_current,                                                                 -- TRUE only for the current rulebook release.
  t.governed_model,                                                             -- Model this release versions.
  t.previous_release,                                                           -- Prior version (owl:priorVersion).
  t.declared_scale,                                                             -- Initial, Patch, Minor or Major as decided.
  t.version_major,                                                              -- Major number.
  t.version_minor,                                                              -- Minor number.
  t.version_patch,                                                              -- Patch number.
  t.migration_plan,                                                             -- Migration plan for a breaking release.
  t.version_decision_rationale,                                                 -- Why this version increment was chosen.
  t.version_decided_by_agent,                                                   -- Who made the versioning decision.
  t.approved_by_agent,                                                          -- Who approved publication.
  t.rulebook_commit,                                                            -- Version-control tag or commit of the release.
  t.license,                                                                    -- Licence the release is published under.
  t.permanent_iri,                                                              -- Permanent identifier of the release.
  t.namespace_prefix,                                                           -- Preferred namespace prefix (vann:preferredNamespacePrefix).
  t.funding_note,                                                               -- Funding acknowledgement (schema:funding).
  calc_rulebook_releases_prev_major(t.rulebook_release_id) AS prev_major,       -- Previous major number.
  calc_rulebook_releases_prev_minor(t.rulebook_release_id) AS prev_minor,       -- Previous minor number.
  calc_rulebook_releases_prev_patch(t.rulebook_release_id) AS prev_patch,       -- Previous patch number.
  calc_rulebook_releases_prev_issued_at(t.rulebook_release_id) AS prev_issued_at,-- When the previous release was issued.
  calc_rulebook_releases_model_current_release(t.rulebook_release_id) AS model_current_release,-- Release the model is declared at now.
  calc_rulebook_releases_expected_major(t.rulebook_release_id) AS expected_major,-- Major number the declared scale calls for.
  calc_rulebook_releases_expected_minor(t.rulebook_release_id) AS expected_minor,-- Minor number the declared scale calls for.
  calc_rulebook_releases_expected_patch(t.rulebook_release_id) AS expected_patch,-- Patch number the declared scale calls for.
  calc_rulebook_releases_is_increment_inconsistent_with_scale(t.rulebook_release_id) AS is_increment_inconsistent_with_scale,-- TRUE when the version number does not follow from the previous one and the declared patch, minor or major scale.
  calc_rulebook_releases_days_since_previous_release(t.rulebook_release_id) AS days_since_previous_release,-- Length of the release cycle.
  calc_rulebook_releases_is_long_release_cycle(t.rulebook_release_id) AS is_long_release_cycle,-- TRUE when more than sixty days passed since the previous release instead of a short repeated cycle.
  calc_rulebook_releases_is_declared_current_release(t.rulebook_release_id) AS is_declared_current_release,-- TRUE for the release the model is currently declared at.
  calc_rulebook_releases_log_entry_count(t.rulebook_release_id) AS log_entry_count,-- Change log entries shipped in the release.
  calc_rulebook_releases_logical_change_count(t.rulebook_release_id) AS logical_change_count,-- Entries that alter the logical model.
  calc_rulebook_releases_non_additive_change_count(t.rulebook_release_id) AS non_additive_change_count,-- Entries that break backward compatibility.
  calc_rulebook_releases_class_removal_or_rename_count(t.rulebook_release_id) AS class_removal_or_rename_count,-- Classes removed or renamed.
  calc_rulebook_releases_invalidating_domain_range_count(t.rulebook_release_id) AS invalidating_domain_range_count,-- Domain or range changes invalidating instance assertions.
  calc_rulebook_releases_inconsistent_disjointness_count(t.rulebook_release_id) AS inconsistent_disjointness_count,-- Disjointness axioms making individuals inconsistent.
  calc_rulebook_releases_schema_addition_count(t.rulebook_release_id) AS schema_addition_count,-- Additive schema changes.
  calc_rulebook_releases_suite_update_count(t.rulebook_release_id) AS suite_update_count,-- Steward updates to the validation suite made for this release.
  calc_rulebook_releases_consumer_count(t.rulebook_release_id) AS consumer_count,-- Consumers depending on the model.
  calc_rulebook_releases_notified_consumer_count(t.rulebook_release_id) AS notified_consumer_count,-- Consumers told of the release.
  calc_rulebook_releases_revalidated_consumer_count(t.rulebook_release_id) AS revalidated_consumer_count,-- Consumers re-validated against the release.
  calc_rulebook_releases_validation_run_count(t.rulebook_release_id) AS validation_run_count,-- Validation runs for changes shipped in the release.
  calc_rulebook_releases_validation_failure_total(t.rulebook_release_id) AS validation_failure_total,-- Acceptance-run failures for changes in the release.
  calc_rulebook_releases_consistent_run_count(t.rulebook_release_id) AS consistent_run_count,-- Runs whose machine consistency check confirmed no inconsistency.
  (SELECT settled #>> ARRAY[t.rulebook_release_id::text, 'cq_run_count'] FROM settled)::integer AS cq_run_count,-- Competency questions run as tasks against the release.
  calc_rulebook_releases_answerable_cq_run_count(t.rulebook_release_id) AS answerable_cq_run_count,-- Questions the release could answer.
  calc_rulebook_releases_regressed_baseline_count(t.rulebook_release_id) AS regressed_baseline_count,-- Original questions that regressed in the release.
  (SELECT settled #>> ARRAY[t.rulebook_release_id::text, 'cq_coverage_percent'] FROM settled)::numeric AS cq_coverage_percent,-- Share of the question runs the release could answer.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_release,''), 'cq_coverage_percent'] FROM settled)::numeric AS prev_cq_coverage_percent,-- Question coverage of the previous release.
  (SELECT settled #>> ARRAY[NULLIF(t.previous_release,''), 'cq_run_count'] FROM settled)::integer AS prev_cq_run_count,-- Question runs against the previous release.
  calc_rulebook_releases_scored_criterion_count(t.rulebook_release_id) AS scored_criterion_count,-- Quality criteria the release was scored against.
  calc_rulebook_releases_stated_criterion_count(t.rulebook_release_id) AS stated_criterion_count,-- Stated quality criteria.
  calc_rulebook_releases_patch_alters_logical_model(t.rulebook_release_id) AS patch_alters_logical_model,-- TRUE when a patch release changed the logical model instead of only documentation, labels and comments.
  calc_rulebook_releases_minor_is_not_backward_compatible(t.rulebook_release_id) AS minor_is_not_backward_compatible,-- TRUE when a minor release contains a change that is not additive and backward compatible.
  calc_rulebook_releases_class_removal_without_major(t.rulebook_release_id) AS class_removal_without_major,-- TRUE when a class was removed or renamed in a release that is not major.
  calc_rulebook_releases_invalidating_domain_range_without_major(t.rulebook_release_id) AS invalidating_domain_range_without_major,-- TRUE when a domain or range change invalidating instance assertions shipped in a release that is not major.
  calc_rulebook_releases_inconsistent_disjointness_without_major(t.rulebook_release_id) AS inconsistent_disjointness_without_major,-- TRUE when a disjointness axiom making individuals inconsistent shipped in a release that is not major.
  calc_rulebook_releases_is_breaking_release(t.rulebook_release_id) AS is_breaking_release,-- TRUE for a major release or any release containing a breaking change.
  calc_rulebook_releases_breaking_release_with_unrevalidated_cons(t.rulebook_release_id) AS breaking_release_with_unrevalidated_consumers,-- TRUE when a breaking release left consumers that were never updated and re-validated.
  calc_rulebook_releases_breaking_release_without_migration_plan(t.rulebook_release_id) AS breaking_release_without_migration_plan,-- TRUE when a breaking release shipped with no migration plan.
  calc_rulebook_releases_is_undocumented_version_decision(t.rulebook_release_id) AS is_undocumented_version_decision,-- TRUE when a governed release records no rationale or no decider for its version increment.
  calc_rulebook_releases_is_unannounced_to_dependents(t.rulebook_release_id) AS is_unannounced_to_dependents,-- TRUE when some consumer that depends on the model was not told of the release.
  calc_rulebook_releases_is_release_without_recorded_changes(t.rulebook_release_id) AS is_release_without_recorded_changes,-- TRUE when a release after the first records no change log entries, so what changed is not on record.
  calc_rulebook_releases_suite_lags_release(t.rulebook_release_id) AS suite_lags_release,-- TRUE when a release added schema but the steward made no matching validation-suite update.
  calc_rulebook_releases_is_untagged_release(t.rulebook_release_id) AS is_untagged_release,-- TRUE when a governed release has no version-control tag or commit.
  calc_rulebook_releases_published_without_approval(t.rulebook_release_id) AS published_without_approval,-- TRUE when a release was published without a recorded publication approval.
  calc_rulebook_releases_released_despite_failed_validation(t.rulebook_release_id) AS released_despite_failed_validation,-- TRUE when a release shipped changes whose acceptance validation failed.
  calc_rulebook_releases_released_without_consistency_check(t.rulebook_release_id) AS released_without_consistency_check,-- TRUE when no machine consistency check confirmed a governed release consistent.
  calc_rulebook_releases_passed_validation_at_release(t.rulebook_release_id) AS passed_validation_at_release,-- TRUE when every acceptance run for the release passed.
  calc_rulebook_releases_cq_coverage_declined(t.rulebook_release_id) AS cq_coverage_declined,-- TRUE when the release answers a smaller share of its questions than the previous release did.
  calc_rulebook_releases_has_baseline_regression(t.rulebook_release_id) AS has_baseline_regression,-- TRUE when the release can no longer answer at least one original question.
  calc_rulebook_releases_released_without_cq_task_test(t.rulebook_release_id) AS released_without_cq_task_test,-- TRUE when a governed release was never tested by running its competency questions as tasks.
  calc_rulebook_releases_well_formed_but_requirements_unshown(t.rulebook_release_id) AS well_formed_but_requirements_unshown,-- TRUE when a release passed validation runs but was never shown to answer its requirement questions.
  calc_rulebook_releases_is_not_scored_against_criteria(t.rulebook_release_id) AS is_not_scored_against_criteria,-- TRUE when a governed release was not scored against every stated quality criterion.
  calc_rulebook_releases_is_released_without_licence_or_permanent(t.rulebook_release_id) AS is_released_without_licence_or_permanent_id-- TRUE when a governed release carries no licence or no permanent identifier.
FROM rulebook_releases t;

-- ----------------------------------------------------------------------------
-- vw_ontology_profiles: Versioned ontology and vocabulary dependencies. PKO mappings always identify the exact profile and version.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ontology_profiles CASCADE;
CREATE VIEW vw_ontology_profiles WITH (security_invoker = ON) AS
SELECT
  t.ontology_profile_id,                                                        -- Stored logical identifier for one OntologyProfiles row.
  calc_ontology_profiles_name(t.ontology_profile_id) AS name,                   -- Human-readable calculated display alias for the OntologyProfiles row.
  t.label,                                                                      -- Human-readable ontology or vocabulary name.
  t.version,                                                                    -- Referenced release or specification version.
  t.version_iri,                                                                -- Exact version IRI or normative specification URI.
  t.namespace_iri,                                                              -- Namespace used for class/property IRIs.
  t.license,                                                                    -- License or standards body attribution.
  t.scope,                                                                      -- How the profile is used in this rulebook.
  calc_ontology_profiles_mapping_count(t.ontology_profile_id) AS mapping_count, -- Semantic mappings that use this ontology profile.
  t.evaluation_context,                                                         -- Instant the dependency is judged against.
  calc_ontology_profiles_as_of_instant(t.ontology_profile_id) AS as_of_instant, -- Judgment instant.
  t.last_revised_at,                                                            -- When the standard last published any revision.
  t.last_major_revision_at,                                                     -- When the standard last published a major revision.
  t.dependency_reviewed_at,                                                     -- When we last reviewed our dependency on it.
  calc_ontology_profiles_days_since_last_revision(t.ontology_profile_id) AS days_since_last_revision,-- Days since any revision.
  calc_ontology_profiles_days_since_major_revision(t.ontology_profile_id) AS days_since_major_revision,-- Days since the last major revision.
  calc_ontology_profiles_days_since_dependency_reviewed(t.ontology_profile_id) AS days_since_dependency_reviewed,-- Days since our dependency review.
  calc_ontology_profiles_recent_deprecation_count(t.ontology_profile_id) AS recent_deprecation_count,-- Adopted terms the standard deprecated in the last two years.
  calc_ontology_profiles_requires_frequent_review(t.ontology_profile_id) AS requires_frequent_review,-- TRUE when the standard deprecates often or went through a major revision in the last two years.
  calc_ontology_profiles_change_rate_profile(t.ontology_profile_id) AS change_rate_profile,-- How fast the standard changes: FrequentDeprecation, RecentMajorRevision, Dormant, or Unassessed.
  calc_ontology_profiles_is_review_overdue_for_change_rate(t.ontology_profile_id) AS is_review_overdue_for_change_rate,-- TRUE when a fast-changing standard has not had its dependency reviewed in 180 days.
  t.adoption_stage,                                                             -- 1 vocabulary, 2 lightweight ontology, 3 process and decision modeling.
  t.adopted_at,                                                                 -- When the model adopted the standard.
  t.prerequisite_profile,                                                       -- Earlier-stage standard this one builds on.
  calc_ontology_profiles_prerequisite_adopted_at(t.ontology_profile_id) AS prerequisite_adopted_at,-- When that standard was adopted.
  calc_ontology_profiles_skips_adoption_path(t.ontology_profile_id) AS skips_adoption_path,-- TRUE when a later-stage standard was adopted before the earlier-stage standard it builds on, or with none.
  t.supporting_programme,                                                       -- The funded programme that produced or supported this vocabulary.
  t.namespace_checked_at,                                                       -- When the namespace was last fetched by tools/check_namespace_resolution.py.
  t.namespace_http_status,                                                      -- HTTP status the namespace returned when last fetched.
  t.namespace_serves_rdf,                                                       -- Whether fetching the namespace with an RDF Accept header returned RDF.
  calc_ontology_profiles_namespace_is_http(t.ontology_profile_id) AS namespace_is_http,-- Whether the namespace is an HTTP(S) URI, the first Linked Data requirement, rather than a urn: or other non-resolvable identifier.
  calc_ontology_profiles_namespace_dereferences(t.ontology_profile_id) AS namespace_dereferences,-- The namespace is an HTTP URI and fetching it actually returned a document.
  calc_ontology_profiles_publishes_following_linked_data_principl(t.ontology_profile_id) AS publishes_following_linked_data_principles-- The vocabulary is published the way Linked Data requires: an HTTP URI that resolves, serves RDF when asked for it, and carries links to other terms.
FROM ontology_profiles t;

-- ----------------------------------------------------------------------------
-- vw_evaluation_contexts: The instant this rulebook's time-dependent witnesses are evaluated against. Modeled as data rather than wall-clock so every freshness, overdue, and validity answer is reproducible and auditable: asking the same question tomorrow yields the same answer. Exactly one row carries IsCurrent.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_evaluation_contexts CASCADE;
CREATE VIEW vw_evaluation_contexts WITH (security_invoker = ON) AS
SELECT
  t.evaluation_context_id,                                                      -- Stored logical identifier for one EvaluationContexts row.
  calc_evaluation_contexts_name(t.evaluation_context_id) AS name,               -- Human-readable calculated display alias for the EvaluationContexts row.
  t.label,                                                                      -- What this evaluation instant represents.
  t.as_of_instant,                                                              -- The instant all time-dependent witnesses are evaluated against.
  t.is_current,                                                                 -- TRUE for the single active evaluation context.
  t.rationale,                                                                  -- Why this instant was chosen.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  calc_evaluation_contexts_explicit_fragment_count(t.evaluation_context_id) AS explicit_fragment_count,-- Pieces of knowledge on record, judged at this instant, that are written down.
  calc_evaluation_contexts_tacit_fragment_count(t.evaluation_context_id) AS tacit_fragment_count,-- Pieces of knowledge on record that live in practiced hands and were drawn out of a person.
  calc_evaluation_contexts_implicit_fragment_count(t.evaluation_context_id) AS implicit_fragment_count,-- Pieces of knowledge on record that everybody acts on and nobody had ever stated.
  calc_evaluation_contexts_situated_judgment_fragment_count(t.evaluation_context_id) AS situated_judgment_fragment_count,-- Pieces of knowledge on record that are a judgment call for one situation.
  calc_evaluation_contexts_model_reasoned_answer_count(t.evaluation_context_id) AS model_reasoned_answer_count,-- Assistant answers on record where the language model did the reasoning itself.
  calc_evaluation_contexts_otherwise_reasoned_answer_count(t.evaluation_context_id) AS otherwise_reasoned_answer_count,-- Assistant answers on record where the reasoning was done by a query or a reasoner, or none was needed.
  calc_evaluation_contexts_assistant_answer_count(t.evaluation_context_id) AS assistant_answer_count,-- Every assistant answer on record.
  calc_evaluation_contexts_model_reasoned_failed_answer_count(t.evaluation_context_id) AS model_reasoned_failed_answer_count,-- Of the answers the language model reasoned out itself, how many of the tasks failed.
  calc_evaluation_contexts_out_of_order_step_execution_count(t.evaluation_context_id) AS out_of_order_step_execution_count,-- Step executions on record that were carried out of the order the procedure specifies.
  calc_evaluation_contexts_in_order_step_execution_count(t.evaluation_context_id) AS in_order_step_execution_count,-- Step executions on record that followed the order the procedure specifies.
  calc_evaluation_contexts_step_execution_count(t.evaluation_context_id) AS step_execution_count,-- Every step execution on record.
  calc_evaluation_contexts_early_start_step_execution_count(t.evaluation_context_id) AS early_start_step_execution_count,-- Step executions on record that began before the step they depend on had finished.
  calc_evaluation_contexts_exact_mapping_count(t.evaluation_context_id) AS exact_mapping_count,-- Concepts of this book that map exactly onto a term PKO itself defines.
  calc_evaluation_contexts_aligned_mapping_count(t.evaluation_context_id) AS aligned_mapping_count,-- Concepts of this book that map onto one of the older standards PKO reuses.
  calc_evaluation_contexts_extension_mapping_count(t.evaluation_context_id) AS extension_mapping_count-- Concepts of this book that PKO does not define: the book's own extensions, labelled as such.
FROM evaluation_contexts t;

-- ----------------------------------------------------------------------------
-- vw_organizations: Organizations that own, adopt, govern, or execute procedures. Maps to prov:Organization.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_organizations CASCADE;
CREATE VIEW vw_organizations WITH (security_invoker = ON) AS
SELECT
  t.organization_id,                                                            -- Stored logical identifier for one Organizations row.
  calc_organizations_name(t.organization_id) AS name,                           -- Human-readable calculated display alias for the Organizations row.
  t.display_name,                                                               -- Organization's human-readable name.
  t.organization_type,                                                          -- Type such as Company, Department, Vendor, or Regulator.
  t.external_identifier,                                                        -- Identifier in an operational directory or master-data system.
  t.semantic_type_iri,                                                          -- Exact RDF class IRI for the organization.
  calc_organizations_failed_ai_initiative_count(t.organization_id) AS failed_ai_initiative_count,-- AI initiatives that failed.
  calc_organizations_owned_procedure_count(t.organization_id) AS owned_procedure_count,-- Procedures the organization has captured.
  calc_organizations_ai_fails_for_lack_of_captured_knowledge(t.organization_id) AS ai_fails_for_lack_of_captured_knowledge,-- TRUE for an organization with a failed AI initiative that has captured no procedures.
  calc_organizations_product_delivery_function_count(t.organization_id) AS product_delivery_function_count,-- Functions that deliver the organization's own products.
  calc_organizations_provider_held_delivery_method_count(t.organization_id) AS provider_held_delivery_method_count,-- Of those, functions whose method knowledge a provider holds.
  calc_organizations_is_hollowed_out_firm(t.organization_id) AS is_hollowed_out_firm,-- TRUE when every function that delivers the organization's own products depends on method knowledge a provider holds.
  calc_organizations_audit_finding_count(t.organization_id) AS audit_finding_count,-- Audit items where the organization holds less knowledge than it needs.
  calc_organizations_filled_knowledge_position_count(t.organization_id) AS filled_knowledge_position_count,-- Filled knowledge engineering, information architecture and ontology positions.
  calc_organizations_has_knowledge_findings_without_knowledge_sta(t.organization_id) AS has_knowledge_findings_without_knowledge_staff,-- TRUE when audits found knowledge shortfalls and the organization employs no knowledge engineer, information architect or ontologist to address them.
  calc_organizations_departed_holder_know_how_count(t.organization_id) AS departed_holder_know_how_count,-- Know-how whose carrier has left.
  calc_organizations_lost_departed_know_how_count(t.organization_id) AS lost_departed_know_how_count,-- Know-how that left with its carrier, neither transferred nor captured.
  calc_organizations_retained_departed_know_how_percent(t.organization_id) AS retained_departed_know_how_percent,-- Share of departed carriers' know-how the organization kept.
  calc_organizations_memory_leaves_with_staff(t.organization_id) AS memory_leaves_with_staff,-- TRUE when some know-how of people who left was not retained.
  calc_organizations_captured_own_know_how_count(t.organization_id) AS captured_own_know_how_count,-- The organization's own know-how captured in its repository.
  calc_organizations_documentation_entry_count(t.organization_id) AS documentation_entry_count,-- Repository entries for the organization's procedures.
  calc_organizations_unallocated_documentation_count(t.organization_id) AS unallocated_documentation_count,-- Entries written outside allotted time.
  calc_organizations_transfer_given_count(t.organization_id) AS transfer_given_count,-- Transfers given by the organization's people.
  calc_organizations_unallocated_transfer_count(t.organization_id) AS unallocated_transfer_count,-- Transfers given outside allotted time.
  calc_organizations_treats_knowledge_work_as_unvalued(t.organization_id) AS treats_knowledge_work_as_unvalued,-- TRUE when most documentation and knowledge transfer happens outside the time the organization allots.
  calc_organizations_person_carried_know_how_count(t.organization_id) AS person_carried_know_how_count,-- Know-how carried by people.
  calc_organizations_facility_carried_know_how_count(t.organization_id) AS facility_carried_know_how_count,-- Know-how carried by plants.
  calc_organizations_system_carried_know_how_count(t.organization_id) AS system_carried_know_how_count,-- Know-how carried by systems.
  calc_organizations_holds_know_how_in_people_plants_and_systems(t.organization_id) AS holds_know_how_in_people_plants_and_systems,-- TRUE when the organization's how-to-build knowledge is carried at once by people, plants and systems.
  calc_organizations_staged_decline_count(t.organization_id) AS staged_decline_count,-- Capability declines that followed the decline of the preceding stage.
  calc_organizations_eroded_in_stages(t.organization_id) AS eroded_in_stages    -- TRUE when facility investment, then engineer training, then how-to-make upkeep declined in sequence.
FROM organizations t;

-- ----------------------------------------------------------------------------
-- vw_agents: Human and software agents that create, modify, approve, or execute procedural knowledge. Maps to prov:Agent.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_agents CASCADE;
CREATE VIEW vw_agents WITH (security_invoker = ON) AS
SELECT
  t.agent_id,                                                                   -- Stored logical identifier for one Agents row.
  calc_agents_name(t.agent_id) AS name,                                         -- Human-readable calculated display alias for the Agents row.
  t.display_name,                                                               -- Agent's human-readable name.
  t.agent_kind,                                                                 -- Human, AIAgent, AutomatedPipeline, Organization, or another explicit agent category.
  t.organization,                                                               -- Organization to which the agent belongs.
  t.contact_address,                                                            -- Contact address when applicable.
  t.version_or_employment_key,                                                  -- Model version, pipeline release, or employment assignment key.
  calc_agents_count_of_current_role_assignments(t.agent_id) AS count_of_current_role_assignments,-- How many role assignments this agent currently holds. Counts only CURRENT assignments via the CurrentAgentKey echo — counting all assignments would report a departed agent as engaged forever.
  calc_agents_is_still_engaged(t.agent_id) AS is_still_engaged,                 -- TRUE when this agent currently holds at least one role in the organization.
  calc_agents_decision_count(t.agent_id) AS decision_count,                     -- Total decisions this agent has recorded.
  calc_agents_overridden_decision_count(t.agent_id) AS overridden_decision_count,-- Decisions by this agent that a human corrected or reversed.
  calc_agents_override_rate_percent(t.agent_id) AS override_rate_percent,       -- Percentage of this agent's decisions that were overridden by a human.
  calc_agents_is_non_human(t.agent_id) AS is_non_human,                         -- TRUE when this agent is an AI agent or an automated pipeline.
  calc_agents_boundary_violation_count(t.agent_id) AS boundary_violation_count, -- Number of decisions by this agent that violated an authority boundary.
  calc_agents_is_operating_outside_boundary(t.agent_id) AS is_operating_outside_boundary,-- TRUE when this agent has made at least one decision an authority boundary forbids.
  calc_agents_draft_decision_count(t.agent_id) AS draft_decision_count,         -- Number of drafting decisions this agent has made.
  calc_agents_overridden_draft_count(t.agent_id) AS overridden_draft_count,     -- Number of this agent's drafting decisions a human corrected or reversed.
  calc_agents_draft_rewrite_rate_percent(t.agent_id) AS draft_rewrite_rate_percent,-- Percentage of this agent's drafting output that a human rewrote.
  calc_agents_times_named_as_broker(t.agent_id) AS times_named_as_broker,       -- How many active informal-reliance links name this agent as the one actually consulted.
  calc_agents_is_recognized_broker(t.agent_id) AS is_recognized_broker,         -- TRUE when at least three people actively rely on this agent as an informal knowledge broker.
  calc_agents_at_risk_reliance_count(t.agent_id) AS at_risk_reliance_count,     -- How many active informal-reliance links name this agent while this agent holds no current role.
  calc_agents_has_at_risk_knowledge_reliance(t.agent_id) AS has_at_risk_knowledge_reliance,-- TRUE when people are actively relying on this agent even though they have already left every role.
  t.semantic_type_iri,                                                          -- Exact semantic type IRI used when projecting the agent.
  t.represents_organization,                                                    -- For an organization acting as an agent, the organization.
  calc_agents_is_organization_agent(t.agent_id) AS is_organization_agent,       -- TRUE for an organization acting as an agent.
  calc_agents_answer_count(t.agent_id) AS answer_count,                         -- Assistant answers this agent delivered.
  calc_agents_ai_task_completed_count(t.agent_id) AS ai_task_completed_count,   -- Answers whose task completed.
  calc_agents_ai_task_completion_percent(t.agent_id) AS ai_task_completion_percent,-- Share of the agent's tasks that completed.
  calc_agents_is_below_task_completion_target(t.agent_id) AS is_below_task_completion_target,-- TRUE for an AI agent completing fewer than 80% of its tasks.
  calc_agents_runtime_integration_count(t.agent_id) AS runtime_integration_count,-- Integrations delivering knowledge to the agent at run time.
  calc_agents_lacks_runtime_knowledge_integration(t.agent_id) AS lacks_runtime_knowledge_integration,-- TRUE for an AI agent that answers people but receives no knowledge at run time.
  calc_agents_search_event_count(t.agent_id) AS search_event_count,             -- Searches and retrievals logged for the agent.
  calc_agents_is_untracked_ai_consumer(t.agent_id) AS is_untracked_ai_consumer, -- TRUE for an AI agent that consumes knowledge but whose retrievals are never logged.
  calc_agents_accountability_assertion_count(t.agent_id) AS accountability_assertion_count,-- Served, explicitly stated assertions about this agent.
  calc_agents_inferred_category_count(t.agent_id) AS inferred_category_count,   -- Served assertions the reasoner inferred about this agent's category.
  calc_agents_category_not_available_as_inference(t.agent_id) AS category_not_available_as_inference,-- TRUE for an agent named in accountability assertions whose category the graph never infers.
  calc_agents_is_unclassified_agent(t.agent_id) AS is_unclassified_agent,       -- TRUE when an agent is not classified as a person, AI agent, automated pipeline or organization.
  calc_agents_is_ai_agent_without_model_version(t.agent_id) AS is_ai_agent_without_model_version,-- TRUE for an AI agent carrying no model version identifier.
  calc_agents_attributed_artifact_count(t.agent_id) AS attributed_artifact_count,-- Artifacts attributed to the agent.
  calc_agents_has_produced_artifacts(t.agent_id) AS has_produced_artifacts,     -- TRUE when some artifact is attributed to the agent.
  calc_agents_has_artifact_blast_radius(t.agent_id) AS has_artifact_blast_radius,-- TRUE when moving the agent to another version affects steps downstream of its artifacts.
  calc_agents_registry_version_match_count(t.agent_id) AS registry_version_match_count,-- Registry records whose Dublin Core identifier and version match this agent individual.
  calc_agents_is_ai_agent_not_filled_from_registry(t.agent_id) AS is_ai_agent_not_filled_from_registry,-- TRUE for an AI agent individual that no registry record supplies, or whose version disagrees with the registry.
  calc_agents_current_accountable_human_count(t.agent_id) AS current_accountable_human_count,-- Human persons currently accountable for the agent.
  calc_agents_is_ai_agent_without_accountable_human(t.agent_id) AS is_ai_agent_without_accountable_human,-- TRUE for an AI agent currently filling a role with no human person accountable for it.
  t.service_started_at,                                                         -- When the person began practising in the organization.
  t.departure_at,                                                               -- The person's planned or actual departure.
  t.protected_mentoring_hours_per_week,                                         -- Weekly hours protected from production work for mentoring.
  calc_agents_community_count(t.agent_id) AS community_count,                   -- Communities of practice the agent belongs to.
  calc_agents_is_boundary_spanner(t.agent_id) AS is_boundary_spanner,           -- TRUE when the agent belongs to two or more communities of practice.
  calc_agents_sna_identification_count(t.agent_id) AS sna_identification_count, -- Network analyses that identified the agent as a connector.
  calc_agents_is_unidentified_boundary_spanner(t.agent_id) AS is_unidentified_boundary_spanner,-- TRUE when a person connecting communities was never found by a network analysis.
  calc_agents_located_know_how_count(t.agent_id) AS located_know_how_count,     -- Know-how held by someone else that the agent, as broker, can point seekers to.
  calc_agents_required_mentoring_hours_per_week(t.agent_id) AS required_mentoring_hours_per_week,-- Weekly hours the agent's active mentorships need.
  calc_agents_lacks_time_to_mentor(t.agent_id) AS lacks_time_to_mentor,         -- TRUE when a mentor's protected hours fall short of what their active mentorships need.
  calc_agents_transfers_given_count(t.agent_id) AS transfers_given_count,       -- Times the agent passed know-how on.
  calc_agents_recognition_count(t.agent_id) AS recognition_count,               -- Recognitions the agent received for sharing.
  calc_agents_is_unrewarded_sharer(t.agent_id) AS is_unrewarded_sharer,         -- TRUE when someone who repeatedly passes know-how on has never been recognized for it.
  calc_agents_downstream_of_held_steps_count(t.agent_id) AS downstream_of_held_steps_count,-- Steps reachable along artifact hand-offs from the steps whose role this agent currently holds.
  calc_agents_artifact_blast_radius_step_count(t.agent_id) AS artifact_blast_radius_step_count-- For an AI agent, the steps downstream of the steps it holds, found by traversing the artifact hand-off closure.
FROM agents t;

-- ----------------------------------------------------------------------------
-- vw_roles: Stable organizational functions separated from the agents that currently fill them. Maps to pro:Role.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_roles CASCADE;
CREATE VIEW vw_roles WITH (security_invoker = ON) AS
SELECT
  t.role_id,                                                                    -- Stored logical identifier for one Roles row.
  calc_roles_name(t.role_id) AS name,                                           -- Human-readable calculated display alias for the Roles row.
  t.label,                                                                      -- Human-readable role label.
  t.organization,                                                               -- Organization that owns the role.
  t.current_agent,                                                              -- Current agent filling the role; history is retained in RoleAssignments.
  calc_roles_current_agent_kind(t.role_id) AS current_agent_kind,               -- Agent category of the current role filler.
  t.responsibility,                                                             -- Accountability and responsibility assigned to the role.
  calc_roles_active_assignment_count(t.role_id) AS active_assignment_count,     -- Total number of assignment rows ever recorded against this role.
  calc_roles_currently_covered_assignment_count(t.role_id) AS currently_covered_assignment_count,-- Number of assignment rows for this role that are in force right now.
  calc_roles_has_no_current_holder(t.role_id) AS has_no_current_holder,         -- TRUE when no assignment currently covers this role — the role is uncovered.
  calc_roles_count_of_awaited_decisions(t.role_id) AS count_of_awaited_decisions,-- How many change requests name this role as the deciding authority.
  t.current_assignment,                                                         -- The RoleAssignments id of the assignment by which this role is currently held. Deliberately a raw identifier, not a relationship: RoleAssignments already points at Roles, so an FK back would make the two mutually dependent and this rulebook must stay acyclic.
  calc_roles_current_assignment_valid_from(t.role_id) AS current_assignment_valid_from,-- Start of the currently-in-force assignment for this role.
  calc_roles_is_non_human_held(t.role_id) AS is_non_human_held,                 -- TRUE when the role's current agent is an AI agent or automated pipeline.
  calc_roles_is_ungoverned_non_human_role(t.role_id) AS is_ungoverned_non_human_role,-- TRUE when a role is pointed at a non-human agent but has no assignment row granting it.
  calc_roles_departed_assignment_count(t.role_id) AS departed_assignment_count, -- How many assignments to this role have ended.
  calc_roles_has_lost_a_holder(t.role_id) AS has_lost_a_holder,                 -- Whether anyone has ever departed this role.
  calc_roles_is_vacated_role(t.role_id) AS is_vacated_role,                     -- A role somebody departed and that nobody currently covers.
  calc_roles_ungrounded_boundary_count(t.role_id) AS ungrounded_boundary_count, -- How many boundaries constrain this role on lapsed authority.
  calc_roles_is_governed_by_lapsed_authority(t.role_id) AS is_governed_by_lapsed_authority,-- TRUE when at least one constraint on this role rests on knowledge that is no longer valid.
  calc_roles_unescalated_refusal_count(t.role_id) AS unescalated_refusal_count, -- How many refusals this role should have been told about and was not.
  calc_roles_unauthorized_enforcement_assignment_count(t.role_id) AS unauthorized_enforcement_assignment_count,-- How many current assignments of this role are unauthorized enforcement assignments.
  calc_roles_is_ungoverned_enforcement_role(t.role_id) AS is_ungoverned_enforcement_role,-- TRUE when a role that enforces controls on others is held with no recorded authorization.
  t.semantic_type_iri,                                                          -- Exact semantic type IRI for the role.
  t.specializes_role,                                                           -- Role this one specializes.
  t.seniority_level,                                                            -- Senior, Deputy, or blank.
  t.role_family,                                                                -- Family of roles doing the same kind of work.
  calc_roles_specialized_role_family(t.role_id) AS specialized_role_family,     -- Family of the specialized role.
  calc_roles_specialization_count(t.role_id) AS specialization_count,           -- Roles that specialize this one.
  calc_roles_has_specializations(t.role_id) AS has_specializations,             -- TRUE when another role specializes this one.
  calc_roles_is_senior_variant_not_specialization(t.role_id) AS is_senior_variant_not_specialization,-- TRUE when a senior version of a role is not recorded as a specialization of a role in its own family.
  calc_roles_organization_type(t.role_id) AS organization_type,                 -- Kind of organization the role sits in.
  calc_roles_is_not_housed_in_department(t.role_id) AS is_not_housed_in_department,-- TRUE when the role sits directly in a company or division rather than a department.
  calc_roles_capability_tag_count(t.role_id) AS capability_tag_count,           -- Capability tags.
  calc_roles_compliance_review_tag_count(t.role_id) AS compliance_review_tag_count,-- Compliance-review capability tags.
  calc_roles_has_compliance_review_capability(t.role_id) AS has_compliance_review_capability,-- TRUE when the role carries the compliance-review capability.
  calc_roles_role_mention_count(t.role_id) AS role_mention_count,               -- Source mentions judged to mean this role.
  calc_roles_unresolved_role_mention_count(t.role_id) AS unresolved_role_mention_count,-- Such mentions whose wording the role vocabulary does not resolve.
  calc_roles_is_missed_by_phrase_query(t.role_id) AS is_missed_by_phrase_query, -- TRUE when a query for this role through the role vocabulary misses a process that mentions it in other words.
  t.preferred_knowledge_form,                                                   -- Whether people in the role prefer knowledge as Prose or as a Diagram.
  t.escalation_backup_role,                                                     -- Role that backs this one up on escalation.
  calc_roles_current_holder_name(t.role_id) AS current_holder_name,             -- Name of the person or system holding the role.
  calc_roles_backup_role_holder(t.role_id) AS backup_role_holder,               -- Agent holding the escalation backup role.
  calc_roles_has_escalation_backup(t.role_id) AS has_escalation_backup,         -- TRUE when the role names an escalation backup role.
  calc_roles_has_unfilled_escalation_backup(t.role_id) AS has_unfilled_escalation_backup,-- TRUE when the escalation backup role has nobody in it.
  calc_roles_release_approval_step_count(t.role_id) AS release_approval_step_count,-- Production release approval gates assigned to the role.
  calc_roles_is_production_release_approver(t.role_id) AS is_production_release_approver,-- TRUE for the role that approves production releases.
  calc_roles_approval_step_count(t.role_id) AS approval_step_count              -- Approval steps assigned to the role.
FROM roles t;

-- ----------------------------------------------------------------------------
-- vw_role_assignments: Time-bounded records of agents holding roles. Maps to pro:RoleInTime and preserves assignment history instead of overwriting it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_role_assignments: Time-bounded records of agents holding roles. Maps to pro:RoleInTime and preserves assignment history instead of overwriting it.
-- SELF-REFERENTIAL SETTLE: RoleAssignments has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: agent_kind, override_rate_percent, decision_count. Drivers: supersedes_assignment.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_assignments CASCADE;
CREATE VIEW vw_role_assignments WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.role_assignment_id, jsonb_build_object(
      'agent_kind', ((SELECT agent_kind FROM agents WHERE agent_id = ((SELECT NULLIF(t.agent::text,'')))::text)),
      'override_rate_percent', CASE WHEN COALESCE(((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,''))))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_overridden(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100, 0))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0), 0)))::text END,
      'decision_count', (SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))
    ))
    FROM role_assignments t WHERE NULLIF(t.supersedes_assignment,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.role_assignment_id, jsonb_build_object(
      'agent_kind', ((SELECT agent_kind FROM agents WHERE agent_id = ((SELECT NULLIF(t.agent::text,'')))::text)),
      'override_rate_percent', CASE WHEN COALESCE(((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,''))))::NUMERIC, 0) = 0 THEN (0)::text ELSE ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_overridden(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0) * COALESCE(100, 0))) AS v OFFSET 0) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))) AS v OFFSET 0) __safe_numeric), 0), 0)))::text END,
      'decision_count', (SELECT COUNT(*) FROM agent_decision_records WHERE calc_agent_decision_records_role_assignment_when_scored(agent_decision_record_id) = (SELECT NULLIF(t.role_assignment_id::text,'')))
    ))
    FROM role_assignments t
    WHERE NOT (a.settled ? t.role_assignment_id) AND NOT (NULLIF(t.supersedes_assignment,'') IS NULL) AND (NULLIF(t.supersedes_assignment,'') IS NULL OR a.settled ? t.supersedes_assignment)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM role_assignments t
    WHERE NOT (a.settled ? t.role_assignment_id) AND NOT (NULLIF(t.supersedes_assignment,'') IS NULL) AND (NULLIF(t.supersedes_assignment,'') IS NULL OR a.settled ? t.supersedes_assignment))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.role_assignment_id,                                                         -- Stored logical identifier for one RoleAssignments row.
  calc_role_assignments_name(t.role_assignment_id) AS name,                     -- Human-readable calculated display alias for the RoleAssignments row.
  t.role,                                                                       -- Role held during the assignment.
  t.agent,                                                                      -- Agent holding the role.
  t.valid_from,                                                                 -- Start of the assignment's valid-time interval.
  t.valid_to,                                                                   -- End of the assignment's valid-time interval; null means open-ended.
  t.reason,                                                                     -- Rationale for the assignment or reassignment.
  t.status,                                                                     -- Active, Superseded, Planned, or Revoked.
  t.evaluation_context,                                                         -- The evaluation context this assignment's currency is judged under.
  calc_role_assignments_as_of_instant(t.role_assignment_id) AS as_of_instant,   -- The evaluation instant this assignment's currency is judged against.
  calc_role_assignments_is_current(t.role_assignment_id) AS is_current,         -- TRUE when the assignment is valid now.
  calc_role_assignments_current_agent_key(t.role_assignment_id) AS current_agent_key,-- Echoes the Agent id only while this assignment is current; empty otherwise. Lets a parent count CURRENT assignments with a single-criterion COUNTIFS, which is the only shape this transpiler translates correctly.
  calc_role_assignments_is_currently_valid(t.role_assignment_id) AS is_currently_valid,-- TRUE when this role assignment is active and has not lapsed.
  calc_role_assignments_agent_role_key(t.role_assignment_id) AS agent_role_key, -- Composite agent+role key, emitted only for currently-valid assignments.
  calc_role_assignments_has_departed(t.role_assignment_id) AS has_departed,     -- TRUE when this role assignment has ended — the agent no longer holds the role.
  calc_role_assignments_covers_now(t.role_assignment_id) AS covers_now,         -- TRUE when this assignment is both status-Active and inside its valid-time window right now.
  calc_role_assignments_role_when_covering(t.role_assignment_id) AS role_when_covering,-- Echoes the role id when this assignment is currently in force, blank otherwise.
  (SELECT settled #>> ARRAY[t.role_assignment_id::text, 'agent_kind'] FROM settled)::text AS agent_kind,-- Whether the agent holding this assignment is Human, AIAgent, or AutomatedPipeline.
  calc_role_assignments_is_non_human_assignment(t.role_assignment_id) AS is_non_human_assignment,-- TRUE when this assignment places a non-human agent into the role.
  t.supersedes_assignment,                                                      -- The assignment this one replaced, if any.
  (SELECT settled #>> ARRAY[NULLIF(t.supersedes_assignment,''), 'agent_kind'] FROM settled)::text AS predecessor_agent_kind,-- Agent kind of the assignment this one superseded.
  calc_role_assignments_is_human_to_non_human_handover(t.role_assignment_id) AS is_human_to_non_human_handover,-- TRUE when this assignment handed a role from a human to a non-human agent.
  t.approving_authority_role,                                                   -- Role that approved this assignment.
  t.authorizing_change_request,                                                 -- Change request under which this assignment was approved.
  calc_role_assignments_is_unauthorized_non_human_assignment(t.role_assignment_id) AS is_unauthorized_non_human_assignment,-- TRUE when a non-human agent holds this role with no approving authority recorded at all. An authority named without a change request is still an authority; the separate WasAuthorizedByChangeRequest column carries that weaker distinction.
  calc_role_assignments_was_authorized_by_change_request(t.role_assignment_id) AS was_authorized_by_change_request,-- TRUE when this assignment's authorization is traceable to a change request, not merely to a named role. The stronger form of authorization, kept separate so the weaker one is not silently reported as unauthorized.
  (SELECT settled #>> ARRAY[t.role_assignment_id::text, 'decision_count'] FROM settled)::numeric AS decision_count,-- Decisions made under this assignment.
  calc_role_assignments_overridden_decision_count(t.role_assignment_id) AS overridden_decision_count,-- Decisions made under this assignment that a human corrected or reversed.
  (SELECT settled #>> ARRAY[t.role_assignment_id::text, 'override_rate_percent'] FROM settled)::numeric AS override_rate_percent,-- Percentage of decisions under this assignment that a human overrode.
  (SELECT settled #>> ARRAY[NULLIF(t.supersedes_assignment,''), 'override_rate_percent'] FROM settled)::numeric AS predecessor_override_rate_percent,-- Override rate of the assignment this one superseded.
  calc_role_assignments_quality_regressed_vs_predecessor(t.role_assignment_id) AS quality_regressed_vs_predecessor,-- TRUE when this assignment is overridden by humans more often than the assignment it replaced.
  calc_role_assignments_departed_role_key(t.role_assignment_id) AS departed_role_key,-- Composite-key echo: the role this assignment covered when the assignment has ended, blank otherwise.
  t.minimum_decisions_for_comparison,                                           -- The number of decisions below which an override-rate comparison is not considered evidentially meaningful for this role.
  (SELECT settled #>> ARRAY[NULLIF(t.supersedes_assignment,''), 'decision_count'] FROM settled)::numeric AS predecessor_decision_count,-- How many decisions the superseded assignment produced.
  calc_role_assignments_has_sufficient_sample(t.role_assignment_id) AS has_sufficient_sample,-- TRUE when this assignment has produced enough decisions for its override rate to mean anything.
  calc_role_assignments_predecessor_has_sufficient_sample(t.role_assignment_id) AS predecessor_has_sufficient_sample,-- TRUE when the predecessor assignment produced enough decisions to compare against.
  calc_role_assignments_comparison_is_evidentially_sound(t.role_assignment_id) AS comparison_is_evidentially_sound,-- TRUE when both sides of the override-rate comparison rest on adequate samples.
  calc_role_assignments_single_override_swing_percent(t.role_assignment_id) AS single_override_swing_percent,-- How many percentage points one additional override would move this assignment's rate. The fragility of the number.
  calc_role_assignments_quality_verdict_is_unsupported(t.role_assignment_id) AS quality_verdict_is_unsupported,-- TRUE when a quality verdict is being reported for this assignment on a sample too small to support it.
  calc_role_assignments_is_unmeasured_automation_handover(t.role_assignment_id) AS is_unmeasured_automation_handover,-- TRUE when a human-to-machine handover is operating without a statistically meaningful quality comparison behind it.
  calc_role_assignments_error_correction_count(t.role_assignment_id) AS error_correction_count,-- How many of this assignment's decisions were overridden because they were wrong.
  calc_role_assignments_error_rate_percent(t.role_assignment_id) AS error_rate_percent,-- Percentage of this assignment's decisions overridden as errors -- the override rate with reserved-judgment overrides removed.
  t.authorization_decided_at,                                                   -- When the approving authority actually granted this assignment. Empty when no authorization was ever recorded.
  t.authorization_reviewed_at,                                                  -- When the authorization for this assignment was last re-examined.
  t.authorization_review_cadence_days,                                          -- How often this assignment's authorization is promised to be re-examined.
  calc_role_assignments_has_dated_authorization(t.role_assignment_id) AS has_dated_authorization,-- TRUE when this assignment carries both a named approving authority and the date they granted it.
  calc_role_assignments_days_since_authorization_review(t.role_assignment_id) AS days_since_authorization_review,-- How long since this assignment's authorization was last re-examined.
  calc_role_assignments_authorization_is_overdue_for_review(t.role_assignment_id) AS authorization_is_overdue_for_review,-- TRUE when the promised re-examination interval has elapsed without a review.
  calc_role_assignments_is_standing_unreviewed_automation(t.role_assignment_id) AS is_standing_unreviewed_automation,-- TRUE when a currently-active non-human assignment has been running past its authorization review date.
  calc_role_assignments_is_unconditioned_automation_handover(t.role_assignment_id) AS is_unconditioned_automation_handover,-- TRUE when a human-to-machine handover was authorized with no promised review cadence at all -- granted once, permanently.
  t.max_tolerable_error_rate_percent,                                           -- The error rate at or above which this assignment must stop making decisions unaided.
  calc_role_assignments_exceeds_tolerable_error_rate(t.role_assignment_id) AS exceeds_tolerable_error_rate,-- TRUE when this assignment's error rate has reached the threshold set when it was authorized.
  calc_role_assignments_boundary_violation_count_for_assignment(t.role_assignment_id) AS boundary_violation_count_for_assignment,-- How many decisions under this assignment violated an authority boundary.
  calc_role_assignments_has_any_boundary_violation(t.role_assignment_id) AS has_any_boundary_violation,-- TRUE when any decision under this assignment crossed a boundary it was forbidden to cross.
  calc_role_assignments_has_ungrounded_governing_boundary(t.role_assignment_id) AS has_ungrounded_governing_boundary,-- TRUE when at least one boundary constraining this assignment's role rests on lapsed knowledge.
  calc_role_assignments_suspension_condition_met(t.role_assignment_id) AS suspension_condition_met,-- TRUE when any pre-declared condition requiring this assignment to stop deciding unaided has been met.
  calc_role_assignments_is_operating_under_met_suspension_conditi(t.role_assignment_id) AS is_operating_under_met_suspension_condition,-- TRUE when a suspension condition has been met and the assignment is nonetheless still active and still deciding.
  calc_role_assignments_has_declared_suspension_condition(t.role_assignment_id) AS has_declared_suspension_condition,-- TRUE when this assignment has any pre-declared condition under which it must stop at all.
  calc_role_assignments_has_approving_authority(t.role_assignment_id) AS has_approving_authority,-- TRUE when a role is recorded as having approved this assignment.
  calc_role_assignments_has_authorizing_change_request(t.role_assignment_id) AS has_authorizing_change_request,-- TRUE when a change request is recorded as the governance vehicle for this assignment.
  t.is_enforcement_role,                                                        -- Whether this role's function is to enforce controls on other agents' actions.
  calc_role_assignments_is_unauthorized_enforcement_agent(t.role_assignment_id) AS is_unauthorized_enforcement_agent,-- TRUE when a non-human agent enforces controls on others while holding no recorded authorization of its own.
  calc_role_assignments_governance_evidence_count(t.role_assignment_id) AS governance_evidence_count,-- How many independent governance artifacts back this assignment: an approving role, an authorizing change request.
  calc_role_assignments_unauthorized_enforcement_role_key(t.role_assignment_id) AS unauthorized_enforcement_role_key,-- Echoes the role only for non-human assignments nobody authorized; empty otherwise.
  t.semantic_type_iri,                                                          -- Exact class IRI for the assignment event.
  t.for_procedure_version,                                                      -- Procedure version the role is held for (pro:relatesTo).
  calc_role_assignments_scoped_version_status(t.role_assignment_id) AS scoped_version_status,-- Status of that version.
  calc_role_assignments_is_scoped_to_retired_version(t.role_assignment_id) AS is_scoped_to_retired_version,-- TRUE when a current assignment is held for a version that is deprecated or archived.
  calc_role_assignments_predecessor_valid_to(t.role_assignment_id) AS predecessor_valid_to,-- When the superseded assignment ended.
  calc_role_assignments_predecessor_lacks_validity_end(t.role_assignment_id) AS predecessor_lacks_validity_end,-- TRUE when an assignment supersedes one whose validity period was never closed.
  calc_role_assignments_agent_version_key(t.role_assignment_id) AS agent_version_key,-- Model version or employment key of the assigned agent.
  calc_role_assignments_agent_role_pair_key(t.role_assignment_id) AS agent_role_pair_key,-- Agent and role, as one key, regardless of validity.
  calc_role_assignments_is_open_ended(t.role_assignment_id) AS is_open_ended,   -- TRUE when the assignment has no end.
  calc_role_assignments_role_approval_step_count(t.role_assignment_id) AS role_approval_step_count,-- Approval steps assigned to the role.
  calc_role_assignments_receives_approval_notices_now(t.role_assignment_id) AS receives_approval_notices_now-- TRUE when the assignment currently covers a role that approval steps are assigned to, so its agent is who approval notices go to.
FROM role_assignments t;

-- ----------------------------------------------------------------------------
-- vw_communities_of_practice: Socio-technical communities that transmit and maintain procedural knowledge. Explicit ERB-PKO extension.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_communities_of_practice CASCADE;
CREATE VIEW vw_communities_of_practice WITH (security_invoker = ON) AS
SELECT
  t.community_of_practice_id,                                                   -- Stored logical identifier for one CommunitiesOfPractice row.
  calc_communities_of_practice_name(t.community_of_practice_id) AS name,        -- Human-readable calculated display alias for the CommunitiesOfPractice row.
  t.label,                                                                      -- Community's human-readable name.
  t.organization,                                                               -- Organization hosting the community.
  t.steward_role,                                                               -- Role accountable for convening and maintaining the community.
  t.purpose,                                                                    -- Shared practice and knowledge-transfer purpose.
  t.cadence,                                                                    -- Meeting or practice cadence.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.own_vocabulary,                                                             -- The vocabulary the community speaks.
  t.norms,                                                                      -- The community's working norms.
  t.origin,                                                                     -- Grassroots, Mandated or PurchasedPlatform.
  t.open_apprenticeship_places,                                                 -- Apprenticeship places on offer.
  t.is_colocated_trade,                                                         -- TRUE when the trade is concentrated in one place.
  calc_communities_of_practice_has_own_vocabulary_and_norms(t.community_of_practice_id) AS has_own_vocabulary_and_norms,-- TRUE when the community has its own vocabulary and stated norms.
  calc_communities_of_practice_sharing_event_count(t.community_of_practice_id) AS sharing_event_count,-- Know-how transfers inside the community.
  calc_communities_of_practice_is_mandated_without_sharing_norm(t.community_of_practice_id) AS is_mandated_without_sharing_norm,-- TRUE when a community was mandated or bought and no sharing happens in it.
  calc_communities_of_practice_interconnected_know_how_count(t.community_of_practice_id) AS interconnected_know_how_count,-- Know-how in the community that builds on related know-how in the same community.
  calc_communities_of_practice_physical_know_how_count(t.community_of_practice_id) AS physical_know_how_count,-- Know-how about physical work.
  calc_communities_of_practice_digital_know_how_count(t.community_of_practice_id) AS digital_know_how_count,-- Know-how about digital work.
  calc_communities_of_practice_person_carried_know_how_count(t.community_of_practice_id) AS person_carried_know_how_count,-- Know-how carried by people.
  calc_communities_of_practice_spans_physical_and_digital_with_hu(t.community_of_practice_id) AS spans_physical_and_digital_with_humans,-- TRUE when the community's know-how spans physical and digital work and people still carry it.
  calc_communities_of_practice_external_member_count(t.community_of_practice_id) AS external_member_count,-- Members from other organizations.
  calc_communities_of_practice_specialist_member_count(t.community_of_practice_id) AS specialist_member_count,-- Specialists among the members.
  calc_communities_of_practice_employer_move_count(t.community_of_practice_id) AS employer_move_count,-- Know-how carried by people changing employers inside the community.
  calc_communities_of_practice_is_cross_firm_practice_cluster(t.community_of_practice_id) AS is_cross_firm_practice_cluster,-- TRUE when members from several firms share practice, people move between firms, and specialists are at hand.
  calc_communities_of_practice_recent_apprenticeship_count(t.community_of_practice_id) AS recent_apprenticeship_count,-- Apprenticeships started in the community within three years.
  calc_communities_of_practice_is_circulation_ending_for_lack_of_(t.community_of_practice_id) AS is_circulation_ending_for_lack_of_apprentices,-- TRUE when know-how circulates by people moving between firms but offered apprenticeships go unfilled.
  calc_communities_of_practice_ambient_absorption_count(t.community_of_practice_id) AS ambient_absorption_count,-- Know-how absorbed by non-practitioners living among the trade.
  calc_communities_of_practice_has_ambient_trade_know_how(t.community_of_practice_id) AS has_ambient_trade_know_how-- TRUE when a trade concentrated in one place passes know-how even to people who do not practise it.
FROM communities_of_practice t;

-- ----------------------------------------------------------------------------
-- vw_mentorships: Time-bounded apprenticeship relationships that intentionally transfer situated procedural knowledge. Explicit ERB-PKO extension.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_mentorships CASCADE;
CREATE VIEW vw_mentorships WITH (security_invoker = ON) AS
SELECT
  t.mentorship_id,                                                              -- Stored logical identifier for one Mentorships row.
  calc_mentorships_name(t.mentorship_id) AS name,                               -- Human-readable calculated display alias for the Mentorships row.
  t.community_of_practice,                                                      -- Community in which the mentorship operates.
  t.mentor_agent,                                                               -- Experienced practitioner serving as mentor.
  t.learner_agent,                                                              -- Practitioner learning the procedure.
  t.valid_from,                                                                 -- Mentorship start.
  t.valid_to,                                                                   -- Mentorship end.
  t.learning_objective,                                                         -- Procedural capability to be transferred.
  t.evidence_of_completion,                                                     -- Evidence showing completion or competence.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_mentorships_as_of_instant(t.mentorship_id) AS as_of_instant,             -- The modeled evaluation instant.
  t.mentorship_form,                                                            -- Mentoring or Apprenticeship.
  t.employer_worker_obligation,                                                 -- The obligations between employer and worker that make the training worth investing in.
  t.expected_weekly_hours,                                                      -- Weekly mentor hours the mentorship needs.
  calc_mentorships_is_active(t.mentorship_id) AS is_active,                     -- TRUE when the mentorship runs at the evaluation instant.
  calc_mentorships_days_since_started(t.mentorship_id) AS days_since_started,   -- Days since the mentorship began.
  calc_mentorships_is_recent_apprenticeship(t.mentorship_id) AS is_recent_apprenticeship,-- TRUE for an apprenticeship started within three years.
  calc_mentorships_community_label(t.mentorship_id) AS community_label          -- The name of the community of practice this mentorship belongs to.
FROM mentorships t;

-- ----------------------------------------------------------------------------
-- vw_procedure_types: Controlled values used by pko:hasProcedureType.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_procedure_types: Controlled values used by pko:hasProcedureType.
-- SELF-REFERENTIAL SETTLE: ProcedureTypes has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: is_detached_from_taxonomy. Drivers: broader_procedure_type.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_types CASCADE;
CREATE VIEW vw_procedure_types WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.procedure_type_id, jsonb_build_object(
      'is_detached_from_taxonomy', (COALESCE(COALESCE((SELECT NULLIF(t.taxonomy_rank::text,'')), '') <> 'FunctionalDomain', FALSE) AND COALESCE((SELECT NULLIF(t.broader_procedure_type::text,'')) IS NULL, FALSE))
    ))
    FROM procedure_types t WHERE NULLIF(t.broader_procedure_type,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.procedure_type_id, jsonb_build_object(
      'is_detached_from_taxonomy', (COALESCE(COALESCE((SELECT NULLIF(t.taxonomy_rank::text,'')), '') <> 'FunctionalDomain', FALSE) AND COALESCE((SELECT NULLIF(t.broader_procedure_type::text,'')) IS NULL, FALSE))
    ))
    FROM procedure_types t
    WHERE NOT (a.settled ? t.procedure_type_id) AND NOT (NULLIF(t.broader_procedure_type,'') IS NULL) AND (NULLIF(t.broader_procedure_type,'') IS NULL OR a.settled ? t.broader_procedure_type)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM procedure_types t
    WHERE NOT (a.settled ? t.procedure_type_id) AND NOT (NULLIF(t.broader_procedure_type,'') IS NULL) AND (NULLIF(t.broader_procedure_type,'') IS NULL OR a.settled ? t.broader_procedure_type))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.procedure_type_id,                                                          -- Stored logical identifier for one ProcedureTypes row.
  calc_procedure_types_name(t.procedure_type_id) AS name,                       -- Human-readable calculated display alias for the ProcedureTypes row.
  t.label,                                                                      -- Procedure type label.
  t.definition,                                                                 -- Definition and scope of the procedure type.
  t.semantic_type_iri,                                                          -- Exact class IRI for procedure types.
  t.broader_procedure_type,                                                     -- Broader node of the process taxonomy.
  t.taxonomy_rank,                                                              -- FunctionalDomain, ProcessGroup or ProcessType.
  t.distinguishing_facet,                                                       -- Facet whose value distinguishes members of this grouping.
  t.distinguishing_value,                                                       -- The value members share.
  calc_procedure_types_narrower_type_count(t.procedure_type_id) AS narrower_type_count,-- Narrower taxonomy nodes.
  calc_procedure_types_has_narrower_types(t.procedure_type_id) AS has_narrower_types,-- TRUE when narrower process types fall under the node.
  (SELECT settled #>> ARRAY[t.procedure_type_id::text, 'is_detached_from_taxonomy'] FROM settled)::boolean AS is_detached_from_taxonomy,-- TRUE when a node below domain rank has no broader node.
  (SELECT settled #>> ARRAY[NULLIF(t.broader_procedure_type,''), 'is_detached_from_taxonomy'] FROM settled)::boolean AS broader_is_detached,-- Whether the broader node is detached.
  calc_procedure_types_is_unreachable_by_navigation(t.procedure_type_id) AS is_unreachable_by_navigation,-- TRUE when navigating down from the functional domains never reaches this node.
  calc_procedure_types_member_count(t.procedure_type_id) AS member_count,       -- Procedures classified here.
  calc_procedure_types_members_lacking_distinction_count(t.procedure_type_id) AS members_lacking_distinction_count,-- Members that do not have the distinguishing value.
  calc_procedure_types_is_arbitrary_grouping(t.procedure_type_id) AS is_arbitrary_grouping-- TRUE when a grouping has members but names no distinction, or none of its members has the distinction it names.
FROM procedure_types t;

-- ----------------------------------------------------------------------------
-- vw_procedures: Abstract, discoverable procedures. Each version is represented separately in ProcedureVersions. Maps to pko:Procedure and dcat:Resource.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedures CASCADE;
CREATE VIEW vw_procedures WITH (security_invoker = ON) AS
SELECT
  t.procedure_id,                                                               -- Stored logical identifier for one Procedures row.
  calc_procedures_name(t.procedure_id) AS name,                                 -- Human-readable calculated display alias for the Procedures row.
  t.title,                                                                      -- Human-readable title; maps to dcterms:title.
  t.procedure_type,                                                             -- Procedure type; maps to pko:hasProcedureType.
  t.owner_organization,                                                         -- Organization that owns the procedure.
  t.adopted_by_organization,                                                    -- Organization that adopts the procedure; maps to pko:isAdoptedBy.
  t.purpose,                                                                    -- Desired outcome and scope of the procedure.
  t.target,                                                                     -- Thing or population on which the procedure acts; maps to pko:hasProcedureTarget.
  t.is_template,                                                                -- TRUE when the procedure is a reusable template; maps to pko:isTemplate.
  t.current_version_key,                                                        -- Current version identifier, mirrored structurally by ProcedureVersions.IsCurrent.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  calc_procedures_execution_count(t.procedure_id) AS execution_count,           -- Recorded executions across every version of this procedure.
  t.template_procedure,                                                         -- Template this procedure instantiates (pko:hasTemplate).
  t.required_by_regulation,                                                     -- Regulation that makes this procedure mandatory.
  calc_procedures_is_template_instance(t.procedure_id) AS is_template_instance, -- TRUE when the procedure instantiates a template.
  calc_procedures_target_count(t.procedure_id) AS target_count,                 -- Targets the procedure is about.
  calc_procedures_adoption_count(t.procedure_id) AS adoption_count,             -- Organizations that adopted the procedure.
  calc_procedures_specified_step_total(t.procedure_id) AS specified_step_total, -- Steps specified across every version of the procedure.
  calc_procedures_has_no_explicit_steps(t.procedure_id) AS has_no_explicit_steps,-- TRUE for a procedure that exists only as a title and documents: no version specifies a single step.
  calc_procedures_called_by_step_count(t.procedure_id) AS called_by_step_count, -- Steps of other procedures that invoke this one as a sub-procedure.
  calc_procedures_is_nested_procedure(t.procedure_id) AS is_nested_procedure,   -- TRUE when the procedure runs inside a larger procedure.
  calc_procedures_failure_criterion_count(t.procedure_id) AS failure_criterion_count,-- Failure criteria.
  calc_procedures_has_no_failure_criterion(t.procedure_id) AS has_no_failure_criterion,-- TRUE when nothing says what outcome counts as failure.
  calc_procedures_lens_view_count(t.procedure_id) AS lens_view_count,           -- Stakeholder views of the procedure.
  calc_procedures_privileges_single_stakeholder_view(t.procedure_id) AS privileges_single_stakeholder_view,-- TRUE when the procedure is organized for exactly one stakeholder lens.
  calc_procedures_step_level_view_count(t.procedure_id) AS step_level_view_count,-- Views whose lens needs step-level detail.
  calc_procedures_category_level_view_count(t.procedure_id) AS category_level_view_count,-- Views whose lens needs only the category.
  calc_procedures_procedure_type_rank(t.procedure_id) AS procedure_type_rank,   -- Taxonomy rank of the procedure's type.
  calc_procedures_procedure_type_definition(t.procedure_id) AS procedure_type_definition,-- Definition of the procedure's type.
  calc_procedures_has_step_and_category_resolutions(t.procedure_id) AS has_step_and_category_resolutions,-- TRUE when the procedure can be shown both at step level and at its process-type category.
  calc_procedures_is_missing_demanded_resolution(t.procedure_id) AS is_missing_demanded_resolution,-- TRUE when a lens needs step-level detail the procedure does not have, or a category the procedure is not classified into.
  calc_procedures_is_inconsistently_categorized(t.procedure_id) AS is_inconsistently_categorized,-- TRUE when a procedure has no type, is filed at a domain or group rank instead of a process type, or its type has no definition.
  calc_procedures_strategic_alignment_count(t.procedure_id) AS strategic_alignment_count,-- Strategic alignments stated for the procedure.
  calc_procedures_has_no_stated_reason_for_existing(t.procedure_id) AS has_no_stated_reason_for_existing,-- TRUE when nothing ties the procedure to a mission, rationale or value.
  calc_procedures_outcome_measure_count(t.procedure_id) AS outcome_measure_count,-- Outcome measures.
  calc_procedures_unlinked_measure_count(t.procedure_id) AS unlinked_measure_count,-- Outcome measures tied to no business outcome.
  calc_procedures_measures_performance_without_business_link(t.procedure_id) AS measures_performance_without_business_link,-- TRUE when the procedure is measured but no measure connects to a business outcome.
  calc_procedures_hindered_by_count(t.procedure_id) AS hindered_by_count,       -- Operations that work against this one.
  calc_procedures_is_hindered_by_another_operation(t.procedure_id) AS is_hindered_by_another_operation,-- TRUE when another operation works against this one.
  calc_procedures_type_distinguishing_facet(t.procedure_id) AS type_distinguishing_facet,-- Facet the procedure's type claims to distinguish by.
  calc_procedures_type_distinguishing_value(t.procedure_id) AS type_distinguishing_value,-- Value the procedure's type claims its members share.
  calc_procedures_matching_distinction_count(t.procedure_id) AS matching_distinction_count,-- Facet assignments giving the procedure the value its type claims.
  calc_procedures_lacks_type_distinction(t.procedure_id) AS lacks_type_distinction,-- TRUE when the procedure does not have the distinguishing value its grouping claims.
  calc_procedures_lacks_distinction_type_key(t.procedure_id) AS lacks_distinction_type_key,-- Type key when the procedure lacks its type's distinction.
  calc_procedures_managed_vocabulary_count(t.procedure_id) AS managed_vocabulary_count,-- Controlled vocabularies governing the procedure that have a governing role and an establishment date.
  calc_procedures_lacks_managed_controlled_vocabulary(t.procedure_id) AS lacks_managed_controlled_vocabulary,-- TRUE when a procedure with steps has no controlled vocabulary whose metadata is managed.
  calc_procedures_compliance_review_step_count(t.procedure_id) AS compliance_review_step_count,-- Steps performed by a role carrying the compliance-review capability.
  calc_procedures_involves_compliance_review_role(t.procedure_id) AS involves_compliance_review_role,-- TRUE when a compliance-review role takes part in the procedure.
  calc_procedures_is_regulated_but_unformalized(t.procedure_id) AS is_regulated_but_unformalized,-- TRUE for a procedure a regulation requires that exists only as a title and documents.
  calc_procedures_agent_intended_count(t.procedure_id) AS agent_intended_count, -- Agentic AI initiatives aimed at the procedure.
  calc_procedures_is_tacit_only_agent_target(t.procedure_id) AS is_tacit_only_agent_target,-- TRUE for a procedure intended for agent execution that exists only as tacit knowledge.
  calc_procedures_repository_entry_count(t.procedure_id) AS repository_entry_count,-- Repository entries documenting the procedure.
  calc_procedures_stale_entry_count(t.procedure_id) AS stale_entry_count,       -- Repository entries past their review interval.
  calc_procedures_departed_only_know_how_count(t.procedure_id) AS departed_only_know_how_count,-- Know-how of the procedure held only by people who left.
  calc_procedures_has_decayed_transfer_channel(t.procedure_id) AS has_decayed_transfer_channel,-- TRUE when the procedure's documentation has gone stale or some of its know-how is held only by people who left.
  calc_procedures_execution_feedback_entry_count(t.procedure_id) AS execution_feedback_entry_count,-- Repository entries that wrote back what an execution taught.
  calc_procedures_is_executed_without_feedback_loop(t.procedure_id) AS is_executed_without_feedback_loop,-- TRUE when the procedure is executed and nothing from execution was written back into its documentation.
  calc_procedures_machine_authored_entry_count(t.procedure_id) AS machine_authored_entry_count,-- Repository entries written by AI agents or pipelines.
  calc_procedures_practitioner_relationship_count(t.procedure_id) AS practitioner_relationship_count,-- Collection relationships with practitioners on the procedure.
  calc_procedures_is_captured_by_automation_alone(t.procedure_id) AS is_captured_by_automation_alone,-- TRUE when the procedure's knowledge was captured by machines and no practitioner was engaged.
  calc_procedures_unengaged_stakeholder_count(t.procedure_id) AS unengaged_stakeholder_count,-- Stakeholder departments never engaged in shaping the procedure's knowledge.
  calc_procedures_has_unengaged_stakeholder(t.procedure_id) AS has_unengaged_stakeholder,-- TRUE when a stakeholder department of the procedure has not been engaged.
  calc_procedures_recent_starter_count(t.procedure_id) AS recent_starter_count, -- New starters on the procedure within 180 days.
  calc_procedures_untransferred_veteran_know_how_count(t.procedure_id) AS untransferred_veteran_know_how_count,-- Veteran know-how never transferred or captured.
  calc_procedures_departing_veteran_know_how_count(t.procedure_id) AS departing_veteran_know_how_count,-- Untransferred veteran know-how whose holder leaves soon.
  calc_procedures_has_transfer_shortfall_exposure(t.procedure_id) AS has_transfer_shortfall_exposure,-- TRUE when a wave of three or more new starters meets untransferred veteran know-how, or a departing veteran leaves know-how untransferred.
  calc_procedures_proficient_with_capture_count(t.procedure_id) AS proficient_with_capture_count,-- Proficient starters who learned from captured knowledge.
  calc_procedures_proficient_without_capture_count(t.procedure_id) AS proficient_without_capture_count,-- Proficient starters who learned without captured knowledge.
  calc_procedures_days_with_capture_total(t.procedure_id) AS days_with_capture_total,-- Total days to proficiency with captured knowledge.
  calc_procedures_days_without_capture_total(t.procedure_id) AS days_without_capture_total,-- Total days to proficiency without captured knowledge.
  calc_procedures_avg_days_to_proficiency_with_capture(t.procedure_id) AS avg_days_to_proficiency_with_capture,-- Average days to proficiency with captured knowledge.
  calc_procedures_avg_days_to_proficiency_without_capture(t.procedure_id) AS avg_days_to_proficiency_without_capture,-- Average days to proficiency without captured knowledge.
  calc_procedures_formalization_does_not_ease_onboarding(t.procedure_id) AS formalization_does_not_ease_onboarding,-- TRUE when starters who learned from captured knowledge took at least as long as those who did not.
  calc_procedures_collected_material_count(t.procedure_id) AS collected_material_count,-- Materials collected about the procedure.
  calc_procedures_in_work_capture_count(t.procedure_id) AS in_work_capture_count,-- Of those, materials captured in the course of executing the work.
  calc_procedures_is_capture_separate_from_work(t.procedure_id) AS is_capture_separate_from_work,-- TRUE when knowledge about the procedure is collected, but never in the course of the work.
  calc_procedures_expert_acquisition_hours(t.procedure_id) AS expert_acquisition_hours,-- Expert hours spent capturing knowledge about the procedure.
  calc_procedures_compliance_document_count(t.procedure_id) AS compliance_document_count-- Documents kept for compliance with this procedure, separate from how the work is done.
FROM procedures t;

-- ----------------------------------------------------------------------------
-- vw_procedure_versions: Versioned procedure specifications. Maps to pko:Procedure plus DCAT version relations and PKO versionNumber/newVersionMotivation/changelogDescription.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_versions CASCADE;
CREATE VIEW vw_procedure_versions WITH (security_invoker = ON) AS
SELECT
  t.procedure_version_id,                                                       -- Stored logical identifier for one ProcedureVersions row.
  calc_procedure_versions_name(t.procedure_version_id) AS name,                 -- Human-readable calculated display alias for the ProcedureVersions row.
  t.procedure,                                                                  -- Abstract procedure of which this is a version.
  t.version_number,                                                             -- Version number; maps to pko:versionNumber.
  t.title,                                                                      -- Version-specific title.
  t.status,                                                                     -- PKO procedure status individual: Draft, Validation, Approval, Approved, Deprecated, or Archived.
  t.issued_at,                                                                  -- Issue timestamp; maps to dcterms:issued.
  t.modified_at,                                                                -- Last semantic modification; maps to dcterms:modified.
  t.created_by_agent,                                                           -- Agent that created the version; maps to dcterms:creator.
  t.modified_by_agent,                                                          -- Agent that last modified the version; maps to pko:wasModifiedBy.
  t.new_version_motivation,                                                     -- Reason for the new version; maps to pko:newVersionMotivation.
  t.changelog_description,                                                      -- Semantic change description; maps to pko:changelogDescription.
  t.is_current,                                                                 -- TRUE when this is the current version.
  calc_procedure_versions_count_of_steps(t.procedure_version_id) AS count_of_steps,-- Number of steps in this version.
  calc_procedure_versions_count_of_open_knowledge_gaps(t.procedure_version_id) AS count_of_open_knowledge_gaps,-- Open knowledge gaps for this version.
  calc_procedure_versions_is_ready_for_execution(t.procedure_version_id) AS is_ready_for_execution,-- TRUE when approved, populated, and free of blocking knowledge gaps.
  calc_procedure_versions_specified_step_count(t.procedure_version_id) AS specified_step_count,-- How many steps the specification defines for this version.
  calc_procedure_versions_overdue_review_count(t.procedure_version_id) AS overdue_review_count,-- How many reviews of this procedure version are past due.
  calc_procedure_versions_open_change_request_count(t.procedure_version_id) AS open_change_request_count,-- How many change requests are open against this version.
  calc_procedure_versions_open_high_severity_gap_count(t.procedure_version_id) AS open_high_severity_gap_count,-- How many high-severity knowledge gaps are open against this version.
  calc_procedure_versions_is_fit_to_execute(t.procedure_version_id) AS is_fit_to_execute,-- TRUE when this version is approved, current on review, and carries no open change request or high-severity gap.
  calc_procedure_versions_steward_review_cadence_days(t.procedure_version_id) AS steward_review_cadence_days,-- The review cadence promised by this version's stewardship assignment, in days. Summed because a version has at most one active steward; this is the hop that lets ReviewEvents resolve the promise via a primary-key match.
  calc_procedure_versions_count_of_stewardship_assignments(t.procedure_version_id) AS count_of_stewardship_assignments,-- How many stewardship assignments of any vintage point at this version.
  calc_procedure_versions_has_any_steward(t.procedure_version_id) AS has_any_steward,-- TRUE if any stewardship assignment has ever named this version.
  calc_procedure_versions_is_live(t.procedure_version_id) AS is_live,           -- TRUE when this version is in a state where somebody could execute it.
  calc_procedure_versions_is_unstewarded(t.procedure_version_id) AS is_unstewarded,-- TRUE when no stewardship assignment names this version.
  calc_procedure_versions_is_live_and_unstewarded(t.procedure_version_id) AS is_live_and_unstewarded,-- TRUE when an executable version has nobody accountable for keeping it healthy.
  calc_procedure_versions_count_of_open_blocking_gaps(t.procedure_version_id) AS count_of_open_blocking_gaps,-- How many open blocking gaps stand against this version.
  calc_procedure_versions_has_open_blocking_gap(t.procedure_version_id) AS has_open_blocking_gap,-- TRUE when at least one open blocking gap stands against this version.
  calc_procedure_versions_is_live_with_blocking_gap(t.procedure_version_id) AS is_live_with_blocking_gap,-- TRUE when an executable version carries an unresolved blocking knowledge gap.
  calc_procedure_versions_should_not_be_executable(t.procedure_version_id) AS should_not_be_executable,-- TRUE when the model says this version is ready to execute while a blocking gap is open against it.
  calc_procedure_versions_count_of_unapproved_reliance_fragments(t.procedure_version_id) AS count_of_unapproved_reliance_fragments,-- How many unapproved claims this version is relying on.
  calc_procedure_versions_runs_on_unapproved_knowledge(t.procedure_version_id) AS runs_on_unapproved_knowledge,-- TRUE when this version depends on at least one claim the knowledge authority has not approved.
  calc_procedure_versions_count_of_overdue_gaps(t.procedure_version_id) AS count_of_overdue_gaps,-- How many acknowledged unknowns against this version have outlived their tolerance.
  calc_procedure_versions_count_of_change_requests(t.procedure_version_id) AS count_of_change_requests,-- How many change requests have ever been raised against this version.
  calc_procedure_versions_count_of_review_events(t.procedure_version_id) AS count_of_review_events,-- How many review events have ever been recorded against this version.
  calc_procedure_versions_has_governance_record(t.procedure_version_id) AS has_governance_record,-- TRUE when at least one change request or review event exists for this version.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_procedure_versions_as_of_instant(t.procedure_version_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_procedure_versions_days_since_modified(t.procedure_version_id) AS days_since_modified,-- Days since this version's content was last changed.
  calc_procedure_versions_days_since_last_review(t.procedure_version_id) AS days_since_last_review,-- Days since the most recent review of this version.
  calc_procedure_versions_was_modified_since_last_review(t.procedure_version_id) AS was_modified_since_last_review,-- TRUE when the version was edited more recently than it was reviewed.
  calc_procedure_versions_modifier_is_authority(t.procedure_version_id) AS modifier_is_authority,-- The kind of agent that last modified this version.
  calc_procedure_versions_has_unwitnessed_change(t.procedure_version_id) AS has_unwitnessed_change,-- TRUE when a live version's current content postdates every review it has had.
  calc_procedure_versions_count_of_stale_fragments(t.procedure_version_id) AS count_of_stale_fragments,-- How many supporting claims have outlived this version's review cadence.
  calc_procedure_versions_knowledge_is_staler_than_cadence(t.procedure_version_id) AS knowledge_is_staler_than_cadence,-- TRUE when this version rests on at least one claim older than its own review cadence.
  calc_procedure_versions_compound_fragile_fragment_count(t.procedure_version_id) AS compound_fragile_fragment_count,-- How many compound-fragile knowledge fragments this version rests on.
  calc_procedure_versions_rests_on_compound_fragile_knowledge(t.procedure_version_id) AS rests_on_compound_fragile_knowledge,-- A live procedure version resting on at least one knowledge fragment that carries three or more decay signals.
  calc_procedure_versions_concentrated_witness_session_count(t.procedure_version_id) AS concentrated_witness_session_count,-- How many concentrated single-witness sessions underwrite this version's knowledge base.
  calc_procedure_versions_knowledge_base_is_concentrated(t.procedure_version_id) AS knowledge_base_is_concentrated,-- A live version where at least one single-witness session alone underwrites three or more of its live claims.
  calc_procedure_versions_machine_consumed_unapproved_count(t.procedure_version_id) AS machine_consumed_unapproved_count,-- How many unapproved claims this version feeds directly to software-assigned steps.
  calc_procedure_versions_feeds_unapproved_knowledge_to_machines(t.procedure_version_id) AS feeds_unapproved_knowledge_to_machines,-- A live version that hands unapproved knowledge to a step no human is positioned to review.
  calc_procedure_versions_genuinely_overdue_fragment_count(t.procedure_version_id) AS genuinely_overdue_fragment_count,-- How many of this version's claims are overdue by actual review record rather than by inference.
  calc_procedure_versions_awaited_decision_count(t.procedure_version_id) AS awaited_decision_count,-- How many decisions are pending against this live version.
  calc_procedure_versions_scoped_open_blocking_gap_count(t.procedure_version_id) AS scoped_open_blocking_gap_count,-- How many open blocking gaps belong to THIS version, correctly scoped.
  calc_procedure_versions_is_blocked_on_pending_decision(t.procedure_version_id) AS is_blocked_on_pending_decision,-- A live version carrying both an undecided change request and an open blocking gap — the gap cannot close until the decision lands.
  calc_procedure_versions_unexercised_human_gate_count(t.procedure_version_id) AS unexercised_human_gate_count,-- How many of this version's human-only gates have never been approached by software.
  calc_procedure_versions_ai_boundary_is_unevidenced(t.procedure_version_id) AS ai_boundary_is_unevidenced,-- A live version whose human-only gates rest on assertion rather than on any observed attempt by software.
  calc_procedure_versions_load_bearing_unapproved_count(t.procedure_version_id) AS load_bearing_unapproved_count,-- How many high-blast-radius unapproved claims this version rests on.
  calc_procedure_versions_unlanded_decision_count(t.procedure_version_id) AS unlanded_decision_count,-- How many decided-but-unimplemented change requests hold this version's fitness down.
  calc_procedure_versions_unrehearsed_control_entry_count(t.procedure_version_id) AS unrehearsed_control_entry_count,-- How many unrehearsed control entries exist in this procedure version.
  calc_procedure_versions_has_unrehearsed_control_entry(t.procedure_version_id) AS has_unrehearsed_control_entry,-- Whether this live version has at least one blocking control that is only reachable by a path nobody has ever walked.
  calc_procedure_versions_is_live_with_unrehearsed_control(t.procedure_version_id) AS is_live_with_unrehearsed_control,-- A version that is live for execution while carrying at least one never-rehearsed blocking control entry.
  calc_procedure_versions_cadence_breach_count(t.procedure_version_id) AS cadence_breach_count,-- How many review events on this version are past their promised cadence.
  calc_procedure_versions_is_in_cadence_breach(t.procedure_version_id) AS is_in_cadence_breach,-- Whether this version currently has at least one review event past the cadence its steward promised.
  calc_procedure_versions_has_decision_in_flight(t.procedure_version_id) AS has_decision_in_flight,-- Whether this version has at least one change request that is still open.
  calc_procedure_versions_is_unremediated_cadence_breach(t.procedure_version_id) AS is_unremediated_cadence_breach,-- A cadence breach with no open change request against the version — a broken promise with no response in motion.
  calc_procedure_versions_is_managed_cadence_breach(t.procedure_version_id) AS is_managed_cadence_breach,-- A cadence breach where a change request is at least open against the version.
  calc_procedure_versions_governance_is_silent(t.procedure_version_id) AS governance_is_silent,-- A live version with neither a change request nor a review event ever recorded against it.
  calc_procedure_versions_valid_fragment_count(t.procedure_version_id) AS valid_fragment_count,-- How many currently-valid knowledge fragments are attached to this version.
  calc_procedure_versions_still_owns_valid_knowledge(t.procedure_version_id) AS still_owns_valid_knowledge,-- Whether this version still holds at least one knowledge fragment that is currently valid.
  calc_procedure_versions_incoming_supersession_count(t.procedure_version_id) AS incoming_supersession_count,-- How many other versions declare that they supersede this one.
  calc_procedure_versions_is_still_referenced(t.procedure_version_id) AS is_still_referenced,-- Whether any other version points at this one through a supersession link.
  calc_procedure_versions_is_load_bearing_orphan(t.procedure_version_id) AS is_load_bearing_orphan,-- An unstewarded version that is still referenced by a supersession link or still owns currently-valid knowledge — nobody is accountable for it and something still depends on it.
  calc_procedure_versions_is_cleanly_retired(t.procedure_version_id) AS is_cleanly_retired,-- An unstewarded version that nothing depends on — a genuine, safe retirement.
  calc_procedure_versions_stalled_implementation_count(t.procedure_version_id) AS stalled_implementation_count,-- How many approved-but-unimplemented change requests are stalled against this version.
  calc_procedure_versions_is_held_unfit_by_landed_decisions(t.procedure_version_id) AS is_held_unfit_by_landed_decisions,-- A version reading unfit to execute specifically because approved changes have not been marked implemented.
  calc_procedure_versions_undeclared_control_kind_count(t.procedure_version_id) AS undeclared_control_kind_count,-- How many steps in this version have not declared a control kind.
  calc_procedure_versions_control_taxonomy_is_incomplete(t.procedure_version_id) AS control_taxonomy_is_incomplete,-- Whether this version contains any step whose control kind is unstated — meaning role-based and id-based control predicates cannot be trusted to cover it.
  calc_procedure_versions_has_approved_change_request(t.procedure_version_id) AS has_approved_change_request,-- TRUE when at least one change request against this version has been approved.
  calc_procedure_versions_approved_change_request_count(t.procedure_version_id) AS approved_change_request_count,-- How many change requests against this version have been approved.
  calc_procedure_versions_unwatched_unowned_control_count(t.procedure_version_id) AS unwatched_unowned_control_count,-- How many blocking controls in the model are neither computed nor owned.
  calc_procedure_versions_mining_run_count(t.procedure_version_id) AS mining_run_count,-- How many process-mining conformance runs exist for this procedure version.
  calc_procedure_versions_drifted_mining_run_count(t.procedure_version_id) AS drifted_mining_run_count,-- How many mining runs found major, real drift while this version was live.
  calc_procedure_versions_has_unresolved_mining_drift(t.procedure_version_id) AS has_unresolved_mining_drift,-- TRUE when mined operational evidence contradicts this live version's documented path.
  calc_procedure_versions_entry_step_id(t.procedure_version_id) AS entry_step_id,-- The step this procedure version starts at: the one step no transition leads into.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  calc_procedure_versions_execution_count(t.procedure_version_id) AS execution_count,-- Recorded executions of this procedure version.
  t.expected_duration_value,                                                    -- Expected duration, numeric part (time:numericDuration).
  t.expected_duration_unit,                                                     -- Expected duration unit (time:unitType).
  calc_procedure_versions_status_is_pko(t.procedure_version_id) AS status_is_pko,-- Whether the version's status is a PKO 2.0.0 procedure status.
  calc_procedure_versions_uses_non_pko_status(t.procedure_version_id) AS uses_non_pko_status,-- TRUE when the version holds a status PKO does not define.
  calc_procedure_versions_exception_count(t.procedure_version_id) AS exception_count,-- Documented exceptions.
  calc_procedure_versions_fallback_transition_count(t.procedure_version_id) AS fallback_transition_count,-- Fallback transitions.
  calc_procedure_versions_alternative_transition_count(t.procedure_version_id) AS alternative_transition_count,-- Alternative transitions.
  calc_procedure_versions_has_no_exception_handling(t.procedure_version_id) AS has_no_exception_handling,-- TRUE when a version with steps captures only the normative path: no exception, fallback or alternative.
  calc_procedure_versions_latest_source_document_modified_at(t.procedure_version_id) AS latest_source_document_modified_at,-- Most recent modification of any document the version references.
  calc_procedure_versions_days_document_trails_version(t.procedure_version_id) AS days_document_trails_version,-- Days by which the referenced documents trail the version's own last change.
  calc_procedure_versions_document_lags_practice(t.procedure_version_id) AS document_lags_practice,-- TRUE when the documents a version rests on have not changed for more than sixty days of changes to the version itself.
  calc_procedure_versions_human_step_count(t.procedure_version_id) AS human_step_count,-- Steps whose role is held by a person.
  calc_procedure_versions_non_human_step_count(t.procedure_version_id) AS non_human_step_count,-- Steps whose role is held by software or AI.
  calc_procedure_versions_mixes_human_and_software_steps(t.procedure_version_id) AS mixes_human_and_software_steps,-- TRUE when one version mixes human steps with software or AI steps.
  calc_procedure_versions_day_run_count(t.procedure_version_id) AS day_run_count,-- Executions on the day shift.
  calc_procedure_versions_night_run_count(t.procedure_version_id) AS night_run_count,-- Executions on the night shift.
  calc_procedure_versions_day_deviating_run_count(t.procedure_version_id) AS day_deviating_run_count,-- Day-shift executions with a step deviation.
  calc_procedure_versions_night_deviating_run_count(t.procedure_version_id) AS night_deviating_run_count,-- Night-shift executions with a step deviation.
  calc_procedure_versions_is_inconsistent_across_shifts(t.procedure_version_id) AS is_inconsistent_across_shifts,-- TRUE when one shift runs the version cleanly and the other deviates.
  calc_procedure_versions_overlaps_relation_count(t.procedure_version_id) AS overlaps_relation_count,-- Overlaps relations among the version's steps.
  calc_procedure_versions_enables_relation_count(t.procedure_version_id) AS enables_relation_count,-- Enables relations among the version's steps.
  calc_procedure_versions_prevents_relation_count(t.procedure_version_id) AS prevents_relation_count,-- Prevents relations among the version's steps.
  calc_procedure_versions_steps_without_ontology_type_count(t.procedure_version_id) AS steps_without_ontology_type_count,-- Steps carried over from a notation with no ontology type.
  calc_procedure_versions_rests_on_notation_only(t.procedure_version_id) AS rests_on_notation_only,-- TRUE when some steps of the version carry no ontology type, so they mean nothing outside the diagram they came from.
  calc_procedure_versions_is_current_without_motivation(t.procedure_version_id) AS is_current_without_motivation,-- TRUE for a current version that never recorded why it was created.
  calc_procedure_versions_conditionless_step_count(t.procedure_version_id) AS conditionless_step_count,-- Steps with no precondition.
  calc_procedure_versions_is_under_specified_for_execution(t.procedure_version_id) AS is_under_specified_for_execution,-- TRUE when a version cannot tell an executor what must hold, or what to do when things go wrong: no steps, no step with a precondition, or no exception handling.
  calc_procedure_versions_coarse_top_level_step_count(t.procedure_version_id) AS coarse_top_level_step_count,-- Top-level steps written at Activity detail.
  calc_procedure_versions_fine_top_level_step_count(t.procedure_version_id) AS fine_top_level_step_count,-- Top-level steps written at Action detail.
  calc_procedure_versions_mixes_granularity_at_one_level(t.procedure_version_id) AS mixes_granularity_at_one_level,-- TRUE when one level of a version mixes whole activities with single actions, so detail is weighted unevenly.
  calc_procedure_versions_procedure_type_of_version(t.procedure_version_id) AS procedure_type_of_version,-- Procedure type.
  calc_procedure_versions_created_by_agent_kind(t.procedure_version_id) AS created_by_agent_kind,-- Kind of agent that created the version.
  calc_procedure_versions_elicitation_session_count(t.procedure_version_id) AS elicitation_session_count,-- Elicitation sessions behind the version.
  calc_procedure_versions_expert_capture_count(t.procedure_version_id) AS expert_capture_count,-- Capture-form submissions authored by domain experts.
  calc_procedure_versions_elicitation_evidence_count(t.procedure_version_id) AS elicitation_evidence_count,-- Sessions plus expert captures: evidence tacit knowledge was elicited.
  calc_procedure_versions_indexed_segment_count(t.procedure_version_id) AS indexed_segment_count,-- Retrieval segments served from the version: how rich it is for AI.
  calc_procedure_versions_search_count(t.procedure_version_id) AS search_count, -- Searches made while working with the version.
  calc_procedure_versions_successful_search_count(t.procedure_version_id) AS successful_search_count,-- Searches that found something useful.
  calc_procedure_versions_search_success_percent(t.procedure_version_id) AS search_success_percent,-- How findable the version is.
  calc_procedure_versions_open_question_annotation_count(t.procedure_version_id) AS open_question_annotation_count,-- Open clarifying questions practitioners attached: how unclear it is.
  calc_procedure_versions_is_inadequate_for_use(t.procedure_version_id) AS is_inadequate_for_use,-- TRUE when a version is too thin to guide AI, hard to find, or unclear to collaborators.
  calc_procedure_versions_served_assertion_count(t.procedure_version_id) AS served_assertion_count,-- Graph assertions served from the version.
  calc_procedure_versions_lacks_machine_interpretable_encoding(t.procedure_version_id) AS lacks_machine_interpretable_encoding,-- TRUE for a current version with no retrieval segments for search or no graph assertions for reasoning and AI.
  calc_procedure_versions_structured_query_count(t.procedure_version_id) AS structured_query_count,-- Structured queries over the version.
  calc_procedure_versions_profile_validated_submission_count(t.procedure_version_id) AS profile_validated_submission_count,-- Submissions of the version that validated against the PKO profile.
  calc_procedure_versions_reasoned_assertion_count(t.procedure_version_id) AS reasoned_assertion_count,-- Served assertions of the version in a snapshot a reasoner found consistent.
  calc_procedure_versions_is_not_query_validate_reason_ready(t.procedure_version_id) AS is_not_query_validate_reason_ready,-- TRUE for a current version that no structured query reads, no profile validation passed, or no reasoner has checked.
  calc_procedure_versions_published_projection_count(t.procedure_version_id) AS published_projection_count,-- Published documents and diagrams of the version.
  calc_procedure_versions_consumer_sync_count(t.procedure_version_id) AS consumer_sync_count,-- Consuming systems holding the version.
  calc_procedure_versions_is_unreachable_knowledge(t.procedure_version_id) AS is_unreachable_knowledge,-- TRUE for a current version nobody can reach: no published projection and no consuming system.
  calc_procedure_versions_human_sync_count(t.procedure_version_id) AS human_sync_count,-- Systems read by people that hold the version.
  calc_procedure_versions_machine_sync_count(t.procedure_version_id) AS machine_sync_count,-- Systems read by AI that hold the version.
  calc_procedure_versions_human_channel_count(t.procedure_version_id) AS human_channel_count,-- Ways people receive the version.
  calc_procedure_versions_machine_channel_count(t.procedure_version_id) AS machine_channel_count,-- Ways machines receive the version.
  calc_procedure_versions_serves_only_humans_or_only_machines(t.procedure_version_id) AS serves_only_humans_or_only_machines,-- TRUE for a current version conveyed to people or to machines, but not both.
  calc_procedure_versions_fresh_mining_run_count(t.procedure_version_id) AS fresh_mining_run_count,-- Process-mining conformance runs within the freshness window.
  calc_procedure_versions_lacks_continuous_drift_detection(t.procedure_version_id) AS lacks_continuous_drift_detection,-- TRUE for a current, executed version with no recent automated check of enacted against documented process.
  calc_procedure_versions_outcome_measurement_count(t.procedure_version_id) AS outcome_measurement_count,-- Operational outcome measurements linked to the version.
  calc_procedure_versions_is_disconnected_from_outcomes(t.procedure_version_id) AS is_disconnected_from_outcomes,-- TRUE for a current, executed version no operational outcome is linked to.
  calc_procedure_versions_ai_contribution_count(t.procedure_version_id) AS ai_contribution_count,-- AI insights proposed about the version.
  calc_procedure_versions_ai_consumption_count(t.procedure_version_id) AS ai_consumption_count,-- Assertions and segments of the version served to AI.
  calc_procedure_versions_uses_ai_in_one_direction_only(t.procedure_version_id) AS uses_ai_in_one_direction_only,-- TRUE when AI only consumes the version and never contributes to it, or only contributes and never consumes it.
  calc_procedure_versions_is_unmodified_for_twelve_months(t.procedure_version_id) AS is_unmodified_for_twelve_months,-- TRUE for a current workflow not modified in more than twelve months.
  calc_procedure_versions_design_decision_count(t.procedure_version_id) AS design_decision_count,-- Design decisions recorded with the version.
  calc_procedure_versions_is_live_without_recorded_decisions(t.procedure_version_id) AS is_live_without_recorded_decisions,-- TRUE for a live version with no design decision recorded alongside it.
  calc_procedure_versions_ai_artifact_consuming_input_count(t.procedure_version_id) AS ai_artifact_consuming_input_count,-- Inputs of the version's steps fed by an AI agent's artifact.
  calc_procedure_versions_contains_steps_affected_by_ai_agent_cha(t.procedure_version_id) AS contains_steps_affected_by_ai_agent_change,-- TRUE when the workflow contains a step that consumes an AI agent's artifact, so changing that agent affects it.
  calc_procedure_versions_interview_session_count(t.procedure_version_id) AS interview_session_count,-- Interview sessions for the version.
  calc_procedure_versions_observation_session_count(t.procedure_version_id) AS observation_session_count,-- Observation sessions for the version.
  calc_procedure_versions_workshop_session_count(t.procedure_version_id) AS workshop_session_count,-- Workshop sessions for the version.
  calc_procedure_versions_protocol_session_count(t.procedure_version_id) AS protocol_session_count,-- Think-aloud, retrospective, laddering and grid sessions for the version.
  calc_procedure_versions_incident_session_count(t.procedure_version_id) AS incident_session_count,-- Critical incident sessions for the version.
  calc_procedure_versions_reconciled_divergence_count(t.procedure_version_id) AS reconciled_divergence_count,-- Workflow disagreements settled for the version.
  calc_procedure_versions_complementary_method_count(t.procedure_version_id) AS complementary_method_count,-- Distinct families of elicitation used for the version.
  calc_procedure_versions_relies_on_single_method(t.procedure_version_id) AS relies_on_single_method,-- TRUE when the version's knowledge was elicited with one family of method only.
  calc_procedure_versions_misses_a_required_elicitation_mode(t.procedure_version_id) AS misses_a_required_elicitation_mode,-- TRUE for an elicited version lacking a workshop, a structured interview, observation, or a session that settled a disagreement.
  calc_procedure_versions_critical_incident_count(t.procedure_version_id) AS critical_incident_count,-- Critical incidents collected for the version.
  calc_procedure_versions_judgment_unprobed_by_incidents(t.procedure_version_id) AS judgment_unprobed_by_incidents,-- TRUE when a version relies on tacit or situated judgment yet no critical incident was collected to surface it.
  calc_procedure_versions_sme_approval_count(t.procedure_version_id) AS sme_approval_count,-- Approvals of the representation by subject matter experts it affects.
  calc_procedure_versions_sme_ai_evaluation_count(t.procedure_version_id) AS sme_ai_evaluation_count,-- Evaluations of AI output on this version by affected subject matter experts.
  calc_procedure_versions_is_approved_without_sme_signoff(t.procedure_version_id) AS is_approved_without_sme_signoff,-- TRUE for an approved version no affected subject matter expert approved the representation of.
  calc_procedure_versions_experts_evaluate_ai_not_representation(t.procedure_version_id) AS experts_evaluate_ai_not_representation,-- TRUE when experts were recruited to evaluate AI output on a version but none to approve the representation it rests on.
  calc_procedure_versions_ke_session_count(t.procedure_version_id) AS ke_session_count,-- Sessions the knowledge engineer ran for the version.
  calc_procedure_versions_ke_field_session_count(t.procedure_version_id) AS ke_field_session_count,-- Sessions the knowledge engineer ran where the work is done.
  calc_procedure_versions_is_studied_only_from_the_desk(t.procedure_version_id) AS is_studied_only_from_the_desk,-- TRUE when the knowledge engineer elicited the version but never went where the work happens.
  calc_procedure_versions_judgment_held_outside_sop_count(t.procedure_version_id) AS judgment_held_outside_sop_count,-- Unformalized knowledge of the version its SOP says nothing about.
  calc_procedure_versions_tacit_holding_count(t.procedure_version_id) AS tacit_holding_count,-- Holdings of the version in tacit form.
  calc_procedure_versions_explicit_holding_count(t.procedure_version_id) AS explicit_holding_count,-- Holdings of the version in explicit form.
  calc_procedure_versions_tacit_share_exceeds_explicit(t.procedure_version_id) AS tacit_share_exceeds_explicit,-- TRUE when more of the version's knowledge is held tacitly than in explicit carriers.
  calc_procedure_versions_hands_held_count(t.procedure_version_id) AS hands_held_count,-- Unformalized knowledge held only in operators' memory.
  calc_procedure_versions_negotiated_practice_count(t.procedure_version_id) AS negotiated_practice_count,-- Unformalized knowledge held as unspoken crew agreements.
  calc_procedure_versions_lives_in_hands_silence_and_negotiation(t.procedure_version_id) AS lives_in_hands_silence_and_negotiation,-- TRUE when the version's knowledge lives at once in experienced hands, in what its SOP leaves unsaid, and in unspoken crew agreements.
  calc_procedure_versions_process_model_trace_count(t.procedure_version_id) AS process_model_trace_count,-- Origin traces of the version as a process model.
  calc_procedure_versions_is_live_model_untraced(t.procedure_version_id) AS is_live_model_untraced,-- TRUE when an executable process model traces to no collection activity.
  calc_procedure_versions_trailing_practice_trace_count(t.procedure_version_id) AS trailing_practice_trace_count,-- Contradictions showing a document of this version trailing practice.
  calc_procedure_versions_is_documented_behind_practice(t.procedure_version_id) AS is_documented_behind_practice,-- TRUE when the version's documentation trails how the work is performed.
  t.standardization_driver,                                                     -- Why the version was standardized: Compliance or Practice.
  calc_procedure_versions_tacit_fragment_count(t.procedure_version_id) AS tacit_fragment_count,-- Tacit knowledge fragments captured for the version.
  calc_procedure_versions_is_standardized_without_tacit_capture(t.procedure_version_id) AS is_standardized_without_tacit_capture,-- TRUE when a version standardized for compliance has no tacit knowledge captured behind it.
  calc_procedure_versions_tacit_form_fragment_count(t.procedure_version_id) AS tacit_form_fragment_count,-- Tacit fragments attached to the version.
  calc_procedure_versions_situated_judgment_fragment_count(t.procedure_version_id) AS situated_judgment_fragment_count,-- Situated-judgment fragments attached to the version.
  calc_procedure_versions_tacit_judgment_fragment_count(t.procedure_version_id) AS tacit_judgment_fragment_count,-- Tacit or situated-judgment fragments attached to the version.
  calc_procedure_versions_first_step(t.procedure_version_id) AS first_step,     -- Declared first step (pko:hasFirstStep), read from the step that declares itself first.
  calc_procedure_versions_fallback_step(t.procedure_version_id) AS fallback_step,-- Declared fallback step (pko:hasFallbackStep), read from the step that declares itself the fallback.
  calc_procedure_versions_first_step_disagrees_with_graph(t.procedure_version_id) AS first_step_disagrees_with_graph,-- TRUE when the transition graph has an entry step and the declared first step is a different one. A graph whose first step also receives a loop-back has no entry step, and is not a disagreement.
  calc_procedure_versions_declared_first_step_count(t.procedure_version_id) AS declared_first_step_count,-- Steps of the version that declare themselves its first step.
  calc_procedure_versions_graph_entry_step_count(t.procedure_version_id) AS graph_entry_step_count,-- Steps of the version with no incoming transition.
  calc_procedure_versions_owner_organization(t.procedure_version_id) AS owner_organization-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
FROM procedure_versions t;

-- ----------------------------------------------------------------------------
-- vw_procedure_version_links: Directed links between versioned procedures. Maps to dcat:previousVersion/dcat:hasVersion and pko:nextVersion.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_version_links CASCADE;
CREATE VIEW vw_procedure_version_links WITH (security_invoker = ON) AS
SELECT
  t.procedure_version_link_id,                                                  -- Stored logical identifier for one ProcedureVersionLinks row.
  calc_procedure_version_links_name(t.procedure_version_link_id) AS name,       -- Human-readable calculated display alias for the ProcedureVersionLinks row.
  t.previous_procedure_version,                                                 -- Earlier version.
  t.next_procedure_version,                                                     -- Later version.
  t.relation_iri,                                                               -- Exact version relation IRI.
  t.change_summary,                                                             -- Summary of semantic change across the edge.
  calc_procedure_version_links_superseded_version_key(t.procedure_version_link_id) AS superseded_version_key-- Echoes the superseded (previous) version id for rows that express a next-version relation. Supersession is carried by RelationIri here, not by a separate link-kind column.
FROM procedure_version_links t;

-- ----------------------------------------------------------------------------
-- vw_procedure_status_changes: Lifecycle events that move a procedure version between PKO statuses. Maps to pko:ChangeOfStatus, fromStatus, toStatus, and prov:atTime.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_status_changes CASCADE;
CREATE VIEW vw_procedure_status_changes WITH (security_invoker = ON) AS
SELECT
  t.procedure_status_change_id,                                                 -- Stored logical identifier for one ProcedureStatusChanges row.
  calc_procedure_status_changes_name(t.procedure_status_change_id) AS name,     -- Human-readable calculated display alias for the ProcedureStatusChanges row.
  t.procedure_version,                                                          -- Procedure version whose status changed.
  t.from_status,                                                                -- Previous PKO status.
  t.to_status,                                                                  -- New PKO status.
  t.changed_at,                                                                 -- Time of change; maps to prov:atTime.
  t.changed_by_agent,                                                           -- Agent responsible for the change.
  t.motivation,                                                                 -- Reason for changing status.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.change_kind,                                                                -- Create, Modify, Extract, Validate, Approve or Archive.
  t.procedure_execution,                                                        -- Execution the change applies to, when it is not a version change.
  calc_procedure_status_changes_is_unattributed_change(t.procedure_status_change_id) AS is_unattributed_change,-- TRUE when nobody is recorded as making the change.
  calc_procedure_status_changes_change_kind_contradicts_target(t.procedure_status_change_id) AS change_kind_contradicts_target-- TRUE when the kind of change does not match the status it moved to.
FROM procedure_status_changes t;

-- ----------------------------------------------------------------------------
-- vw_steps: Version-scoped units of work. Atomic steps map to pplan:Step; composite steps map to pplan:MultiStep. The specification is never conflated with execution.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_steps CASCADE;
CREATE VIEW vw_steps WITH (security_invoker = ON) AS
SELECT
  t.step_id,                                                                    -- Stored logical identifier for one Steps row.
  calc_steps_name(t.step_id) AS name,                                           -- Human-readable calculated display alias for the Steps row.
  t.procedure_version,                                                          -- Procedure version containing the step; maps to pko:hasStep/pplan:isStepOfPlan.
  t.step_number,                                                                -- Stable sequence label; maps to pko:stepNumber.
  t.title,                                                                      -- Human-readable step title.
  t.step_kind,                                                                  -- Atomic or MultiStep.
  t.assigned_role,                                                              -- Role responsible for the step.
  calc_steps_assigned_role_label(t.step_id) AS assigned_role_label,             -- Resolved role label.
  calc_steps_assigned_agent_kind(t.step_id) AS assigned_agent_kind,             -- Current role-filler category.
  t.instruction,                                                                -- Normative step instruction.
  t.expected_duration_minutes,                                                  -- Expected duration represented as an OWL-Time duration in semantic projections.
  t.expertise_level,                                                            -- PKO expertise level: Junior, Senior, Expert, or Master.
  t.requires_human_confirmation,                                                -- TRUE when a human must confirm the step; maps to pko:wasConfirmedBy at execution.
  calc_steps_blocking_requirement_count(t.step_id) AS blocking_requirement_count,-- How many blocking requirements the specification attaches to this step.
  calc_steps_stale_binding_count(t.step_id) AS stale_binding_count,             -- How many operational bindings for this step are currently outside their freshness SLA.
  calc_steps_authoritative_stale_count(t.step_id) AS authoritative_stale_count, -- How many authoritative bindings for this step are currently stale.
  calc_steps_available_exception_count(t.step_id) AS available_exception_count, -- How many active exceptions the specification defines for this step.
  calc_steps_declared_verification_count(t.step_id) AS declared_verification_count,-- How many verifications the specification declares for this step.
  calc_steps_is_preparation_step(t.step_id) AS is_preparation_step,             -- TRUE for steps whose assigned role produces the work product rather than reviewing it.
  calc_steps_is_approval_step(t.step_id) AS is_approval_step,                   -- TRUE for steps whose assigned role is an approval authority.
  calc_steps_stale_authoritative_binding_count(t.step_id) AS stale_authoritative_binding_count,-- Number of authoritative bindings for this step that are past their freshness SLA.
  calc_steps_inputs_are_fresh(t.step_id) AS inputs_are_fresh,                   -- TRUE when no authoritative binding for this step is stale.
  calc_steps_is_software_assigned(t.step_id) AS is_software_assigned,           -- TRUE when this step is specified to be performed by software rather than a person.
  calc_steps_is_human_approval_gate(t.step_id) AS is_human_approval_gate,       -- TRUE for the steps that exist specifically to place a human commitment between drafting and delivery.
  calc_steps_gate_held_by_human(t.step_id) AS gate_held_by_human,               -- TRUE when a designated approval gate is in fact assigned to a human role.
  calc_steps_binding_boundary_count(t.step_id) AS binding_boundary_count,       -- Number of authority boundaries currently binding at this step.
  calc_steps_assigned_role_is_ungoverned(t.step_id) AS assigned_role_is_ungoverned,-- Whether this step's assigned role is a non-human role with no governing assignment.
  calc_steps_unusable_binding_count(t.step_id) AS unusable_binding_count,       -- Number of bindings at this step that are unapproved or stale.
  calc_steps_all_sources_usable(t.step_id) AS all_sources_usable,               -- TRUE when every binding at this step is an approved, fresh source.
  t.control_kind,                                                               -- What kind of control this step is: Preparation, Approval, LegalReview, Verification, Extraction, Publication, Retrospective, or None. That policy-04 is a legal review is a property OF policy-04, not of a formula that happens to name it; storing it as data makes downstream predicates portable to procedures that do not exist yet.
  calc_steps_unwarranted_boundary_count(t.step_id) AS unwarranted_boundary_count,-- How many boundaries governing this step are being enforced without a valid ratifying claim.
  calc_steps_is_governed_by_unwarranted_boundary(t.step_id) AS is_governed_by_unwarranted_boundary,-- Whether this step's constraints on machine authority rest on a claim that is no longer valid.
  calc_steps_software_execution_count(t.step_id) AS software_execution_count,   -- How many times a software agent has actually executed this step.
  calc_steps_has_been_approached_by_software(t.step_id) AS has_been_approached_by_software,-- Whether any software agent has ever executed this step.
  calc_steps_is_unexercised_human_gate(t.step_id) AS is_unexercised_human_gate, -- A human-only approval gate that no software agent has ever attempted — the control is asserted, not demonstrated.
  calc_steps_is_demonstrated_human_gate(t.step_id) AS is_demonstrated_human_gate,-- A human gate that software has actually reached and that a human nevertheless held.
  calc_steps_unexercised_gate_version_key(t.step_id) AS unexercised_gate_version_key,-- Composite-key echo: this step's procedure version when the step is an unexercised human gate, blank otherwise.
  calc_steps_has_declared_control_kind(t.step_id) AS has_declared_control_kind, -- Whether this step declares what kind of control it is.
  calc_steps_undeclared_control_version_key(t.step_id) AS undeclared_control_version_key,-- Composite-key echo: this step's procedure version when the step has no declared control kind, blank otherwise.
  calc_steps_approval_step_is_software_assigned(t.step_id) AS approval_step_is_software_assigned,-- An approval-kind step whose assigned role is currently held by an AI agent or automated pipeline.
  calc_steps_unwitnessed_blocking_count(t.step_id) AS unwitnessed_blocking_count,-- How many blocking controls bound to this step have no computed witness.
  calc_steps_reachable_step_count(t.step_id) AS reachable_step_count,           -- Number of steps this step can lead to through one or more transitions, including itself when it lies on a rework loop.
  calc_steps_reached_from_step_count(t.step_id) AS reached_from_step_count,     -- Number of steps that can lead to this step through one or more transitions, including itself when it lies on a rework loop.
  calc_steps_self_reach_count(t.step_id) AS self_reach_count,                   -- 1 when the closure contains the pair (this step, this step), i.e. some path of one or more transitions returns to this step; otherwise 0.
  calc_steps_is_on_rework_loop(t.step_id) AS is_on_rework_loop,                 -- The procedure can send work back to this step after it has run: the step lies on a cycle of the step graph.
  calc_steps_is_blocking_control_on_rework_loop(t.step_id) AS is_blocking_control_on_rework_loop,-- A step carrying at least one blocking requirement can be re-entered, so that control must hold on every pass, not only the first.
  calc_steps_incoming_transition_count(t.step_id) AS incoming_transition_count, -- Number of transitions, of any kind, that lead into this step.
  calc_steps_is_entry_step(t.step_id) AS is_entry_step,                         -- No transition leads into this step: the procedure version starts here.
  calc_steps_entry_step_key(t.step_id) AS entry_step_key,                       -- Composite-key echo: this step's id when it is its procedure version's entry step, blank otherwise.
  calc_steps_version_entry_step_id(t.step_id) AS version_entry_step_id,         -- The entry step of this step's procedure version.
  calc_steps_gate_free_reach_from_entry_count(t.step_id) AS gate_free_reach_from_entry_count,-- 1 when some route of one or more gate-free transitions leads from the procedure version's entry step to this step; otherwise 0.
  calc_steps_is_reachable_from_entry_without_human_gate(t.step_id) AS is_reachable_from_entry_without_human_gate,-- Work can arrive at this step from the start of the procedure without passing any human approval gate.
  calc_steps_is_gate_bypassed_publication(t.step_id) AS is_gate_bypassed_publication,-- A publication step the procedure can reach without human sign-off: the approval gate is structurally bypassable.
  t.semantic_type_iri,                                                          -- Exact P-Plan class IRI.
  t.parent_step,                                                                -- The multi-step this step sits in (pko:isStepOfMultiStep).
  t.first_child_step,                                                           -- For a multi-step, its first sub-step (pko:hasFirstStep).
  t.verifies_step,                                                              -- For a verification step, the step it checks (pko:isStepVerificationOf).
  t.remedy_for_error,                                                           -- Error this step remedies (pko:addressesError).
  t.calls_procedure,                                                            -- Sub-procedure this step invokes.
  t.isolates_energy_source,                                                     -- Energy source this step isolates.
  t.prerequisite_step,                                                          -- Step whose completion this step requires first (the requires relation).
  t.min_repetitions,                                                            -- Minimum times the step runs in one execution (pko:minRepetitions).
  t.max_repetitions,                                                            -- Maximum times the step may run in one execution (pko:maxRepetitions).
  t.description,                                                                -- Longer description of the step (dct:description).
  calc_steps_child_step_count(t.step_id) AS child_step_count,                   -- Sub-steps of this step.
  calc_steps_parent_step_kind(t.step_id) AS parent_step_kind,                   -- Kind of the parent step.
  calc_steps_is_composite_without_children(t.step_id) AS is_composite_without_children,-- TRUE for a step declared MultiStep that has no sub-steps.
  calc_steps_precondition_count(t.step_id) AS precondition_count,               -- Preconditions.
  calc_steps_postcondition_count(t.step_id) AS postcondition_count,             -- Postconditions.
  calc_steps_invariant_count(t.step_id) AS invariant_count,                     -- Invariants.
  calc_steps_safety_critical_condition_count(t.step_id) AS safety_critical_condition_count,-- Safety-critical conditions.
  calc_steps_failure_mode_count(t.step_id) AS failure_mode_count,               -- Documented failure modes.
  calc_steps_cue_count(t.step_id) AS cue_count,                                 -- Cues a practitioner reads during the step.
  calc_steps_danger_cue_count(t.step_id) AS danger_cue_count,                   -- Danger cues that call for escalation.
  calc_steps_decision_point_count(t.step_id) AS decision_point_count,           -- Decision points.
  calc_steps_knowledge_fragment_count(t.step_id) AS knowledge_fragment_count,   -- Knowledge fragments attached to the step.
  calc_steps_has_instruction_only(t.step_id) AS has_instruction_only,           -- TRUE for a step that carries only its one-line instruction: no condition, cue, failure mode, decision or captured knowledge.
  calc_steps_input_variable_count(t.step_id) AS input_variable_count,           -- Declared input variables.
  calc_steps_output_variable_count(t.step_id) AS output_variable_count,         -- Declared output variables (what the step produces).
  calc_steps_required_lock_count(t.step_id) AS required_lock_count,             -- Locks the step requires.
  calc_steps_required_protective_equipment_count(t.step_id) AS required_protective_equipment_count,-- Protective equipment the step requires.
  calc_steps_is_isolation_without_lock(t.step_id) AS is_isolation_without_lock, -- TRUE when a step isolates an energy source but requires no lock to hold the isolation.
  calc_steps_referenced_resource_count(t.step_id) AS referenced_resource_count, -- Resources the step references.
  calc_steps_untyped_version_key(t.step_id) AS untyped_version_key,             -- Version key for a step with no ontology type.
  calc_steps_is_accountable_to_software(t.step_id) AS is_accountable_to_software,-- TRUE when the role accountable for the step is held by software or an AI agent.
  calc_steps_has_downstream_steps(t.step_id) AS has_downstream_steps,           -- TRUE when any step follows this one anywhere along the ordering chain.
  calc_steps_incompleteness_cue_count(t.step_id) AS incompleteness_cue_count,   -- Cues that show the step did not fully take effect.
  calc_steps_has_incompleteness_cue(t.step_id) AS has_incompleteness_cue,       -- TRUE when the step documents a cue that shows it did not fully take effect.
  calc_steps_has_postcondition(t.step_id) AS has_postcondition,                 -- TRUE when the step states what must hold after it.
  calc_steps_accountable_agent(t.step_id) AS accountable_agent,                 -- Agent currently holding the step's role.
  calc_steps_has_no_accountable_agent(t.step_id) AS has_no_accountable_agent,   -- TRUE when nobody currently holds the role accountable for the step.
  calc_steps_conditionless_version_key(t.step_id) AS conditionless_version_key, -- Version key for a step with no precondition.
  calc_steps_prerequisite_downstream_count(t.step_id) AS prerequisite_downstream_count,-- Closure pairs showing the step's prerequisite comes after it in the specified order.
  calc_steps_prerequisite_is_downstream(t.step_id) AS prerequisite_is_downstream,-- TRUE when the specification orders a step before the step it requires, so following the order is unsafe.
  calc_steps_states_operational_knowledge(t.step_id) AS states_operational_knowledge,-- TRUE when the step states all three things the operational level needs: what it follows, what it depends on, and what must hold first.
  calc_steps_bottleneck_allocation_count(t.step_id) AS bottleneck_allocation_count,-- Resources allocated to the step whose demand exceeds capacity.
  calc_steps_is_bottleneck_step(t.step_id) AS is_bottleneck_step,               -- TRUE when the step waits on a resource whose demand exceeds its capacity.
  t.stage,                                                                      -- Stage the step is grouped in.
  t.detail_level,                                                               -- Activity (bundles many actions), Task, or Action (a single physical or system action).
  calc_steps_coarse_top_level_version_key(t.step_id) AS coarse_top_level_version_key,-- Version key for a top-level step at Activity detail.
  calc_steps_fine_top_level_version_key(t.step_id) AS fine_top_level_version_key,-- Version key for a top-level step at Action detail.
  calc_steps_context_sensitivity_count(t.step_id) AS context_sensitivity_count, -- Recorded ways the step's significance depends on context.
  calc_steps_unscoped_sensitivity_count(t.step_id) AS unscoped_sensitivity_count,-- Context dependencies with no applicability scope.
  calc_steps_is_context_sensitive_but_unscoped(t.step_id) AS is_context_sensitive_but_unscoped,-- TRUE when the step's significance depends on context and some such dependency says nowhere where it holds.
  calc_steps_version_procedure(t.step_id) AS version_procedure,                 -- Procedure the step's version belongs to.
  calc_steps_assigned_role_does_compliance_review(t.step_id) AS assigned_role_does_compliance_review,-- Whether the step's role carries the compliance-review capability.
  calc_steps_compliance_review_procedure_key(t.step_id) AS compliance_review_procedure_key,-- Procedure key for a step performed by a compliance-review role.
  calc_steps_step_procedure_type(t.step_id) AS step_procedure_type,             -- Procedure type of the step's version.
  calc_steps_is_release_approval_gate(t.step_id) AS is_release_approval_gate,   -- TRUE for an approval gate in a software release procedure.
  calc_steps_regulatory_requirement_count(t.step_id) AS regulatory_requirement_count,-- Requirements on the step that a regulation imposes.
  calc_steps_tool_function_count(t.step_id) AS tool_function_count,             -- Functions an agent may invoke at the step.
  calc_steps_parseable_condition_count(t.step_id) AS parseable_condition_count, -- Conditions stored as machine-parseable expressions.
  calc_steps_dmn_decision_count(t.step_id) AS dmn_decision_count,               -- Decision points encoded as DMN decisions.
  calc_steps_tool_use_rules_only_in_prose(t.step_id) AS tool_use_rules_only_in_prose,-- TRUE for a step where an agent uses tools but no condition or decision is stored in parseable form.
  calc_steps_open_outdated_flag_count(t.step_id) AS open_outdated_flag_count,   -- Open practitioner flags that the step's guidance is outdated.
  calc_steps_has_reported_reality_mismatch(t.step_id) AS has_reported_reality_mismatch,-- TRUE for a step practitioners' feedback says no longer matches how the work is done.
  calc_steps_deviated_run_count(t.step_id) AS deviated_run_count,               -- Executions of the step that recorded a deviation.
  calc_steps_is_drifted_from_practice(t.step_id) AS is_drifted_from_practice,   -- TRUE when practice deviates from the step repeatedly, or deviates where practitioners flagged the guidance outdated.
  calc_steps_ai_failure_count(t.step_id) AS ai_failure_count,                   -- Failed AI assistant tasks during this step.
  calc_steps_is_ai_failure_point(t.step_id) AS is_ai_failure_point,             -- TRUE for a step where an AI assistant has failed a task.
  calc_steps_ai_artifact_input_count(t.step_id) AS ai_artifact_input_count,     -- Inputs fed by an artifact an AI agent's step produces.
  calc_steps_consumes_ai_agent_artifact(t.step_id) AS consumes_ai_agent_artifact,-- TRUE when the step takes an AI agent's artifact as an input.
  calc_steps_collection_evidence_count(t.step_id) AS collection_evidence_count, -- Traces from this step to collected material, in any role.
  calc_steps_has_collection_evidence(t.step_id) AS has_collection_evidence,     -- TRUE when the step traces to at least one collected material.
  calc_steps_activity_origin_trace_count(t.step_id) AS activity_origin_trace_count,-- Origin traces of this step as an activity definition.
  calc_steps_version_model_trace_count(t.step_id) AS version_model_trace_count, -- Origin traces of the step's process model.
  calc_steps_is_untraced_activity_in_traced_model(t.step_id) AS is_untraced_activity_in_traced_model,-- TRUE when the step belongs to a traced process model but its own definition traces to no collection.
  calc_steps_elicited_validation_count(t.step_id) AS elicited_validation_count, -- Validations of this step captured from people.
  calc_steps_elicited_extension_count(t.step_id) AS elicited_extension_count,   -- Extensions of this step captured from people.
  calc_steps_downstream_artifact_step_count(t.step_id) AS downstream_artifact_step_count,-- Steps reachable from this step along artifact hand-offs.
  t.is_declared_first_step,                                                     -- TRUE for the step its version declares as its first step.
  t.is_declared_fallback_step,                                                  -- TRUE for the step its version declares as its fallback step.
  calc_steps_declared_first_step_key(t.step_id) AS declared_first_step_key,     -- Step key when declared first.
  calc_steps_declared_fallback_step_key(t.step_id) AS declared_fallback_step_key,-- Step key when declared the fallback.
  calc_steps_owner_organization(t.step_id) AS owner_organization                -- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
FROM steps t;

-- ----------------------------------------------------------------------------
-- vw_step_transitions: Directed control-flow edges represented as first-class pko:Transition instances with fromStep/toStep and next/alternative/fallback semantics.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_transitions CASCADE;
CREATE VIEW vw_step_transitions WITH (security_invoker = ON) AS
SELECT
  t.step_transition_id,                                                         -- Stored logical identifier for one StepTransitions row.
  calc_step_transitions_name(t.step_transition_id) AS name,                     -- Human-readable calculated display alias for the StepTransitions row.
  t.procedure_version,                                                          -- Procedure version whose control flow owns the transition.
  t.from_step,                                                                  -- Source step; maps to pko:fromStep.
  t.to_step,                                                                    -- Destination step; maps to pko:toStep.
  t.transition_kind,                                                            -- Next, Alternative, or Fallback.
  t.condition,                                                                  -- Condition under which the edge is taken.
  t.priority,                                                                   -- Evaluation priority when several outgoing edges exist.
  calc_step_transitions_is_recovery_path(t.step_transition_id) AS is_recovery_path,-- TRUE when this transition is a non-default path taken because something went wrong.
  calc_step_transitions_count_of_from_step_executions(t.step_transition_id) AS count_of_from_step_executions,-- How many times the step this transition leaves from has actually been executed.
  calc_step_transitions_count_of_to_step_executions(t.step_transition_id) AS count_of_to_step_executions,-- How many times the step this transition arrives at has actually been executed.
  calc_step_transitions_has_reachable_origin(t.step_transition_id) AS has_reachable_origin,-- TRUE when the origin step of this transition has been executed at least once.
  calc_step_transitions_has_reachable_target(t.step_transition_id) AS has_reachable_target,-- TRUE when the destination step of this transition has been executed at least once.
  calc_step_transitions_is_never_exercised(t.step_transition_id) AS is_never_exercised,-- TRUE when at least one end of this transition has never appeared in any step execution.
  calc_step_transitions_is_untested_recovery_path(t.step_transition_id) AS is_untested_recovery_path,-- TRUE for a Fallback or Alternative transition whose endpoints show no execution evidence.
  calc_step_transitions_count_of_observed_traversals(t.step_transition_id) AS count_of_observed_traversals,-- How many times this exact transition has actually been traversed.
  calc_step_transitions_has_been_traversed(t.step_transition_id) AS has_been_traversed,-- TRUE when this transition has been walked at least once.
  calc_step_transitions_is_unwalked_recovery_path(t.step_transition_id) AS is_unwalked_recovery_path,-- TRUE for a Fallback/Alternative transition with zero recorded traversals.
  calc_step_transitions_target_blocking_requirement_count(t.step_transition_id) AS target_blocking_requirement_count,-- How many blocking requirements are attached to the step this transition lands on.
  calc_step_transitions_target_carries_blocking_control(t.step_transition_id) AS target_carries_blocking_control,-- Whether the destination step of this transition carries at least one blocking control.
  calc_step_transitions_is_unrehearsed_control_entry(t.step_transition_id) AS is_unrehearsed_control_entry,-- A recovery path that has never been traversed and that leads into a step carrying a blocking control.
  calc_step_transitions_unrehearsed_control_version_key(t.step_transition_id) AS unrehearsed_control_version_key,-- Composite-key echo: this transition's procedure version when it is an unrehearsed control entry, blank otherwise.
  calc_step_transitions_from_step_is_human_approval_gate(t.step_transition_id) AS from_step_is_human_approval_gate,-- This transition leaves a human approval gate.
  calc_step_transitions_to_step_is_human_approval_gate(t.step_transition_id) AS to_step_is_human_approval_gate,-- This transition enters a human approval gate.
  calc_step_transitions_avoids_human_approval_gate(t.step_transition_id) AS avoids_human_approval_gate,-- Neither end of this transition is a human approval gate, so a route made only of such transitions never passes a gate.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  calc_step_transitions_decision_point_count(t.step_transition_id) AS decision_point_count,-- Decision points that select this transition.
  calc_step_transitions_is_undocumented_branch(t.step_transition_id) AS is_undocumented_branch-- TRUE for an alternative or fallback branch no decision point explains.
FROM step_transitions t;

-- ----------------------------------------------------------------------------
-- vw_actions: Human actions required by steps. Maps to pko:Action and pko:requiresAction.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_actions CASCADE;
CREATE VIEW vw_actions WITH (security_invoker = ON) AS
SELECT
  t.action_id,                                                                  -- Stored logical identifier for one Actions row.
  calc_actions_name(t.action_id) AS name,                                       -- Human-readable calculated display alias for the Actions row.
  t.label,                                                                      -- Action label.
  t.definition,                                                                 -- Normative definition of the action.
  t.semantic_type_iri                                                           -- Exact PKO class IRI.
FROM actions t;

-- ----------------------------------------------------------------------------
-- vw_functions: Software or algorithmic functions required by steps. Maps to pko:Function and pko:requiresFunction.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_functions CASCADE;
CREATE VIEW vw_functions WITH (security_invoker = ON) AS
SELECT
  t.function_id,                                                                -- Stored logical identifier for one Functions row.
  calc_functions_name(t.function_id) AS name,                                   -- Human-readable calculated display alias for the Functions row.
  t.label,                                                                      -- Function label.
  t.definition,                                                                 -- Deterministic or AI-assisted behavior.
  t.implementation_key,                                                         -- Operational implementation or model key.
  t.semantic_type_iri                                                           -- Exact PKO class IRI.
FROM functions t;

-- ----------------------------------------------------------------------------
-- vw_tools: Tools required to execute steps. Maps to m4ing:Tool and pko:requiresTool.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tools CASCADE;
CREATE VIEW vw_tools WITH (security_invoker = ON) AS
SELECT
  t.tool_id,                                                                    -- Stored logical identifier for one Tools row.
  calc_tools_name(t.tool_id) AS name,                                           -- Human-readable calculated display alias for the Tools row.
  t.label,                                                                      -- Tool label.
  t.purpose,                                                                    -- Operational purpose.
  t.semantic_type_iri                                                           -- Exact semantic class IRI.
FROM tools t;

-- ----------------------------------------------------------------------------
-- vw_step_actions: Many-to-many Step/Action semantics normalized into a first-class ERB junction table.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_actions CASCADE;
CREATE VIEW vw_step_actions WITH (security_invoker = ON) AS
SELECT
  t.step_action_id,                                                             -- Stored logical identifier for one StepActions row.
  calc_step_actions_name(t.step_action_id) AS name,                             -- Human-readable calculated display alias for the StepActions row.
  t.step,                                                                       -- Step side of the relationship.
  t."action"                                                                    -- Action side of the relationship.
FROM step_actions t;

-- ----------------------------------------------------------------------------
-- vw_step_functions: Many-to-many Step/Function semantics normalized into an ERB junction table.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_functions CASCADE;
CREATE VIEW vw_step_functions WITH (security_invoker = ON) AS
SELECT
  t.step_function_id,                                                           -- Stored logical identifier for one StepFunctions row.
  calc_step_functions_name(t.step_function_id) AS name,                         -- Human-readable calculated display alias for the StepFunctions row.
  t.step,                                                                       -- Step side of the relationship.
  t.function                                                                    -- Function side of the relationship.
FROM step_functions t;

-- ----------------------------------------------------------------------------
-- vw_step_tools: Many-to-many Step/Tool semantics normalized into an ERB junction table.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_tools CASCADE;
CREATE VIEW vw_step_tools WITH (security_invoker = ON) AS
SELECT
  t.step_tool_id,                                                               -- Stored logical identifier for one StepTools row.
  calc_step_tools_name(t.step_tool_id) AS name,                                 -- Human-readable calculated display alias for the StepTools row.
  t.step,                                                                       -- Step side of the relationship.
  t.tool                                                                        -- Tool side of the relationship.
FROM step_tools t;

-- ----------------------------------------------------------------------------
-- vw_requirements: Normative requirements applied to procedures, steps, or transitions. Maps to pko:Requirement and pko:hasRequirement.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_requirements CASCADE;
CREATE VIEW vw_requirements WITH (security_invoker = ON) AS
SELECT
  t.requirement_id,                                                             -- Stored logical identifier for one Requirements row.
  calc_requirements_name(t.requirement_id) AS name,                             -- Human-readable calculated display alias for the Requirements row.
  t.label,                                                                      -- Requirement label.
  t.requirement_type,                                                           -- Controlled requirement type; maps to pko:hasRequirementType.
  t.statement,                                                                  -- Normative requirement statement.
  t.rationale,                                                                  -- Why the requirement exists.
  t.is_blocking,                                                                -- TRUE when unsatisfied requirement blocks execution or approval.
  calc_requirements_satisfaction_record_count(t.requirement_id) AS satisfaction_record_count,-- How many times this requirement has ever been evaluated against an execution.
  calc_requirements_step_binding_count(t.requirement_id) AS step_binding_count, -- How many steps the specification binds this requirement to.
  calc_requirements_is_bound_to_any_step(t.requirement_id) AS is_bound_to_any_step,-- TRUE when at least one step carries this requirement.
  calc_requirements_has_ever_been_evaluated(t.requirement_id) AS has_ever_been_evaluated,-- TRUE when this requirement has at least one satisfaction record in the model.
  calc_requirements_negative_outcome_count(t.requirement_id) AS negative_outcome_count,-- How many times this requirement has ever produced a less-than-satisfied outcome.
  calc_requirements_is_inoperative_control(t.requirement_id) AS is_inoperative_control,-- TRUE for a blocking requirement that is attached to a step in the specification but has never once been evaluated on any execution.
  calc_requirements_is_decorative_control(t.requirement_id) AS is_decorative_control,-- TRUE for a blocking requirement that is not attached to any step at all.
  t.has_computed_witness,                                                       -- Whether a computed predicate in this rulebook evaluates this requirement, as opposed to it being satisfied by human assertion only.
  t.witness_field_name,                                                         -- The fully-qualified Table.Field of the predicate that computes this requirement, when one exists.
  calc_requirements_has_ever_produced_negative(t.requirement_id) AS has_ever_produced_negative,-- TRUE when this requirement has at least once been scored as anything other than Satisfied.
  calc_requirements_is_unfalsified_control(t.requirement_id) AS is_unfalsified_control,-- TRUE for a blocking control that HAS been evaluated at least once and has never returned a negative result.
  calc_requirements_claims_a_witness_field(t.requirement_id) AS claims_a_witness_field,-- TRUE when this requirement names a field it claims computes it.
  calc_requirements_named_witness_field_exists(t.requirement_id) AS named_witness_field_exists,-- TRUE when the field named in WitnessFieldName actually exists in the field catalog AND is a derived (calculated/lookup/aggregation) field.
  calc_requirements_derived_has_computed_witness(t.requirement_id) AS derived_has_computed_witness,-- Whether this requirement genuinely has a computed witness, derived from the field catalog rather than asserted.
  calc_requirements_witness_claim_is_unverified(t.requirement_id) AS witness_claim_is_unverified,-- TRUE when the hand-typed HasComputedWitness flag disagrees with what the field catalog says.
  calc_requirements_is_unwitnessed_blocking_control(t.requirement_id) AS is_unwitnessed_blocking_control,-- TRUE for a blocking control with no verified computed witness behind it.
  calc_requirements_witness_fire_count(t.requirement_id) AS witness_fire_count, -- How many times this requirement's evaluation has returned a non-Satisfied result.
  calc_requirements_witness_has_never_fired(t.requirement_id) AS witness_has_never_fired,-- TRUE for a requirement that has a computed witness which has never once returned a negative result.
  calc_requirements_evaluation_sample_size(t.requirement_id) AS evaluation_sample_size,-- How many times this requirement has been evaluated at all.
  calc_requirements_has_meaningful_sample(t.requirement_id) AS has_meaningful_sample,-- TRUE when this requirement has been evaluated often enough that a clean record is informative.
  t.minimum_sample_for_assurance,                                               -- The number of clean evaluations this control must accumulate before its silence counts as evidence.
  calc_requirements_is_untested_witness(t.requirement_id) AS is_untested_witness,-- TRUE for a witness that has never fired and has not been exercised enough for that silence to mean anything.
  calc_requirements_is_evidenced_holding_control(t.requirement_id) AS is_evidenced_holding_control,-- TRUE for a witness that has never fired across a sample large enough for that to constitute evidence.
  calc_requirements_control_assurance_state(t.requirement_id) AS control_assurance_state,-- One of Decorative, Inoperative, Asserted, Demonstrated, Holding, or Untested — the single control-health verdict for this requirement.
  calc_requirements_unexercised_binding_count(t.requirement_id) AS unexercised_binding_count,-- How many of this control's step bindings have never been evaluated.
  calc_requirements_witness_is_partially_scoped(t.requirement_id) AS witness_is_partially_scoped,-- TRUE when a control has a computed witness but at least one of its step bindings has never been exercised by it.
  t.accountable_role,                                                           -- The role answerable for this control operating as designed.
  calc_requirements_accountable_agent(t.requirement_id) AS accountable_agent,   -- The person currently holding the accountable role for this control.
  calc_requirements_has_named_owner(t.requirement_id) AS has_named_owner,       -- TRUE when a role has been named as accountable for this control.
  calc_requirements_is_orphaned_blocking_control(t.requirement_id) AS is_orphaned_blocking_control,-- TRUE for a blocking control with nobody named as accountable for it.
  calc_requirements_is_unwatched_and_unowned(t.requirement_id) AS is_unwatched_and_unowned,-- TRUE for a blocking control that nothing computes and nobody owns.
  calc_requirements_attestation_exposure_note(t.requirement_id) AS attestation_exposure_note,-- States, per control, what kind of exposure attesting to it creates.
  calc_requirements_unwatched_unowned_flag(t.requirement_id) AS unwatched_unowned_flag,-- Constant marker echoed when this control is both unwatched and unowned.
  t.controlled_term,                                                            -- Controlled vocabulary term this requirement's concept maps to, if any.
  calc_requirements_uses_controlled_vocabulary(t.requirement_id) AS uses_controlled_vocabulary,-- TRUE when this requirement points at a controlled term instead of only free-texting the concept.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.regulatory_framework,                                                       -- Regulation that imposes the requirement.
  calc_requirements_is_regulatory_requirement(t.requirement_id) AS is_regulatory_requirement,-- TRUE when a regulation imposes the requirement.
  calc_requirements_constraint_trace_count(t.requirement_id) AS constraint_trace_count,-- Traces of this requirement as a constraint.
  calc_requirements_is_untraced_bound_constraint(t.requirement_id) AS is_untraced_bound_constraint,-- TRUE when a constraint bound to a step traces to no collection activity.
  calc_requirements_recorded_pass_count(t.requirement_id) AS recorded_pass_count,-- PASS marks recorded on every step this control is bound to. Set beside SatisfactionRecordCount, it says how often somebody passed the step against how often anybody asked whether the control held.
  calc_requirements_is_passed_but_never_evaluated(t.requirement_id) AS is_passed_but_never_evaluated,-- TRUE for a blocking control whose steps carry PASS marks while the control itself has never once been evaluated. The green on those steps says nothing about the control.
  calc_requirements_failed_check_count(t.requirement_id) AS failed_check_count, -- Checks on record, of a condition that enforces this control, that found the condition did not hold.
  calc_requirements_is_breached_but_never_failed(t.requirement_id) AS is_breached_but_never_failed-- TRUE when the book holds a failed check of a condition this control enforces, and the control's own record still says it has never failed. The breach is on record; the control never heard about it.
FROM requirements t;

-- ----------------------------------------------------------------------------
-- vw_step_requirements: Many-to-many Step/Requirement semantics normalized into an ERB junction table.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_requirements CASCADE;
CREATE VIEW vw_step_requirements WITH (security_invoker = ON) AS
SELECT
  t.step_requirement_id,                                                        -- Stored logical identifier for one StepRequirements row.
  calc_step_requirements_name(t.step_requirement_id) AS name,                   -- Human-readable calculated display alias for the StepRequirements row.
  t.step,                                                                       -- Step side of the relationship.
  t.requirement,                                                                -- Requirement side of the relationship.
  calc_step_requirements_requirement_is_blocking(t.step_requirement_id) AS requirement_is_blocking,-- Whether this spec-side step/requirement binding names a blocking control.
  calc_step_requirements_blocking_step_key(t.step_requirement_id) AS blocking_step_key,-- Echoes the Step id only when the bound requirement is blocking; empty otherwise.
  calc_step_requirements_step_when_blocking(t.step_requirement_id) AS step_when_blocking,-- Echoes the step id when the bound requirement is blocking, blank otherwise.
  calc_step_requirements_requirement_lacks_witness(t.step_requirement_id) AS requirement_lacks_witness,-- Whether the requirement bound at this step is a blocking control with no computed witness.
  calc_step_requirements_unwitnessed_step_key(t.step_requirement_id) AS unwitnessed_step_key,-- Echoes the step id when the requirement bound here has no computed witness.
  calc_step_requirements_satisfaction_count_for_binding(t.step_requirement_id) AS satisfaction_count_for_binding,-- How many times this specific (step, requirement) binding has been evaluated in any execution.
  calc_step_requirements_binding_was_ever_exercised(t.step_requirement_id) AS binding_was_ever_exercised,-- TRUE when this specific (step, requirement) pair has been evaluated at least once.
  calc_step_requirements_is_unexercised_blocking_binding(t.step_requirement_id) AS is_unexercised_blocking_binding,-- TRUE for a blocking control bound to a step where it has never actually been evaluated.
  calc_step_requirements_unexercised_binding_requirement_key(t.step_requirement_id) AS unexercised_binding_requirement_key,-- Echoes the requirement id when this binding has never been exercised.
  calc_step_requirements_requirement_is_regulatory(t.step_requirement_id) AS requirement_is_regulatory,-- Whether a regulation imposes the requirement.
  calc_step_requirements_pass_count_on_step(t.step_requirement_id) AS pass_count_on_step-- How many executions of this binding's step were recorded as PASS.
FROM step_requirements t;

-- ----------------------------------------------------------------------------
-- vw_step_verifications: Verification definitions attached to steps. Maps to pko:StepVerification and pko:SignalVerification.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_verifications CASCADE;
CREATE VIEW vw_step_verifications WITH (security_invoker = ON) AS
SELECT
  t.step_verification_id,                                                       -- Stored logical identifier for one StepVerifications row.
  calc_step_verifications_name(t.step_verification_id) AS name,                 -- Human-readable calculated display alias for the StepVerifications row.
  t.step,                                                                       -- Step whose execution is verified; maps to pko:hasStepVerification.
  t.verification_kind,                                                          -- SignalVerification, ApprovalVerification, ProvenanceVerification, or another documented kind.
  t.signal_identifier,                                                          -- Signal or evidence key; maps to pko:signalIdentifier for signal verifications.
  t.expected_signal_value,                                                      -- Expected value; maps to pko:expectedSignalValue.
  t.instruction,                                                                -- How to verify the step.
  t.semantic_type_iri                                                           -- Exact PKO or extension class IRI.
FROM step_verifications t;

-- ----------------------------------------------------------------------------
-- vw_rationales: First-class rationale statements explaining why procedural commitments and design decisions exist. Explicit ERB-PKO extension, represented as prov:Entity/dcat:Resource in projections.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rationales CASCADE;
CREATE VIEW vw_rationales WITH (security_invoker = ON) AS
SELECT
  t.rationale_id,                                                               -- Stored logical identifier for one Rationales row.
  calc_rationales_name(t.rationale_id) AS name,                                 -- Human-readable calculated display alias for the Rationales row.
  t.procedure_version,                                                          -- Version justified by the rationale.
  t.step,                                                                       -- Optional step justified by the rationale.
  t.title,                                                                      -- Rationale title.
  t.statement,                                                                  -- Reasoned explanation.
  t.status,                                                                     -- Draft, Reviewed, Approved, or Superseded.
  t.authority_role,                                                             -- Role authorized to approve the rationale.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM rationales t;

-- ----------------------------------------------------------------------------
-- vw_exceptions: Documented exceptions, fallbacks, and alternative handling. Aligns structurally with PKO fallback/alternative steps and requirements; the exception record itself is an ERB-PKO extension.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_exceptions CASCADE;
CREATE VIEW vw_exceptions WITH (security_invoker = ON) AS
SELECT
  t.exception_id,                                                               -- Stored logical identifier for one Exceptions row.
  calc_exceptions_name(t.exception_id) AS name,                                 -- Human-readable calculated display alias for the Exceptions row.
  t.procedure_version,                                                          -- Procedure version containing the exception.
  t.trigger_step,                                                               -- Step at which the exception becomes relevant.
  t.condition,                                                                  -- Exception condition.
  t.handling,                                                                   -- Required handling and guardrails.
  t.approval_role,                                                              -- Role that approves use of the exception.
  t.fallback_role,                                                              -- Role or function that executes fallback handling.
  t.status,                                                                     -- Active, Draft, Retired, or Superseded.
  calc_exceptions_active_exception_step_key(t.exception_id) AS active_exception_step_key,-- Echoes the TriggerStep id only for exceptions currently in Active status.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM exceptions t;

-- ----------------------------------------------------------------------------
-- vw_resources: Documents, datasets, APIs, templates, images, manuals, and operational records referenced by procedures. Maps to dcat:Resource.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_resources CASCADE;
CREATE VIEW vw_resources WITH (security_invoker = ON) AS
SELECT
  t.resource_id,                                                                -- Stored logical identifier for one Resources row.
  calc_resources_name(t.resource_id) AS name,                                   -- Human-readable calculated display alias for the Resources row.
  t.title,                                                                      -- Resource title; maps to dcterms:title.
  t.resource_kind,                                                              -- Document, Dataset, API, Template, OperationalRecord, Image, Video, or another declared type.
  t.external_uri,                                                               -- Resolvable or organization-internal resource identifier.
  t.created_at,                                                                 -- Creation time; maps to dcterms:created.
  t.modified_at,                                                                -- Modification time; maps to dcterms:modified.
  t.description,                                                                -- Resource description; maps to dcterms:description.
  t.approval_status,                                                            -- Approved, Draft, Deprecated, or Unvetted.
  calc_resources_is_approved_source(t.resource_id) AS is_approved_source,       -- TRUE when this resource is an approved source.
  t.semantic_type_iri,                                                          -- Exact semantic class IRI.
  t.language,                                                                   -- Language (dct:language).
  t.keywords,                                                                   -- Keywords (dcat:keyword).
  t.format,                                                                     -- Media type (dct:format).
  t.created_by_agent,                                                           -- Creator (dct:creator).
  t.modified_by_agent,                                                          -- Last modifier (pko:wasModifiedBy).
  t.extracted_from_resource,                                                    -- Resource this one was extracted from (pko:wasExtractedFrom).
  calc_resources_source_modified_at(t.resource_id) AS source_modified_at,       -- When the source resource last changed.
  calc_resources_is_stale_extraction(t.resource_id) AS is_stale_extraction,     -- TRUE when the source a resource was extracted from changed after the extraction was last updated.
  calc_resources_referencing_step_count(t.resource_id) AS referencing_step_count,-- Steps that reference this resource.
  calc_resources_referencing_version_count(t.resource_id) AS referencing_version_count,-- Procedure versions that reference this resource.
  calc_resources_is_unused_resource(t.resource_id) AS is_unused_resource,       -- TRUE when no procedure or step uses the resource.
  t.artifact_type_concept,                                                      -- Artifact type from the controlled artifact-type scheme.
  calc_resources_is_content_without_organization(t.resource_id) AS is_content_without_organization,-- TRUE when a resource has content but is not typed by the artifact scheme, has no keywords to be found by, or is linked to no procedure or step.
  calc_resources_trailing_practice_count(t.resource_id) AS trailing_practice_count,-- Practice evidence, collected after the document's last revision, that contradicts it.
  calc_resources_is_behind_current_practice(t.resource_id) AS is_behind_current_practice,-- TRUE when the document has fallen behind how the work is currently done.
  t.catalog_entry_for,                                                          -- The procedure this resource is the catalog entry of.
  t.compliance_record_for                                                       -- The procedure this document is kept as a compliance record for.
FROM resources t;

-- ----------------------------------------------------------------------------
-- vw_procedure_resources: Links versioned procedures to supporting resources using PKO/dcterms provenance relations.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_resources CASCADE;
CREATE VIEW vw_procedure_resources WITH (security_invoker = ON) AS
SELECT
  t.procedure_resource_id,                                                      -- Stored logical identifier for one ProcedureResources row.
  calc_procedure_resources_name(t.procedure_resource_id) AS name,               -- Human-readable calculated display alias for the ProcedureResources row.
  t.procedure_version,                                                          -- Procedure version.
  t.resource,                                                                   -- Referenced or source resource.
  t.relation,                                                                   -- wasExtractedFrom, references, generated, used, or another declared relation.
  calc_procedure_resources_relation_iri(t.procedure_resource_id) AS relation_iri,-- Exact semantic property IRI for the relation.
  calc_procedure_resources_resource_modified_at(t.procedure_resource_id) AS resource_modified_at-- When the referenced resource last changed.
FROM procedure_resources t;

-- ----------------------------------------------------------------------------
-- vw_elicitation_sessions: Structured knowledge-elicitation events involving practitioners and knowledge engineers. Explicit ERB-PKO extension, modeled as prov:Activity.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_elicitation_sessions CASCADE;
CREATE VIEW vw_elicitation_sessions WITH (security_invoker = ON) AS
SELECT
  t.elicitation_session_id,                                                     -- Stored logical identifier for one ElicitationSessions row.
  calc_elicitation_sessions_name(t.elicitation_session_id) AS name,             -- Human-readable calculated display alias for the ElicitationSessions row.
  t.procedure_version,                                                          -- Procedure version whose knowledge was elicited.
  t.method,                                                                     -- The knowledge method this session used.
  t.started_at,                                                                 -- Start time; maps to prov:startedAtTime.
  t.ended_at,                                                                   -- End time; maps to prov:endedAtTime.
  t.practitioner_agent,                                                         -- Domain practitioner providing knowledge.
  t.facilitator_agent,                                                          -- Person facilitating elicitation.
  t.summary,                                                                    -- What was learned and captured.
  t.status,                                                                     -- Draft, Reviewed, Approved, or Rejected.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_elicitation_sessions_as_of_instant(t.elicitation_session_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_elicitation_sessions_days_since_elicited(t.elicitation_session_id) AS days_since_elicited,-- Days elapsed since this elicitation session concluded.
  calc_elicitation_sessions_is_single_witness_method(t.elicitation_session_id) AS is_single_witness_method,-- TRUE when this session captured one practitioner's account rather than a group's.
  calc_elicitation_sessions_practitioner_is_still_engaged(t.elicitation_session_id) AS practitioner_is_still_engaged,-- Whether the practitioner whose knowledge this session captured still holds a role here.
  calc_elicitation_sessions_valid_fragments_produced(t.elicitation_session_id) AS valid_fragments_produced,-- How many currently-valid knowledge fragments this one session produced.
  calc_elicitation_sessions_is_high_yield_session(t.elicitation_session_id) AS is_high_yield_session,-- A session that alone underwrites three or more currently-valid claims.
  calc_elicitation_sessions_is_concentrated_single_witness(t.elicitation_session_id) AS is_concentrated_single_witness,-- One unrepeated session with one witness that underwrites three or more live claims.
  calc_elicitation_sessions_is_stale_concentrated_witness(t.elicitation_session_id) AS is_stale_concentrated_witness,-- A concentrated single-witness session more than 180 days old — matching the single-witness expiry horizon loop 1 already established.
  calc_elicitation_sessions_concentrated_session_version_key(t.elicitation_session_id) AS concentrated_session_version_key,-- Composite-key echo: this session's procedure version when the session is a concentrated single witness, blank otherwise.
  t.semantic_type_iri,                                                          -- Class IRI used in semantic projection.
  t.observer_stance,                                                            -- For observation: NonParticipantObservation, Shadowing or LegitimatePeripheralParticipation.
  t.setting,                                                                    -- InSitu (where the work is done), Office or Remote.
  t.recording_reference,                                                        -- The recording of the practitioner's work made during the session, when one was made.
  t.practitioner_reviewed_at,                                                   -- When the practitioner reviewed the recording afterward to explain their reasoning.
  calc_elicitation_sessions_elicitation_mode(t.elicitation_session_id) AS elicitation_mode,-- The family of elicitation the session's method belongs to.
  calc_elicitation_sessions_is_interview(t.elicitation_session_id) AS is_interview,-- TRUE for an interview session.
  calc_elicitation_sessions_is_workshop(t.elicitation_session_id) AS is_workshop,-- TRUE for a workshop session.
  calc_elicitation_sessions_why_probe_count(t.elicitation_session_id) AS why_probe_count,-- Probes asking why a choice is made.
  calc_elicitation_sessions_shortfall_probe_count(t.elicitation_session_id) AS shortfall_probe_count,-- Probes asking what happens when the procedure falls short.
  calc_elicitation_sessions_is_interview_without_why_probe(t.elicitation_session_id) AS is_interview_without_why_probe,-- TRUE for an interview that never asked why a choice is made.
  calc_elicitation_sessions_is_interview_without_shortfall_probe(t.elicitation_session_id) AS is_interview_without_shortfall_probe,-- TRUE for an interview that never asked what happens when the procedure falls short.
  calc_elicitation_sessions_initiator_count(t.elicitation_session_id) AS initiator_count,-- Participants who start the process.
  calc_elicitation_sessions_executor_count(t.elicitation_session_id) AS executor_count,-- Participants who carry the process out.
  calc_elicitation_sessions_dependent_count(t.elicitation_session_id) AS dependent_count,-- Participants who depend on the process's results.
  calc_elicitation_sessions_uninvited_participant_count(t.elicitation_session_id) AS uninvited_participant_count,-- Participants whose position is normally not invited.
  calc_elicitation_sessions_gathers_whole_process_chain(t.elicitation_session_id) AS gathers_whole_process_chain,-- TRUE for a workshop that gathered people who start, carry out and depend on the process.
  calc_elicitation_sessions_is_workshop_without_usual_outsiders(t.elicitation_session_id) AS is_workshop_without_usual_outsiders,-- TRUE for a workshop in which nobody normally left out took part.
  calc_elicitation_sessions_method_family(t.elicitation_session_id) AS method_family,-- The family of the session's method.
  calc_elicitation_sessions_facilitator_knowledge_engineer_role_c(t.elicitation_session_id) AS facilitator_knowledge_engineer_role_count,-- Knowledge engineer roles the facilitator currently holds.
  calc_elicitation_sessions_facilitator_is_knowledge_engineer(t.elicitation_session_id) AS facilitator_is_knowledge_engineer,-- TRUE when the session was run by the organization's knowledge engineer.
  calc_elicitation_sessions_is_generic_or_unskilled_capture(t.elicitation_session_id) AS is_generic_or_unskilled_capture,-- TRUE when a session captured knowledge with a method outside the elicitation family or without a skilled elicitor running it.
  calc_elicitation_sessions_is_ke_field_session(t.elicitation_session_id) AS is_ke_field_session,-- TRUE for a session the knowledge engineer ran where the work is done.
  calc_elicitation_sessions_is_reviewed_recording(t.elicitation_session_id) AS is_reviewed_recording-- TRUE when the practitioner reviewed a recording of their own work afterward to explain it.
FROM elicitation_sessions t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_fragments: Explicit records of tacit, implicit, explicit, and situated procedural knowledge. This is an ERB-PKO extension represented as provenance-bearing dcat:Resource instances.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_fragments CASCADE;
CREATE VIEW vw_knowledge_fragments WITH (security_invoker = ON) AS
SELECT
  t.knowledge_fragment_id,                                                      -- Stored logical identifier for one KnowledgeFragments row.
  calc_knowledge_fragments_name(t.knowledge_fragment_id) AS name,               -- Human-readable calculated display alias for the KnowledgeFragments row.
  t.procedure_version,                                                          -- Procedure version informed by the fragment.
  t.step,                                                                       -- Optional step to which the fragment applies.
  t.knowledge_form,                                                             -- Tacit, Implicit, Explicit, SituatedJudgment, LessonLearned, or another declared form.
  t.statement,                                                                  -- Captured knowledge statement.
  t.elicitation_session,                                                        -- Optional elicitation session that produced the fragment.
  t.source_agent,                                                               -- Practitioner or source agent.
  t.confidence,                                                                 -- Low, Medium, or High confidence.
  t.valid_from,                                                                 -- Start of the fragment's valid-time interval.
  t.valid_to,                                                                   -- End of the fragment's valid-time interval.
  t.status,                                                                     -- Draft, Reviewed, Approved, Rejected, or Superseded.
  t.owner_role,                                                                 -- Role accountable for maintaining the fragment.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_knowledge_fragments_as_of_instant(t.knowledge_fragment_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_knowledge_fragments_is_currently_valid(t.knowledge_fragment_id) AS is_currently_valid,-- TRUE when the fragment is approved and valid now.
  calc_knowledge_fragments_source_agent_is_still_engaged(t.knowledge_fragment_id) AS source_agent_is_still_engaged,-- Whether the agent who is the source of this claim still holds a role here.
  calc_knowledge_fragments_source_agent_kind(t.knowledge_fragment_id) AS source_agent_kind,-- Whether the source of this claim is a Human, an AIAgent, or an AutomatedPipeline.
  calc_knowledge_fragments_has_human_source(t.knowledge_fragment_id) AS has_human_source,-- TRUE when the claim originates from a human practitioner rather than software.
  calc_knowledge_fragments_has_orphaned_provenance(t.knowledge_fragment_id) AS has_orphaned_provenance,-- TRUE when we still rely on this claim but the agent who gave it to us no longer holds a role here.
  calc_knowledge_fragments_is_undefendable_tacit_claim(t.knowledge_fragment_id) AS is_undefendable_tacit_claim,-- TRUE when an orphaned claim is of a kind that lives in a person's head rather than in a document.
  calc_knowledge_fragments_is_approved(t.knowledge_fragment_id) AS is_approved, -- TRUE when this claim has passed knowledge-authority approval.
  calc_knowledge_fragments_is_within_validity_window(t.knowledge_fragment_id) AS is_within_validity_window,-- TRUE when this claim's stated validity window contains the present moment.
  calc_knowledge_fragments_is_relied_upon(t.knowledge_fragment_id) AS is_relied_upon,-- TRUE when this claim is attached to a specific step and is inside its validity window — i.e. it is operationally in play.
  calc_knowledge_fragments_step_procedure_version_status(t.knowledge_fragment_id) AS step_procedure_version_status,-- The procedure version owning the step this claim is attached to.
  calc_knowledge_fragments_is_attached_to_live_version(t.knowledge_fragment_id) AS is_attached_to_live_version,-- Whether the procedure version this claim belongs to is currently executable.
  calc_knowledge_fragments_is_unapproved_but_relied_on(t.knowledge_fragment_id) AS is_unapproved_but_relied_on,-- TRUE when a live procedure is acting on a claim that has not been approved by the knowledge authority.
  calc_knowledge_fragments_evidence_age_days(t.knowledge_fragment_id) AS evidence_age_days,-- Age in days of the elicitation session this claim came from.
  calc_knowledge_fragments_has_recorded_elicitation(t.knowledge_fragment_id) AS has_recorded_elicitation,-- TRUE when this claim traces to a recorded elicitation session.
  calc_knowledge_fragments_is_from_single_witness(t.knowledge_fragment_id) AS is_from_single_witness,-- Whether this claim rests on a single practitioner's account.
  calc_knowledge_fragments_evidence_expiry_days(t.knowledge_fragment_id) AS evidence_expiry_days,-- How many days this claim's evidence is trusted for, given how it was gathered.
  calc_knowledge_fragments_evidence_has_expired(t.knowledge_fragment_id) AS evidence_has_expired,-- TRUE when the evidence behind this claim is older than we trust evidence of its kind to be.
  calc_knowledge_fragments_owner_agent(t.knowledge_fragment_id) AS owner_agent, -- The agent currently holding the role that owns this claim.
  calc_knowledge_fragments_is_awaiting_approval(t.knowledge_fragment_id) AS is_awaiting_approval,-- TRUE when this claim has been reviewed but not yet approved.
  calc_knowledge_fragments_owner_is_me(t.knowledge_fragment_id) AS owner_is_me, -- TRUE when the People Policy Owner role owns this claim.
  calc_knowledge_fragments_is_my_unfinished_approval(t.knowledge_fragment_id) AS is_my_unfinished_approval,-- TRUE when a claim I own has been reviewed and is waiting on my approval.
  calc_knowledge_fragments_is_invoked_by_an_exception(t.knowledge_fragment_id) AS is_invoked_by_an_exception,-- How many documented exception handlers trigger on the same step this claim is attached to.
  calc_knowledge_fragments_has_operational_reliance(t.knowledge_fragment_id) AS has_operational_reliance,-- TRUE when an exception handler exists on the step this claim governs.
  calc_knowledge_fragments_is_unapproved_and_operationally_live(t.knowledge_fragment_id) AS is_unapproved_and_operationally_live,-- TRUE when a claim awaiting my approval is already being acted on through a documented exception path.
  calc_knowledge_fragments_age_days(t.knowledge_fragment_id) AS age_days,       -- Days since this claim became valid.
  calc_knowledge_fragments_is_low_confidence(t.knowledge_fragment_id) AS is_low_confidence,-- TRUE when this claim was recorded with less than high confidence.
  calc_knowledge_fragments_owning_version_cadence_days(t.knowledge_fragment_id) AS owning_version_cadence_days,-- The review cadence promised for the version this claim supports.
  calc_knowledge_fragments_exceeds_owning_cadence(t.knowledge_fragment_id) AS exceeds_owning_cadence,-- TRUE when this claim is older than the review cadence promised for the version it supports.
  calc_knowledge_fragments_is_aging_low_confidence_claim(t.knowledge_fragment_id) AS is_aging_low_confidence_claim,-- TRUE when a claim we were never sure about has also outlived its version's review cadence.
  calc_knowledge_fragments_owner_role_agent_kind(t.knowledge_fragment_id) AS owner_role_agent_kind,-- Agent kind of whoever currently holds the role that owns this knowledge fragment.
  calc_knowledge_fragments_is_human_owned(t.knowledge_fragment_id) AS is_human_owned,-- TRUE when the owning role is currently held by a human.
  calc_knowledge_fragments_is_ai_validated_by_ai(t.knowledge_fragment_id) AS is_ai_validated_by_ai,-- TRUE when knowledge came from a non-human source AND is owned by a non-human-held role.
  calc_knowledge_fragments_review_cadence_days(t.knowledge_fragment_id) AS review_cadence_days,-- The review cadence promised for the procedure version this fragment supports, resolved via ProcedureVersions because INDEX/MATCH only matches a target primary key.
  calc_knowledge_fragments_is_overdue_for_review(t.knowledge_fragment_id) AS is_overdue_for_review,-- TRUE when a currently-valid fragment has gone longer than its stewardship cadence without review.
  calc_knowledge_fragments_predates_current_role_holder(t.knowledge_fragment_id) AS predates_current_role_holder,-- TRUE when this knowledge became valid before the current holder of its owning role took the role.
  calc_knowledge_fragments_owner_role_assignment_valid_from(t.knowledge_fragment_id) AS owner_role_assignment_valid_from,-- When the current holder of the owning role took that role.
  t.last_reviewed_at,                                                           -- When this fragment was last actually reviewed and reaffirmed by its owning role. Null when it has never been reviewed since authoring. IsOverdueForReview infers recency from ValidFrom, which records when the claim became TRUE, not when anyone last looked at it. Those are different events, and the inference is deliberately left in place under its own name rather than silently rewritten to fall back on this column.
  calc_knowledge_fragments_fragility_signal_count(t.knowledge_fragment_id) AS fragility_signal_count,-- How many of the four loop-1 decay signals are simultaneously true for this fragment: single witness, overdue for review, low confidence, operational reliance.
  calc_knowledge_fragments_is_compound_fragile(t.knowledge_fragment_id) AS is_compound_fragile,-- A fragment carrying at least three of the four decay signals at once.
  calc_knowledge_fragments_is_single_point_of_failure(t.knowledge_fragment_id) AS is_single_point_of_failure,-- A claim that rests on exactly one person's word and that an active exception handler actually routes cases against.
  calc_knowledge_fragments_is_expiring_single_point_of_failure(t.knowledge_fragment_id) AS is_expiring_single_point_of_failure,-- A single-sourced, operationally relied-upon claim that is also past its review date.
  calc_knowledge_fragments_compound_fragile_version_key(t.knowledge_fragment_id) AS compound_fragile_version_key,-- Composite-key echo: this fragment's procedure version when the fragment is compound-fragile, blank otherwise.
  calc_knowledge_fragments_valid_fragment_session_key(t.knowledge_fragment_id) AS valid_fragment_session_key,-- Composite-key echo: the elicitation session behind this fragment when the fragment is currently valid, blank otherwise.
  calc_knowledge_fragments_consuming_step_is_software_assigned(t.knowledge_fragment_id) AS consuming_step_is_software_assigned,-- Whether the step that consumes this fragment is assigned to an AI agent or an automated pipeline.
  calc_knowledge_fragments_consuming_step_agent_kind(t.knowledge_fragment_id) AS consuming_step_agent_kind,-- The kind of agent currently holding the role assigned to the step that consumes this fragment.
  calc_knowledge_fragments_is_unapproved_and_machine_consumed(t.knowledge_fragment_id) AS is_unapproved_and_machine_consumed,-- An unapproved claim that a software-assigned step actually relies on — executed literally, with no human in position to notice it is wrong.
  calc_knowledge_fragments_is_unapproved_and_human_consumed(t.knowledge_fragment_id) AS is_unapproved_and_human_consumed,-- An unapproved claim relied on by a human-assigned step — a reviewable risk rather than a silent one.
  calc_knowledge_fragments_machine_consumed_unapproved_version_ke(t.knowledge_fragment_id) AS machine_consumed_unapproved_version_key,-- Composite-key echo: this fragment's procedure version when the fragment is unapproved and machine-consumed, blank otherwise.
  calc_knowledge_fragments_has_review_record(t.knowledge_fragment_id) AS has_review_record,-- Whether this fragment has ever had an actual review recorded, as opposed to merely having a ValidFrom date.
  calc_knowledge_fragments_days_since_actual_review(t.knowledge_fragment_id) AS days_since_actual_review,-- Days elapsed since this fragment was last actually reviewed. Zero when no review has ever been recorded — read this only alongside HasReviewRecord, never on its own.
  calc_knowledge_fragments_is_unreviewed_since_authoring(t.knowledge_fragment_id) AS is_unreviewed_since_authoring,-- A currently-valid claim that nobody has ever reviewed since it was written.
  calc_knowledge_fragments_is_genuinely_overdue(t.knowledge_fragment_id) AS is_genuinely_overdue,-- A valid claim whose LAST ACTUAL REVIEW is older than the cadence its owning version promised.
  calc_knowledge_fragments_review_recency_is_inferred(t.knowledge_fragment_id) AS review_recency_is_inferred,-- A fragment reported overdue by the loop-1 inference purely because no review has ever been recorded — the number is an artifact of missing data, not evidence of neglect.
  calc_knowledge_fragments_inference_disagrees_with_record(t.knowledge_fragment_id) AS inference_disagrees_with_record,-- A fragment the ValidFrom inference calls overdue but which was in fact reviewed inside its cadence — a false positive in the loop-1 predicate, now provable.
  calc_knowledge_fragments_genuinely_overdue_version_key(t.knowledge_fragment_id) AS genuinely_overdue_version_key,-- Composite-key echo: this fragment's procedure version when the fragment is genuinely overdue, blank otherwise.
  calc_knowledge_fragments_ratified_boundary_count(t.knowledge_fragment_id) AS ratified_boundary_count,-- How many currently-binding authority boundaries this fragment ratifies.
  calc_knowledge_fragments_reliance_surface_count(t.knowledge_fragment_id) AS reliance_surface_count,-- Total number of distinct downstream dependents on this claim: exception handlers plus ratified authority boundaries.
  calc_knowledge_fragments_days_awaiting_my_approval(t.knowledge_fragment_id) AS days_awaiting_my_approval,-- How long a claim of mine has been sitting at Reviewed without my approval. Zero when the claim is not mine or is already decided.
  calc_knowledge_fragments_is_high_blast_radius_unapproved(t.knowledge_fragment_id) AS is_high_blast_radius_unapproved,-- An unapproved, operationally live claim of mine with more than one distinct downstream dependent.
  calc_knowledge_fragments_is_long_unapproved(t.knowledge_fragment_id) AS is_long_unapproved,-- A claim that has waited on my signature for more than thirty days.
  calc_knowledge_fragments_unapproved_load_bearing_version_key(t.knowledge_fragment_id) AS unapproved_load_bearing_version_key,-- Composite-key echo: this fragment's procedure version when it is a high-blast-radius unapproved claim, blank otherwise.
  calc_knowledge_fragments_owner_role_is_vacated(t.knowledge_fragment_id) AS owner_role_is_vacated,-- Whether the role that owns this claim is currently vacated.
  calc_knowledge_fragments_is_orphaned_by_role(t.knowledge_fragment_id) AS is_orphaned_by_role,-- A currently-valid claim whose owning role nobody holds — accountable to a vacancy.
  calc_knowledge_fragments_valid_fragment_version_key(t.knowledge_fragment_id) AS valid_fragment_version_key,-- Composite-key echo: this fragment's owning procedure version when the fragment is currently valid, blank otherwise.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.cognitive_basis,                                                            -- Intuition, PatternRecognition or Judgment for tacit knowledge; Articulated for knowledge stated outright.
  t.tacitness_degree,                                                           -- Position on the tacit-to-explicit spectrum: 1 fully articulated to 5 not articulable.
  t.lost_in_translation,                                                        -- What the explicit statement fails to carry of the practice it was drawn from.
  t.encoded_as,                                                                 -- HardRule, ConditionedGuidance, CueNarrative or Statement.
  t.stated_conditions,                                                          -- The conditions under which the fragment holds, as captured.
  calc_knowledge_fragments_is_flattened_to_brittle_rule(t.knowledge_fragment_id) AS is_flattened_to_brittle_rule,-- TRUE when tacit or situated knowledge was encoded as a hard rule with no conditions saying when it holds.
  calc_knowledge_fragments_corroboration_count(t.knowledge_fragment_id) AS corroboration_count,-- Independent supporting data points.
  calc_knowledge_fragments_rests_on_single_data_point(t.knowledge_fragment_id) AS rests_on_single_data_point,-- TRUE for approved knowledge no second session or practitioner supports.
  calc_knowledge_fragments_owner_organization(t.knowledge_fragment_id) AS owner_organization-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
FROM knowledge_fragments t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_gaps: Known unknowns and missing procedural coverage. Explicit ERB-PKO extension used to govern scope and prevent silent incompleteness.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_gaps CASCADE;
CREATE VIEW vw_knowledge_gaps WITH (security_invoker = ON) AS
SELECT
  t.knowledge_gap_id,                                                           -- Stored logical identifier for one KnowledgeGaps row.
  calc_knowledge_gaps_name(t.knowledge_gap_id) AS name,                         -- Human-readable calculated display alias for the KnowledgeGaps row.
  t.procedure_version,                                                          -- Affected procedure version.
  t.step,                                                                       -- Affected step.
  t.statement,                                                                  -- What is not yet known or represented.
  t.severity,                                                                   -- Low, Medium, High, or Critical.
  t.blocking_kind,                                                              -- Blocking or NonBlocking.
  t.status,                                                                     -- Open, Investigating, Resolved, AcceptedRisk, or Closed.
  t.owner_role,                                                                 -- Role responsible for resolving the gap.
  t.identified_at,                                                              -- Time the gap was identified.
  t.resolution_plan,                                                            -- Resolution plan or final resolution.
  calc_knowledge_gaps_is_open(t.knowledge_gap_id) AS is_open,                   -- TRUE when the gap remains open.
  calc_knowledge_gaps_open_gap_version_key(t.knowledge_gap_id) AS open_gap_version_key,-- Echoes the ProcedureVersion id for open high-severity knowledge gaps.
  calc_knowledge_gaps_is_blocking(t.knowledge_gap_id) AS is_blocking,           -- TRUE when this gap is declared blocking rather than informational.
  calc_knowledge_gaps_is_open_and_blocking(t.knowledge_gap_id) AS is_open_and_blocking,-- TRUE when this gap is both unresolved and declared blocking.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_knowledge_gaps_as_of_instant(t.knowledge_gap_id) AS as_of_instant,       -- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_knowledge_gaps_days_open(t.knowledge_gap_id) AS days_open,               -- Days this gap has been unresolved, or zero once closed.
  calc_knowledge_gaps_tolerance_days(t.knowledge_gap_id) AS tolerance_days,     -- How long a gap of this severity may remain open before it becomes a governance failure in its own right.
  calc_knowledge_gaps_is_overdue_gap(t.knowledge_gap_id) AS is_overdue_gap,     -- TRUE when this acknowledged unknown has outlived the tolerance for its severity.
  calc_knowledge_gaps_owner_agent(t.knowledge_gap_id) AS owner_agent,           -- The agent currently holding the role that owns resolving this gap.
  calc_knowledge_gaps_owner_is_still_engaged(t.knowledge_gap_id) AS owner_is_still_engaged,-- Whether the agent responsible for closing this gap still holds a role here.
  calc_knowledge_gaps_has_resolution_plan(t.knowledge_gap_id) AS has_resolution_plan,-- TRUE when someone has written down how this gap would be closed.
  calc_knowledge_gaps_is_abandoned_unknown(t.knowledge_gap_id) AS is_abandoned_unknown,-- TRUE when an overdue gap has either no plan or no living owner — an admission of ignorance that nobody is acting on.
  calc_knowledge_gaps_open_blocking_gap_version_key(t.knowledge_gap_id) AS open_blocking_gap_version_key,-- Composite-key echo: this gap's procedure version when the gap is both open and blocking, blank otherwise.
  calc_knowledge_gaps_owner_role_is_vacated(t.knowledge_gap_id) AS owner_role_is_vacated,-- Whether the role that owns this gap is currently vacated.
  calc_knowledge_gaps_is_ownerless_open_gap(t.knowledge_gap_id) AS is_ownerless_open_gap,-- An open gap whose owning role nobody currently holds — an acknowledged unknown with nobody accountable for closing it.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.gap_cause,                                                                  -- Gatekeeping, Sabotage, Undocumented or Unknown; blank when never classified.
  t.holder_declined_to_share,                                                   -- TRUE when an elicitation recorded the one person who knows declining to share it.
  t.siloed_within,                                                              -- The group the knowledge stays inside.
  t.drawn_out_by_session,                                                       -- The session that drew the gatekept knowledge out.
  t.codified_as_fragment,                                                       -- The fragment it was codified as.
  calc_knowledge_gaps_is_known_and_unresolved(t.knowledge_gap_id) AS is_known_and_unresolved,-- TRUE for an identified gap that is still open.
  calc_knowledge_gaps_is_gatekeeping_or_sabotage(t.knowledge_gap_id) AS is_gatekeeping_or_sabotage,-- TRUE for a gap caused by gatekeeping or knowledge sabotage.
  calc_knowledge_gaps_is_unattributed_gatekeeping(t.knowledge_gap_id) AS is_unattributed_gatekeeping,-- TRUE when a holder was recorded declining to share but the gap is not identified as gatekeeping or sabotage.
  calc_knowledge_gaps_is_required_gatekept_uncodified(t.knowledge_gap_id) AS is_required_gatekept_uncodified,-- TRUE for blocking gatekept or sabotaged knowledge never drawn out and codified.
  calc_knowledge_gaps_owner_organization(t.knowledge_gap_id) AS owner_organization,-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
  t.answered_by_model_change_request,                                           -- The change to the book that was raised to close this gap, when there is one.
  calc_knowledge_gaps_answering_change_title(t.knowledge_gap_id) AS answering_change_title,-- What the change that answers this gap asks for.
  calc_knowledge_gaps_answering_change_status(t.knowledge_gap_id) AS answering_change_status-- Where the change that answers this gap has got to.
FROM knowledge_gaps t;

-- ----------------------------------------------------------------------------
-- vw_faqs: Frequently asked procedural questions. Maps to pko:FrequentlyAskedQuestion, question, answer, hasFAQCategory, and hasFAQTarget.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_faqs CASCADE;
CREATE VIEW vw_faqs WITH (security_invoker = ON) AS
SELECT
  t.faq_id,                                                                     -- Stored logical identifier for one FAQs row.
  calc_faqs_name(t.faq_id) AS name,                                             -- Human-readable calculated display alias for the FAQs row.
  t.procedure_version,                                                          -- Procedure version addressed by the FAQ.
  t.step,                                                                       -- Optional step targeted by the FAQ.
  t.category,                                                                   -- FAQ category.
  t.target_kind,                                                                -- Procedure, Step, Tool, Resource, or Execution.
  t.question,                                                                   -- FAQ question; maps to pko:question.
  t.answer,                                                                     -- Approved answer; maps to pko:answer.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.resource,                                                                   -- The FAQ's own catalog entry as a resource.
  calc_faqs_resolution_count(t.faq_id) AS resolution_count,                     -- Questions this FAQ resolved.
  calc_faqs_is_unused_faq(t.faq_id) AS is_unused_faq                            -- TRUE when no question asked during execution was ever resolved by this FAQ.
FROM faqs t;

-- ----------------------------------------------------------------------------
-- vw_explanations: Explainable derivation artifacts associated with procedural decisions. Maps to pko:Explanation and pko:hasExplanation.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_explanations CASCADE;
CREATE VIEW vw_explanations WITH (security_invoker = ON) AS
SELECT
  t.explanation_id,                                                             -- Stored logical identifier for one Explanations row.
  calc_explanations_name(t.explanation_id) AS name,                             -- Human-readable calculated display alias for the Explanations row.
  t.procedure_version,                                                          -- Procedure version explained.
  t.step,                                                                       -- Step explained.
  t.title,                                                                      -- Explanation title.
  t.description,                                                                -- What the explanation traces.
  t.semantic_type_iri                                                           -- Exact PKO class IRI.
FROM explanations t;

-- ----------------------------------------------------------------------------
-- vw_procedure_executions: Concrete enactments of procedure specifications. Maps to pko:ProcedureExecution and remains separate from ProcedureVersions.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_executions CASCADE;
CREATE VIEW vw_procedure_executions WITH (security_invoker = ON) AS
SELECT
  t.procedure_execution_id,                                                     -- Stored logical identifier for one ProcedureExecutions row.
  calc_procedure_executions_name(t.procedure_execution_id) AS name,             -- Human-readable calculated display alias for the ProcedureExecutions row.
  t.procedure_version,                                                          -- Exact procedure specification executed; maps to pko:hasExecutedProcedure.
  t.execution_status,                                                           -- PKO execution status: InProgress, Completed, Paused, or Cancelled.
  t.started_at,                                                                 -- Execution start; maps to prov:startedAtTime.
  t.ended_at,                                                                   -- Execution end; maps to prov:endedAtTime.
  t.executed_by_agent,                                                          -- Agent accountable for the overall execution; maps to pko:wasExecutedBy.
  t.context,                                                                    -- Execution-specific scope or target.
  t.operational_record_uri,                                                     -- Identifier in the operational execution system.
  calc_procedure_executions_expected_step_count(t.procedure_execution_id) AS expected_step_count,-- How many steps this execution was supposed to perform.
  calc_procedure_executions_completed_step_count(t.procedure_execution_id) AS completed_step_count,-- How many steps of this execution actually reached Completed.
  calc_procedure_executions_control_breach_count(t.procedure_execution_id) AS control_breach_count,-- Total step executions in this run that carry at least one control breach.
  calc_procedure_executions_late_step_count(t.procedure_execution_id) AS late_step_count,-- How many steps in this execution ran long.
  calc_procedure_executions_is_structurally_complete(t.procedure_execution_id) AS is_structurally_complete,-- TRUE when every specified step of the procedure version reached Completed in this execution.
  calc_procedure_executions_diverged_from_specification(t.procedure_execution_id) AS diverged_from_specification,-- TRUE when the execution either skipped specified steps or carried at least one control breach.
  calc_procedure_executions_all_blocking_controls_evaluated(t.procedure_execution_id) AS all_blocking_controls_evaluated,-- TRUE when every blocking requirement bound to every step of this execution received a satisfaction record.
  calc_procedure_executions_unevaluated_blocking_total(t.procedure_execution_id) AS unevaluated_blocking_total,-- How many step executions in this run left at least one blocking control unevaluated.
  calc_procedure_executions_separation_of_duties_held(t.procedure_execution_id) AS separation_of_duties_held,-- TRUE when no agent both prepared and approved within this execution.
  calc_procedure_executions_separation_violation_count(t.procedure_execution_id) AS separation_violation_count,-- Number of segregation-of-duties violations in this execution.
  calc_procedure_executions_is_attestation_ready(t.procedure_execution_id) AS is_attestation_ready,-- TRUE only when every step completed, no control breached, every blocking control was actually evaluated, and segregation of duties held.
  calc_procedure_executions_attestation_blocker_summary(t.procedure_execution_id) AS attestation_blocker_summary,-- Names the highest-severity reason the attestation cannot be signed, or empty when it can.
  calc_procedure_executions_executed_version_is_fit(t.procedure_execution_id) AS executed_version_is_fit,-- Whether the procedure version this execution ran against is currently fit to execute.
  calc_procedure_executions_signed_against_unfit_version(t.procedure_execution_id) AS signed_against_unfit_version,-- TRUE when a completed execution was run against a procedure version the organization no longer stands behind.
  calc_procedure_executions_asserted_only_control_count(t.procedure_execution_id) AS asserted_only_control_count,-- How many blocking controls in this execution passed on human assertion alone.
  calc_procedure_executions_assurance_is_mostly_asserted(t.procedure_execution_id) AS assurance_is_mostly_asserted,-- TRUE when any blocking control in this execution passed without a computed witness behind it.
  calc_procedure_executions_unreachable_handling_failure_count(t.procedure_execution_id) AS unreachable_handling_failure_count,-- Number of deliveries in this execution where unreachable handling was wrong -- either fabricated acknowledgement or no exception invoked.
  calc_procedure_executions_retention_breach_count(t.procedure_execution_id) AS retention_breach_count,-- Number of transmitted messages in this execution whose text we no longer hold despite an active retention obligation.
  calc_procedure_executions_cleared_legal_review_count(t.procedure_execution_id) AS cleared_legal_review_count,-- How many passed legal reviews exist for this execution.
  calc_procedure_executions_has_cleared_legal_review(t.procedure_execution_id) AS has_cleared_legal_review,-- TRUE when legal review has passed for this execution.
  calc_procedure_executions_abandoned_failure_count(t.procedure_execution_id) AS abandoned_failure_count,-- Number of failed deliveries in this run that nobody picked up.
  calc_procedure_executions_delivered_count(t.procedure_execution_id) AS delivered_count,-- Number of confirmed-delivered messages in this run.
  calc_procedure_executions_total_delivery_attempt_count(t.procedure_execution_id) AS total_delivery_attempt_count,-- Total delivery records of any status for this run.
  calc_procedure_executions_has_abandoned_failures(t.procedure_execution_id) AS has_abandoned_failures,-- TRUE when this run has any untriaged delivery failure.
  calc_procedure_executions_mishandled_refusal_count(t.procedure_execution_id) AS mishandled_refusal_count,-- Number of gate refusals in this run that were either overridden or silently dropped.
  calc_procedure_executions_unclean_step_count(t.procedure_execution_id) AS unclean_step_count,-- Number of step executions in this run that were not clean.
  calc_procedure_executions_ran_clean(t.procedure_execution_id) AS ran_clean,   -- TRUE when every step execution in this run was clean.
  calc_procedure_executions_count_of_approval_executions(t.procedure_execution_id) AS count_of_approval_executions,-- How many human approval gates were executed in this run.
  calc_procedure_executions_has_human_approval(t.procedure_execution_id) AS has_human_approval,-- TRUE when at least one human approval gate was executed in this run.
  calc_procedure_executions_count_of_delivery_executions(t.procedure_execution_id) AS count_of_delivery_executions,-- How many times the send step ran in this execution.
  calc_procedure_executions_has_delivered(t.procedure_execution_id) AS has_delivered,-- TRUE when this run has sent communications to employees.
  calc_procedure_executions_delivered_without_approval(t.procedure_execution_id) AS delivered_without_approval,-- TRUE when a run sent employee communications without executing a human approval gate.
  calc_procedure_executions_invalid_approval_count(t.procedure_execution_id) AS invalid_approval_count,-- Number of approval-type requirements in this run that are incomplete or non-human-evaluated.
  calc_procedure_executions_approval_chain_is_complete(t.procedure_execution_id) AS approval_chain_is_complete,-- TRUE when every approval-type requirement in this run is fully satisfied by a human.
  calc_procedure_executions_vacuously_clean_step_count(t.procedure_execution_id) AS vacuously_clean_step_count,-- How many steps in this run were clean only because nothing checked them.
  calc_procedure_executions_preparation_step_count(t.procedure_execution_id) AS preparation_step_count,-- How many preparation steps this execution actually ran.
  calc_procedure_executions_approval_step_count(t.procedure_execution_id) AS approval_step_count,-- How many approval steps this execution actually ran.
  calc_procedure_executions_separation_was_testable(t.procedure_execution_id) AS separation_was_testable,-- TRUE when this execution contained both a preparation step and an approval step, so segregation of duties had an opportunity to fail.
  calc_procedure_executions_separation_held_under_test(t.procedure_execution_id) AS separation_held_under_test,-- TRUE only when segregation of duties both could have failed and did not.
  calc_procedure_executions_separation_is_vacuously_green(t.procedure_execution_id) AS separation_is_vacuously_green,-- TRUE when the segregation control reports as held on a run where it could not have failed.
  calc_procedure_executions_separation_assurance_note(t.procedure_execution_id) AS separation_assurance_note,-- The sentence that goes into the control narrative for this execution.
  calc_procedure_executions_ungoverned_divergence_count(t.procedure_execution_id) AS ungoverned_divergence_count,-- How many steps in this run departed from spec with nothing authorising the departure.
  calc_procedure_executions_divergence_was_fully_governed(t.procedure_execution_id) AS divergence_was_fully_governed,-- TRUE when this run departed from specification and every departure was authorised.
  calc_procedure_executions_computedly_witnessed_control_count(t.procedure_execution_id) AS computedly_witnessed_control_count,-- How many blocking controls in this run were cleared by something computed.
  calc_procedure_executions_evaluated_control_count(t.procedure_execution_id) AS evaluated_control_count,-- Total blocking controls actually evaluated in this run, computed and asserted together.
  calc_procedure_executions_computed_assurance_ratio(t.procedure_execution_id) AS computed_assurance_ratio,-- The fraction of evaluated blocking controls in this run that rest on a computed witness rather than a human assertion.
  calc_procedure_executions_interested_party_assertion_count(t.procedure_execution_id) AS interested_party_assertion_count,-- How many controls in this run were cleared by assertion from someone with an interest in the outcome.
  calc_procedure_executions_assurance_grade(t.procedure_execution_id) AS assurance_grade,-- Names the quality of the assurance behind this execution, worst case first.
  calc_procedure_executions_attestation_would_be_weakly_based(t.procedure_execution_id) AS attestation_would_be_weakly_based,-- TRUE when the model says I may sign, but the basis for that permission is mostly or partly unwitnessed assertion.
  calc_procedure_executions_independent_human_observation_count(t.procedure_execution_id) AS independent_human_observation_count,-- How many verifications in this run were independently observed by a human with evidence attached.
  calc_procedure_executions_has_any_independent_observation(t.procedure_execution_id) AS has_any_independent_observation,-- TRUE when at least one verification in this run was independently observed by a human.
  calc_procedure_executions_self_attested_approval_count(t.procedure_execution_id) AS self_attested_approval_count,-- How many approval steps in this run rested on self-attestation.
  calc_procedure_executions_assurance_chain_is_circular(t.procedure_execution_id) AS assurance_chain_is_circular,-- TRUE when every approval in this run rests on self-attestation and no independent human observation exists anywhere in it.
  calc_procedure_executions_latest_attestation_instant(t.procedure_execution_id) AS latest_attestation_instant,-- The most recent signature instant for this execution.
  calc_procedure_executions_has_been_attested(t.procedure_execution_id) AS has_been_attested,-- TRUE when someone has signed for this execution.
  calc_procedure_executions_attestation_count(t.procedure_execution_id) AS attestation_count,-- How many signatures exist against this execution.
  calc_procedure_executions_post_attestation_score_count(t.procedure_execution_id) AS post_attestation_score_count,-- How many controls were scored after this execution was signed.
  calc_procedure_executions_basis_changed_after_signature(t.procedure_execution_id) AS basis_changed_after_signature,-- TRUE when controls this attestation depended on were scored after the signature was given.
  calc_procedure_executions_requires_re_attestation(t.procedure_execution_id) AS requires_re_attestation,-- TRUE when the basis changed after signature AND the execution no longer reads as attestable.
  calc_procedure_executions_intended_recipient_count(t.procedure_execution_id) AS intended_recipient_count,-- How many sends this campaign proposed to make.
  calc_procedure_executions_reached_recipient_count(t.procedure_execution_id) AS reached_recipient_count,-- How many of those sends actually left our systems.
  calc_procedure_executions_silently_dropped_count(t.procedure_execution_id) AS silently_dropped_count,-- How many intended recipients disappeared from this campaign with no record.
  calc_procedure_executions_delivery_yield_percent(t.procedure_execution_id) AS delivery_yield_percent,-- Percentage of intended recipients who actually received the communication.
  calc_procedure_executions_campaign_silently_lost_audience(t.procedure_execution_id) AS campaign_silently_lost_audience,-- TRUE when a campaign lost intended recipients without producing any record of the loss.
  calc_procedure_executions_unrecorded_refusal_count(t.procedure_execution_id) AS unrecorded_refusal_count,-- How many sends this execution refused without recording the refusal anywhere.
  calc_procedure_executions_has_unrecorded_refusals(t.procedure_execution_id) AS has_unrecorded_refusals,-- TRUE when this run contains at least one refusal that left no trace anywhere.
  calc_procedure_executions_independently_confirmed_intent_count(t.procedure_execution_id) AS independently_confirmed_intent_count,-- How many of this execution's send decisions were corroborated by a delivery record.
  calc_procedure_executions_send_decisions_are_entirely_self_witn(t.procedure_execution_id) AS send_decisions_are_entirely_self_witnessed,-- TRUE when no send decision in this run was confirmed by anything other than the pipeline itself.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.title,                                                                      -- Execution title (dct:title).
  t.description,                                                                -- Execution description (dct:description).
  t.confirmed_by_agent,                                                         -- Who confirmed the execution (pko:wasConfirmedBy).
  t.facility,                                                                   -- Where it ran.
  t.shift,                                                                      -- Day or Night, where the work runs in shifts.
  t.executed_on_machine,                                                        -- Machine the procedure was executed on (pko-ind:isExecutedOnMachine).
  t.observations,                                                               -- What the executor noticed.
  t.outcome,                                                                    -- How it turned out.
  calc_procedure_executions_participant_count(t.procedure_execution_id) AS participant_count,-- Associated agents besides the executor.
  calc_procedure_executions_deviating_step_count(t.procedure_execution_id) AS deviating_step_count,-- Step executions that recorded a deviation.
  calc_procedure_executions_has_step_deviation(t.procedure_execution_id) AS has_step_deviation,-- TRUE when any step deviated.
  calc_procedure_executions_deviating_facility_key(t.procedure_execution_id) AS deviating_facility_key,-- Facility key when the run deviated.
  calc_procedure_executions_clean_facility_key(t.procedure_execution_id) AS clean_facility_key,-- Facility key when the run did not deviate.
  calc_procedure_executions_deviating_day_version_key(t.procedure_execution_id) AS deviating_day_version_key,-- Version key for a deviating day-shift run.
  calc_procedure_executions_deviating_night_version_key(t.procedure_execution_id) AS deviating_night_version_key,-- Version key for a deviating night-shift run.
  calc_procedure_executions_status_change_count(t.procedure_execution_id) AS status_change_count,-- Status changes recorded against the execution itself.
  calc_procedure_executions_claims_completion_without_all_steps(t.procedure_execution_id) AS claims_completion_without_all_steps,-- TRUE when an execution is marked completed but not every specified step completed.
  calc_procedure_executions_is_unconfirmed_completion(t.procedure_execution_id) AS is_unconfirmed_completion,-- TRUE when an execution completed with nobody recorded as confirming it.
  calc_procedure_executions_has_no_recorded_outcome(t.procedure_execution_id) AS has_no_recorded_outcome,-- TRUE when an execution records no outcome.
  calc_procedure_executions_feedback_count(t.procedure_execution_id) AS feedback_count,-- Feedback filed about the execution.
  calc_procedure_executions_is_unreported_mistake(t.procedure_execution_id) AS is_unreported_mistake,-- TRUE when an execution deviated from its steps and nobody filed any feedback about it.
  calc_procedure_executions_owner_organization(t.procedure_execution_id) AS owner_organization,-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
  t.stopped_at_knowledge_gap,                                                   -- The knowledge gap this run stopped at: the procedure had no answer, so the run ended instead of someone guessing.
  calc_procedure_executions_stopped_at_gap_statement(t.procedure_execution_id) AS stopped_at_gap_statement,-- What nobody knows, in the gap this run stopped at.
  calc_procedure_executions_stopped_at_gap_status(t.procedure_execution_id) AS stopped_at_gap_status,-- Whether the gap this run stopped at is still open.
  calc_procedure_executions_stopped_at_gap_change_title(t.procedure_execution_id) AS stopped_at_gap_change_title,-- The change to the book that answers the gap this run stopped at.
  calc_procedure_executions_stopped_at_gap_change_status(t.procedure_execution_id) AS stopped_at_gap_change_status-- Where the change that answers this run's gap has got to.
FROM procedure_executions t;

-- ----------------------------------------------------------------------------
-- vw_step_executions: Concrete executions of specified steps. Maps to pko:StepExecution, hasExecutedStep, includesStepExecution, and nextStepExecution.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_executions CASCADE;
CREATE VIEW vw_step_executions WITH (security_invoker = ON) AS
SELECT
  t.step_execution_id,                                                          -- Stored logical identifier for one StepExecutions row.
  calc_step_executions_name(t.step_execution_id) AS name,                       -- Human-readable calculated display alias for the StepExecutions row.
  t.procedure_execution,                                                        -- Parent procedure execution.
  t.step,                                                                       -- Specified step executed; maps to pko:hasExecutedStep.
  t.executed_by_agent,                                                          -- Agent executing the step; maps to pko:wasExecutedBy.
  t.execution_status,                                                           -- InProgress, Completed, Paused, Cancelled, or Failed.
  t.started_at,                                                                 -- Execution start.
  t.ended_at,                                                                   -- Execution end.
  t.verification_result,                                                        -- PASS, WARN, FAIL, or PENDING.
  t.deviation,                                                                  -- Observed deviation from the specification.
  calc_step_executions_actual_duration_minutes(t.step_execution_id) AS actual_duration_minutes,-- Observed duration in minutes.
  calc_step_executions_expected_duration_minutes(t.step_execution_id) AS expected_duration_minutes,-- Expected duration from the specification.
  calc_step_executions_is_late(t.step_execution_id) AS is_late,                 -- TRUE when actual duration exceeds expected duration.
  calc_step_executions_blocking_unmet_count(t.step_execution_id) AS blocking_unmet_count,-- How many blocking requirements attached to this step execution are recorded as not fully satisfied.
  calc_step_executions_blocking_unmet_count_safe(t.step_execution_id) AS blocking_unmet_count_safe,-- Count of blocking-but-unmet requirements on this step execution, computed via the single-criterion key so no criterion is dropped.
  calc_step_executions_proceeded_past_blocking_control(t.step_execution_id) AS proceeded_past_blocking_control,-- TRUE when a step execution reached Completed even though a blocking requirement on it was never fully satisfied.
  calc_step_executions_expected_blocking_count(t.step_execution_id) AS expected_blocking_count,-- How many blocking requirements this execution's step was supposed to have evaluated.
  calc_step_executions_evaluated_blocking_count(t.step_execution_id) AS evaluated_blocking_count,-- How many blocking requirements actually received a satisfaction record on this step execution, at any level.
  calc_step_executions_unevaluated_blocking_count(t.step_execution_id) AS unevaluated_blocking_count,-- Blocking requirements that were bound to this step but never assessed on this execution.
  calc_step_executions_has_unevaluated_blocking_control(t.step_execution_id) AS has_unevaluated_blocking_control,-- TRUE when at least one blocking control bound to this step was never evaluated on this execution.
  calc_step_executions_stale_authoritative_source_count(t.step_execution_id) AS stale_authoritative_source_count,-- Number of stale authoritative sources bound to the step this execution ran.
  calc_step_executions_ran_on_stale_authoritative_source(t.step_execution_id) AS ran_on_stale_authoritative_source,-- TRUE when this execution's step depends on at least one authoritative source that is outside its freshness SLA.
  calc_step_executions_has_deviation_note(t.step_execution_id) AS has_deviation_note,-- TRUE when a human recorded some deviation narrative on this execution.
  calc_step_executions_is_late_and_unexplained(t.step_execution_id) AS is_late_and_unexplained,-- TRUE when the execution exceeded its expected duration and no deviation was recorded.
  calc_step_executions_available_exception_count_for_step(t.step_execution_id) AS available_exception_count_for_step,-- How many active exceptions were available to this execution's step.
  calc_step_executions_had_uninvoked_exception_available(t.step_execution_id) AS had_uninvoked_exception_available,-- TRUE when an execution ran long with no explanation despite the specification defining an active exception for exactly that situation.
  calc_step_executions_expected_verification_count(t.step_execution_id) AS expected_verification_count,-- How many verifications this execution was supposed to perform.
  calc_step_executions_performed_verification_count(t.step_execution_id) AS performed_verification_count,-- How many verification outcomes were actually recorded against this execution.
  calc_step_executions_skipped_verification_count(t.step_execution_id) AS skipped_verification_count,-- Declared verifications with no recorded outcome on this execution.
  calc_step_executions_has_skipped_verification(t.step_execution_id) AS has_skipped_verification,-- TRUE when a declared verification was never performed on this execution.
  calc_step_executions_claims_pass_without_evidence(t.step_execution_id) AS claims_pass_without_evidence,-- TRUE when an execution asserts PASS while at least one declared verification has no recorded outcome.
  calc_step_executions_step_is_preparation(t.step_execution_id) AS step_is_preparation,-- Whether this execution ran a preparation step.
  calc_step_executions_step_is_approval(t.step_execution_id) AS step_is_approval,-- Whether this execution ran an approval step.
  calc_step_executions_preparer_agent_key(t.step_execution_id) AS preparer_agent_key,-- Composite execution+agent key, emitted only for preparation steps.
  calc_step_executions_approver_agent_key(t.step_execution_id) AS approver_agent_key,-- Composite execution+agent key, emitted only for approval steps.
  calc_step_executions_prepared_by_this_agent_count(t.step_execution_id) AS prepared_by_this_agent_count,-- On an approval row, how many preparation steps in the SAME procedure execution were run by this same agent.
  calc_step_executions_violates_separation_of_duties(t.step_execution_id) AS violates_separation_of_duties,-- TRUE when the agent approving this step also prepared work earlier in the same procedure execution.
  calc_step_executions_required_role_for_step(t.step_execution_id) AS required_role_for_step,-- The role the specification assigns to this step.
  calc_step_executions_executor_role_key(t.step_execution_id) AS executor_role_key,-- The agent+role pair that would need to exist as a valid assignment for this execution to be properly authorized.
  calc_step_executions_executor_authority_count(t.step_execution_id) AS executor_authority_count,-- How many currently-valid role assignments grant this executor the role their step required.
  calc_step_executions_executor_held_required_role(t.step_execution_id) AS executor_held_required_role,-- TRUE when the executing agent holds a currently-valid assignment to the role the step required.
  calc_step_executions_is_unauthorized_approval(t.step_execution_id) AS is_unauthorized_approval,-- TRUE when an approval step was executed by an agent who does not hold the required approving role.
  calc_step_executions_completed_execution_key(t.step_execution_id) AS completed_execution_key,-- Echoes the parent execution id only for completed steps.
  calc_step_executions_control_breach_execution_key(t.step_execution_id) AS control_breach_execution_key,-- Echoes the parent execution id when this step execution carries ANY control breach.
  calc_step_executions_late_execution_key(t.step_execution_id) AS late_execution_key,-- Echoes the parent execution id only for steps that ran past their expected duration.
  calc_step_executions_executor_agent_kind(t.step_execution_id) AS executor_agent_kind,-- Human, AIAgent, or AutomatedPipeline — what kind of agent actually ran this step.
  calc_step_executions_executor_is_human(t.step_execution_id) AS executor_is_human,-- TRUE when a human executed this step.
  calc_step_executions_step_requires_human_confirmation(t.step_execution_id) AS step_requires_human_confirmation,-- Whether the specification requires this step to be human-confirmed.
  calc_step_executions_non_human_ran_human_step(t.step_execution_id) AS non_human_ran_human_step,-- TRUE when a step requiring human confirmation was executed by an AI agent or automated pipeline.
  calc_step_executions_non_human_approval(t.step_execution_id) AS non_human_approval,-- TRUE when an approval-authority step was executed by a non-human agent, regardless of the RequiresHumanConfirmation flag.
  calc_step_executions_unevaluated_blocking_execution_key(t.step_execution_id) AS unevaluated_blocking_execution_key,-- Echoes the parent execution id when this step left a blocking control unevaluated.
  calc_step_executions_separation_violation_execution_key(t.step_execution_id) AS separation_violation_execution_key,-- Echoes the parent execution id when this step execution violates segregation of duties.
  calc_step_executions_self_witnessed_verification_count(t.step_execution_id) AS self_witnessed_verification_count,-- How many of this execution's verifications were observed by the same agent who ran the step.
  calc_step_executions_unbacked_verification_count(t.step_execution_id) AS unbacked_verification_count,-- How many verifications on this execution recorded a matching signal with no retained evidence artifact.
  calc_step_executions_approval_rests_on_self_attestation(t.step_execution_id) AS approval_rests_on_self_attestation,-- TRUE when an approval step's verification was either self-witnessed by the approver or never performed at all.
  calc_step_executions_exception_invocation_count(t.step_execution_id) AS exception_invocation_count,-- How many specified exceptions were invoked during this step execution.
  calc_step_executions_ran_under_exception(t.step_execution_id) AS ran_under_exception,-- TRUE when this execution invoked at least one specified exception.
  calc_step_executions_is_completed(t.step_execution_id) AS is_completed,       -- TRUE when this step execution reached a completed state.
  calc_step_executions_is_verification_passed(t.step_execution_id) AS is_verification_passed,-- TRUE only when this step execution's verification actually passed. PENDING and FAIL are both not-passed.
  calc_step_executions_is_legal_review_step(t.step_execution_id) AS is_legal_review_step,-- TRUE for executions of the legal and privacy review step.
  calc_step_executions_cleared_legal_review_key(t.step_execution_id) AS cleared_legal_review_key,-- Carries the execution id only when this row is a PASSED legal review; empty string otherwise.
  calc_step_executions_assigned_role(t.step_execution_id) AS assigned_role,     -- The role the specification assigns to this step.
  calc_step_executions_role_current_agent(t.step_execution_id) AS role_current_agent,-- The agent currently designated to hold the step's assigned role.
  calc_step_executions_executor_is_designated_agent(t.step_execution_id) AS executor_is_designated_agent,-- TRUE when the agent that executed the step is the agent currently designated for the step's role.
  calc_step_executions_inputs_were_fresh_at_run(t.step_execution_id) AS inputs_were_fresh_at_run,-- Freshness verdict for the step this execution ran.
  calc_step_executions_ran_on_stale_inputs(t.step_execution_id) AS ran_on_stale_inputs,-- TRUE when an execution completed even though its step's authoritative inputs are stale.
  calc_step_executions_unresolved_issue_count(t.step_execution_id) AS unresolved_issue_count,-- Number of unresolved issue occurrences recorded against this execution.
  calc_step_executions_has_deviation(t.step_execution_id) AS has_deviation,     -- TRUE when a deviation from the specification was recorded.
  calc_step_executions_is_clean(t.step_execution_id) AS is_clean,               -- TRUE when this execution passed verification, deviated from nothing, left no open issue, and finished on time.
  calc_step_executions_procedure_execution_when_unclean(t.step_execution_id) AS procedure_execution_when_unclean,-- Echoes the parent execution id when this step execution is not clean, blank otherwise.
  calc_step_executions_evaluated_requirement_count(t.step_execution_id) AS evaluated_requirement_count,-- Number of requirements actually scored against this execution.
  calc_step_executions_required_blocking_count(t.step_execution_id) AS required_blocking_count,-- Number of blocking requirements the specification demands for this step.
  calc_step_executions_has_unevaluated_blocking_requirement(t.step_execution_id) AS has_unevaluated_blocking_requirement,-- TRUE when fewer requirements were scored than the step has blocking requirements.
  calc_step_executions_executing_agent_kind(t.step_execution_id) AS executing_agent_kind,-- The kind of agent that actually performed this step execution.
  calc_step_executions_was_executed_by_software(t.step_execution_id) AS was_executed_by_software,-- TRUE when software actually performed this step.
  calc_step_executions_step_is_software_assigned(t.step_execution_id) AS step_is_software_assigned,-- Whether the step being executed was specified as a software step.
  calc_step_executions_software_did_human_work(t.step_execution_id) AS software_did_human_work,-- TRUE when software performed a step the procedure specified for a human.
  calc_step_executions_is_approval_execution(t.step_execution_id) AS is_approval_execution,-- Whether this execution is of a designated human approval gate.
  calc_step_executions_is_verified(t.step_execution_id) AS is_verified,         -- TRUE when this execution recorded a positive verification outcome.
  calc_step_executions_unconfirmed_non_human_decision_count(t.step_execution_id) AS unconfirmed_non_human_decision_count,-- Number of material non-human decisions in this execution that no human confirmed.
  calc_step_executions_requires_human_confirmation(t.step_execution_id) AS requires_human_confirmation,-- Whether the specification requires human confirmation for this step.
  calc_step_executions_human_confirmation_missing(t.step_execution_id) AS human_confirmation_missing,-- TRUE when a step requiring human confirmation contains unconfirmed material non-human decisions.
  calc_step_executions_drafted_from_unusable_source(t.step_execution_id) AS drafted_from_unusable_source,-- TRUE when a drafting execution completed despite an unapproved or stale source at its step.
  calc_step_executions_inputs_were_usable(t.step_execution_id) AS inputs_were_usable,-- Source-usability verdict for the step this execution ran.
  calc_step_executions_software_execution_step_key(t.step_execution_id) AS software_execution_step_key,-- Composite-key echo: the step this execution ran when it was carried out by software, blank otherwise.
  calc_step_executions_step_control_kind(t.step_execution_id) AS step_control_kind,-- The control kind of the step this execution ran.
  calc_step_executions_unfalsified_clearance_count(t.step_execution_id) AS unfalsified_clearance_count,-- How many of this step's blocking clearances came from controls that have never once failed.
  calc_step_executions_all_clearances_are_unfalsified(t.step_execution_id) AS all_clearances_are_unfalsified,-- TRUE when every blocking control evaluated on this step is one that has never returned a negative result.
  calc_step_executions_stale_at_run_count(t.step_execution_id) AS stale_at_run_count,-- How many authoritative sources this step read that were already out of SLA when it read them.
  calc_step_executions_was_stale_when_i_ran_it(t.step_execution_id) AS was_stale_when_i_ran_it,-- TRUE when this execution consumed at least one authoritative source that was stale at the time of reading.
  calc_step_executions_staleness_answer_is_tense_dependent(t.step_execution_id) AS staleness_answer_is_tense_dependent,-- TRUE when the as-of-now staleness verdict disagrees with the as-of-run verdict for the same step.
  calc_step_executions_has_any_declared_check(t.step_execution_id) AS has_any_declared_check,-- TRUE when the specification declared at least one verification or one blocking requirement for this step.
  calc_step_executions_performed_check_count(t.step_execution_id) AS performed_check_count,-- Total number of checks actually carried out on this execution, verifications plus blocking-control evaluations.
  calc_step_executions_declared_check_count(t.step_execution_id) AS declared_check_count,-- Total number of checks the specification called for on this step.
  calc_step_executions_is_unchecked_by_design(t.step_execution_id) AS is_unchecked_by_design,-- TRUE when the specification asked for no verification and no blocking control on this step at all.
  calc_step_executions_is_vacuously_clean(t.step_execution_id) AS is_vacuously_clean,-- TRUE when this execution reads clean and nothing was ever declared that could have made it read otherwise.
  calc_step_executions_is_substantively_clean(t.step_execution_id) AS is_substantively_clean,-- TRUE when this execution is clean AND every declared check was actually performed.
  calc_step_executions_vacuously_clean_execution_key(t.step_execution_id) AS vacuously_clean_execution_key,-- Echoes the parent execution id when this step is vacuously clean.
  calc_step_executions_uncorroborated_pass_count(t.step_execution_id) AS uncorroborated_pass_count,-- How many of this step's passing verifications were observed by the executor with no evidence attached.
  calc_step_executions_evidence_position_is_weak(t.step_execution_id) AS evidence_position_is_weak,-- TRUE when every verification performed on this step was an uncorroborated self-witnessed pass.
  calc_step_executions_preparation_execution_key(t.step_execution_id) AS preparation_execution_key,-- Echoes the parent execution id when this step execution is a preparation step.
  calc_step_executions_approval_execution_key(t.step_execution_id) AS approval_execution_key,-- Echoes the parent execution id when this step execution is an approval step.
  calc_step_executions_has_governing_instrument(t.step_execution_id) AS has_governing_instrument,-- TRUE when this step's departure from spec is covered by an invoked exception or an approved change request against its procedure version.
  calc_step_executions_has_approved_change_coverage(t.step_execution_id) AS has_approved_change_coverage,-- Whether the procedure version this step belongs to has an approved change request that could account for a departure.
  calc_step_executions_version_of_step(t.step_execution_id) AS version_of_step, -- The procedure version this step execution's specification step belongs to.
  calc_step_executions_is_ungoverned_divergence(t.step_execution_id) AS is_ungoverned_divergence,-- TRUE when this step departed from specification and no exception or approved change covers it.
  calc_step_executions_ungoverned_divergence_execution_key(t.step_execution_id) AS ungoverned_divergence_execution_key,-- Echoes the parent execution id when this step diverged without governance.
  calc_step_executions_self_attested_approval_execution_key(t.step_execution_id) AS self_attested_approval_execution_key,-- Echoes the parent execution id when this approval rested on self-attestation.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.previous_step_execution,                                                    -- Step execution that ran immediately before (pko:previousStepExecution).
  t.confirmed_by_agent,                                                         -- Who confirmed the step (pko:wasConfirmedBy).
  t.description,                                                                -- What happened during the step (dct:description).
  calc_step_executions_previous_executed_step(t.step_execution_id) AS previous_executed_step,-- Step the previous step execution ran.
  calc_step_executions_specified_transition_from_previous_count(t.step_execution_id) AS specified_transition_from_previous_count,-- Transitions the specification allows from the previous step to this one.
  calc_step_executions_is_out_of_specified_order(t.step_execution_id) AS is_out_of_specified_order,-- TRUE when a step ran straight after a step the specification does not let lead to it.
  calc_step_executions_execution_version(t.step_execution_id) AS execution_version,-- Version the parent procedure execution enacts.
  calc_step_executions_executes_step_of_other_version(t.step_execution_id) AS executes_step_of_other_version,-- TRUE when a step execution records a step from a different specification than the one its procedure execution enacts.
  calc_step_executions_repetition_count(t.step_execution_id) AS repetition_count,-- Times this step ran within the same procedure execution.
  calc_step_executions_step_max_repetitions(t.step_execution_id) AS step_max_repetitions,-- Maximum repetitions the specification allows.
  calc_step_executions_exceeds_max_repetitions(t.step_execution_id) AS exceeds_max_repetitions,-- TRUE when a step ran more often in one execution than its specification allows.
  calc_step_executions_lacks_required_confirmation(t.step_execution_id) AS lacks_required_confirmation,-- TRUE when a step that requires human confirmation completed with nobody recorded as confirming it.
  calc_step_executions_failed_precondition_count(t.step_execution_id) AS failed_precondition_count,-- Preconditions that did not hold.
  calc_step_executions_violated_invariant_count(t.step_execution_id) AS violated_invariant_count,-- Invariants that did not hold.
  calc_step_executions_proceeded_despite_failed_precondition(t.step_execution_id) AS proceeded_despite_failed_precondition,-- TRUE when a step completed although one of its preconditions was checked and did not hold.
  calc_step_executions_unescalated_danger_cue_count(t.step_execution_id) AS unescalated_danger_cue_count,-- Danger cues seen and not escalated.
  calc_step_executions_ignored_danger_cue(t.step_execution_id) AS ignored_danger_cue,-- TRUE when a danger cue was observed during the step and nobody escalated it.
  calc_step_executions_used_entity_count(t.step_execution_id) AS used_entity_count,-- Entities used.
  calc_step_executions_generated_entity_count(t.step_execution_id) AS generated_entity_count,-- Entities generated.
  calc_step_executions_step_input_variable_count(t.step_execution_id) AS step_input_variable_count,-- Inputs the step declares.
  calc_step_executions_ran_without_declared_inputs(t.step_execution_id) AS ran_without_declared_inputs,-- TRUE when a completed step declares inputs but its execution records none of them being used.
  calc_step_executions_step_prerequisite(t.step_execution_id) AS step_prerequisite,-- Step the specification requires to be complete first.
  calc_step_executions_completed_prerequisite_run_count(t.step_execution_id) AS completed_prerequisite_run_count,-- Completed executions of that prerequisite step in the same procedure execution.
  calc_step_executions_ran_before_prerequisite_completed(t.step_execution_id) AS ran_before_prerequisite_completed,-- TRUE when a step ran in an execution where its declared prerequisite never completed.
  calc_step_executions_deviation_execution_key(t.step_execution_id) AS deviation_execution_key,-- Procedure execution key when the step deviated.
  calc_step_executions_broke_invariant(t.step_execution_id) AS broke_invariant, -- TRUE when an invariant did not hold during the step.
  calc_step_executions_is_blocked_by_incomplete_prerequisite(t.step_execution_id) AS is_blocked_by_incomplete_prerequisite,-- TRUE for an unfinished step whose prerequisite has not completed in the same execution.
  calc_step_executions_owner_organization(t.step_execution_id) AS owner_organization,-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
  calc_step_executions_incomplete_cue_observation_count(t.step_execution_id) AS incomplete_cue_observation_count,-- Warning signs observed on this step execution that mean the step is not finished.
  calc_step_executions_is_blocked_by_observed_cue(t.step_execution_id) AS is_blocked_by_observed_cue,-- A warning sign that means 'not finished' was seen on this step execution, so the normal next step must not be offered; only a fallback is.
  calc_step_executions_is_blocked_by_failed_precondition(t.step_execution_id) AS is_blocked_by_failed_precondition-- A check on this step recorded that a precondition did not hold. The step may not be marked done; only a fallback is offered, exactly as for an observed warning sign.
FROM step_executions t;

-- ----------------------------------------------------------------------------
-- vw_requirement_satisfactions: Execution-time evaluations of requirements. Maps to pko:RequirementSatisfaction, refersToRequirement, and hasRequirementSatisfactionLevel.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_requirement_satisfactions CASCADE;
CREATE VIEW vw_requirement_satisfactions WITH (security_invoker = ON) AS
SELECT
  t.requirement_satisfaction_id,                                                -- Stored logical identifier for one RequirementSatisfactions row.
  calc_requirement_satisfactions_name(t.requirement_satisfaction_id) AS name,   -- Human-readable calculated display alias for the RequirementSatisfactions row.
  t.step_execution,                                                             -- Execution being evaluated.
  t.requirement,                                                                -- Requirement evaluated.
  t.satisfaction_level,                                                         -- NotEvaluated, NotSatisfied, PartiallySatisfied, or Satisfied.
  t.evidence,                                                                   -- Evidence supporting the evaluation.
  t.evaluated_by_agent,                                                         -- Agent that evaluated satisfaction.
  t.evaluated_at,                                                               -- Evaluation timestamp.
  calc_requirement_satisfactions_requirement_is_blocking(t.requirement_satisfaction_id) AS requirement_is_blocking,-- Whether the requirement being evaluated on this satisfaction row is a blocking control.
  calc_requirement_satisfactions_is_fully_satisfied(t.requirement_satisfaction_id) AS is_fully_satisfied,-- TRUE only when the requirement is recorded as fully Satisfied. PartiallySatisfied, Unsatisfied, Waived, and blank are all FALSE.
  calc_requirement_satisfactions_is_blocking_and_unmet(t.requirement_satisfaction_id) AS is_blocking_and_unmet,-- TRUE when a blocking requirement is recorded at anything less than fully Satisfied. This is the control-failure witness at the requirement grain.
  calc_requirement_satisfactions_blocking_unmet_step_key(t.requirement_satisfaction_id) AS blocking_unmet_step_key,-- Echoes the parent StepExecution id only when this row is a blocking-unmet violation; empty string otherwise.
  calc_requirement_satisfactions_blocking_satisfaction_step_key(t.requirement_satisfaction_id) AS blocking_satisfaction_step_key,-- Echoes the parent StepExecution id when this satisfaction row concerns a blocking requirement.
  calc_requirement_satisfactions_negative_outcome_requirement_key(t.requirement_satisfaction_id) AS negative_outcome_requirement_key,-- Echoes the Requirement id only when this evaluation came out at less than fully Satisfied.
  calc_requirement_satisfactions_evaluator_agent_kind(t.requirement_satisfaction_id) AS evaluator_agent_kind,-- What kind of agent evaluated this requirement satisfaction.
  calc_requirement_satisfactions_non_human_evaluated_human_contro(t.requirement_satisfaction_id) AS non_human_evaluated_human_control,-- TRUE when a blocking requirement was evaluated by a non-human agent.
  calc_requirement_satisfactions_requirement_has_computed_witness(t.requirement_satisfaction_id) AS requirement_has_computed_witness,-- Whether the requirement this row evaluates has a computed witness behind it.
  calc_requirement_satisfactions_is_asserted_only(t.requirement_satisfaction_id) AS is_asserted_only,-- TRUE when a blocking requirement is recorded as Satisfied purely on human assertion, with no computed predicate behind it.
  calc_requirement_satisfactions_asserted_only_execution_key(t.requirement_satisfaction_id) AS asserted_only_execution_key,-- Echoes the grandparent procedure execution id for assertion-only satisfactions.
  calc_requirement_satisfactions_parent_procedure_execution(t.requirement_satisfaction_id) AS parent_procedure_execution,-- The procedure execution this satisfaction ultimately belongs to.
  calc_requirement_satisfactions_step_execution_when_scored(t.requirement_satisfaction_id) AS step_execution_when_scored,-- Echoes the step-execution id when a satisfaction level was actually recorded, blank otherwise.
  calc_requirement_satisfactions_is_human_evaluated(t.requirement_satisfaction_id) AS is_human_evaluated,-- TRUE when a human evaluated this requirement satisfaction.
  calc_requirement_satisfactions_requirement_is_approval_type(t.requirement_satisfaction_id) AS requirement_is_approval_type,-- The requirement's type, e.g. Approval, Control, Privacy.
  calc_requirement_satisfactions_is_invalid_approval(t.requirement_satisfaction_id) AS is_invalid_approval,-- TRUE when an approval-type requirement is not fully satisfied, or was not evaluated by a human.
  calc_requirement_satisfactions_procedure_execution_of_satisfact(t.requirement_satisfaction_id) AS procedure_execution_of_satisfaction,-- The run this satisfaction belongs to.
  calc_requirement_satisfactions_run_when_invalid_approval(t.requirement_satisfaction_id) AS run_when_invalid_approval,-- Echoes the run id when this is an invalid approval, blank otherwise.
  calc_requirement_satisfactions_requirement_is_unfalsified(t.requirement_satisfaction_id) AS requirement_is_unfalsified,-- Whether the requirement behind this satisfaction record has never once returned a negative result.
  calc_requirement_satisfactions_is_clearance_by_unfalsified_cont(t.requirement_satisfaction_id) AS is_clearance_by_unfalsified_control,-- TRUE when this record cleared a step against a blocking control that has never produced a negative outcome.
  calc_requirement_satisfactions_unfalsified_clearance_step_key(t.requirement_satisfaction_id) AS unfalsified_clearance_step_key,-- Echoes the step execution id when this clearance came from an unfalsified control.
  calc_requirement_satisfactions_spec_step_of_execution(t.requirement_satisfaction_id) AS spec_step_of_execution,-- The specification step behind the step execution this satisfaction was recorded against.
  calc_requirement_satisfactions_binding_key(t.requirement_satisfaction_id) AS binding_key,-- The StepRequirements binding this satisfaction record exercised.
  calc_requirement_satisfactions_scored_step_executor_agent(t.requirement_satisfaction_id) AS scored_step_executor_agent,-- The agent who executed the step this satisfaction record scores.
  calc_requirement_satisfactions_evaluator_is_step_executor(t.requirement_satisfaction_id) AS evaluator_is_step_executor,-- TRUE when the agent who scored this control is the same agent who performed the step being scored.
  calc_requirement_satisfactions_run_owner_agent(t.requirement_satisfaction_id) AS run_owner_agent,-- The agent accountable for the whole procedure execution this satisfaction sits inside.
  calc_requirement_satisfactions_evaluator_owns_the_run(t.requirement_satisfaction_id) AS evaluator_owns_the_run,-- TRUE when the agent scoring this control is the agent accountable for the execution it belongs to.
  calc_requirement_satisfactions_is_interested_party_assertion(t.requirement_satisfaction_id) AS is_interested_party_assertion,-- TRUE when a blocking control's only evidence is an assertion made by someone with an interest in the outcome.
  calc_requirement_satisfactions_has_written_evidence(t.requirement_satisfaction_id) AS has_written_evidence,-- TRUE when this satisfaction record carries any evidence text at all.
  calc_requirement_satisfactions_is_bare_assertion(t.requirement_satisfaction_id) AS is_bare_assertion,-- TRUE when a blocking control was cleared with no computed witness and no written justification.
  calc_requirement_satisfactions_interested_assertion_execution_k(t.requirement_satisfaction_id) AS interested_assertion_execution_key,-- Echoes the parent execution id when this record is an interested-party assertion.
  calc_requirement_satisfactions_is_computedly_witnessed(t.requirement_satisfaction_id) AS is_computedly_witnessed,-- TRUE when this record scores a blocking control that has a computed witness behind it.
  calc_requirement_satisfactions_computed_witness_execution_key(t.requirement_satisfaction_id) AS computed_witness_execution_key,-- Echoes the parent execution id when this control was computationally witnessed.
  calc_requirement_satisfactions_step_executor_agent(t.requirement_satisfaction_id) AS step_executor_agent,-- The agent who executed the step this satisfaction record scores.
  calc_requirement_satisfactions_was_scored_after_attestation(t.requirement_satisfaction_id) AS was_scored_after_attestation,-- TRUE when this control was scored after the run it belongs to had already been attested.
  calc_requirement_satisfactions_attestation_instant_for_run(t.requirement_satisfaction_id) AS attestation_instant_for_run,-- When the parent execution was attested, if it has been.
  calc_requirement_satisfactions_post_attestation_score_execution(t.requirement_satisfaction_id) AS post_attestation_score_execution_key,-- Echoes the parent execution id when this control was scored after signature.
  t.semantic_type_iri                                                           -- Exact PKO class IRI.
FROM requirement_satisfactions t;

-- ----------------------------------------------------------------------------
-- vw_errors: Reusable error definitions encountered during execution. Maps to pko:Error, errorCode, and errorCause.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_errors CASCADE;
CREATE VIEW vw_errors WITH (security_invoker = ON) AS
SELECT
  t.error_id,                                                                   -- Stored logical identifier for one Errors row.
  calc_errors_name(t.error_id) AS name,                                         -- Human-readable calculated display alias for the Errors row.
  t.label,                                                                      -- Error label.
  t.error_code,                                                                 -- Error code; maps to pko:errorCode.
  t.error_cause,                                                                -- Known or suspected cause; maps to pko:errorCause.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.description,                                                                -- Error description (dct:description).
  calc_errors_remedy_step_count(t.error_id) AS remedy_step_count,               -- Steps that remedy this error.
  calc_errors_occurrence_count(t.error_id) AS occurrence_count,                 -- Times the error was encountered.
  calc_errors_has_no_remedy_step(t.error_id) AS has_no_remedy_step              -- TRUE when an error has been encountered and no step of any procedure remedies it.
FROM errors t;

-- ----------------------------------------------------------------------------
-- vw_issue_occurrences: Concrete issue events during execution. Maps to pko:IssueOccurrence, hasEncounteredError, wasEncounteredBy, issueCause, and issueSolution.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_issue_occurrences CASCADE;
CREATE VIEW vw_issue_occurrences WITH (security_invoker = ON) AS
SELECT
  t.issue_occurrence_id,                                                        -- Stored logical identifier for one IssueOccurrences row.
  calc_issue_occurrences_name(t.issue_occurrence_id) AS name,                   -- Human-readable calculated display alias for the IssueOccurrences row.
  t.step_execution,                                                             -- Step execution during which the issue occurred.
  t.error,                                                                      -- Error encountered.
  t.encountered_by_agent,                                                       -- Agent that encountered or reported the issue.
  t.occurred_at,                                                                -- Occurrence time.
  t.issue_cause,                                                                -- Execution-specific cause; maps to pko:issueCause.
  t.issue_solution,                                                             -- Applied solution; maps to pko:issueSolution.
  t.status,                                                                     -- Open, Monitoring, Resolved, or Closed.
  calc_issue_occurrences_is_unresolved(t.issue_occurrence_id) AS is_unresolved, -- TRUE when this issue occurrence has not been closed out.
  calc_issue_occurrences_step_execution_when_unresolved(t.issue_occurrence_id) AS step_execution_when_unresolved,-- Echoes the step-execution id when the issue is unresolved, blank otherwise.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  calc_issue_occurrences_executed_step(t.issue_occurrence_id) AS executed_step, -- Step the issue occurred on.
  calc_issue_occurrences_failed_condition_count_on_run(t.issue_occurrence_id) AS failed_condition_count_on_run,-- Conditions that did not hold on the same step execution.
  calc_issue_occurrences_coincided_with_failed_condition(t.issue_occurrence_id) AS coincided_with_failed_condition,-- TRUE when the issue occurred on a step execution where a checked condition did not hold.
  calc_issue_occurrences_has_no_recorded_solution(t.issue_occurrence_id) AS has_no_recorded_solution,-- TRUE when an issue records no solution.
  t.redesign_change_request,                                                    -- The change request that redesigned the procedure in response to the failure.
  calc_issue_occurrences_redesign_implemented_at(t.issue_occurrence_id) AS redesign_implemented_at,-- When that redesign was implemented.
  calc_issue_occurrences_is_failure_without_landed_redesign(t.issue_occurrence_id) AS is_failure_without_landed_redesign,-- TRUE when a recorded failure has no redesign, or its redesign never landed.
  calc_issue_occurrences_improvement_cycle_path(t.issue_occurrence_id) AS improvement_cycle_path-- Failure observed, how it was recorded, and the redesign that followed.
FROM issue_occurrences t;

-- ----------------------------------------------------------------------------
-- vw_user_questions: Questions asked by agents during execution. Maps to pko:UserQuestionOccurrence, questionByUser, wasAskedBy, and isQuestionAddressedBy.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_user_questions CASCADE;
CREATE VIEW vw_user_questions WITH (security_invoker = ON) AS
SELECT
  t.user_question_id,                                                           -- Stored logical identifier for one UserQuestions row.
  calc_user_questions_name(t.user_question_id) AS name,                         -- Human-readable calculated display alias for the UserQuestions row.
  t.step_execution,                                                             -- Execution context for the question.
  t.asked_by_agent,                                                             -- Agent asking the question.
  t.asked_at,                                                                   -- Question time.
  t.question_text,                                                              -- Question text; maps to pko:questionByUser.
  t.resolved_by_faq,                                                            -- FAQ used to resolve the question.
  t.addressed_by_resource,                                                      -- Resource that addressed the question.
  t.status,                                                                     -- Open, Answered, Escalated, or Closed.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  calc_user_questions_is_unaddressed_question(t.user_question_id) AS is_unaddressed_question-- TRUE when a question asked during execution has no resource or FAQ addressing it.
FROM user_questions t;

-- ----------------------------------------------------------------------------
-- vw_user_feedback: Feedback supplied by users about a procedure or execution. Maps to pko:UserFeedbackOccurrence, feedbackOnProcedureExecution, and wasProvidedBy.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_user_feedback CASCADE;
CREATE VIEW vw_user_feedback WITH (security_invoker = ON) AS
SELECT
  t.user_feedback_id,                                                           -- Stored logical identifier for one UserFeedback row.
  calc_user_feedback_name(t.user_feedback_id) AS name,                          -- Human-readable calculated display alias for the UserFeedback row.
  t.procedure_execution,                                                        -- Execution receiving feedback.
  t.provided_by_agent,                                                          -- Agent providing feedback.
  t.provided_at,                                                                -- Feedback time.
  t.feedback_text,                                                              -- Feedback statement.
  t.disposition,                                                                -- Accepted, Rejected, UnderReview, or Deferred.
  t.change_request_key,                                                         -- Related change request identifier.
  t.semantic_type_iri,                                                          -- Exact PKO class IRI.
  t.feedback_on_procedure,                                                      -- Remark about the procedure itself (pko:feedbackOnProcedure).
  t.feedback_on_execution,                                                      -- Remark about this execution (pko:feedbackOnProcedureExecution).
  calc_user_feedback_is_unactioned_procedure_critique(t.user_feedback_id) AS is_unactioned_procedure_critique,-- TRUE when feedback criticizes the procedure and no change request carries it forward.
  t.reveals_tacit_knowledge,                                                    -- TRUE when the feedback surfaces know-how the procedure does not hold.
  calc_user_feedback_collection_follow_up_count(t.user_feedback_id) AS collection_follow_up_count,-- Collected materials this feedback prompted.
  calc_user_feedback_is_tacit_signal_not_fed_into_collection(t.user_feedback_id) AS is_tacit_signal_not_fed_into_collection-- TRUE when feedback that surfaces tacit know-how prompted no collection.
FROM user_feedback t;

-- ----------------------------------------------------------------------------
-- vw_stewardship_assignments: Separates ongoing stewardship from authority to approve semantic commitments. Explicit ERB-PKO governance extension.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_stewardship_assignments CASCADE;
CREATE VIEW vw_stewardship_assignments WITH (security_invoker = ON) AS
SELECT
  t.stewardship_assignment_id,                                                  -- Stored logical identifier for one StewardshipAssignments row.
  calc_stewardship_assignments_name(t.stewardship_assignment_id) AS name,       -- Human-readable calculated display alias for the StewardshipAssignments row.
  t.procedure_version,                                                          -- Governed procedure version.
  t.steward_role,                                                               -- Role responsible for health, review, and maintenance.
  t.authority_role,                                                             -- Role authorized to approve semantic changes.
  t.valid_from,                                                                 -- Start of stewardship interval.
  t.valid_to,                                                                   -- End of stewardship interval.
  t.review_cadence_days,                                                        -- Required review cadence.
  calc_stewardship_assignments_count_of_review_events(t.stewardship_assignment_id) AS count_of_review_events,-- How many review events have ever been recorded for the procedure version this assignment stewards.
  calc_stewardship_assignments_has_ever_been_reviewed(t.stewardship_assignment_id) AS has_ever_been_reviewed,-- TRUE if at least one review event exists for the stewarded procedure version.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_stewardship_assignments_as_of_instant(t.stewardship_assignment_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_stewardship_assignments_is_current_assignment(t.stewardship_assignment_id) AS is_current_assignment,-- TRUE when this stewardship assignment is in force right now.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM stewardship_assignments t;

-- ----------------------------------------------------------------------------
-- vw_change_requests: Governed requests for semantic or operational change, anchored to a procedure version and authority. Explicit ERB-PKO extension.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_requests CASCADE;
CREATE VIEW vw_change_requests WITH (security_invoker = ON) AS
SELECT
  t.change_request_id,                                                          -- Stored logical identifier for one ChangeRequests row.
  calc_change_requests_name(t.change_request_id) AS name,                       -- Human-readable calculated display alias for the ChangeRequests row.
  t.procedure_version,                                                          -- Procedure version affected.
  t.title,                                                                      -- Change title.
  t.change_kind,                                                                -- Defect, Enhancement, NewRequirement, DataOperation, or BreakingChange.
  t.status,                                                                     -- Draft, UnderReview, Approved, Rejected, Implemented, or Closed.
  t.requested_by_agent,                                                         -- Agent requesting the change.
  t.authority_role,                                                             -- Role authorized to approve the change.
  t.requested_at,                                                               -- Request time.
  t.decided_at,                                                                 -- Decision time.
  t.impact_assessment,                                                          -- Expected effect on commitments, data, projections, and tests.
  calc_change_requests_is_open(t.change_request_id) AS is_open,                 -- TRUE while the change request is still outstanding. An Approved request stays open until ImplementedAt records that it actually landed — approval is a decision, not an outcome.
  calc_change_requests_open_change_version_key(t.change_request_id) AS open_change_version_key,-- Echoes the ProcedureVersion id only for change requests still open.
  calc_change_requests_is_decided(t.change_request_id) AS is_decided,           -- TRUE when a decision timestamp has been recorded.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_change_requests_as_of_instant(t.change_request_id) AS as_of_instant,     -- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_change_requests_days_pending(t.change_request_id) AS days_pending,       -- Days from request to decision, or to now if still undecided.
  calc_change_requests_is_still_pending(t.change_request_id) AS is_still_pending,-- TRUE when the request is in an open status and has no decision recorded.
  calc_change_requests_is_stalled(t.change_request_id) AS is_stalled,           -- TRUE when an undecided change request has been pending more than fourteen days.
  calc_change_requests_authority_agent(t.change_request_id) AS authority_agent, -- The agent currently holding the authority role that owes a decision on this request.
  calc_change_requests_requester_is_authority(t.change_request_id) AS requester_is_authority,-- TRUE when the agent who raised the request is also the agent who decides it.
  calc_change_requests_awaits_authority_decision(t.change_request_id) AS awaits_authority_decision,-- TRUE when this request is formally before its authority and no decision has been recorded.
  calc_change_requests_authority_role_label(t.change_request_id) AS authority_role_label,-- Human-readable label of the role that owes a decision.
  calc_change_requests_touches_live_version(t.change_request_id) AS touches_live_version,-- Whether the version this request would alter is currently executable.
  calc_change_requests_is_live_decision_backlog(t.change_request_id) AS is_live_decision_backlog,-- TRUE when a decision I owe is blocking a change to a procedure currently in production.
  calc_change_requests_blocks_an_open_gap(t.change_request_id) AS blocks_an_open_gap,-- TRUE when an undecided request against a live version is the kind that exists to close a known gap.
  t.implemented_at,                                                             -- When the approved change was actually applied to the procedure version. Null until it lands. Distinct from DecidedAt, which records only that the authority ruled. Approval and implementation are separate events; conflating them is what left IsOpen with no terminal state.
  calc_change_requests_backlog_version_key(t.change_request_id) AS backlog_version_key,-- Composite-key echo: this request's procedure version when it is live decision backlog, blank otherwise.
  calc_change_requests_is_my_pending_decision(t.change_request_id) AS is_my_pending_decision,-- A change request awaiting a decision that is mine personally to make.
  calc_change_requests_is_my_blocking_backlog(t.change_request_id) AS is_my_blocking_backlog,-- A decision waiting on me that is holding an open gap on a live procedure.
  calc_change_requests_is_my_overdue_backlog(t.change_request_id) AS is_my_overdue_backlog,-- A blocking decision that has waited on me for more than two weeks.
  calc_change_requests_is_implemented(t.change_request_id) AS is_implemented,   -- Whether the approved change has actually been applied.
  calc_change_requests_is_my_decided_request(t.change_request_id) AS is_my_decided_request,-- A change request I have personally ruled on.
  calc_change_requests_is_my_decided_but_unlanded(t.change_request_id) AS is_my_decided_but_unlanded,-- A decision I have made that has not yet been applied — still counted against me by the loop-1 open-request measure.
  calc_change_requests_decision_latency_days(t.change_request_id) AS decision_latency_days,-- How many days I took to rule, once ruled. Zero when undecided — read only alongside IsDecided.
  calc_change_requests_implementation_latency_days(t.change_request_id) AS implementation_latency_days,-- How many days elapsed between my ruling and the change actually landing. Zero when not yet implemented.
  calc_change_requests_delay_is_downstream_of_me(t.change_request_id) AS delay_is_downstream_of_me,-- A request I decided promptly that is nevertheless still outstanding because nobody has implemented it.
  calc_change_requests_unlanded_version_key(t.change_request_id) AS unlanded_version_key,-- Composite-key echo: this request's procedure version when I have decided it but it has not landed, blank otherwise.
  calc_change_requests_is_approved_not_implemented(t.change_request_id) AS is_approved_not_implemented,-- A change request the authority approved but that has not yet been applied.
  calc_change_requests_days_since_approval(t.change_request_id) AS days_since_approval,-- How many days have elapsed since the authority decided this request. Zero when undecided.
  calc_change_requests_is_stalled_implementation(t.change_request_id) AS is_stalled_implementation,-- An approved change request that has sat unimplemented for more than two weeks.
  calc_change_requests_stalled_implementation_version_key(t.change_request_id) AS stalled_implementation_version_key,-- Composite-key echo: this request's procedure version when its implementation is stalled, blank otherwise.
  calc_change_requests_approved_version_key(t.change_request_id) AS approved_version_key,-- Echoes the target version id when this change request was approved.
  calc_change_requests_is_approved_decision(t.change_request_id) AS is_approved_decision,-- TRUE when this change request was decided in the affirmative.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  calc_change_requests_owner_organization(t.change_request_id) AS owner_organization-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
FROM change_requests t;

-- ----------------------------------------------------------------------------
-- vw_review_events: Periodic governance reviews that test competency coverage, staleness, and semantic integrity. Explicit ERB-PKO extension represented as prov:Activity.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_review_events CASCADE;
CREATE VIEW vw_review_events WITH (security_invoker = ON) AS
SELECT
  t.review_event_id,                                                            -- Stored logical identifier for one ReviewEvents row.
  calc_review_events_name(t.review_event_id) AS name,                           -- Human-readable calculated display alias for the ReviewEvents row.
  t.procedure_version,                                                          -- Reviewed procedure version.
  t.review_kind,                                                                -- Review type.
  t.reviewed_at,                                                                -- Review timestamp.
  t.reviewed_by_agent,                                                          -- Reviewing agent.
  t.outcome,                                                                    -- Passed, PassedWithChange, Failed, or Deferred.
  t.related_change_request,                                                     -- Change request produced or considered.
  t.next_review_due,                                                            -- Next required review.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_review_events_as_of_instant(t.review_event_id) AS as_of_instant,         -- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_review_events_is_overdue(t.review_event_id) AS is_overdue,               -- TRUE when review is overdue.
  calc_review_events_overdue_version_key(t.review_event_id) AS overdue_version_key,-- Echoes the ProcedureVersion id only when this review is past its next-due date.
  calc_review_events_promised_cadence_days(t.review_event_id) AS promised_cadence_days,-- The review cadence promised for this procedure version, resolved via ProcedureVersions because INDEX/MATCH can only match a target table primary key.
  calc_review_events_days_since_reviewed(t.review_event_id) AS days_since_reviewed,-- Elapsed days since this review actually happened.
  calc_review_events_exceeds_promised_cadence(t.review_event_id) AS exceeds_promised_cadence,-- TRUE when more days have elapsed since this review than the stewardship assignment promised as a cadence.
  calc_review_events_cadence_drift_days(t.review_event_id) AS cadence_drift_days,-- Signed drift: positive means we are past the promised cadence by this many days; negative means we are still inside it.
  calc_review_events_promise_and_behavior_disagree(t.review_event_id) AS promise_and_behavior_disagree,-- TRUE when the promised cadence has been blown but the hand-entered NextReviewDue still says we are fine.
  calc_review_events_cadence_breach_version_key(t.review_event_id) AS cadence_breach_version_key,-- Composite-key echo: this review event's procedure version when the promised cadence has been exceeded, blank otherwise.
  t.semantic_type_iri,                                                          -- Class IRI used in projection.
  calc_review_events_version_modified_at(t.review_event_id) AS version_modified_at,-- Last-modified date of the reviewed version.
  calc_review_events_review_did_not_refresh_modified(t.review_event_id) AS review_did_not_refresh_modified-- TRUE when a review happened after the version's last-modified date, so the review never refreshed it.
FROM review_events t;

-- ----------------------------------------------------------------------------
-- vw_learning_activities: Learning, retrospective, tabletop, and onboarding activities that convert execution experience into maintained knowledge. Explicit ERB-PKO extension represented as prov:Activity.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_learning_activities CASCADE;
CREATE VIEW vw_learning_activities WITH (security_invoker = ON) AS
SELECT
  t.learning_activity_id,                                                       -- Stored logical identifier for one LearningActivities row.
  calc_learning_activities_name(t.learning_activity_id) AS name,                -- Human-readable calculated display alias for the LearningActivities row.
  t.community_of_practice,                                                      -- Community hosting the activity.
  t.procedure_version,                                                          -- Procedure version practiced or reviewed.
  t.activity_kind,                                                              -- Retrospective, TabletopExercise, Onboarding, Drill, or Apprenticeship.
  t.occurred_at,                                                                -- Activity time.
  t.facilitator_agent,                                                          -- Facilitator.
  t.outcome,                                                                    -- Knowledge or competence produced.
  t.evidence_resource,                                                          -- Evidence or material produced.
  t.semantic_type_iri                                                           -- Class IRI used in projection.
FROM learning_activities t;

-- ----------------------------------------------------------------------------
-- vw_operational_bindings: Live bindings between procedural semantics and operational data/resources. Explicit ERB-PKO extension using DCAT/DCMI/PROV identifiers.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_operational_bindings CASCADE;
CREATE VIEW vw_operational_bindings WITH (security_invoker = ON) AS
SELECT
  t.operational_binding_id,                                                     -- Stored logical identifier for one OperationalBindings row.
  calc_operational_bindings_name(t.operational_binding_id) AS name,             -- Human-readable calculated display alias for the OperationalBindings row.
  t.procedure_version,                                                          -- Procedure version using the binding.
  t.step,                                                                       -- Step using the binding.
  t.resource,                                                                   -- Bound operational resource.
  t.access_mode,                                                                -- Read, Write, ReadWrite, Subscribe, or Publish.
  t.record_or_schema_key,                                                       -- Operational record, table, event, or schema key.
  t.last_observed_at,                                                           -- Most recent successful observation.
  t.freshness_sla_minutes,                                                      -- Maximum allowed data age.
  t.is_authoritative,                                                           -- TRUE when the binding is authoritative for the represented fact.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_operational_bindings_as_of_instant(t.operational_binding_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_operational_bindings_age_minutes(t.operational_binding_id) AS age_minutes,-- Current observed age.
  calc_operational_bindings_is_fresh(t.operational_binding_id) AS is_fresh,     -- TRUE when within freshness SLA.
  calc_operational_bindings_stale_binding_step_key(t.operational_binding_id) AS stale_binding_step_key,-- Echoes the bound Step id only when the binding is outside its freshness SLA.
  calc_operational_bindings_authoritative_stale_step_key(t.operational_binding_id) AS authoritative_stale_step_key,-- Echoes the bound Step id only when an AUTHORITATIVE binding is stale.
  calc_operational_bindings_is_stale_and_authoritative(t.operational_binding_id) AS is_stale_and_authoritative,-- TRUE when an authoritative binding has aged past its freshness SLA.
  calc_operational_bindings_step_when_stale(t.operational_binding_id) AS step_when_stale,-- Echoes the step id when this authoritative binding is stale, blank otherwise.
  calc_operational_bindings_resource_is_approved(t.operational_binding_id) AS resource_is_approved,-- Whether the resource behind this binding is an approved source.
  calc_operational_bindings_is_usable_for_drafting(t.operational_binding_id) AS is_usable_for_drafting,-- TRUE when this binding points at an approved source that is still inside its freshness SLA.
  calc_operational_bindings_step_when_unusable(t.operational_binding_id) AS step_when_unusable,-- Echoes the step id when this binding is NOT usable for drafting, blank otherwise.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM operational_bindings t;

-- ----------------------------------------------------------------------------
-- vw_communication_policies: Channel-specific communication policy projected from the same canonical procedure. Uses ODRL-style policy semantics plus ERB-PKO channel constraints.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_communication_policies CASCADE;
CREATE VIEW vw_communication_policies WITH (security_invoker = ON) AS
SELECT
  t.communication_policy_id,                                                    -- Stored logical identifier for one CommunicationPolicies row.
  calc_communication_policies_name(t.communication_policy_id) AS name,          -- Human-readable calculated display alias for the CommunicationPolicies row.
  t.procedure_version,                                                          -- Procedure version governing the channel.
  t.channel,                                                                    -- Email, SMS, Push, Postal, or another declared channel.
  t.audience_rule,                                                              -- Rule that identifies eligible recipients.
  t.consent_required,                                                           -- Whether active consent is required.
  t.quiet_hours_start,                                                          -- Recipient-local quiet-hours start.
  t.quiet_hours_end,                                                            -- Recipient-local quiet-hours end.
  t.max_message_length,                                                         -- Maximum message length for one unit.
  t.max_segments,                                                               -- Maximum number of channel segments.
  t.retention_days,                                                             -- Retention period for rendered messages and delivery records.
  t.approval_role,                                                              -- Role approving the channel policy.
  t.required_content,                                                           -- Content that every message must include.
  t.authority_statement,                                                        -- Which artifact is authoritative.
  t.status,                                                                     -- Draft, Active, Suspended, or Retired.
  calc_communication_policies_consent_violation_count(t.communication_policy_id) AS consent_violation_count,-- Number of consent violations attributable to this channel policy.
  t.quiet_hours_start_hour,                                                     -- The hour (0-23) at which the quiet window opens. Stored rather than parsed from QuietHoursStart: VALUE(LEFT(...)) does not translate — the transpiler casts the "20:00" string to a timestamp and the view errors. The sending system already knows this number, so modeling it as a parse would dress a broken derivation up as a rule.
  t.quiet_hours_end_hour,                                                       -- Numeric hour 0-23 at which quiet hours end. Seeded 8 for comm-sms-policy, 0 for comm-email-policy.
  calc_communication_policies_quiet_hours_violation_count(t.communication_policy_id) AS quiet_hours_violation_count,-- Number of transmitted messages that breached this policy's quiet-hours window.
  t.required_opt_out_phrase,                                                    -- The exact opt-out phrase every message on this channel must contain. Seeded 'Reply STOP' for comm-sms-policy, empty string for comm-email-policy.
  calc_communication_policies_is_active_policy(t.communication_policy_id) AS is_active_policy,-- TRUE only when this channel policy is in Active status.
  t.semantic_type_iri                                                           -- ODRL Policy class IRI.
FROM communication_policies t;

-- ----------------------------------------------------------------------------
-- vw_message_templates: Approved channel templates projected from the canonical rulebook without becoming a second source of policy meaning.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_message_templates CASCADE;
CREATE VIEW vw_message_templates WITH (security_invoker = ON) AS
SELECT
  t.message_template_id,                                                        -- Stored logical identifier for one MessageTemplates row.
  calc_message_templates_name(t.message_template_id) AS name,                   -- Human-readable calculated display alias for the MessageTemplates row.
  t.communication_policy,                                                       -- Channel policy governing the template.
  t.resource,                                                                   -- Template resource.
  t.subject_template,                                                           -- Subject template where supported.
  t.body_template,                                                              -- Body template.
  t.locale,                                                                     -- Locale or language tag.
  t.status,                                                                     -- Draft, Approved, Retired, or Superseded.
  calc_message_templates_policy_max_message_length(t.message_template_id) AS policy_max_message_length,-- Per-segment character limit inherited from the governing channel policy.
  calc_message_templates_policy_max_segments(t.message_template_id) AS policy_max_segments,-- Maximum permitted segment count from the governing channel policy.
  calc_message_templates_body_template_length(t.message_template_id) AS body_template_length,-- Character length of the raw template body before variable substitution.
  calc_message_templates_is_template_over_length(t.message_template_id) AS is_template_over_length,-- TRUE when the template body alone already exceeds the single-segment limit before any variables are substituted in.
  calc_message_templates_valid_approval_count(t.message_template_id) AS valid_approval_count,-- Number of properly-authorized approvals on record for this template.
  calc_message_templates_has_valid_approval(t.message_template_id) AS has_valid_approval,-- TRUE when at least one properly-authorized approval exists for this template.
  calc_message_templates_is_claiming_unbacked_approval(t.message_template_id) AS is_claiming_unbacked_approval,-- TRUE when a template's Status says Approved but no properly-authorized approval record backs it. The phantom-approval witness.
  t.current_body_hash,                                                          -- Digest of the template's current body text, maintained whenever the body is edited.
  calc_message_templates_last_approved_body_hash(t.message_template_id) AS last_approved_body_hash,-- Digest of the body text as it stood at the most recent valid approval.
  t.last_valid_approval,                                                        -- The TemplateApprovals id of the approval this template is currently sendable under. Deliberately a raw identifier, not a relationship: TemplateApprovals already points at MessageTemplates, so declaring an FK back would make the two tables mutually dependent and the rulebook is required to stay acyclic. The value is still resolved by INDEX/MATCH in LastApprovedBodyHash.
  calc_message_templates_has_body_drifted(t.message_template_id) AS has_body_drifted,-- TRUE when the template body no longer matches what was approved.
  calc_message_templates_is_sendable_under_approval(t.message_template_id) AS is_sendable_under_approval,-- TRUE only when the template is marked Approved, has a properly-authorized approval, AND its body still matches what was approved.
  calc_message_templates_drifted_send_count(t.message_template_id) AS drifted_send_count,-- How many messages went out from this template while it was not validly sendable.
  calc_message_templates_unanswered_delivery_count(t.message_template_id) AS unanswered_delivery_count,-- How many transmitted messages from this template drew no acknowledgement.
  calc_message_templates_transmitted_delivery_count(t.message_template_id) AS transmitted_delivery_count,-- How many deliveries using this template were actually transmitted.
  calc_message_templates_template_draws_no_response(t.message_template_id) AS template_draws_no_response,-- TRUE when every transmitted message from this template went unacknowledged.
  calc_message_templates_last_approval_at(t.message_template_id) AS last_approval_at,-- When this template's currently-governing approval was decided.
  t.semantic_type_iri                                                           -- Resource class IRI.
FROM message_templates t;

-- ----------------------------------------------------------------------------
-- vw_semantic_mappings: Machine-readable alignment from ERB table/field paths to exact PKO or reused ontology terms. Extension mappings are never presented as native PKO.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_semantic_mappings CASCADE;
CREATE VIEW vw_semantic_mappings WITH (security_invoker = ON) AS
SELECT
  t.semantic_mapping_id,                                                        -- Stored logical identifier for one SemanticMappings row.
  calc_semantic_mappings_name(t.semantic_mapping_id) AS name,                   -- Human-readable calculated display alias for the SemanticMappings row.
  t.source_path,                                                                -- ERB table, field, or discriminator path.
  t.mapping_kind,                                                               -- class, objectProperty, datatypeProperty, individual, or rule.
  t.target_iri,                                                                 -- Exact target semantic IRI.
  t.mapping_relation,                                                           -- exact, aligned, subclass, subproperty, or extension.
  t.ontology_profile,                                                           -- Versioned ontology profile containing the target term.
  calc_semantic_mappings_profile_namespace_dereferences(t.semantic_mapping_id) AS profile_namespace_dereferences,-- Whether the profile's namespace answered when it was last fetched.
  t.notes,                                                                      -- Mapping semantics and boundaries.
  t.available_standard_iri,                                                     -- A term in a reused standard that already means what this extension term means.
  calc_semantic_mappings_reinvents_standard_term(t.semantic_mapping_id) AS reinvents_standard_term,-- TRUE when an extension term was minted although a reused standard already has one.
  calc_semantic_mappings_is_non_resolvable_term_iri(t.semantic_mapping_id) AS is_non_resolvable_term_iri-- The term cannot be looked up: either its IRI is not an HTTP URI, or the namespace it lives in did not answer when it was last fetched. Measured, not inferred from the IRI's spelling.
FROM semantic_mappings t;

-- ----------------------------------------------------------------------------
-- vw_witness_loops: One row per role-question expansion loop. Each loop poses questions that only became askable because of the previous loop's predicates.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_witness_loops CASCADE;
CREATE VIEW vw_witness_loops WITH (security_invoker = ON) AS
SELECT
  t.witness_loop_id,                                                            -- Stored logical identifier for one WitnessLoops row.
  calc_witness_loops_name(t.witness_loop_id) AS name,                           -- Human-readable calculated display alias for the WitnessLoops row.
  t.loop_number,                                                                -- Ordinal of this expansion loop. Loop 1 is the founding set of role questions.
  t.title,                                                                      -- Short title for what this loop set out to make askable.
  t.premise,                                                                    -- Why this loop's questions became askable. For loop N>1 this names the loop N-1 predicates that made them possible.
  t.started_at,                                                                 -- Time this loop began.
  t.completed_at,                                                               -- Time this loop was committed. Null while in progress.
  calc_witness_loops_question_count(t.witness_loop_id) AS question_count,       -- How many role questions were posed in this loop.
  calc_witness_loops_is_complete(t.witness_loop_id) AS is_complete,             -- TRUE once the loop has been committed.
  t.fields_after,                                                               -- Total fields in the rulebook after this loop completed.
  t.derived_after,                                                              -- Derived fields after this loop completed.
  t.witnessed_after,                                                            -- Fields invented for a role question after this loop completed.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM witness_loops t;

-- ----------------------------------------------------------------------------
-- vw_role_questions: One row per question a named role wants answered. Every invented predicate in this rulebook traces back to one of these.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_questions CASCADE;
CREATE VIEW vw_role_questions WITH (security_invoker = ON) AS
SELECT
  t.role_question_id,                                                           -- Stored logical identifier for one RoleQuestions row.
  calc_role_questions_name(t.role_question_id) AS name,                         -- Human-readable calculated display alias for the RoleQuestions row.
  t.asking_role,                                                                -- The role that wants this question answered.
  t.witness_loop,                                                               -- The expansion loop in which this question was posed.
  t.question_text,                                                              -- The question in the role's own words.
  t.why_it_matters,                                                             -- What goes wrong in the real world when this question cannot be answered.
  t.answerable_before,                                                          -- TRUE if the model could already answer this before its loop ran. FALSE means the loop had to invent predicates for it.
  calc_role_questions_predicate_count(t.role_question_id) AS predicate_count,   -- How many fields were invented to answer this question.
  calc_role_questions_is_answered(t.role_question_id) AS is_answered,           -- TRUE when at least one predicate exists to answer this question.
  t.witnessed_answer,                                                           -- The current reading of this question's predicates, extracted from the substrate after the loop ran: which witness columns fire, on how many rows out of how many. Written by tools/extract_computed_answers.py from values Postgres computed — never recomputed in Python. This is what lets a later loop plan against materialized answers instead of imagined ones.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM role_questions t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_fields: A complete census of every field in this rulebook. Reconciled from the real schemas by tools/reconcile_field_catalog.py — never hand-maintained. Fields invented by a witness loop carry an InventedForQuestion FK.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_fields CASCADE;
CREATE VIEW vw_rulebook_fields WITH (security_invoker = ON) AS
SELECT
  t.rulebook_field_id,                                                          -- Stored logical identifier for one RulebookFields row. Formed as <TargetTable>.<FieldName>.
  calc_rulebook_fields_name(t.rulebook_field_id) AS name,                       -- Human-readable calculated display alias for the RulebookFields row.
  t.target_table,                                                               -- The table this field lives on.
  t.field_name,                                                                 -- The field's name within its table.
  t.field_type,                                                                 -- raw, calculated, lookup, relationship, or aggregation.
  t.datatype,                                                                   -- The field's declared datatype.
  t.formula,                                                                    -- The field's formula when it is derived. Null for raw and relationship fields.
  t.related_to,                                                                 -- For a relationship field, the table it points at. Structural catalog metadata beside FieldType and Datatype; the published vocabulary reads it to give each object property its range.
  t.invented_for_question,                                                      -- The role question that motivated this field's existence. Null for fields that predate the witness-loop exercise.
  calc_rulebook_fields_is_derived(t.rulebook_field_id) AS is_derived,           -- TRUE when this field is computed rather than stored.
  calc_rulebook_fields_is_witness(t.rulebook_field_id) AS is_witness,           -- TRUE when this field exists because a role asked a question. These are the fields the witness loops added.
  calc_rulebook_fields_disagreeing_substrate_count(t.rulebook_field_id) AS disagreeing_substrate_count,-- How many substrates computed this field differently from the answer key in the latest conformance run. 0 means every substrate agreed.
  calc_rulebook_fields_is_substrate_contested(t.rulebook_field_id) AS is_substrate_contested,-- True when at least one substrate disagrees about this field's values.
  t.measured_substantive_count,                                                 -- Rows of this field's vw_* column holding a substantive value (not blank, false or zero), measured in Postgres by tools/measure_catalog.py.
  t.measured_distinct_value_count,                                              -- Distinct values of this field's vw_* column, with blank counted as one value, measured in Postgres.
  calc_rulebook_fields_has_measured_data(t.rulebook_field_id) AS has_measured_data,-- TRUE when Postgres holds at least one substantive value (not blank, false or zero) for this field.
  calc_rulebook_fields_is_discriminating(t.rulebook_field_id) AS is_discriminating,-- TRUE when the field takes at least two distinct values over the seed data, so it can tell rows apart. An all-true or all-false witness states nothing.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM rulebook_fields t;

-- ----------------------------------------------------------------------------
-- vw_test_suites: Groups of conformance checks. Rollups here are computed from TestCases, so the board's headline is itself a derived field.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_test_suites CASCADE;
CREATE VIEW vw_test_suites WITH (security_invoker = ON) AS
SELECT
  t.test_suite_id,                                                              -- Stored logical identifier for one TestSuites row.
  calc_test_suites_name(t.test_suite_id) AS name,                               -- Human-readable calculated display alias for the TestSuites row.
  t.label,                                                                      -- Display name for this suite.
  calc_test_suites_test_count(t.test_suite_id) AS test_count,                   -- How many checks belong to this suite.
  calc_test_suites_pass_count(t.test_suite_id) AS pass_count,                   -- How many checks passed on the last run.
  calc_test_suites_blocking_fail_count(t.test_suite_id) AS blocking_fail_count, -- How many blocking checks failed. This is the number that must be zero for the board to be green.
  calc_test_suites_is_green(t.test_suite_id) AS is_green,                       -- TRUE when no blocking check is failing. Advisory warnings do not break the board.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM test_suites t;

-- ----------------------------------------------------------------------------
-- vw_test_cases: The conformance suite, as data. One row per check, naming what it checks and — where applicable — the role question whose answer it defends. tools/run_test_suite.py executes these rows and writes the outcome back; it invents no checks of its own.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_test_cases CASCADE;
CREATE VIEW vw_test_cases WITH (security_invoker = ON) AS
SELECT
  t.test_case_id,                                                               -- Stored logical identifier for one TestCases row.
  calc_test_cases_name(t.test_case_id) AS name,                                 -- Human-readable calculated display alias for the TestCases row.
  t.test_kind,                                                                  -- What class of check this is. One of: structural (the rulebook's own shape), formula-translates (the transpiler emitted a real function, not a NULL stub), view-loads (the view exists and is queryable), fk-resolves (every FK value names a real row), witness-discriminates (a boolean witness can distinguish cases in this data), witness-fires (a specific witness reads TRUE on at least one row), provenance (every invented field traces to a question), catalog-sync (RulebookFields matches the real schemas), question-answered (a role question has at least one predicate answering it), invariant (a domain rule that must hold), remediation (a seeded violation was resolved in model rather than deleted).
  t.subject,                                                                    -- What is under test — a Table.Field, a table, a view, or a question id.
  t.target_table,                                                               -- The table this check reads, when it reads one.
  t.target_field,                                                               -- The field this check reads, when it reads one.
  t.assertion,                                                                  -- What must be true, stated so a human can judge the verdict without reading code.
  t.defends_question,                                                           -- The role question whose answer this check protects. Null for checks that defend the model's structure rather than a specific question.
  t.suite,                                                                      -- The suite this check belongs to.
  t.severity,                                                                   -- blocking — a failure means the model is stating something false; advisory — a failure means the model cannot state something it should be able to. Vacuity is advisory by design: a witness that cannot fire on this seed is not necessarily wrong, and forcing it red would create pressure to fabricate data.
  calc_test_cases_is_blocking(t.test_case_id) AS is_blocking,                   -- TRUE when a failure of this check means the model is asserting something false.
  t.last_outcome,                                                               -- PASS, WARN, FAIL, or SKIP from the most recent run. Written by tools/run_test_suite.py from the substrate — never hand-edited.
  t.last_detail,                                                                -- The observed reading behind LastOutcome, e.g. a fire count or the error text.
  t.last_run_at,                                                                -- When this check last ran.
  calc_test_cases_is_passing(t.test_case_id) AS is_passing,                     -- TRUE when the last run passed outright.
  calc_test_cases_is_failing(t.test_case_id) AS is_failing,                     -- TRUE when the last run failed. A blocking failure means the model is asserting something false.
  calc_test_cases_needs_attention(t.test_case_id) AS needs_attention,           -- TRUE when this check failed and its failure means the model is wrong. This is the number that must be zero.
  calc_test_cases_passing_suite_key(t.test_case_id) AS passing_suite_key,       -- Echoes the suite id only for checks that passed; empty otherwise. Single-criterion COUNTIFS key.
  calc_test_cases_needs_attention_suite_key(t.test_case_id) AS needs_attention_suite_key,-- Echoes the suite id only for blocking checks that failed; empty otherwise. Single-criterion COUNTIFS key.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM test_cases t;

-- ----------------------------------------------------------------------------
-- vw_exception_invocations: ExceptionInvocations (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_exception_invocations CASCADE;
CREATE VIEW vw_exception_invocations WITH (security_invoker = ON) AS
SELECT
  t.exception_invocation_id,                                                    -- Stored logical identifier for one ExceptionInvocations row.
  calc_exception_invocations_name(t.exception_invocation_id) AS name,           -- Human-readable calculated display alias.
  t.step_execution,                                                             -- The execution during which the exception was invoked.
  t.exception,                                                                  -- The specified exception that was invoked.
  t.invoked_by_agent,                                                           -- Agent who invoked the exception.
  t.approved_by_agent,                                                          -- Agent who approved the invocation. Must satisfy the exception's ApprovalRole.
  t.invoked_at,                                                                 -- When the exception was invoked.
  t.handling_applied,                                                           -- What was actually done, in the invoker's words.
  calc_exception_invocations_expected_handling(t.exception_invocation_id) AS expected_handling,-- The handling the specification prescribes.
  calc_exception_invocations_required_approval_role(t.exception_invocation_id) AS required_approval_role,-- The role the specification requires to approve this exception.
  calc_exception_invocations_required_approval_role_holder(t.exception_invocation_id) AS required_approval_role_holder,-- The agent who currently holds the role that must approve this exception.
  calc_exception_invocations_approval_role_matches(t.exception_invocation_id) AS approval_role_matches,-- TRUE when the agent who approved is the holder of the role the exception requires.
  calc_exception_invocations_is_approved(t.exception_invocation_id) AS is_approved,-- TRUE when an approver was recorded at all.
  calc_exception_invocations_is_improperly_approved(t.exception_invocation_id) AS is_improperly_approved,-- TRUE when an exception was invoked without an approver, or approved by an agent who does not hold the required role.
  calc_exception_invocations_invoker_agent_kind(t.exception_invocation_id) AS invoker_agent_kind,-- What kind of agent invoked the exception.
  calc_exception_invocations_invoker_also_prepared_key(t.exception_invocation_id) AS invoker_also_prepared_key,-- Composite execution+approver key, in the same key space as StepExecutions.PreparerAgentKey.
  calc_exception_invocations_parent_procedure_execution(t.exception_invocation_id) AS parent_procedure_execution,-- The procedure execution this invocation belongs to.
  calc_exception_invocations_approver_prepared_count(t.exception_invocation_id) AS approver_prepared_count,-- How many preparation steps in the same execution were run by the agent who approved this exception.
  calc_exception_invocations_delegated_to_preparer(t.exception_invocation_id) AS delegated_to_preparer,-- TRUE when an exception routed approval authority to an agent who prepared work in the same execution.
  calc_exception_invocations_is_ungoverned_invocation(t.exception_invocation_id) AS is_ungoverned_invocation,-- TRUE when an exception was invoked without proper role authority, or routed authority to the preparer.
  t.semantic_type_iri                                                           -- Extension IRI — PKO does not define exception invocation.
FROM exception_invocations t;

-- ----------------------------------------------------------------------------
-- vw_verification_outcomes: VerificationOutcomes (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_verification_outcomes CASCADE;
CREATE VIEW vw_verification_outcomes WITH (security_invoker = ON) AS
SELECT
  t.verification_outcome_id,                                                    -- Stored logical identifier for one VerificationOutcomes row.
  calc_verification_outcomes_name(t.verification_outcome_id) AS name,           -- Human-readable calculated display alias.
  t.step_execution,                                                             -- The execution during which the verification was performed.
  t.step_verification,                                                          -- The declared verification being performed.
  t.observed_signal_value,                                                      -- The value the signal actually read at verification time.
  t.observed_by_agent,                                                          -- Agent who observed the signal.
  t.observed_at,                                                                -- When the signal was observed.
  t.evidence_uri,                                                               -- Pointer to the retained artifact backing the observation.
  calc_verification_outcomes_expected_signal_value(t.verification_outcome_id) AS expected_signal_value,-- The value the specification expects.
  calc_verification_outcomes_signal_identifier(t.verification_outcome_id) AS signal_identifier,-- Which signal this outcome concerns.
  calc_verification_outcomes_signal_matches_expected(t.verification_outcome_id) AS signal_matches_expected,-- TRUE when the observed value equals the expected value.
  calc_verification_outcomes_has_evidence(t.verification_outcome_id) AS has_evidence,-- TRUE when a retained artifact backs this observation.
  calc_verification_outcomes_is_unbacked_observation(t.verification_outcome_id) AS is_unbacked_observation,-- TRUE when a verification was recorded as matching but no evidence artifact was retained.
  calc_verification_outcomes_is_self_witnessed(t.verification_outcome_id) AS is_self_witnessed,-- TRUE when the agent who observed the verification signal is the same agent who executed the step being verified.
  calc_verification_outcomes_step_executor_agent(t.verification_outcome_id) AS step_executor_agent,-- The agent who executed the step this verification outcome concerns.
  calc_verification_outcomes_self_witnessed_step_key(t.verification_outcome_id) AS self_witnessed_step_key,-- Echoes the StepExecution id only for self-witnessed verifications.
  calc_verification_outcomes_unbacked_step_key(t.verification_outcome_id) AS unbacked_step_key,-- Echoes the StepExecution id when a verification matched but retained no evidence.
  calc_verification_outcomes_is_self_witnessed_and_unbacked(t.verification_outcome_id) AS is_self_witnessed_and_unbacked,-- TRUE when the executor observed their own passing signal and attached no evidence.
  calc_verification_outcomes_is_uncorroborated_pass(t.verification_outcome_id) AS is_uncorroborated_pass,-- TRUE when a PASSING signal was self-observed with no evidence behind it.
  calc_verification_outcomes_uncorroborated_pass_step_key(t.verification_outcome_id) AS uncorroborated_pass_step_key,-- Echoes the step execution id when this outcome is an uncorroborated pass.
  calc_verification_outcomes_observer_is_non_human(t.verification_outcome_id) AS observer_is_non_human,-- Whether the agent who recorded this observation is non-human. Agents has no PrimaryRole column and an FK from Agents back to Roles would create a table cycle, so the independence question is answered by agent kind rather than by role.
  calc_verification_outcomes_observer_is_independent_of_executor(t.verification_outcome_id) AS observer_is_independent_of_executor,-- TRUE when someone other than the step's executor recorded the observation.
  calc_verification_outcomes_is_independent_human_observation(t.verification_outcome_id) AS is_independent_human_observation,-- TRUE when a human other than the step's executor observed this signal and attached evidence.
  calc_verification_outcomes_independent_observation_execution_ke(t.verification_outcome_id) AS independent_observation_execution_key,-- Echoes the parent execution id when this is an independent human observation.
  calc_verification_outcomes_parent_procedure_execution_of_outcom(t.verification_outcome_id) AS parent_procedure_execution_of_outcome,-- The procedure execution this verification outcome belongs to.
  t.semantic_type_iri                                                           -- Extension IRI — PKO 2.0.0 has no execution-side verification outcome class.
FROM verification_outcomes t;

-- ----------------------------------------------------------------------------
-- vw_observed_transitions: The proxy above cannot tell a walked fallback from a happy-path step that happens to share an endpoint. PKO models Transition as a first-class thing; its execution counterpart is missing. Without a table that records WHICH transition a step execution arrived by, 'has this fallback ever been walked' is permanently unanswerable rather than merely unanswered. This is an extension (https://effortlessapi.github.io/effortless-rulebooks/ns/pko-extension#ObservedTransition), not a native PKO term.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_observed_transitions CASCADE;
CREATE VIEW vw_observed_transitions WITH (security_invoker = ON) AS
SELECT
  t.observed_transition_id,                                                     -- Stored logical identifier for one ObservedTransitions row.
  calc_observed_transitions_name(t.observed_transition_id) AS name,             -- Human-readable calculated display alias.
  t.procedure_execution,                                                        -- The procedure execution during which this transition was traversed.
  t.step_transition,                                                            -- The specification-level transition that was actually taken.
  t.arriving_step_execution,                                                    -- The step execution that this traversal produced.
  t.observed_at,                                                                -- When the traversal occurred.
  t.trigger_reason,                                                             -- Why this path rather than the default was taken.
  t.semantic_type_iri                                                           -- Extension class IRI.
FROM observed_transitions t;

-- ----------------------------------------------------------------------------
-- vw_recipients: Recipients (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_recipients CASCADE;
CREATE VIEW vw_recipients WITH (security_invoker = ON) AS
SELECT
  t.recipient_id,                                                               -- Stored logical identifier for one Recipients row.
  calc_recipients_name(t.recipient_id) AS name,                                 -- Human-readable calculated display alias for the Recipients row.
  t.display_name,                                                               -- Employee display name as carried in the consent registry.
  t.organization,                                                               -- Organization the recipient belongs to.
  t.email_address,                                                              -- Corporate email address; empty string when the recipient has no valid corporate email.
  t.mobile_number,                                                              -- Mobile number in E.164 form; empty string when no mobile number is on file.
  t.sms_consent_status,                                                         -- Consent state as observed in the consent registry: Granted, Revoked, or NeverGiven.
  t.sms_consent_at,                                                             -- Timestamp at which the current SMS consent state took effect.
  t.consent_binding,                                                            -- Operational binding through which this consent state was observed.
  calc_recipients_has_sms_consent(t.recipient_id) AS has_sms_consent,           -- TRUE only when the recipient's SMS consent state is Granted.
  calc_recipients_is_email_reachable(t.recipient_id) AS is_email_reachable,     -- TRUE when a corporate email address is on file for this recipient.
  calc_recipients_is_sms_reachable(t.recipient_id) AS is_sms_reachable,         -- TRUE when a mobile number is on file for this recipient.
  calc_recipients_is_unreachable(t.recipient_id) AS is_unreachable,             -- TRUE when the recipient has neither an email address nor a mobile number -- the exc-unreachable trigger condition.
  calc_recipients_is_communicationally_stranded(t.recipient_id) AS is_communicationally_stranded,-- TRUE when every channel we hold for this person is either non-consenting or unreachable, so no lawful route exists at all.
  t.semantic_type_iri                                                           -- Extension IRI; recipients are not a PKO 2.0.0 native class.
FROM recipients t;

-- ----------------------------------------------------------------------------
-- vw_message_deliveries: MessageDeliveries (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_message_deliveries CASCADE;
CREATE VIEW vw_message_deliveries WITH (security_invoker = ON) AS
SELECT
  t.message_delivery_id,                                                        -- Stored logical identifier for one MessageDeliveries row.
  calc_message_deliveries_name(t.message_delivery_id) AS name,                  -- Human-readable calculated display alias for the MessageDeliveries row.
  t.procedure_execution,                                                        -- The procedure execution this send was performed under.
  t.step_execution,                                                             -- The step execution that performed the send.
  t.recipient,                                                                  -- Who the message was sent to.
  t.message_template,                                                           -- Template that was rendered for this send.
  t.sent_by_agent,                                                              -- Agent that performed the send.
  t.rendered_body,                                                              -- The exact body text that was transmitted, after variable substitution.
  t.sent_at,                                                                    -- Transmission timestamp.
  t.sent_at_local_hour,                                                         -- Hour of day 0-23 in the RECIPIENT's local timezone at transmission. Stored raw because recipient-local time is what the quiet-hours rule is written against and it is not derivable from SentAt alone.
  t.delivery_status,                                                            -- Sent, Delivered, Failed, Suppressed, or Bounced.
  t.suppression_reason,                                                         -- When DeliveryStatus is Suppressed, why; empty string otherwise.
  t.invoked_exception,                                                          -- Documented exception invoked for this delivery, when one was.
  t.acknowledged_at,                                                            -- When the recipient acknowledged; null when not acknowledged.
  calc_message_deliveries_policy_channel(t.message_delivery_id) AS policy_channel,-- The communication policy governing the template that was sent.
  calc_message_deliveries_channel_name(t.message_delivery_id) AS channel_name,  -- Channel (Email, SMS) of the policy this delivery went out under.
  calc_message_deliveries_policy_requires_consent(t.message_delivery_id) AS policy_requires_consent,-- Whether the governing policy requires active consent for this channel.
  calc_message_deliveries_recipient_has_sms_consent(t.message_delivery_id) AS recipient_has_sms_consent,-- Whether the recipient of this delivery had SMS consent on file.
  calc_message_deliveries_was_actually_transmitted(t.message_delivery_id) AS was_actually_transmitted,-- TRUE when the message actually left our systems. Suppressed and Failed messages never reached the carrier.
  calc_message_deliveries_is_consent_violation(t.message_delivery_id) AS is_consent_violation,-- TRUE when a message was actually transmitted on a consent-required channel to a recipient without consent. This is the TCPA witness.
  calc_message_deliveries_consent_violation_policy_key(t.message_delivery_id) AS consent_violation_policy_key,-- Carries the policy id only on rows that are consent violations; empty string otherwise.
  calc_message_deliveries_policy_quiet_hours_start_hour(t.message_delivery_id) AS policy_quiet_hours_start_hour,-- Quiet-hours start hour (0-23) from the governing policy.
  calc_message_deliveries_policy_quiet_hours_end_hour(t.message_delivery_id) AS policy_quiet_hours_end_hour,-- Quiet-hours end hour (0-23) from the governing policy.
  calc_message_deliveries_policy_has_quiet_hours(t.message_delivery_id) AS policy_has_quiet_hours,-- TRUE when the governing policy actually declares a quiet-hours window. comm-email-policy has 00:00-00:00, meaning no window.
  calc_message_deliveries_quiet_window_wraps_midnight(t.message_delivery_id) AS quiet_window_wraps_midnight,-- TRUE when the quiet window crosses midnight (20:00 -> 08:00 does).
  calc_message_deliveries_is_inside_quiet_window(t.message_delivery_id) AS is_inside_quiet_window,-- TRUE when the recipient-local send hour falls inside the declared quiet window, handling the midnight wrap correctly.
  calc_message_deliveries_is_quiet_hours_violation(t.message_delivery_id) AS is_quiet_hours_violation,-- TRUE when a message was actually transmitted inside a declared quiet-hours window. The quiet-hours witness.
  calc_message_deliveries_quiet_hours_violation_policy_key(t.message_delivery_id) AS quiet_hours_violation_policy_key,-- Carries the policy id only on quiet-hours violations; empty string otherwise.
  calc_message_deliveries_recipient_is_unreachable(t.message_delivery_id) AS recipient_is_unreachable,-- Whether the recipient has neither email nor mobile on file -- the exc-unreachable trigger.
  calc_message_deliveries_is_acknowledged(t.message_delivery_id) AS is_acknowledged,-- TRUE when an acknowledgement timestamp is recorded for this delivery.
  calc_message_deliveries_invoked_exception_condition(t.message_delivery_id) AS invoked_exception_condition,-- The documented condition of the exception invoked on this delivery, if any.
  calc_message_deliveries_has_unreachable_exception_invoked(t.message_delivery_id) AS has_unreachable_exception_invoked,-- TRUE when the documented unreachable-recipient exception was formally invoked on this delivery.
  calc_message_deliveries_is_fabricated_acknowledgement(t.message_delivery_id) AS is_fabricated_acknowledgement,-- TRUE when an acknowledgement is recorded for a recipient we could not reach. This is the misrepresentation witness.
  calc_message_deliveries_is_unhandled_unreachable(t.message_delivery_id) AS is_unhandled_unreachable,-- TRUE when a recipient was unreachable but no documented exception was invoked -- the case fell on the floor silently.
  calc_message_deliveries_unreachable_failure_key(t.message_delivery_id) AS unreachable_failure_key,-- Carries the execution id on any unreachable-handling failure; empty string otherwise.
  calc_message_deliveries_policy_retention_days(t.message_delivery_id) AS policy_retention_days,-- Retention commitment in days inherited from the governing channel policy.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_message_deliveries_as_of_instant(t.message_delivery_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_message_deliveries_age_days(t.message_delivery_id) AS age_days,          -- Days elapsed since transmission.
  calc_message_deliveries_is_within_retention_window(t.message_delivery_id) AS is_within_retention_window,-- TRUE while this delivery is still inside its committed retention period.
  calc_message_deliveries_has_rendered_body(t.message_delivery_id) AS has_rendered_body,-- TRUE when the exact transmitted text is still held on this record.
  calc_message_deliveries_is_evidence_required(t.message_delivery_id) AS is_evidence_required,-- TRUE when we are still obliged to hold this message's text.
  calc_message_deliveries_is_retention_breach(t.message_delivery_id) AS is_retention_breach,-- TRUE when we are obliged to hold the message text and do not. The evidentiary-gap witness.
  calc_message_deliveries_retention_breach_execution_key(t.message_delivery_id) AS retention_breach_execution_key,-- Carries the execution id on retention breaches; empty string otherwise.
  calc_message_deliveries_sending_step_execution_step(t.message_delivery_id) AS sending_step_execution_step,-- Which procedure step this delivery was performed under.
  calc_message_deliveries_execution_has_cleared_legal_review(t.message_delivery_id) AS execution_has_cleared_legal_review,-- Whether legal review had passed for the execution this delivery belongs to.
  calc_message_deliveries_is_unreviewed_send(t.message_delivery_id) AS is_unreviewed_send,-- TRUE when a message was transmitted under an execution whose legal review had not passed. The ungated-send witness.
  calc_message_deliveries_rendered_body_length(t.message_delivery_id) AS rendered_body_length,-- Character length of the exact text that was actually transmitted.
  calc_message_deliveries_policy_max_message_length_at_send(t.message_delivery_id) AS policy_max_message_length_at_send,-- The per-segment limit that governed this specific send.
  calc_message_deliveries_segment_count(t.message_delivery_id) AS segment_count,-- How many channel segments the transmitted text occupied.
  calc_message_deliveries_policy_max_segments_at_send(t.message_delivery_id) AS policy_max_segments_at_send,-- The segment ceiling that governed this specific send.
  calc_message_deliveries_is_over_segment_limit(t.message_delivery_id) AS is_over_segment_limit,-- TRUE when a transmitted message split into more segments than the policy permits. The oversize witness.
  calc_message_deliveries_template_has_valid_approval(t.message_delivery_id) AS template_has_valid_approval,-- Whether the template used for this delivery had a properly-authorized approval.
  calc_message_deliveries_is_unapproved_send(t.message_delivery_id) AS is_unapproved_send,-- TRUE when a message was transmitted using a template with no valid approval behind it.
  calc_message_deliveries_policy_required_opt_out_phrase(t.message_delivery_id) AS policy_required_opt_out_phrase,-- The opt-out phrase required for this delivery's channel.
  calc_message_deliveries_policy_requires_opt_out(t.message_delivery_id) AS policy_requires_opt_out,-- TRUE when the governing channel policy declares a required opt-out phrase at all.
  calc_message_deliveries_opt_out_phrase_position(t.message_delivery_id) AS opt_out_phrase_position,-- Character position at which the required opt-out phrase appears in the transmitted text; 0 when absent.
  calc_message_deliveries_has_opt_out_phrase(t.message_delivery_id) AS has_opt_out_phrase,-- TRUE when the required opt-out phrase appears anywhere in the transmitted text.
  calc_message_deliveries_is_opt_out_in_first_segment(t.message_delivery_id) AS is_opt_out_in_first_segment,-- TRUE when the opt-out phrase falls inside the first segment, where it is guaranteed to be read.
  calc_message_deliveries_is_missing_required_opt_out(t.message_delivery_id) AS is_missing_required_opt_out,-- TRUE when a transmitted message on an opt-out-required channel did not contain the phrase at all. The hard witness.
  calc_message_deliveries_is_opt_out_at_risk_of_truncation(t.message_delivery_id) AS is_opt_out_at_risk_of_truncation,-- TRUE when the opt-out phrase is present but sits beyond the first segment, where carrier truncation or out-of-order delivery can hide it. The soft witness.
  calc_message_deliveries_is_failed_delivery(t.message_delivery_id) AS is_failed_delivery,-- TRUE when the message left our systems but did not land.
  calc_message_deliveries_is_suppressed(t.message_delivery_id) AS is_suppressed,-- TRUE when we deliberately chose not to transmit.
  calc_message_deliveries_is_triaged(t.message_delivery_id) AS is_triaged,      -- TRUE when some documented exception was formally invoked on this delivery -- i.e. a human or a rule picked it up.
  calc_message_deliveries_is_abandoned_failure(t.message_delivery_id) AS is_abandoned_failure,-- TRUE when a delivery failed and no documented exception was invoked. The abandoned-bounce witness.
  calc_message_deliveries_abandoned_failure_execution_key(t.message_delivery_id) AS abandoned_failure_execution_key,-- Carries the execution id on abandoned failures; empty string otherwise.
  calc_message_deliveries_reached_execution_key(t.message_delivery_id) AS reached_execution_key,-- Carries the execution id on confirmed-delivered messages; empty string otherwise.
  calc_message_deliveries_template_was_sendable(t.message_delivery_id) AS template_was_sendable,-- Whether the template used for this delivery was fully sendable under a current, matching approval.
  calc_message_deliveries_is_drifted_send(t.message_delivery_id) AS is_drifted_send,-- TRUE when a message was transmitted from a template that was not validly sendable at the time. The drift witness.
  calc_message_deliveries_drifted_send_template_key(t.message_delivery_id) AS drifted_send_template_key,-- Carries the template id on drifted sends; empty string otherwise.
  calc_message_deliveries_was_sent_outside_business_hours(t.message_delivery_id) AS was_sent_outside_business_hours,-- TRUE when this message landed before 08:00 or after 18:00 in the recipient's local time.
  calc_message_deliveries_was_delivered_and_unanswered(t.message_delivery_id) AS was_delivered_and_unanswered,-- TRUE when a message actually reached someone and no acknowledgement came back.
  calc_message_deliveries_is_poorly_timed_unanswered(t.message_delivery_id) AS is_poorly_timed_unanswered,-- TRUE when an unanswered message was delivered outside business hours -- a timing hypothesis for the silence.
  calc_message_deliveries_is_well_timed_unanswered(t.message_delivery_id) AS is_well_timed_unanswered,-- TRUE when a message was delivered at a reasonable hour and still drew no response.
  calc_message_deliveries_unanswered_template_key(t.message_delivery_id) AS unanswered_template_key,-- The template id when this delivery went unanswered, otherwise empty string.
  calc_message_deliveries_transmitted_template_key(t.message_delivery_id) AS transmitted_template_key,-- The template id when this delivery actually reached someone.
  t.approving_agent_at_send,                                                    -- The agent whose approval authorized this specific transmission, frozen at send time.
  t.approving_role_at_send,                                                     -- The role that agent held when they approved, frozen at send time.
  t.approval_decided_at_send,                                                   -- When the relied-upon approval was granted, frozen at send time.
  calc_message_deliveries_approval_preceded_send(t.message_delivery_id) AS approval_preceded_send,-- TRUE when the approval we relied on was granted before the message went out.
  calc_message_deliveries_has_frozen_approval_evidence(t.message_delivery_id) AS has_frozen_approval_evidence,-- TRUE when this delivery carries a complete frozen record of who authorized it and when.
  calc_message_deliveries_provenance_is_live_derived(t.message_delivery_id) AS provenance_is_live_derived,-- TRUE when we have no frozen evidence and the only available answer comes from recomputing against today's template state.
  calc_message_deliveries_current_last_approval_at(t.message_delivery_id) AS current_last_approval_at,-- The template's most recent approval time as it stands NOW, for comparison against what was approved at send.
  calc_message_deliveries_template_reapproved_since_send(t.message_delivery_id) AS template_reapproved_since_send,-- TRUE when the template has picked up a newer approval since this message was transmitted.
  calc_message_deliveries_is_unprovable_approval_claim(t.message_delivery_id) AS is_unprovable_approval_claim,-- TRUE when we assert this send was approved, hold no frozen evidence, and the template has been re-approved since. The claim cannot be substantiated from the record.
  t.reminder_sent_at,                                                           -- When I sent a follow-up reminder about this unacknowledged message. Empty when I never did.
  t.reminder_count,                                                             -- How many reminders I have sent for this delivery.
  calc_message_deliveries_has_sent_reminder(t.message_delivery_id) AS has_sent_reminder,-- TRUE when at least one reminder went out for this delivery.
  calc_message_deliveries_acknowledgement_is_outstanding(t.message_delivery_id) AS acknowledgement_is_outstanding,-- TRUE when a message actually reached someone, carried an acknowledgement obligation, and has not been acknowledged.
  calc_message_deliveries_outstanding_age_days(t.message_delivery_id) AS outstanding_age_days,-- How long this acknowledgement has been outstanding.
  calc_message_deliveries_is_unchased_acknowledgement(t.message_delivery_id) AS is_unchased_acknowledgement,-- TRUE when an acknowledgement has been outstanding for more than 7 days and I have never sent a reminder.
  calc_message_deliveries_is_exhausted_follow_up(t.message_delivery_id) AS is_exhausted_follow_up,-- TRUE when I have sent three or more reminders and still have no acknowledgement -- the point at which this stops being my work and becomes a human escalation.
  calc_message_deliveries_needs_human_escalation(t.message_delivery_id) AS needs_human_escalation,-- TRUE when follow-up is exhausted and no exception has been invoked to close out the obligation.
  t.semantic_type_iri                                                           -- Extension IRI; per-recipient delivery events are not a PKO 2.0.0 native class.
FROM message_deliveries t;

-- ----------------------------------------------------------------------------
-- vw_template_approvals: TemplateApprovals (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_template_approvals CASCADE;
CREATE VIEW vw_template_approvals WITH (security_invoker = ON) AS
SELECT
  t.template_approval_id,                                                       -- Stored logical identifier for one TemplateApprovals row.
  calc_template_approvals_name(t.template_approval_id) AS name,                 -- Human-readable calculated display alias for the TemplateApprovals row.
  t.message_template,                                                           -- Template this decision applies to.
  t.decided_by_agent,                                                           -- Agent who made the approval decision.
  t.decided_in_role,                                                            -- Role the agent was acting in when deciding.
  t.decision,                                                                   -- Approved, Rejected, or Withdrawn.
  t.decided_at,                                                                 -- When the decision was recorded.
  t.approved_body_hash,                                                         -- Digest of the exact template body that was approved, so later edits are detectable.
  t.notes,                                                                      -- Approver's rationale or conditions.
  calc_template_approvals_is_approval_decision(t.template_approval_id) AS is_approval_decision,-- TRUE when this decision row is an approval rather than a rejection or withdrawal.
  calc_template_approvals_template_policy(t.template_approval_id) AS template_policy,-- The communication policy governing the template being approved.
  calc_template_approvals_required_approval_role(t.template_approval_id) AS required_approval_role,-- The role the governing policy designates as approver -- communications-manager for both current policies.
  calc_template_approvals_is_decided_by_required_role(t.template_approval_id) AS is_decided_by_required_role,-- TRUE when the approving role matches the role the policy designates.
  calc_template_approvals_valid_approval_template_key(t.template_approval_id) AS valid_approval_template_key,-- Carries the template id only on approvals made by the correct role; empty string otherwise.
  t.semantic_type_iri                                                           -- Extension IRI; template approval events are not a PKO 2.0.0 native class.
FROM template_approvals t;

-- ----------------------------------------------------------------------------
-- vw_send_intents: SendIntents (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_send_intents: SendIntents (added by witness loop 1).
-- SELF-REFERENTIAL SETTLE: SendIntents has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: is_cleared_to_send. Drivers: alternate_channel_intent, retry_intent.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_send_intents CASCADE;
CREATE VIEW vw_send_intents WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.send_intent_id, jsonb_build_object(
      'is_cleared_to_send', (COALESCE((((COALESCE((SELECT calc_communication_policies_is_active_policy(communication_policy_id)::boolean FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NOT NULL, FALSE) AND COALESCE((COALESCE((((COALESCE(NOT (COALESCE((SELECT consent_required::boolean FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NOT NULL, FALSE)), FALSE) OR COALESCE((SELECT calc_recipients_has_sms_consent(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))) IS NOT NULL, FALSE))))::boolean, FALSE) AND COALESCE(((CASE WHEN COALESCE((SELECT channel::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), '') = 'SMS' THEN ((SELECT calc_recipients_is_sms_reachable(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))))::text ELSE ((SELECT calc_recipients_is_email_reachable(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))))::text END))::boolean, FALSE)), FALSE))))::boolean, FALSE) AND COALESCE((COALESCE((((COALESCE(NOT (COALESCE(((COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0) <> COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0)))::boolean, FALSE)), FALSE) OR COALESCE(NOT (COALESCE(((CASE WHEN ((COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0) > COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0)))::boolean THEN ((COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) >= COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE) OR COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) < COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)))::text ELSE ((COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) >= COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) < COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)))::text END))::boolean, FALSE)), FALSE))))::boolean, FALSE) AND COALESCE((COALESCE((((COALESCE((((COALESCE(COALESCE(((SELECT (NULLIF(t.proposed_body_length::text,''))::integer))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_segment_count::text,''))::integer), 0) <= COALESCE((SELECT max_segments::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE))))::boolean, FALSE) AND COALESCE((((COALESCE((SELECT required_opt_out_phrase::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NULL, FALSE) OR COALESCE((COALESCE(COALESCE(((SELECT (NULLIF(t.proposed_opt_out_position::text,''))::integer))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_opt_out_position::text,''))::integer), 0) <= COALESCE((SELECT max_message_length::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)), FALSE))))::boolean, FALSE))))::boolean, FALSE) AND COALESCE((((COALESCE((SELECT calc_message_templates_is_sendable_under_approval(message_template_id)::boolean FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,''))) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT calc_procedure_executions_has_cleared_legal_review(procedure_execution_id)::boolean FROM procedure_executions WHERE procedure_execution_id = (SELECT NULLIF(t.procedure_execution::text,''))) IS NOT NULL, FALSE) AND COALESCE(((COALESCE((SELECT calc_roles_current_agent_kind(role_id)::text FROM roles WHERE role_id = (SELECT approval_role::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,''))))), '') = 'Human'))::boolean, FALSE)), FALSE))))::boolean, FALSE)), FALSE)), FALSE))
    ))
    FROM send_intents t WHERE NULLIF(t.alternate_channel_intent,'') IS NULL AND NULLIF(t.retry_intent,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.send_intent_id, jsonb_build_object(
      'is_cleared_to_send', (COALESCE((((COALESCE((SELECT calc_communication_policies_is_active_policy(communication_policy_id)::boolean FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NOT NULL, FALSE) AND COALESCE((COALESCE((((COALESCE(NOT (COALESCE((SELECT consent_required::boolean FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NOT NULL, FALSE)), FALSE) OR COALESCE((SELECT calc_recipients_has_sms_consent(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))) IS NOT NULL, FALSE))))::boolean, FALSE) AND COALESCE(((CASE WHEN COALESCE((SELECT channel::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), '') = 'SMS' THEN ((SELECT calc_recipients_is_sms_reachable(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))))::text ELSE ((SELECT calc_recipients_is_email_reachable(recipient_id)::boolean FROM recipients WHERE recipient_id = (SELECT NULLIF(t.recipient::text,''))))::text END))::boolean, FALSE)), FALSE))))::boolean, FALSE) AND COALESCE((COALESCE((((COALESCE(NOT (COALESCE(((COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0) <> COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0)))::boolean, FALSE)), FALSE) OR COALESCE(NOT (COALESCE(((CASE WHEN ((COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0) > COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0)))::boolean THEN ((COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) >= COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE) OR COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) < COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)))::text ELSE ((COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) >= COALESCE((SELECT quiet_hours_start_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_send_at_local_hour::text,''))::integer), 0) < COALESCE((SELECT quiet_hours_end_hour::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)))::text END))::boolean, FALSE)), FALSE))))::boolean, FALSE) AND COALESCE((COALESCE((((COALESCE((((COALESCE(COALESCE(((SELECT (NULLIF(t.proposed_body_length::text,''))::integer))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_segment_count::text,''))::integer), 0) <= COALESCE((SELECT max_segments::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE))))::boolean, FALSE) AND COALESCE((((COALESCE((SELECT required_opt_out_phrase::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))) IS NULL, FALSE) OR COALESCE((COALESCE(COALESCE(((SELECT (NULLIF(t.proposed_opt_out_position::text,''))::integer))::NUMERIC, 0) > 0, FALSE) AND COALESCE(COALESCE((SELECT (NULLIF(t.proposed_opt_out_position::text,''))::integer), 0) <= COALESCE((SELECT max_message_length::integer FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,'')))), 0), FALSE)), FALSE))))::boolean, FALSE))))::boolean, FALSE) AND COALESCE((((COALESCE((SELECT calc_message_templates_is_sendable_under_approval(message_template_id)::boolean FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,''))) IS NOT NULL, FALSE) AND COALESCE((COALESCE((SELECT calc_procedure_executions_has_cleared_legal_review(procedure_execution_id)::boolean FROM procedure_executions WHERE procedure_execution_id = (SELECT NULLIF(t.procedure_execution::text,''))) IS NOT NULL, FALSE) AND COALESCE(((COALESCE((SELECT calc_roles_current_agent_kind(role_id)::text FROM roles WHERE role_id = (SELECT approval_role::text FROM communication_policies WHERE communication_policy_id = (SELECT communication_policy::text FROM message_templates WHERE message_template_id = (SELECT NULLIF(t.message_template::text,''))))), '') = 'Human'))::boolean, FALSE)), FALSE))))::boolean, FALSE)), FALSE)), FALSE))
    ))
    FROM send_intents t
    WHERE NOT (a.settled ? t.send_intent_id) AND NOT (NULLIF(t.alternate_channel_intent,'') IS NULL AND NULLIF(t.retry_intent,'') IS NULL) AND (NULLIF(t.alternate_channel_intent,'') IS NULL OR a.settled ? t.alternate_channel_intent) AND (NULLIF(t.retry_intent,'') IS NULL OR a.settled ? t.retry_intent)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM send_intents t
    WHERE NOT (a.settled ? t.send_intent_id) AND NOT (NULLIF(t.alternate_channel_intent,'') IS NULL AND NULLIF(t.retry_intent,'') IS NULL) AND (NULLIF(t.alternate_channel_intent,'') IS NULL OR a.settled ? t.alternate_channel_intent) AND (NULLIF(t.retry_intent,'') IS NULL OR a.settled ? t.retry_intent))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.send_intent_id,                                                             -- Stored logical identifier for one SendIntents row.
  calc_send_intents_name(t.send_intent_id) AS name,                             -- Human-readable calculated display alias for the SendIntents row.
  t.procedure_execution,                                                        -- Execution this send intent belongs to.
  t.step_execution,                                                             -- Step execution evaluating this intent.
  t.recipient,                                                                  -- Intended recipient.
  t.message_template,                                                           -- Template the pipeline intends to render and send.
  t.proposed_body,                                                              -- The fully rendered text the pipeline intends to transmit, before transmission.
  t.proposed_send_at_local_hour,                                                -- Hour 0-23 in the recipient's local timezone at which the pipeline intends to transmit.
  t.evaluated_at,                                                               -- When the pipeline evaluated the gates for this intent.
  t.resulting_delivery,                                                         -- The delivery record produced from this intent, whether transmitted or suppressed.
  calc_send_intents_intent_policy(t.send_intent_id) AS intent_policy,           -- The communication policy governing the template this intent would send.
  calc_send_intents_intent_channel(t.send_intent_id) AS intent_channel,         -- Channel this intent would transmit on.
  calc_send_intents_policy_is_active(t.send_intent_id) AS policy_is_active,     -- Whether the governing policy is currently Active rather than Draft, Suspended, or Retired.
  calc_send_intents_intent_requires_consent(t.send_intent_id) AS intent_requires_consent,-- Whether the governing policy requires consent for this channel.
  calc_send_intents_recipient_has_channel_consent(t.send_intent_id) AS recipient_has_channel_consent,-- Whether the intended recipient has active SMS consent on record.
  calc_send_intents_consent_gate_passed(t.send_intent_id) AS consent_gate_passed,-- TRUE when either the channel does not require consent, or the recipient has granted it.
  calc_send_intents_recipient_is_sms_reachable(t.send_intent_id) AS recipient_is_sms_reachable,-- Whether a mobile number is on file for the intended recipient.
  calc_send_intents_recipient_is_email_reachable(t.send_intent_id) AS recipient_is_email_reachable,-- Whether an email address is on file for the intended recipient.
  calc_send_intents_reachability_gate_passed(t.send_intent_id) AS reachability_gate_passed,-- TRUE when the recipient is reachable on the channel this intent would use.
  calc_send_intents_permission_gate_passed(t.send_intent_id) AS permission_gate_passed,-- TRUE when the policy is active, consent is satisfied, and the recipient is reachable on this channel. The channel-permission gate.
  calc_send_intents_intent_quiet_start_hour(t.send_intent_id) AS intent_quiet_start_hour,-- Quiet-hours start hour from the governing policy.
  calc_send_intents_intent_quiet_end_hour(t.send_intent_id) AS intent_quiet_end_hour,-- Quiet-hours end hour from the governing policy.
  calc_send_intents_intent_policy_has_quiet_hours(t.send_intent_id) AS intent_policy_has_quiet_hours,-- TRUE when the governing policy declares a real quiet-hours window.
  calc_send_intents_intent_quiet_window_wraps(t.send_intent_id) AS intent_quiet_window_wraps,-- TRUE when the quiet window crosses midnight.
  calc_send_intents_intent_is_inside_quiet_window(t.send_intent_id) AS intent_is_inside_quiet_window,-- TRUE when the proposed recipient-local send hour falls inside the forbidden window.
  calc_send_intents_timing_gate_passed(t.send_intent_id) AS timing_gate_passed, -- TRUE when transmitting now is permitted on timing grounds. The timing gate.
  calc_send_intents_hours_until_window_opens(t.send_intent_id) AS hours_until_window_opens,-- How many hours the pipeline must defer before transmission becomes permitted; 0 when already permitted.
  calc_send_intents_intent_max_message_length(t.send_intent_id) AS intent_max_message_length,-- Per-segment character limit from the governing policy.
  calc_send_intents_intent_max_segments(t.send_intent_id) AS intent_max_segments,-- Segment ceiling from the governing policy.
  t.proposed_body_length,                                                       -- Character count of ProposedBody, written by the pipeline at render time.
  t.proposed_segment_count,                                                     -- Number of channel segments ProposedBody will occupy, computed by the pipeline at render time.
  calc_send_intents_length_gate_passed(t.send_intent_id) AS length_gate_passed, -- TRUE when the proposed text is non-empty and fits within the segment ceiling.
  calc_send_intents_intent_required_opt_out_phrase(t.send_intent_id) AS intent_required_opt_out_phrase,-- Opt-out phrase the governing policy requires in every message on this channel.
  t.proposed_opt_out_position,                                                  -- Character position of the required opt-out phrase within ProposedBody; 0 when absent. Written by the pipeline at render time.
  calc_send_intents_opt_out_gate_passed(t.send_intent_id) AS opt_out_gate_passed,-- TRUE when no opt-out is required, or the required phrase is present within the first segment.
  calc_send_intents_content_gate_passed(t.send_intent_id) AS content_gate_passed,-- TRUE when the proposed text satisfies every content rule of the governing channel policy.
  calc_send_intents_template_is_sendable(t.send_intent_id) AS template_is_sendable,-- Whether the template carries a current, properly-authorized, non-drifted approval.
  calc_send_intents_execution_has_legal_clearance(t.send_intent_id) AS execution_has_legal_clearance,-- Whether legal review has passed for the execution this intent belongs to.
  calc_send_intents_intent_approval_role(t.send_intent_id) AS intent_approval_role,-- The role the governing policy designates as the approving authority.
  calc_send_intents_approval_role_agent_kind(t.send_intent_id) AS approval_role_agent_kind,-- Whether the agent currently filling the designated approval role is Human, AIAgent, or AutomatedPipeline.
  calc_send_intents_approval_is_human(t.send_intent_id) AS approval_is_human,   -- TRUE when the designated approval role is currently held by a human agent.
  calc_send_intents_authorization_gate_passed(t.send_intent_id) AS authorization_gate_passed,-- TRUE only when the template is validly approved, legal review has cleared, and the approving role is held by a human. The authorization gate.
  (SELECT settled #>> ARRAY[t.send_intent_id::text, 'is_cleared_to_send'] FROM settled)::boolean AS is_cleared_to_send,-- TRUE only when all four gates pass. THE single column the pipeline reads before transmitting.
  calc_send_intents_blocking_gate_name(t.send_intent_id) AS blocking_gate_name, -- Names the first gate that refused, for the suppression reason; empty string when cleared.
  calc_send_intents_has_resulting_delivery(t.send_intent_id) AS has_resulting_delivery,-- TRUE when this intent produced a delivery record of any status.
  calc_send_intents_resulting_delivery_was_transmitted(t.send_intent_id) AS resulting_delivery_was_transmitted,-- Whether the delivery produced from this intent actually left our systems.
  calc_send_intents_is_overridden_refusal(t.send_intent_id) AS is_overridden_refusal,-- TRUE when a gate refused and the message was transmitted regardless. The override witness.
  calc_send_intents_is_silently_dropped(t.send_intent_id) AS is_silently_dropped,-- TRUE when a gate refused and no delivery record of any kind was produced -- the recipient vanished from the run.
  calc_send_intents_resulting_delivery_exception(t.send_intent_id) AS resulting_delivery_exception,-- The documented exception invoked on the delivery produced from this intent, if any.
  calc_send_intents_refusal_cited_an_exception(t.send_intent_id) AS refusal_cited_an_exception,-- TRUE when the suppression produced by this refusal cited a documented exception.
  calc_send_intents_is_properly_handled_refusal(t.send_intent_id) AS is_properly_handled_refusal,-- TRUE when a refusal correctly resulted in a non-transmitted delivery record citing a documented exception. The positive witness.
  calc_send_intents_refusal_failure_execution_key(t.send_intent_id) AS refusal_failure_execution_key,-- Carries the execution id on any mishandled refusal; empty string otherwise.
  calc_send_intents_intent_execution_key(t.send_intent_id) AS intent_execution_key,-- The procedure execution id for every intent, used as the campaign rollup key.
  calc_send_intents_delivered_intent_execution_key(t.send_intent_id) AS delivered_intent_execution_key,-- The execution id when this intent actually reached a person, otherwise empty string.
  calc_send_intents_dropped_intent_execution_key(t.send_intent_id) AS dropped_intent_execution_key,-- The execution id when this intent was refused and left no record at all.
  calc_send_intents_my_approval_was_in_force(t.send_intent_id) AS my_approval_was_in_force,-- TRUE when the template carried a valid approval at the moment this intent was evaluated.
  calc_send_intents_refused_on_approved_content(t.send_intent_id) AS refused_on_approved_content,-- TRUE when the pipeline refused an intent on content grounds even though the template was approved.
  calc_send_intents_refused_on_opt_out_only(t.send_intent_id) AS refused_on_opt_out_only,-- TRUE when the only content failure was a missing or mispositioned opt-out phrase.
  calc_send_intents_refusal_was_on_my_rules(t.send_intent_id) AS refusal_was_on_my_rules,-- TRUE when the refusal came from a communications rule I own -- content, length, opt-out, quiet hours.
  calc_send_intents_refusal_was_outside_my_control(t.send_intent_id) AS refusal_was_outside_my_control,-- TRUE when the refusal came from consent, reachability, or authorization -- none of which I can fix by editing a template.
  t.approver_was_notified,                                                      -- Whether the approving human was informed that this intent was refused.
  calc_send_intents_is_unreported_refusal_on_my_rules(t.send_intent_id) AS is_unreported_refusal_on_my_rules,-- TRUE when a refusal I own and could have fixed was never surfaced to me.
  calc_send_intents_is_approval_overridden_silently(t.send_intent_id) AS is_approval_overridden_silently,-- TRUE when the pipeline overrode a valid human approval on content grounds and told nobody.
  t.alternate_channel_intent,                                                   -- The follow-up intent raised on a different channel after this one was refused. Stored as a raw identifier rather than an FK: SendIntents pointing at SendIntents would make the table self-referential in a way the DAG contract does not allow here.
  calc_send_intents_has_alternate_channel_attempt(t.send_intent_id) AS has_alternate_channel_attempt,-- TRUE when a follow-up intent on another channel was raised for this refused send.
  (SELECT settled #>> ARRAY[NULLIF(t.alternate_channel_intent,''), 'is_cleared_to_send'] FROM settled)::boolean AS alternate_attempt_was_cleared,-- Whether the follow-up intent itself passed all gates.
  calc_send_intents_is_refused_with_no_alternative(t.send_intent_id) AS is_refused_with_no_alternative,-- TRUE when a send was refused and no attempt was ever made on any other channel.
  calc_send_intents_exception_prescribed_an_alternative(t.send_intent_id) AS exception_prescribed_an_alternative,-- TRUE when the documented exception for this refusal prescribes a different-channel send as the correct handling.
  calc_send_intents_prescribed_handling_was_performed(t.send_intent_id) AS prescribed_handling_was_performed,-- TRUE when the exception prescribed an alternate channel and an alternate intent was actually raised and cleared.
  calc_send_intents_is_suppression_without_remedy(t.send_intent_id) AS is_suppression_without_remedy,-- TRUE when we cited an exception that prescribed an alternate channel and then never performed it.
  t.refusal_recorded_at,                                                        -- When this refusal was written to a durable record. Empty when no record was ever emitted.
  t.refusal_notified_role,                                                      -- The role informed that this send was refused.
  calc_send_intents_has_durable_refusal_record(t.send_intent_id) AS has_durable_refusal_record,-- TRUE when this refusal was written down somewhere a human can find it.
  calc_send_intents_refusal_was_escalated(t.send_intent_id) AS refusal_was_escalated,-- TRUE when a specific role was notified of this refusal.
  calc_send_intents_is_unrecorded_refusal(t.send_intent_id) AS is_unrecorded_refusal,-- TRUE when I refused a send and produced no delivery record, no refusal record, and no exception. The refusal left no trace of any kind.
  calc_send_intents_is_unescalated_refusal(t.send_intent_id) AS is_unescalated_refusal,-- TRUE when a refusal was recorded but no human role was ever told.
  calc_send_intents_unescalated_refusal_role_key(t.send_intent_id) AS unescalated_refusal_role_key,-- Echoes the role that should have been told about this refusal, but only when the refusal went unrecorded. Empty otherwise.
  calc_send_intents_unrecorded_refusal_execution_key(t.send_intent_id) AS unrecorded_refusal_execution_key,-- Echoes the parent procedure execution only for refusals nobody recorded; empty otherwise.
  t.retry_intent,                                                               -- The intent I raised when the quiet window reopened for this deferred send. Raw identifier rather than an FK: a SendIntents self-reference is not expressible as a relationship without making the table depend on itself.
  calc_send_intents_was_deferred_on_timing(t.send_intent_id) AS was_deferred_on_timing,-- TRUE when the timing gate is the reason this intent did not clear, and every other gate passed.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_send_intents_as_of_instant(t.send_intent_id) AS as_of_instant,           -- The evaluation instant this row's time-dependent witnesses are judged against.
  calc_send_intents_window_has_since_reopened(t.send_intent_id) AS window_has_since_reopened,-- TRUE when enough time has passed since evaluation that the quiet window this intent hit must have closed.
  calc_send_intents_has_retry_attempt(t.send_intent_id) AS has_retry_attempt,   -- TRUE when a retry intent was raised for this deferred send.
  (SELECT settled #>> ARRAY[NULLIF(t.retry_intent,''), 'is_cleared_to_send'] FROM settled)::boolean AS retry_was_cleared,-- Whether the retry intent itself passed all gates.
  calc_send_intents_is_abandoned_deferral(t.send_intent_id) AS is_abandoned_deferral,-- TRUE when a send was deferred for timing, the window has since reopened, and no retry was ever raised. A deferral silently converted into a cancellation.
  calc_send_intents_deferral_age_hours(t.send_intent_id) AS deferral_age_hours, -- How long this deferred intent has been sitting since evaluation.
  calc_send_intents_is_stale_deferral(t.send_intent_id) AS is_stale_deferral,   -- TRUE when a deferred send has been waiting more than 24 hours -- longer than any quiet window can justify.
  t.evaluating_role_assignment,                                                 -- The RoleAssignments id under which the pipeline evaluated this send intent. Raw rather than an FK because SendIntents already sits downstream of the execution graph and an added edge to RoleAssignments is not needed to resolve it.
  calc_send_intents_enforced_by_unauthorized_agent(t.send_intent_id) AS enforced_by_unauthorized_agent,-- Whether the gate decision on this intent was made by an agent holding an unauthorized enforcement assignment.
  calc_send_intents_consent_input_was_resolvable(t.send_intent_id) AS consent_input_was_resolvable,-- TRUE when the recipient's consent state was actually retrievable, as opposed to absent and read as a refusal.
  calc_send_intents_recipient_consent_status_raw(t.send_intent_id) AS recipient_consent_status_raw,-- The recipient's consent status as a string: Granted, Revoked, NeverGiven, or empty if no consent record exists at all.
  calc_send_intents_policy_input_was_resolvable(t.send_intent_id) AS policy_input_was_resolvable,-- TRUE when a governing communication policy was actually found for this intent.
  calc_send_intents_all_gate_inputs_resolved(t.send_intent_id) AS all_gate_inputs_resolved,-- TRUE when every input my gates depend on was actually retrievable.
  calc_send_intents_is_unevaluable_refusal(t.send_intent_id) AS is_unevaluable_refusal,-- TRUE when I refused a send but at least one gate input could not be resolved -- so I do not actually know whether the rule was violated or merely unreadable.
  t.gate_result_was_independently_confirmed,                                    -- Whether any agent other than me verified this gate outcome.
  calc_send_intents_is_self_witnessed_decision(t.send_intent_id) AS is_self_witnessed_decision,-- TRUE when the entire decision to send or refuse rests solely on my own computation, unconfirmed by anything else.
  calc_send_intents_is_independently_confirmed(t.send_intent_id) AS is_independently_confirmed,-- TRUE when this intent's decision was corroborated by an actual delivery record rather than resting solely on the pipeline's own say-so.
  calc_send_intents_independently_confirmed_execution_key(t.send_intent_id) AS independently_confirmed_execution_key,-- Echoes the parent execution only for independently confirmed intents; empty otherwise.
  t.semantic_type_iri                                                           -- Extension IRI; pre-send intents are not a PKO 2.0.0 native class.
FROM send_intents t;

-- ----------------------------------------------------------------------------
-- vw_agent_decision_records: AgentDecisionRecords (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_agent_decision_records CASCADE;
CREATE VIEW vw_agent_decision_records WITH (security_invoker = ON) AS
SELECT
  t.agent_decision_record_id,                                                   -- Stored logical identifier for one AgentDecisionRecords row.
  calc_agent_decision_records_name(t.agent_decision_record_id) AS name,         -- Human-readable calculated display alias for the AgentDecisionRecords row.
  t.step_execution,                                                             -- Step execution during which the decision was made.
  t.deciding_agent,                                                             -- Agent that made the decision.
  t.decision_kind,                                                              -- Classification, Prioritization, Draft, Suppression, Escalation, or Posting.
  t.decision_summary,                                                           -- What the agent decided, in one sentence.
  t.decided_at,                                                                 -- When the decision was made.
  t.materiality_band,                                                           -- BelowThreshold, Material, or Escalated.
  t.human_disposition,                                                          -- Accepted, Corrected, Reversed, or NotReviewed.
  t.reviewed_by_agent,                                                          -- Human agent that dispositioned the decision.
  t.reviewed_at,                                                                -- When a human dispositioned the decision.
  calc_agent_decision_records_was_overridden(t.agent_decision_record_id) AS was_overridden,-- TRUE when a human corrected or reversed this decision.
  calc_agent_decision_records_was_reviewed(t.agent_decision_record_id) AS was_reviewed,-- TRUE when a human actually dispositioned this decision.
  calc_agent_decision_records_deciding_agent_kind(t.agent_decision_record_id) AS deciding_agent_kind,-- Whether the deciding agent is Human, AIAgent, or AutomatedPipeline.
  calc_agent_decision_records_deciding_agent_when_overridden(t.agent_decision_record_id) AS deciding_agent_when_overridden,-- Echoes the deciding agent id when the decision was overridden, blank otherwise.
  t.under_role_assignment,                                                      -- Role assignment in force when the decision was made; anchors the decision to one side of a handover.
  calc_agent_decision_records_role_assignment_when_scored(t.agent_decision_record_id) AS role_assignment_when_scored,-- Echoes the governing role assignment when one is recorded, blank otherwise.
  calc_agent_decision_records_role_assignment_when_overridden(t.agent_decision_record_id) AS role_assignment_when_overridden,-- Echoes the governing role assignment when the decision was overridden, blank otherwise.
  calc_agent_decision_records_step_of_decision(t.agent_decision_record_id) AS step_of_decision,-- The specified step at which this decision was made.
  calc_agent_decision_records_boundary_match_key(t.agent_decision_record_id) AS boundary_match_key,-- Composite key of step, deciding agent kind, and decision kind for this decision.
  calc_agent_decision_records_matching_boundary_count(t.agent_decision_record_id) AS matching_boundary_count,-- Number of authority boundaries this decision matches.
  calc_agent_decision_records_violated_authority_boundary(t.agent_decision_record_id) AS violated_authority_boundary,-- TRUE when this decision matches an authority boundary that forbids it.
  calc_agent_decision_records_reviewer_agent_kind(t.agent_decision_record_id) AS reviewer_agent_kind,-- Agent kind of the reviewer, if any.
  calc_agent_decision_records_has_human_confirmation(t.agent_decision_record_id) AS has_human_confirmation,-- TRUE when a human agent actually dispositioned this decision.
  calc_agent_decision_records_needs_human_confirmation(t.agent_decision_record_id) AS needs_human_confirmation,-- TRUE when a non-human agent made a material or escalated decision.
  calc_agent_decision_records_is_unconfirmed_non_human_decision(t.agent_decision_record_id) AS is_unconfirmed_non_human_decision,-- TRUE when a material non-human decision was never confirmed by a human.
  calc_agent_decision_records_step_execution_when_unconfirmed(t.agent_decision_record_id) AS step_execution_when_unconfirmed,-- Echoes the step-execution id when the decision is an unconfirmed non-human material decision, blank otherwise.
  calc_agent_decision_records_agent_when_boundary_violated(t.agent_decision_record_id) AS agent_when_boundary_violated,-- Echoes the deciding agent id when the decision violated a boundary, blank otherwise.
  calc_agent_decision_records_review_latency_minutes(t.agent_decision_record_id) AS review_latency_minutes,-- Minutes between the decision and its human disposition; 0 when never reviewed. Declared number, not integer: DATETIME_DIFF returns a numeric and an integer cast makes the entire view fail on read.
  calc_agent_decision_records_is_draft_kind(t.agent_decision_record_id) AS is_draft_kind,-- TRUE when this decision produced text — the drafter's own output class.
  calc_agent_decision_records_agent_when_draft_overridden(t.agent_decision_record_id) AS agent_when_draft_overridden,-- Echoes the deciding agent id when a drafting decision was overridden, blank otherwise.
  calc_agent_decision_records_agent_when_draft(t.agent_decision_record_id) AS agent_when_draft,-- Echoes the deciding agent id when the decision produced text, blank otherwise.
  t.override_reason_kind,                                                       -- Why the human changed my output: ErrorCorrection, JudgmentReserved, PolicyChange, or empty when not overridden.
  calc_agent_decision_records_is_error_correction(t.agent_decision_record_id) AS is_error_correction,-- TRUE when the override corrected something I got wrong.
  calc_agent_decision_records_is_reserved_judgment_override(t.agent_decision_record_id) AS is_reserved_judgment_override,-- TRUE when the override was a human exercising authority the procedure always reserved to them.
  calc_agent_decision_records_override_reason_is_recorded(t.agent_decision_record_id) AS override_reason_is_recorded,-- TRUE when an override carries a stated reason.
  calc_agent_decision_records_is_unexplained_override(t.agent_decision_record_id) AS is_unexplained_override,-- TRUE when my output was changed and nobody recorded why.
  calc_agent_decision_records_error_correction_role_assignment_ke(t.agent_decision_record_id) AS error_correction_role_assignment_key,-- The role assignment id when this decision was overridden as an error correction, otherwise empty.
  calc_agent_decision_records_boundary_violation_role_assignment_(t.agent_decision_record_id) AS boundary_violation_role_assignment_key,-- Echoes the role assignment this decision was made under, but only when the decision violated an authority boundary. Empty otherwise.
  t.semantic_type_iri                                                           -- Extension class IRI for an agent decision record.
FROM agent_decision_records t;

-- ----------------------------------------------------------------------------
-- vw_delivered_communications: Everything above is a proxy for the real question, which is instance-level: THIS message, to THIS recipient, rendered from THIS template, authorized by THIS approval. The model has MessageTemplates and CommunicationPolicies as specifications and no record of a single thing ever sent. Without an instance table, 'can I show that what was sent matched what I approved' is permanently unanswerable rather than merely unanswered — and it is the question a disputing employee actually asks. Extension term (https://effortlessapi.github.io/effortless-rulebooks/ns/pko-extension#DeliveredCommunication); PKO has no native class for a delivered artifact instance.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_delivered_communications CASCADE;
CREATE VIEW vw_delivered_communications WITH (security_invoker = ON) AS
SELECT
  t.delivered_communication_id,                                                 -- Stored logical identifier for one DeliveredCommunications row.
  calc_delivered_communications_name(t.delivered_communication_id) AS name,     -- Human-readable calculated display alias.
  t.procedure_execution,                                                        -- The run that produced this delivery.
  t.sending_step_execution,                                                     -- The policy-07 step execution that sent it.
  t.authorizing_step_execution,                                                 -- The human approval gate execution that authorized this content. Null means nobody approved it.
  t.message_template,                                                           -- The approved template this delivery was rendered from.
  t.channel,                                                                    -- Email or SMS.
  t.recipient_key,                                                              -- Opaque recipient identifier; no personal data in the rulebook.
  t.sent_at,                                                                    -- When the message was dispatched.
  t.rendered_content_hash,                                                      -- Hash of the exact bytes delivered, for comparison against the approved rendering.
  t.approved_content_hash,                                                      -- Hash of the content as it stood at the approval gate.
  t.delivery_status,                                                            -- Provider-reported delivery outcome.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  calc_delivered_communications_has_authorization(t.delivered_communication_id) AS has_authorization,-- TRUE when this delivery names the approval that authorized it.
  calc_delivered_communications_content_matches_approval(t.delivered_communication_id) AS content_matches_approval,-- TRUE when the bytes delivered are the bytes approved.
  calc_delivered_communications_authorized_at(t.delivered_communication_id) AS authorized_at,-- When the authorizing approval completed.
  calc_delivered_communications_was_approved_before_sending(t.delivered_communication_id) AS was_approved_before_sending,-- TRUE when the approval preceded the send.
  calc_delivered_communications_is_defensible(t.delivered_communication_id) AS is_defensible-- TRUE when this delivery can be defended in a dispute: authorized, unaltered, and approved beforehand.
FROM delivered_communications t;

-- ----------------------------------------------------------------------------
-- vw_authority_boundaries: AuthorityBoundaries (added by witness loop 1).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_authority_boundaries CASCADE;
CREATE VIEW vw_authority_boundaries WITH (security_invoker = ON) AS
SELECT
  t.authority_boundary_id,                                                      -- Stored logical identifier for one AuthorityBoundaries row.
  calc_authority_boundaries_name(t.authority_boundary_id) AS name,              -- Human-readable calculated display alias for the AuthorityBoundaries row.
  t.step,                                                                       -- Step at which the boundary applies.
  t.forbidden_agent_kind,                                                       -- Agent kind that may not perform the forbidden decision kind: Human, AIAgent, or AutomatedPipeline.
  t.forbidden_decision_kind,                                                    -- Decision kind forbidden to that agent kind at this step.
  t.ratified_by_knowledge_fragment,                                             -- Knowledge fragment that states the boundary.
  t.enforcing_requirement,                                                      -- Requirement under which the boundary is enforced, if any.
  t.authority_role,                                                             -- Role accountable for the boundary.
  t.valid_from,                                                                 -- Start of the boundary's valid-time interval.
  t.valid_to,                                                                   -- End of the boundary's valid-time interval; null means open-ended.
  t.status,                                                                     -- Approved, Proposed, or Retired.
  t.evaluation_context,                                                         -- The evaluation context this boundary's currency is judged under.
  calc_authority_boundaries_as_of_instant(t.authority_boundary_id) AS as_of_instant,-- The evaluation instant this boundary is judged against.
  calc_authority_boundaries_is_currently_binding(t.authority_boundary_id) AS is_currently_binding,-- TRUE when this boundary is approved and inside its valid-time window right now.
  calc_authority_boundaries_ratifying_fragment_is_valid(t.authority_boundary_id) AS ratifying_fragment_is_valid,-- Whether the knowledge fragment that ratified this boundary is still valid.
  calc_authority_boundaries_step_when_binding(t.authority_boundary_id) AS step_when_binding,-- Echoes the step id when this boundary is currently binding, blank otherwise.
  calc_authority_boundaries_boundary_match_key(t.authority_boundary_id) AS boundary_match_key,-- Composite key of step, forbidden agent kind, and forbidden decision kind.
  calc_authority_boundaries_violation_count(t.authority_boundary_id) AS violation_count,-- Number of recorded decisions that this boundary forbids.
  calc_authority_boundaries_is_untested(t.authority_boundary_id) AS is_untested,-- TRUE when a binding boundary has never been triggered by any recorded decision.
  calc_authority_boundaries_has_ratifying_fragment(t.authority_boundary_id) AS has_ratifying_fragment,-- TRUE when this boundary names a knowledge fragment as its justification. FALSE means the rule constrains behaviour on nobody's recorded authority — strictly worse than resting on an expired claim, and previously invisible because the ratification lookup returned NULL.
  calc_authority_boundaries_is_unwarranted(t.authority_boundary_id) AS is_unwarranted,-- TRUE when a binding constraint on authority rests on no ratifying claim at all, or on one that is no longer valid. Either way the rule is being enforced without a live justification.
  calc_authority_boundaries_ratifying_fragment_is_overdue(t.authority_boundary_id) AS ratifying_fragment_is_overdue,-- Whether the fragment ratifying this boundary is past its review date.
  calc_authority_boundaries_ratifying_fragment_is_single_witness(t.authority_boundary_id) AS ratifying_fragment_is_single_witness,-- Whether the fragment ratifying this boundary rests on a single witness.
  calc_authority_boundaries_warrant_is_thin(t.authority_boundary_id) AS warrant_is_thin,-- A binding boundary whose ratifying knowledge is either overdue for review or single-sourced — still valid, but weakly warranted.
  calc_authority_boundaries_is_unwarranted_and_untested(t.authority_boundary_id) AS is_unwarranted_and_untested,-- A boundary whose ratification has lapsed and which no agent decision has ever been evaluated against — we cannot show it works and we cannot show why it exists.
  calc_authority_boundaries_unwarranted_boundary_step_key(t.authority_boundary_id) AS unwarranted_boundary_step_key,-- Composite-key echo: the step this boundary governs when the boundary is unwarranted, blank otherwise.
  calc_authority_boundaries_ratifying_fragment_key(t.authority_boundary_id) AS ratifying_fragment_key,-- Composite-key echo: the fragment ratifying this boundary when the boundary is currently binding, blank otherwise.
  calc_authority_boundaries_ratifying_fragment_status(t.authority_boundary_id) AS ratifying_fragment_status,-- The status string of the knowledge fragment that ratifies this boundary: Approved, Reviewed, Draft, or empty.
  calc_authority_boundaries_ratification_lapsed(t.authority_boundary_id) AS ratification_lapsed,-- TRUE when this boundary names a ratifying fragment and that fragment is no longer valid.
  calc_authority_boundaries_binds_despite_lapsed_ratification(t.authority_boundary_id) AS binds_despite_lapsed_ratification,-- TRUE when a boundary is still enforced against agents while the knowledge that authorized it has lapsed.
  calc_authority_boundaries_is_ungrounded_and_untested(t.authority_boundary_id) AS is_ungrounded_and_untested,-- TRUE when a boundary has lapsed ratification AND has never once been exercised -- so neither its authority nor its operation has ever been demonstrated.
  calc_authority_boundaries_constrained_role_assignment_key(t.authority_boundary_id) AS constrained_role_assignment_key,-- The role id this boundary constrains, emitted only when the boundary is ungrounded.
  t.semantic_type_iri                                                           -- Extension class IRI for an authority boundary.
FROM authority_boundaries t;

-- ----------------------------------------------------------------------------
-- vw_binding_observations: BindingObservations (added by witness loop 2).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_binding_observations CASCADE;
CREATE VIEW vw_binding_observations WITH (security_invoker = ON) AS
SELECT
  t.binding_observation_id,                                                     -- Primary key of an execution-side observation of one operational binding, frozen at the moment a step actually ran.
  calc_binding_observations_name(t.binding_observation_id) AS name,             -- Human-readable calculated display alias for the BindingObservations row.
  t.step_execution,                                                             -- The step execution during which this binding was read.
  t.operational_binding,                                                        -- The spec-side binding this observation instantiates.
  t.observed_source_timestamp,                                                  -- The LastObservedAt value the source actually carried at run time, captured then and never recomputed.
  t.read_at,                                                                    -- When the step execution actually read this binding.
  calc_binding_observations_sla_minutes_at_run(t.binding_observation_id) AS sla_minutes_at_run,-- The freshness SLA declared for this binding.
  calc_binding_observations_age_at_run_minutes(t.binding_observation_id) AS age_at_run_minutes,-- How old the source data was at the instant the step read it.
  calc_binding_observations_was_stale_at_run(t.binding_observation_id) AS was_stale_at_run,-- TRUE when an authoritative source was already outside its SLA at the moment the step consumed it.
  calc_binding_observations_is_authoritative_binding(t.binding_observation_id) AS is_authoritative_binding,-- Whether the binding observed is the authoritative source for its record key.
  calc_binding_observations_stale_at_run_step_key(t.binding_observation_id) AS stale_at_run_step_key-- Echoes the step execution id when the source was stale at run time.
FROM binding_observations t;

-- ----------------------------------------------------------------------------
-- vw_attestations: Attestations (added by witness loop 2).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_attestations CASCADE;
CREATE VIEW vw_attestations WITH (security_invoker = ON) AS
SELECT
  t.attestation_id,                                                             -- Primary key of a signature event: one person, one execution, one instant.
  calc_attestations_name(t.attestation_id) AS name,                             -- Human-readable calculated display alias for the Attestations row.
  t.procedure_execution,                                                        -- The execution being attested to.
  t.signed_by_agent,                                                            -- The human who signed.
  t.signed_at,                                                                  -- The instant of signature.
  t.assurance_grade_at_signing,                                                 -- The AssuranceGrade string as the model reported it at the moment of signature, captured then and never recomputed.
  t.version_was_fit_at_signing,                                                 -- Whether the executed procedure version was fit to execute at the moment of signature.
  calc_attestations_version_is_fit_now(t.attestation_id) AS version_is_fit_now, -- Whether the executed version reads as fit today.
  calc_attestations_fitness_verdict_has_drifted(t.attestation_id) AS fitness_verdict_has_drifted,-- TRUE when the fitness of the signed version reads differently today than it did at signature.
  calc_attestations_assurance_grade_now(t.attestation_id) AS assurance_grade_now,-- The AssuranceGrade the model reports for this execution today.
  calc_attestations_assurance_grade_has_drifted(t.attestation_id) AS assurance_grade_has_drifted,-- TRUE when the assurance behind this signature is described differently now than it was at signature.
  calc_attestations_would_not_survive_restatement(t.attestation_id) AS would_not_survive_restatement-- TRUE when re-deriving this attestation today would not reproduce what the model said when it was signed.
FROM attestations t;

-- ----------------------------------------------------------------------------
-- vw_app_role_profiles: One row per role, carrying how that role is presented: its accent colour, its 128x128 icon, and the login-card copy. Presentation is data, so the app never hardcodes a colour or a label per role.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_role_profiles CASCADE;
CREATE VIEW vw_app_role_profiles WITH (security_invoker = ON) AS
SELECT
  t.app_role_profile_id,                                                        -- Stored logical identifier for one AppRoleProfiles row.
  calc_app_role_profiles_name(t.app_role_profile_id) AS name,                   -- Human-readable calculated display alias for the AppRoleProfiles row.
  t.role,                                                                       -- The role this presentation profile describes.
  t.display_label,                                                              -- Label shown on the login card and in the app chrome.
  t.role_kind,                                                                  -- human or software. Drives the login-card silhouette and the icon plate shape.
  t.accent_color,                                                               -- Hex accent colour. Distinctive per role; used for chrome, the left-nav active state, and the icon plate.
  t.icon_mark,                                                                  -- Name of the geometric mark drawn on this role's icon. Colour is never the only signal — the mark discriminates in greyscale.
  t.icon_png_base64,                                                            -- 128x128 PNG icon for this role, base64-encoded, no data: prefix. Rendered on the login card and beside the role name throughout the app.
  t.pitch,                                                                      -- One line of login-card copy: what this role opens the app to do, in that role's own terms.
  t.sort_order,                                                                 -- Display order on the login screen. Human roles first, then software roles.
  calc_app_role_profiles_route_count(t.app_role_profile_id) AS route_count,     -- How many routes this role has.
  t.semantic_type_iri,                                                          -- Semantic type IRI for this row. An extension: PKO does not model application presentation.
  t.device,                                                                     -- The device this role's experience is designed for: phone or tablet.
  t.home_route,                                                                 -- The route this role lands on after signing in.
  t.home_title                                                                  -- The title of that home page, as the role would say it.
FROM app_role_profiles t;

-- ----------------------------------------------------------------------------
-- vw_app_nav_groups: The left-navigation section headers. A route names the group it appears under; the nav renders the groups its active role actually uses.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_nav_groups CASCADE;
CREATE VIEW vw_app_nav_groups WITH (security_invoker = ON) AS
SELECT
  t.app_nav_group_id,                                                           -- Stored logical identifier for one AppNavGroups row.
  calc_app_nav_groups_name(t.app_nav_group_id) AS name,                         -- Human-readable calculated display alias for the AppNavGroups row.
  t.group_label,                                                                -- Section header text rendered in the left navigation.
  calc_app_nav_groups_route_count(t.app_nav_group_id) AS route_count,           -- How many routes sit under this nav group across all roles.
  t.semantic_type_iri                                                           -- Semantic type IRI for this row. An extension: PKO does not model navigation.
FROM app_nav_groups t;

-- ----------------------------------------------------------------------------
-- vw_app_routes: One row per screen in the role-navigated application, as /{role}/{dashboard}/{entity...}. Each carries its purpose in the owning role's voice and brief layout hints, so a later build session has the brief without re-deriving it. Shared detail routes have no owning role.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_routes CASCADE;
CREATE VIEW vw_app_routes WITH (security_invoker = ON) AS
SELECT
  t.app_route_id,                                                               -- Stored logical identifier for one AppRoutes row.
  calc_app_routes_name(t.app_route_id) AS name,                                 -- Human-readable calculated display alias for the AppRoutes row.
  t.route_path,                                                                 -- The URL path, /{role}/{dashboard}/{entity...}. Shared detail routes live under /shared/ because the same entity serves every role.
  t.route_name,                                                                 -- Short label. This is the left-nav text.
  t.surface,                                                                    -- domain | maintainer. Domain routes belong to the twelve accountable Roles. Maintainer routes are the model's own instrumentation (Admin, Explorer) and deliberately have no owning role — 'admin' is not a role anyone is accountable in.
  t.owning_role,                                                                -- The role whose navigation contains this route. Null for shared routes reachable from several roles.
  t.nav_group,                                                                  -- Left-nav section this route appears under. Null for detail routes reached by drill-down rather than from the nav.
  t.nav_order,                                                                  -- Sort order within the nav group.
  t.route_kind,                                                                 -- dashboard | workspace | detail | index | action. Detail routes carry path parameters and are not in the nav.
  t.purpose,                                                                    -- What the role does here, in that role's own voice. This is the brief for the build session.
  t.layout_hints,                                                               -- Brief layout direction: the shape of the screen, what leads, and what must not be collapsed or implied.
  calc_app_routes_is_in_nav(t.app_route_id) AS is_in_nav,                       -- Whether this route appears in the left navigation. Detail routes do not.
  calc_app_routes_is_shared(t.app_route_id) AS is_shared,                       -- Whether this route is shared across domain roles rather than owned by one. A maintainer route is not shared — it belongs to a different surface entirely.
  calc_app_routes_is_maintainer(t.app_route_id) AS is_maintainer,               -- Whether this route is model instrumentation rather than a domain workspace. Maintainer routes are reached from the login page's maintainer section, not from a role card.
  calc_app_routes_question_count(t.app_route_id) AS question_count,             -- How many role questions this route helps answer.
  calc_app_routes_reference_count(t.app_route_id) AS reference_count,           -- How many other routes this route links to.
  calc_app_routes_answers_no_question(t.app_route_id) AS answers_no_question,   -- A domain route owned by a role that answers no role question. Not automatically wrong, but it should be justified. Maintainer routes are excluded: they answer questions about the model itself, which are not RoleQuestions and must not be fabricated as such.
  t.semantic_type_iri                                                           -- Semantic type IRI for this row. An extension: PKO models procedures, not the applications that display them.
FROM app_routes t;

-- ----------------------------------------------------------------------------
-- vw_app_route_questions: Junction: which RoleQuestions each route helps answer. Deliberately many-to-many — a question is answered across several routes and a route serves several questions. It is not, and should not become, 1:1.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_route_questions CASCADE;
CREATE VIEW vw_app_route_questions WITH (security_invoker = ON) AS
SELECT
  t.app_route_question_id,                                                      -- Stored logical identifier for one AppRouteQuestions row.
  calc_app_route_questions_name(t.app_route_question_id) AS name,               -- Human-readable calculated display alias for the AppRouteQuestions row.
  t.route,                                                                      -- The route that helps answer the question.
  t.question,                                                                   -- The role question this route helps answer.
  t.semantic_type_iri                                                           -- Semantic type IRI for this row. An extension.
FROM app_route_questions t;

-- ----------------------------------------------------------------------------
-- vw_app_route_references: Junction: which other routes a route links to. This is the navigation graph between screens, kept as rows rather than embedded lists so the canonical model stays a DAG.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_route_references CASCADE;
CREATE VIEW vw_app_route_references WITH (security_invoker = ON) AS
SELECT
  t.app_route_reference_id,                                                     -- Stored logical identifier for one AppRouteReferences row.
  calc_app_route_references_name(t.app_route_reference_id) AS name,             -- Human-readable calculated display alias for the AppRouteReferences row.
  t.from_route,                                                                 -- The route that links out.
  t.to_route,                                                                   -- The route being linked to.
  t.semantic_type_iri                                                           -- Semantic type IRI for this row. An extension.
FROM app_route_references t;

-- ----------------------------------------------------------------------------
-- vw_rulebook_tables: Census of every table in this rulebook. The table-level counterpart to RulebookFields, and the anchor every access policy points at. Derived by tools/reconcile_field_catalog.py -- never hand-maintained.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_rulebook_tables CASCADE;
CREATE VIEW vw_rulebook_tables WITH (security_invoker = ON) AS
SELECT
  t.rulebook_table_id,                                                          -- Primary key: the rulebook table name, verbatim. rulebook-to-postgres synthesizes a lowercased slug PK for a table with no <Entity>Id and rewrites every FK to it, which broke each formula comparing an FK to TableName.
  t.table_name,                                                                 -- Stored logical identifier: the rulebook table name, e.g. 'Procedures'.
  calc_rulebook_tables_name(t.rulebook_table_id) AS name,                       -- Human-readable calculated display alias.
  t.physical_table,                                                             -- snake_case Postgres base table name emitted by rulebook-to-postgres.
  t.physical_view,                                                              -- snake_case Postgres view name (vw_*) carrying the computed columns.
  t.subject_area,                                                               -- Coarse grouping used to organise role schemas, e.g. 'execution', 'governance'.
  t.is_extension,                                                               -- True when this table is an ERB extension rather than a native/aligned PKO term.
  calc_rulebook_tables_field_count(t.rulebook_table_id) AS field_count,         -- Number of catalogued fields on this table.
  calc_rulebook_tables_policy_count(t.rulebook_table_id) AS policy_count,       -- Number of access policies targeting this table.
  calc_rulebook_tables_is_unsecured(t.rulebook_table_id) AS is_unsecured,       -- True when RLS is enabled but no policy targets the table, so every principal sees zero rows. A fail-closed table nobody has granted access to.
  calc_rulebook_tables_disagreeing_substrate_count(t.rulebook_table_id) AS disagreeing_substrate_count,-- How many substrates got at least one cell of this table wrong in the latest conformance run.
  t.measured_row_count,                                                         -- Rows in this table's vw_* view, measured in Postgres by tools/measure_catalog.py.
  calc_rulebook_tables_has_measured_rows(t.rulebook_table_id) AS has_measured_rows,-- TRUE when Postgres holds at least one row of this table.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.organization_level,                                                         -- Conceptual (what kinds of thing exist), Structural (how instances are arranged) or Contextual (where knowledge applies).
  calc_rulebook_tables_semantic_mapping_count(t.rulebook_table_id) AS semantic_mapping_count,-- Semantic mappings for the table.
  calc_rulebook_tables_meaning_is_only_tabular(t.rulebook_table_id) AS meaning_is_only_tabular,-- TRUE for a table whose meaning is only its column layout: no mapping to any ontology term.
  calc_rulebook_tables_exact_mapping_count(t.rulebook_table_id) AS exact_mapping_count,-- Exact mappings of the table to a reused ontology term.
  calc_rulebook_tables_aligned_mapping_count(t.rulebook_table_id) AS aligned_mapping_count,-- Aligned mappings of the table to a reused standard.
  calc_rulebook_tables_is_unaligned_to_standard(t.rulebook_table_id) AS is_unaligned_to_standard,-- TRUE when a table maps to no term of any external standard, so outside systems cannot interpret it.
  calc_rulebook_tables_semantic_type_iri_field_count(t.rulebook_table_id) AS semantic_type_iri_field_count,-- SemanticTypeIri columns the table declares.
  calc_rulebook_tables_lacks_semantic_type_convention(t.rulebook_table_id) AS lacks_semantic_type_convention,-- TRUE when a table breaks the modeling convention that every row carries a SemanticTypeIri.
  calc_rulebook_tables_is_unsecured_governance_record(t.rulebook_table_id) AS is_unsecured_governance_record,-- TRUE for a governance table no access policy controls.
  calc_rulebook_tables_unrestricted_non_admin_policy_count(t.rulebook_table_id) AS unrestricted_non_admin_policy_count,-- How many of this table's row policies name a principal who is not an administrator and carry no row predicate, so that principal reads every row of the table.
  calc_rulebook_tables_restricted_non_admin_policy_count(t.rulebook_table_id) AS restricted_non_admin_policy_count,-- How many of this table's row policies name a principal who is not an administrator and do cut the rows that principal sees.
  calc_rulebook_tables_is_readable_in_full_by_non_admin(t.rulebook_table_id) AS is_readable_in_full_by_non_admin,-- Some principal who is not an administrator can read every row of this table: a policy exists, so the table is secured, but it controls nothing. This is the violation an access review looks for, and it is the reason 'has a policy' is not the test.
  calc_rulebook_tables_is_controlled_for_every_non_admin(t.rulebook_table_id) AS is_controlled_for_every_non_admin-- Every non-administrator who can reach this table reaches it through a policy that cuts rows. The table is not merely policed; access to it is controlled.
FROM rulebook_tables t;

-- ----------------------------------------------------------------------------
-- vw_access_principals: Security principals -- the identities policies attach to. A principal is the console persona a person logs in as; it maps many-to-one onto a domain Role, so 'who may see this row' is expressed once against the domain vocabulary while the UI keeps its own persona names. Each principal owns exactly one Postgres role and one Postgres schema.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_access_principals CASCADE;
CREATE VIEW vw_access_principals WITH (security_invoker = ON) AS
SELECT
  t.access_principal_id,                                                        -- Stored logical identifier, e.g. 'principal-controller'.
  calc_access_principals_name(t.access_principal_id) AS name,                   -- Human-readable calculated display alias.
  t.label,                                                                      -- Display label shown in the console role picker.
  t.domain_role,                                                                -- Domain role whose authority this principal exercises.
  t.pg_role_name,                                                               -- Postgres role name this principal authenticates as, e.g. 'pko_controller'.
  t.schema_name,                                                                -- Postgres schema that is this principal's entire visible world, e.g. 'pko_controller'.
  t.is_administrator,                                                           -- True when this principal may read every table and edit access policy.
  calc_access_principals_organization_scope(t.access_principal_id) AS organization_scope,-- Organization inherited from the domain role; the default tenancy boundary for row predicates.
  calc_access_principals_role_label(t.access_principal_id) AS role_label,       -- Label of the domain role, for display.
  calc_access_principals_policy_count(t.access_principal_id) AS policy_count,   -- Number of row policies granted to this principal.
  calc_access_principals_grant_count(t.access_principal_id) AS grant_count,     -- Number of field grants held by this principal.
  calc_access_principals_visible_table_count(t.access_principal_id) AS visible_table_count,-- Number of tables exposed in this principal's schema.
  calc_access_principals_has_no_access(t.access_principal_id) AS has_no_access, -- True when the principal holds no policies at all, so its schema is empty and it can read nothing. Fail-closed by construction.
  calc_access_principals_is_over_privileged(t.access_principal_id) AS is_over_privileged,-- True when a non-administrator principal can reach every table in the rulebook -- an admin-equivalent principal that was never declared as one.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM access_principals t;

-- ----------------------------------------------------------------------------
-- vw_access_policies: Row-level security policies: the VERTICAL cut. One row per principal x table x command, carrying the predicate that decides which rows are visible. RowPredicate is emitted verbatim into a Postgres USING clause, so it may call any SECURITY DEFINER calc_* function and therefore reference inference fields many hops down the DAG.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_access_policies CASCADE;
CREATE VIEW vw_access_policies WITH (security_invoker = ON) AS
SELECT
  t.access_policy_id,                                                           -- Stored logical identifier, e.g. 'pol-controller-procedures-select'.
  calc_access_policies_name(t.access_policy_id) AS name,                        -- Human-readable calculated display alias.
  t.principal,                                                                  -- Principal this policy grants to.
  t.target_table,                                                               -- Rulebook table this policy guards.
  t.command,                                                                    -- SQL command the policy governs: SELECT, INSERT, UPDATE, DELETE or ALL.
  t.row_predicate,                                                              -- SQL boolean expression emitted into USING(...). Empty means all rows of the table. Must not sub-select the guarded table -- Postgres raises infinite recursion; route such predicates through a SECURITY DEFINER function instead.
  t.check_predicate,                                                            -- SQL boolean expression emitted into WITH CHECK(...) for write commands. Empty reuses RowPredicate.
  t.rationale,                                                                  -- Why this principal is entitled to these rows, in the granting authority's words.
  t.references_inference,                                                       -- True when RowPredicate calls a calc_* function, i.e. the cut depends on a derived field rather than a stored column.
  calc_access_policies_is_write_command(t.access_policy_id) AS is_write_command,-- True when this policy governs a mutating command.
  calc_access_policies_is_unrestricted(t.access_policy_id) AS is_unrestricted,  -- True when the policy carries no predicate, exposing every row of the target table to the principal.
  calc_access_policies_principal_is_admin(t.access_policy_id) AS principal_is_admin,-- Whether the granted principal is an administrator.
  calc_access_policies_is_unrestricted_non_admin_grant(t.access_policy_id) AS is_unrestricted_non_admin_grant,-- True when a non-administrator principal is granted an unrestricted policy -- a whole-table exposure that no row predicate narrows. The single highest-signal privilege-escalation witness in the model.
  calc_access_policies_is_unwitnessed_write(t.access_policy_id) AS is_unwitnessed_write,-- True when a write policy has no denial test proving it refuses out-of-scope rows. An untested write grant is an assertion, not evidence.
  calc_access_policies_denial_test_count(t.access_policy_id) AS denial_test_count,-- Number of denial tests seeded against this policy.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM access_policies t;

-- ----------------------------------------------------------------------------
-- vw_field_grants: Field-level grants: the HORIZONTAL cut. One row per principal x field. A field with no grant row is not filtered from the principal's view -- it is absent from it, so the column does not exist as far as that principal's SQL is concerned.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_field_grants CASCADE;
CREATE VIEW vw_field_grants WITH (security_invoker = ON) AS
SELECT
  t.field_grant_id,                                                             -- Stored logical identifier, e.g. 'fg-controller-Procedures.Title'.
  calc_field_grants_name(t.field_grant_id) AS name,                             -- Human-readable calculated display alias.
  t.principal,                                                                  -- Principal receiving the grant.
  t.target_field,                                                               -- Catalogued field being exposed.
  t.can_read,                                                                   -- True when the principal may read this field.
  t.can_write,                                                                  -- True when the principal may write this field.
  t.mask_strategy,                                                              -- How the value is presented when read: 'plain', 'redacted' or 'hashed'.
  calc_field_grants_field_table(t.field_grant_id) AS field_table,               -- Table the granted field belongs to.
  calc_field_grants_field_name(t.field_grant_id) AS field_name,                 -- Name of the granted field.
  calc_field_grants_field_is_derived(t.field_grant_id) AS field_is_derived,     -- Whether the granted field is a derived (calculated/lookup/aggregation) field.
  calc_field_grants_is_writable_derived_field(t.field_grant_id) AS is_writable_derived_field,-- True when a derived field has been granted write access. Derived fields are computed by the substrate and cannot be written -- such a grant is incoherent and must be corrected.
  calc_field_grants_is_masked(t.field_grant_id) AS is_masked,                   -- True when the value is transformed rather than shown verbatim.
  calc_field_grants_grant_key_when_readable(t.field_grant_id) AS grant_key_when_readable,-- Composite echo of principal and table, blank unless readable. Enables single-criterion COUNTIFS rollups of readable columns per principal per table, per the documented multi-criteria COUNTIFS defect.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM field_grants t;

-- ----------------------------------------------------------------------------
-- vw_role_schemas: One Postgres schema per principal -- the principal's entire visible world. The schema is the only entry on that principal's search_path, so a table absent from it cannot be named at all.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_schemas CASCADE;
CREATE VIEW vw_role_schemas WITH (security_invoker = ON) AS
SELECT
  t.role_schema_id,                                                             -- Stored logical identifier, e.g. 'schema-controller'.
  calc_role_schemas_name(t.role_schema_id) AS name,                             -- Human-readable calculated display alias.
  t.principal,                                                                  -- Principal that owns this schema.
  t.schema_name,                                                                -- Postgres schema name, e.g. 'pko_controller'.
  calc_role_schemas_search_path(t.role_schema_id) AS search_path,               -- search_path set for this principal's sessions. The principal's own schema only -- public is deliberately excluded so base tables cannot be named.
  t.is_sealed,                                                                  -- True when the principal may not create objects in its own schema.
  calc_role_schemas_view_count(t.role_schema_id) AS view_count,                 -- Number of views exposed in this schema.
  calc_role_schemas_is_empty_schema(t.role_schema_id) AS is_empty_schema,       -- True when the schema exposes no views, so the principal can read nothing at all.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM role_schemas t;

-- ----------------------------------------------------------------------------
-- vw_role_schema_views: The emitted views: one per principal x table. ColumnList is DERIVED from FieldGrants, so toggling a single grant changes the emitted DDL with no second edit anywhere. This is what makes an admin's save reshape the database without touching UI code.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_schema_views CASCADE;
CREATE VIEW vw_role_schema_views WITH (security_invoker = ON) AS
SELECT
  t.role_schema_view_id,                                                        -- Stored logical identifier, e.g. 'rsv-controller-procedures'.
  calc_role_schema_views_name(t.role_schema_view_id) AS name,                   -- Human-readable calculated display alias.
  t.role_schema,                                                                -- Schema this view is emitted into.
  t.principal,                                                                  -- Principal that will read this view.
  t.target_table,                                                               -- Rulebook table this view exposes.
  t.view_name,                                                                  -- Unqualified view name inside the principal's schema, e.g. 'procedures'.
  calc_role_schema_views_schema_name(t.role_schema_view_id) AS schema_name,     -- Schema name, from the owning RoleSchemas row.
  calc_role_schema_views_source_view(t.role_schema_view_id) AS source_view,     -- Underlying computed view this narrows, e.g. 'vw_procedures'.
  calc_role_schema_views_grant_key(t.role_schema_view_id) AS grant_key,         -- Composite key matching FieldGrants.GrantKeyWhenReadable, used to roll up this view's readable column count.
  calc_role_schema_views_column_count(t.role_schema_view_id) AS column_count,   -- Number of columns exposed, derived live from the principal's readable field grants. Change one grant and this view's shape changes.
  calc_role_schema_views_table_field_count(t.role_schema_view_id) AS table_field_count,-- Total catalogued fields on the target table.
  calc_role_schema_views_is_full_width(t.role_schema_view_id) AS is_full_width, -- True when every field on the table is exposed, so the horizontal cut removes nothing.
  calc_role_schema_views_is_degenerate_view(t.role_schema_view_id) AS is_degenerate_view,-- True when the view exposes zero columns -- an emitted view that cannot be selected from. A generator that emits this has produced invalid DDL.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM role_schema_views t;

-- ----------------------------------------------------------------------------
-- vw_jwt_claim_mappings: Maps verified JWT claims onto the SQL accessors row predicates call. Magic-links is the notary: it asserts only that the bearer controls an email address. This table records how that verified email, and any additional claims, become values a policy can test.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_jwt_claim_mappings CASCADE;
CREATE VIEW vw_jwt_claim_mappings WITH (security_invoker = ON) AS
SELECT
  t.jwt_claim_mapping_id,                                                       -- Stored logical identifier, e.g. 'claim-email'.
  calc_jwt_claim_mappings_name(t.jwt_claim_mapping_id) AS name,                 -- Human-readable calculated display alias.
  t.claim_name,                                                                 -- Claim key as it appears in the verified JWT payload, e.g. 'email'.
  t.sql_accessor,                                                               -- SQL function a policy calls to read the claim, e.g. 'app.jwt_email()'.
  t.is_reserved_claim,                                                          -- True for claims magic-links controls and an app cannot override: email, iss, iat, nbf, exp, sub, tenant_id.
  t.maps_to_principal,                                                          -- True when this claim is what resolves the caller to an AccessPrincipals row.
  t.description2,                                                               -- What the claim asserts and who vouches for it.
  calc_jwt_claim_mappings_usage_count(t.jwt_claim_mapping_id) AS usage_count,   -- Number of policies whose predicate calls this accessor.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM jwt_claim_mappings t;

-- ----------------------------------------------------------------------------
-- vw_access_denial_tests: Denial witnesses. A policy with no failing case seeded against it is an assertion, not evidence -- the same acceptance bar the rest of this rulebook holds. Each row names a principal, a query, and the row that MUST NOT come back, so a policy that silently stops enforcing is caught by a red test rather than by an incident.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_access_denial_tests CASCADE;
CREATE VIEW vw_access_denial_tests WITH (security_invoker = ON) AS
SELECT
  t.access_denial_test_id,                                                      -- Stored logical identifier, e.g. 'deny-analyst-other-org-procedures'.
  calc_access_denial_tests_name(t.access_denial_test_id) AS name,               -- Human-readable calculated display alias.
  t.target_policy,                                                              -- Policy this test exercises.
  t.principal,                                                                  -- Principal the query runs as.
  t.target_table,                                                               -- Table queried.
  t.forbidden_row_id,                                                           -- Primary key of the row that must be invisible to this principal.
  t.expected_visible,                                                           -- False for a denial test: the row must not appear. True asserts a row the principal is entitled to does appear.
  t.observed_visible,                                                           -- What the substrate actually returned on the last run. Written back by the verifier, never hand-set.
  t.last_run_at,                                                                -- When this test was last executed against Postgres.
  calc_access_denial_tests_has_run(t.access_denial_test_id) AS has_run,         -- True once the test has been executed at least once.
  calc_access_denial_tests_is_passing(t.access_denial_test_id) AS is_passing,   -- True when observed visibility matches expectation.
  calc_access_denial_tests_is_leak(t.access_denial_test_id) AS is_leak,         -- True when a row that must be invisible was returned. A confirmed access-control breach.
  calc_access_denial_tests_is_unproven(t.access_denial_test_id) AS is_unproven, -- True when the test has never run, so it proves nothing regardless of how it is written.
  t.rationale,                                                                  -- Why this row must (or must not) be visible, and which predicate it exercises.
  calc_access_denial_tests_is_positive_control(t.access_denial_test_id) AS is_positive_control,-- True when this test asserts a row the principal IS entitled to. A denial suite with no positive controls cannot distinguish a working policy from one that denies everything.
  t.forbidden_table,                                                            -- For a table-absence witness: the table that must NOT exist in this principal's schema. Selecting it must raise 'relation does not exist', not return zero rows.
  t.forbidden_column,                                                           -- For a column-absence witness: the column that must NOT exist in this principal's view. Selecting it must raise 'column does not exist', not return null.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM access_denial_tests t;

-- ----------------------------------------------------------------------------
-- vw_app_users: Sign-in identities. One row per person or automation that can authenticate. EmailAddress is what a verified token asserts; everything else about the caller is resolved from here inside the database, never trusted from the token.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_users CASCADE;
CREATE VIEW vw_app_users WITH (security_invoker = ON) AS
SELECT
  t.app_user_id,                                                                -- Stored logical identifier, e.g. 'user-maria-chen'.
  calc_app_users_name(t.app_user_id) AS name,                                   -- Human-readable calculated display alias.
  t.email_address,                                                              -- Verified email. The one claim magic-links vouches for, and the join key from a token back to this row.
  t.display_name,                                                               -- Name shown in the console.
  t.linked_agent,                                                               -- Domain agent this sign-in identity corresponds to.
  t.is_enabled,                                                                 -- False disables sign-in without deleting the identity or its history.
  calc_app_users_agent_kind(t.app_user_id) AS agent_kind,                       -- Whether the linked agent is Human, AIAgent or AutomatedPipeline.
  calc_app_users_organization(t.app_user_id) AS organization,                   -- Organization inherited from the linked agent; the tenancy claim baked into issued tokens.
  calc_app_users_assignment_count(t.app_user_id) AS assignment_count,           -- Number of principals this user may act as.
  calc_app_users_has_no_principal(t.app_user_id) AS has_no_principal,           -- True when the user may act as no principal at all, so a successfully verified token still grants nothing. Authentication without authorization.
  calc_app_users_holds_multiple_principals(t.app_user_id) AS holds_multiple_principals,-- True when the user may act as more than one principal, so the principal cannot be inferred from the email alone and must be chosen explicitly at sign-in.
  calc_app_users_is_non_human_sign_in(t.app_user_id) AS is_non_human_sign_in,   -- True when a non-human agent has a sign-in identity. Pipelines and AI agents authenticate too, and their tokens are scoped exactly like a person's.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM app_users t;

-- ----------------------------------------------------------------------------
-- vw_principal_assignments: Which principals a user may act as. The authorization half of sign-in: a verified email proves who you are, this table decides what you may become. A user with two assignments picks one at sign-in, and the choice is verified here rather than accepted from the client.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_principal_assignments CASCADE;
CREATE VIEW vw_principal_assignments WITH (security_invoker = ON) AS
SELECT
  t.principal_assignment_id,                                                    -- Stored logical identifier, e.g. 'pa-maria-finance-analyst'.
  calc_principal_assignments_name(t.principal_assignment_id) AS name,           -- Human-readable calculated display alias.
  t.app_user,                                                                   -- Sign-in identity being granted.
  t.principal,                                                                  -- Principal the user may act as.
  t.is_default,                                                                 -- True for the principal selected when the user does not name one.
  t.granted_rationale,                                                          -- Why this user may act as this principal.
  calc_principal_assignments_principal_is_admin(t.principal_assignment_id) AS principal_is_admin,-- Whether the assigned principal is an administrator.
  calc_principal_assignments_user_organization(t.principal_assignment_id) AS user_organization,-- Organization of the signing-in user.
  calc_principal_assignments_principal_organization(t.principal_assignment_id) AS principal_organization,-- Organization of the principal being assumed.
  calc_principal_assignments_is_cross_organization_grant(t.principal_assignment_id) AS is_cross_organization_grant,-- True when a user is allowed to act as a principal in a different organization. Legitimate for shared-service roles, but it crosses the tenancy boundary and should be deliberate rather than accidental.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM principal_assignments t;

-- ----------------------------------------------------------------------------
-- vw_issued_tokens: Audit trail of every token minted. A token records which user signed in, which principal they chose, and the claims that were joined from the database at mint time -- so a later question of 'what could this session see' is answerable from data rather than reconstruction.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_issued_tokens CASCADE;
CREATE VIEW vw_issued_tokens WITH (security_invoker = ON) AS
SELECT
  t.issued_token_id,                                                            -- Stored logical identifier for one mint event.
  calc_issued_tokens_name(t.issued_token_id) AS name,                           -- Human-readable calculated display alias.
  t.app_user,                                                                   -- Identity that signed in.
  t.principal,                                                                  -- Principal the token authorises.
  t.issued_at,                                                                  -- When the token was minted.
  t.expires_at,                                                                 -- When the token stops being accepted.
  t.issuer,                                                                     -- Who minted it: 'dev-mint' locally, or the magic-links tenant URL in production.
  t.subject_claim,                                                              -- The 'sub' claim: the AppUserId the bearer is asserted to be.
  t.claims_snapshot,                                                            -- JSON of the additional claims joined from the database at mint time.
  calc_issued_tokens_is_dev_minted(t.issued_token_id) AS is_dev_minted,         -- True when issued by the local dev minter rather than a real magic-links tenant. Dev tokens are genuine RS256 tokens with a genuine keypair; they simply skip the email round-trip.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM issued_tokens t;

-- ----------------------------------------------------------------------------
-- vw_process_mining_runs: One conformance-checking run of a mined event log against a documented procedure version — a third kind of evidence, distinct from an elicitation session (someone's account) or a knowledge fragment (a claim): what the system of record actually did, discovered by process mining rather than told to us.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_mining_runs CASCADE;
CREATE VIEW vw_process_mining_runs WITH (security_invoker = ON) AS
SELECT
  t.process_mining_run_id,                                                      -- Stored logical identifier for one ProcessMiningRuns row.
  calc_process_mining_runs_name(t.process_mining_run_id) AS name,               -- Human-readable calculated display alias for the ProcessMiningRuns row.
  t.procedure_version,                                                          -- Procedure version this mined event log is checked against.
  t.event_log_source,                                                           -- System or log the event log was extracted from (e.g. an ERP audit log).
  t.mined_at,                                                                   -- When this mining/conformance-checking run was performed.
  t.discovered_variant_count,                                                   -- Distinct process variants discovered in the mined event log.
  t.conforming_variant_count,                                                   -- How many of the discovered variants exactly match a documented path through StepTransitions.
  t.deviation_description,                                                      -- Narrative of the most significant discovered deviation, if any.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_process_mining_runs_as_of_instant(t.process_mining_run_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged under.
  calc_process_mining_runs_conformance_rate(t.process_mining_run_id) AS conformance_rate,-- Share of discovered variants that conform to the documented procedure.
  calc_process_mining_runs_is_conformant(t.process_mining_run_id) AS is_conformant,-- TRUE when at least 80% of what actually happened matches what was documented.
  calc_process_mining_runs_has_major_drift_from_documentation(t.process_mining_run_id) AS has_major_drift_from_documentation,-- TRUE when less than half of what actually happened matches what was documented.
  calc_process_mining_runs_days_since_mined(t.process_mining_run_id) AS days_since_mined,-- Days elapsed since this event log was mined.
  calc_process_mining_runs_is_stale_mining_evidence(t.process_mining_run_id) AS is_stale_mining_evidence,-- TRUE when this mining evidence is more than 180 days old.
  calc_process_mining_runs_procedure_version_is_live(t.process_mining_run_id) AS procedure_version_is_live,-- Whether the procedure version this run was checked against is currently live.
  calc_process_mining_runs_is_drift_on_live_version(t.process_mining_run_id) AS is_drift_on_live_version,-- TRUE when a major, real, mined deviation exists against a procedure version people are actually executing right now.
  calc_process_mining_runs_drifted_mining_run_key(t.process_mining_run_id) AS drifted_mining_run_key,-- Composite-key echo: this run's procedure version when the run drifted on a live version, else blank.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  calc_process_mining_runs_people_capture_complement_count(t.process_mining_run_id) AS people_capture_complement_count,-- Captures from people that hold the reasoning behind this run's findings.
  calc_process_mining_runs_is_deviation_unexplained_by_people(t.process_mining_run_id) AS is_deviation_unexplained_by_people,-- TRUE when mining found non-conforming variants and no capture from experienced workers explains them.
  calc_process_mining_runs_undocumented_path_count(t.process_mining_run_id) AS undocumented_path_count,-- Mined hand-offs the documented model does not contain.
  calc_process_mining_runs_has_undocumented_enacted_path(t.process_mining_run_id) AS has_undocumented_enacted_path,-- TRUE when the enacted flow the run reconstructed contains a path the documentation lacks.
  calc_process_mining_runs_conformance_percent(t.process_mining_run_id) AS conformance_percent-- The share of the paths people really took that match the documented procedure, as a whole percent.
FROM process_mining_runs t;

-- ----------------------------------------------------------------------------
-- vw_vocabularies: A controlled vocabulary / SKOS-style concept scheme — one facet of standardized terminology (e.g. a family of control categories) that Requirements and other rows can point at instead of restating the concept in free text each time.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_vocabularies CASCADE;
CREATE VIEW vw_vocabularies WITH (security_invoker = ON) AS
SELECT
  t.vocabulary_id,                                                              -- Stored logical identifier for one Vocabularies row.
  calc_vocabularies_name(t.vocabulary_id) AS name,                              -- Human-readable calculated display alias for the Vocabularies row.
  t.title,                                                                      -- Human-facing name of this controlled vocabulary.
  t.scheme_uri,                                                                 -- SKOS ConceptScheme IRI for this vocabulary.
  t.governing_role,                                                             -- Role accountable for defining and maintaining terms in this vocabulary.
  calc_vocabularies_term_count(t.vocabulary_id) AS term_count,                  -- How many terms belong to this vocabulary.
  calc_vocabularies_orphan_term_count(t.vocabulary_id) AS orphan_term_count,    -- How many terms in this vocabulary have never actually been used.
  calc_vocabularies_has_orphan_terms(t.vocabulary_id) AS has_orphan_terms,      -- TRUE when this vocabulary has at least one defined-but-unused term.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.scheme_kind,                                                                -- ControlledVocabulary, Taxonomy or Thesaurus.
  t.model_layer,                                                                -- VocabularyLayer for controlled concept schemes, kept apart from the ontology layer.
  t.governed_dimension,                                                         -- What the scheme controls: Activity, Role, WorkflowStatus, ArtifactType, AgentCapability, ...
  t.publication_format,                                                         -- How the scheme is published: SKOS Turtle, or a PDF glossary.
  t.prefix,                                                                     -- Namespace prefix.
  t.established_at,                                                             -- When vocabulary control was established.
  t.ontology_modeling_started_at,                                               -- When ontology modeling for the same domain began.
  t.governs_procedure,                                                          -- Procedure whose knowledge the scheme controls.
  calc_vocabularies_is_machine_accessible(t.vocabulary_id) AS is_machine_accessible,-- TRUE when the scheme has an IRI and is published as SKOS.
  calc_vocabularies_managed_scheme_procedure_key(t.vocabulary_id) AS managed_scheme_procedure_key,-- Procedure key when the scheme's metadata is managed.
  calc_vocabularies_organized_transcript_count(t.vocabulary_id) AS organized_transcript_count,-- Transcript materials organized into the scheme.
  calc_vocabularies_organized_field_notes_count(t.vocabulary_id) AS organized_field_notes_count,-- FieldNotes materials organized into the scheme.
  calc_vocabularies_organized_process_map_count(t.vocabulary_id) AS organized_process_map_count,-- ProcessMap materials organized into the scheme.
  calc_vocabularies_organized_mined_event_trace_count(t.vocabulary_id) AS organized_mined_event_trace_count,-- MinedEventTrace materials organized into the scheme.
  calc_vocabularies_organized_document_excerpt_count(t.vocabulary_id) AS organized_document_excerpt_count,-- DocumentExcerpt materials organized into the scheme.
  calc_vocabularies_organized_material_count(t.vocabulary_id) AS organized_material_count,-- Materials organized into the scheme.
  calc_vocabularies_organized_kind_count(t.vocabulary_id) AS organized_kind_count,-- Different kinds of material the scheme holds.
  calc_vocabularies_is_single_kind_frame(t.vocabulary_id) AS is_single_kind_frame,-- TRUE when a scheme organizes several materials but only one kind of knowledge.
  calc_vocabularies_latest_organized_material_at(t.vocabulary_id) AS latest_organized_material_at,-- Most recent collection date among materials organized into the scheme.
  calc_vocabularies_refinement_count(t.vocabulary_id) AS refinement_count,      -- Refinements made to the scheme.
  calc_vocabularies_is_frozen_despite_new_collection(t.vocabulary_id) AS is_frozen_despite_new_collection,-- TRUE when material collected after the scheme was established has never led to a refinement.
  calc_vocabularies_ontology_preceded_vocabulary_control(t.vocabulary_id) AS ontology_preceded_vocabulary_control-- TRUE when ontology modeling began before vocabulary control was established for the domain.
FROM vocabularies t;

-- ----------------------------------------------------------------------------
-- vw_vocabulary_terms: One controlled, defined term (a SKOS Concept) within a Vocabulary. Requirements point at a VocabularyTerm instead of free-texting the same concept in a new Statement every time.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_vocabulary_terms CASCADE;
CREATE VIEW vw_vocabulary_terms WITH (security_invoker = ON) AS
SELECT
  t.vocabulary_term_id,                                                         -- Stored logical identifier for one VocabularyTerms row.
  calc_vocabulary_terms_name(t.vocabulary_term_id) AS name,                     -- Human-readable calculated display alias for the VocabularyTerms row.
  t.vocabulary,                                                                 -- Vocabulary this term belongs to.
  t.pref_label,                                                                 -- SKOS preferred label — the controlled term itself.
  t.alt_labels,                                                                 -- Comma-separated synonyms this term should also match.
  t.definition,                                                                 -- SKOS definition of what this term means.
  calc_vocabulary_terms_usage_count(t.vocabulary_term_id) AS usage_count,       -- How many Requirements point at this exact term instead of free-texting the concept.
  calc_vocabulary_terms_is_orphan_term(t.vocabulary_term_id) AS is_orphan_term, -- TRUE when this term has been defined but nothing in the model actually uses it yet.
  calc_vocabulary_terms_is_widely_adopted_term(t.vocabulary_term_id) AS is_widely_adopted_term,-- TRUE when more than one Requirement shares this exact controlled term.
  calc_vocabulary_terms_orphan_term_vocabulary_key(t.vocabulary_term_id) AS orphan_term_vocabulary_key,-- Composite-key echo: this term's vocabulary when the term is an orphan, else blank.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.scope_note,                                                                 -- SKOS scope note: how the concept is to be used.
  t.broader_term,                                                               -- Direct broader concept (skos:broader).
  calc_vocabulary_terms_broader_term_parent(t.vocabulary_term_id) AS broader_term_parent,-- Broader concept of the broader concept.
  calc_vocabulary_terms_scheme_governed_dimension(t.vocabulary_term_id) AS scheme_governed_dimension,-- What the concept's scheme controls.
  t.concept_iri,                                                                -- Globally unique IRI of the concept.
  t.namespace_iri,                                                              -- Namespace the concept belongs to.
  t.same_as_iri,                                                                -- External term this concept is asserted identical to (owl:sameAs).
  t.introduced_in_release,                                                      -- Model release that introduced the concept.
  calc_vocabulary_terms_introduced_release_issued_at(t.vocabulary_term_id) AS introduced_release_issued_at,-- When that release was issued.
  t.represents_role,                                                            -- For a role-vocabulary concept, the role it names.
  t.definition_revised_at,                                                      -- When the definition was last revised.
  calc_vocabulary_terms_latest_meaning_change_at(t.vocabulary_term_id) AS latest_meaning_change_at,-- Most recent change in what the organization means by the term.
  calc_vocabulary_terms_has_stale_definition(t.vocabulary_term_id) AS has_stale_definition,-- TRUE when the organization's meaning changed after the definition was last revised.
  calc_vocabulary_terms_structural_shift_count(t.vocabulary_term_id) AS structural_shift_count,-- Structural meaning changes to a sense that had held for about two years or more.
  calc_vocabulary_terms_has_structural_sense_shift_across_years(t.vocabulary_term_id) AS has_structural_sense_shift_across_years,-- TRUE when what the term refers to changed shape after holding for years.
  calc_vocabulary_terms_pref_label_practitioner_mention_count(t.vocabulary_term_id) AS pref_label_practitioner_mention_count,-- Practitioner mentions using the preferred label.
  calc_vocabulary_terms_alt_label_practitioner_mention_count(t.vocabulary_term_id) AS alt_label_practitioner_mention_count,-- Practitioner mentions using an alternative label.
  calc_vocabulary_terms_is_organized_around_official_term(t.vocabulary_term_id) AS is_organized_around_official_term,-- TRUE when practitioners repeatedly use an alternative wording more than the preferred label the scheme is organized around.
  calc_vocabulary_terms_source_phrasing_count(t.vocabulary_term_id) AS source_phrasing_count,-- Mentions judged to mean the concept.
  calc_vocabulary_terms_unreconciled_phrasing_count(t.vocabulary_term_id) AS unreconciled_phrasing_count,-- Such mentions whose wording the scheme does not resolve.
  calc_vocabulary_terms_has_unreconciled_variant_phrasings(t.vocabulary_term_id) AS has_unreconciled_variant_phrasings-- TRUE when one concept appears under several phrasings and some are not reconciled to it.
FROM vocabulary_terms t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_broker_links: An informal expertise-network edge: one agent naming another as who they actually go to for a topic, independent of any formal Role or RoleAssignment. RoleAssignments and CommunitiesOfPractice record who is SUPPOSED to know something; this records who people ACTUALLY rely on.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_broker_links CASCADE;
CREATE VIEW vw_knowledge_broker_links WITH (security_invoker = ON) AS
SELECT
  t.knowledge_broker_link_id,                                                   -- Stored logical identifier for one KnowledgeBrokerLinks row.
  calc_knowledge_broker_links_name(t.knowledge_broker_link_id) AS name,         -- Human-readable calculated display alias for the KnowledgeBrokerLinks row.
  t.seeker,                                                                     -- The agent who goes to someone else for this topic.
  t.broker,                                                                     -- The agent who is actually consulted, whether or not they hold a formal role for it.
  t.topic,                                                                      -- The controlled topic this reliance is about.
  t.frequency,                                                                  -- Rarely, Sometimes, or Often.
  t.last_consulted_at,                                                          -- When the seeker last actually consulted the broker on this topic.
  t.evaluation_context,                                                         -- The evaluation context this row's time-dependent witnesses are judged under.
  calc_knowledge_broker_links_as_of_instant(t.knowledge_broker_link_id) AS as_of_instant,-- The evaluation instant this row's time-dependent witnesses are judged under.
  calc_knowledge_broker_links_days_since_consulted(t.knowledge_broker_link_id) AS days_since_consulted,-- Days elapsed since the seeker last consulted the broker.
  calc_knowledge_broker_links_is_active_reliance(t.knowledge_broker_link_id) AS is_active_reliance,-- TRUE when this is a live, ongoing informal dependency rather than a one-off or stale contact.
  calc_knowledge_broker_links_broker_is_still_engaged(t.knowledge_broker_link_id) AS broker_is_still_engaged,-- Whether the broker being relied on still holds any current role at all.
  calc_knowledge_broker_links_is_at_risk_reliance(t.knowledge_broker_link_id) AS is_at_risk_reliance,-- TRUE when someone is actively relying on a broker who has already left every role they held.
  calc_knowledge_broker_links_active_reliance_broker_key(t.knowledge_broker_link_id) AS active_reliance_broker_key,-- Composite-key echo: the broker this link names when the reliance is active, else blank.
  calc_knowledge_broker_links_at_risk_broker_key(t.knowledge_broker_link_id) AS at_risk_broker_key,-- Composite-key echo: the broker this link names when the reliance is at risk, else blank.
  t.semantic_type_iri,                                                          -- Extension class IRI.
  t.points_to_know_how,                                                         -- The know-how the broker points the seeker to.
  calc_knowledge_broker_links_pointed_holder(t.knowledge_broker_link_id) AS pointed_holder,-- Who carries that know-how.
  calc_knowledge_broker_links_locates_other_holder(t.knowledge_broker_link_id) AS locates_other_holder,-- TRUE when the broker knows where know-how is held by someone other than themselves.
  t.seeker_vocabulary,                                                          -- The vocabulary the seeker's community speaks.
  t.seeker_wording,                                                             -- The seeker's word for the topic.
  t.holder_vocabulary,                                                          -- The vocabulary of the community holding the know-how.
  t.holder_wording,                                                             -- The holding community's word for the topic.
  calc_knowledge_broker_links_translation_between_vocabularies(t.knowledge_broker_link_id) AS translation_between_vocabularies-- The broker's translation between the two communities' words; blank when none was needed.
FROM knowledge_broker_links t;

-- ----------------------------------------------------------------------------
-- vw_conformance_substrates: Every tool that compiles this rulebook into something that computes. One is the answer-key author (compile-rulebook bakes derived values into the rulebook's own rows); the rest are graded substrates that re-derive those values natively and are scored cell by cell against them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_conformance_substrates CASCADE;
CREATE VIEW vw_conformance_substrates WITH (security_invoker = ON) AS
SELECT
  t.conformance_substrate_id,                                                   -- Substrate name as the conformance harness knows it, e.g. 'effortless-python'.
  calc_conformance_substrates_name(t.conformance_substrate_id) AS name,         -- Human-readable calculated display alias.
  t.label,                                                                      -- Short human label, e.g. 'Python'.
  t.transpiler,                                                                 -- The effortless.json tool that produces this substrate, e.g. 'rulebook-to-python'.
  t.output_folder,                                                              -- Project folder the tool writes into, e.g. '/effortless-python'.
  t.engine,                                                                     -- What actually evaluates the formulas: a database, a language runtime, a spreadsheet engine or a reasoner.
  t.how_it_computes,                                                            -- One paragraph a curious reader can follow: what the tool emits and how the harness makes it produce answers.
  t.role,                                                                       -- 'answer-key' for the tool whose stored values every other substrate is graded against; 'graded' for everything else.
  t.sort_order,                                                                 -- Display order.
  calc_conformance_substrates_is_graded(t.conformance_substrate_id) AS is_graded,-- True for substrates the harness scores.
  calc_conformance_substrates_run_count(t.conformance_substrate_id) AS run_count,-- How many recorded conformance runs graded this substrate.
  calc_conformance_substrates_latest_cells_tested(t.conformance_substrate_id) AS latest_cells_tested,-- Cells graded in the latest run: every (record x derived field) pair in the answer keys.
  calc_conformance_substrates_latest_cells_passed(t.conformance_substrate_id) AS latest_cells_passed,-- Cells this substrate computed identically to the answer key in the latest run.
  calc_conformance_substrates_latest_harness_errors(t.conformance_substrate_id) AS latest_harness_errors,-- 1 when the latest run could not execute this substrate at all.
  calc_conformance_substrates_latest_cells_failed(t.conformance_substrate_id) AS latest_cells_failed,-- Cells this substrate got wrong, or did not produce, in the latest run.
  calc_conformance_substrates_latest_score(t.conformance_substrate_id) AS latest_score,-- Percent of cells agreeing with the answer key in the latest run.
  calc_conformance_substrates_disagreeing_field_count(t.conformance_substrate_id) AS disagreeing_field_count,-- Derived fields on which this substrate got at least one cell wrong in the latest run.
  calc_conformance_substrates_disagreeing_table_count(t.conformance_substrate_id) AS disagreeing_table_count,-- Tables on which this substrate got at least one cell wrong in the latest run.
  calc_conformance_substrates_is_fully_conformant(t.conformance_substrate_id) AS is_fully_conformant,-- True when the latest run graded this substrate, it ran, and every cell agreed. A substrate never graded is not conformant.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM conformance_substrates t;

-- ----------------------------------------------------------------------------
-- vw_conformance_runs: One execution of the conformance harness over every graded substrate. Kept as history; exactly one run is marked IsLatest, and the per-table, per-field and per-cell detail tables describe that run.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_conformance_runs CASCADE;
CREATE VIEW vw_conformance_runs WITH (security_invoker = ON) AS
SELECT
  t.conformance_run_id,                                                         -- Stored logical identifier, e.g. 'run-20260913-171500'.
  calc_conformance_runs_name(t.conformance_run_id) AS name,                     -- Human-readable calculated display alias.
  t.ran_on,                                                                     -- When the harness graded the substrates.
  t.rulebook_commit,                                                            -- git HEAD of the repository when the run was recorded; the rulebook may also carry uncommitted edits, noted in Notes.
  t.answer_key_author,                                                          -- The substrate whose stored values were the answer keys for this run.
  t.is_latest,                                                                  -- True for the most recent recorded run only. The recorder moves it.
  t.notes,                                                                      -- Anything a reader needs to interpret the run.
  calc_conformance_runs_substrate_count(t.conformance_run_id) AS substrate_count,-- Substrates graded in this run.
  calc_conformance_runs_perfect_substrate_count(t.conformance_run_id) AS perfect_substrate_count,-- Substrates that ran and agreed on every cell.
  calc_conformance_runs_cells_tested(t.conformance_run_id) AS cells_tested,     -- Cells graded across all substrates.
  calc_conformance_runs_cells_passed(t.conformance_run_id) AS cells_passed,     -- Cells that agreed across all substrates.
  calc_conformance_runs_cells_failed(t.conformance_run_id) AS cells_failed,     -- Cells that disagreed across all substrates.
  calc_conformance_runs_overall_score(t.conformance_run_id) AS overall_score,   -- Percent of all graded cells, across all substrates, that agreed.
  calc_conformance_runs_imperfect_substrate_count(t.conformance_run_id) AS imperfect_substrate_count,-- Substrates with at least one disagreeing cell or a harness error.
  calc_conformance_runs_is_fully_conformant(t.conformance_run_id) AS is_fully_conformant,-- True when every substrate graded in this run agreed on every cell: the 100% bar.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM conformance_runs t;

-- ----------------------------------------------------------------------------
-- vw_substrate_run_scores: One substrate's grade in one conformance run, split by field class so a substrate that does scalar math natively but not cross-table joins reads as exactly that.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_substrate_run_scores CASCADE;
CREATE VIEW vw_substrate_run_scores WITH (security_invoker = ON) AS
SELECT
  t.substrate_run_score_id,                                                     -- Stored logical identifier: '<run>|<substrate>'.
  calc_substrate_run_scores_name(t.substrate_run_score_id) AS name,             -- Human-readable calculated display alias.
  t.run,                                                                        -- The run that produced this grade.
  t.substrate,                                                                  -- The substrate graded.
  t.harness_error,                                                              -- Why the substrate could not be run, verbatim from the harness. Blank when it ran.
  t.duration_seconds,                                                           -- Wall-clock seconds to produce answers.
  t.cells_tested,                                                               -- Every (record x derived field) pair in the answer keys.
  t.cells_passed,                                                               -- Cells matching the answer key.
  t.calculated_tested,                                                          -- Cells of calculated (same-row formula) fields.
  t.calculated_passed,                                                          -- Calculated cells that matched.
  t.lookup_tested,                                                              -- Cells of lookup (cross-table INDEX/MATCH) fields.
  t.lookup_passed,                                                              -- Lookup cells that matched.
  t.aggregation_tested,                                                         -- Cells of aggregation (COUNTIFS/SUMIFS rollup) fields.
  t.aggregation_passed,                                                         -- Aggregation cells that matched.
  calc_substrate_run_scores_cells_failed(t.substrate_run_score_id) AS cells_failed,-- Cells that did not match.
  calc_substrate_run_scores_score(t.substrate_run_score_id) AS score,           -- Percent of cells matching.
  calc_substrate_run_scores_calculated_score(t.substrate_run_score_id) AS calculated_score,-- Percent of calculated cells matching.
  calc_substrate_run_scores_lookup_score(t.substrate_run_score_id) AS lookup_score,-- Percent of lookup cells matching.
  calc_substrate_run_scores_aggregation_score(t.substrate_run_score_id) AS aggregation_score,-- Percent of aggregation cells matching.
  calc_substrate_run_scores_is_perfect(t.substrate_run_score_id) AS is_perfect, -- True when the substrate ran and matched every cell.
  calc_substrate_run_scores_perfect_run_key(t.substrate_run_score_id) AS perfect_run_key,-- The run id when this grade is perfect, else blank; lets the run count its perfect substrates with a single-criterion COUNTIFS.
  calc_substrate_run_scores_is_in_latest_run(t.substrate_run_score_id) AS is_in_latest_run,-- Whether this grade belongs to the latest run.
  calc_substrate_run_scores_latest_cells_tested(t.substrate_run_score_id) AS latest_cells_tested,-- CellsTested when in the latest run, else 0.
  calc_substrate_run_scores_latest_cells_passed(t.substrate_run_score_id) AS latest_cells_passed,-- CellsPassed when in the latest run, else 0.
  calc_substrate_run_scores_latest_error_flag(t.substrate_run_score_id) AS latest_error_flag,-- 1 when this is the latest run and the harness could not run the substrate.
  calc_substrate_run_scores_substrate_label(t.substrate_run_score_id) AS substrate_label,-- The substrate's short label.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM substrate_run_scores t;

-- ----------------------------------------------------------------------------
-- vw_table_conformance: Latest run only: how one substrate did on one table. The grid of these rows is the substrate-by-table heatmap.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_table_conformance CASCADE;
CREATE VIEW vw_table_conformance WITH (security_invoker = ON) AS
SELECT
  t.table_conformance_id,                                                       -- Stored logical identifier: '<substrate>|<Table>'.
  calc_table_conformance_name(t.table_conformance_id) AS name,                  -- Human-readable calculated display alias.
  t.run,                                                                        -- The run this row describes.
  t.substrate,                                                                  -- The substrate graded.
  t.rulebook_table,                                                             -- The table graded.
  t.record_count,                                                               -- Rows in the answer key for this table.
  t.derived_field_count,                                                        -- Derived fields graded on this table.
  t.cells_tested,                                                               -- RecordCount x DerivedFieldCount.
  t.cells_passed,                                                               -- Cells matching the answer key.
  t.is_missing_answer_file,                                                     -- True when the substrate produced no answers for this table at all; every cell then counts as failed.
  calc_table_conformance_cells_failed(t.table_conformance_id) AS cells_failed,  -- Cells that did not match.
  calc_table_conformance_score(t.table_conformance_id) AS score,                -- Percent of cells matching.
  calc_table_conformance_is_perfect(t.table_conformance_id) AS is_perfect,      -- True when every cell matched.
  calc_table_conformance_imperfect_substrate_key(t.table_conformance_id) AS imperfect_substrate_key,-- The substrate id when this table is imperfect, else blank.
  calc_table_conformance_imperfect_table_key(t.table_conformance_id) AS imperfect_table_key,-- The table id when this table is imperfect, else blank.
  calc_table_conformance_disagreeing_field_count(t.table_conformance_id) AS disagreeing_field_count,-- Fields on this table the substrate got at least one cell wrong.
  calc_table_conformance_substrate_label(t.table_conformance_id) AS substrate_label,-- The substrate's short label.
  calc_table_conformance_subject_area(t.table_conformance_id) AS subject_area,  -- The table's subject area.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM table_conformance t;

-- ----------------------------------------------------------------------------
-- vw_field_disagreements: Latest run only: a derived field on which one substrate got at least one cell wrong. A field with no row here agreed everywhere. CellsFailed is the true count; CellDisagreements holds a sample of the cells.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_field_disagreements CASCADE;
CREATE VIEW vw_field_disagreements WITH (security_invoker = ON) AS
SELECT
  t.field_disagreement_id,                                                      -- Stored logical identifier: '<substrate>|<Table>.<Field>'.
  calc_field_disagreements_name(t.field_disagreement_id) AS name,               -- Human-readable calculated display alias.
  t.substrate,                                                                  -- The substrate that disagreed.
  t.rulebook_field,                                                             -- The field it disagreed on.
  t.table_conformance,                                                          -- The substrate-by-table row this field belongs to.
  t.field_class,                                                                -- calculated, lookup or aggregation.
  t.cells_failed,                                                               -- Every cell of this field the substrate got wrong, not just the sampled ones.
  t.dominant_reason,                                                            -- The harness's most frequent reason: 'wrong/null value', 'missing record' or 'missing entity file'.
  calc_field_disagreements_sampled_cell_count(t.field_disagreement_id) AS sampled_cell_count,-- Failing cells recorded as CellDisagreements rows.
  calc_field_disagreements_is_fully_sampled(t.field_disagreement_id) AS is_fully_sampled,-- True when every failing cell is recorded, not just a sample.
  calc_field_disagreements_formula(t.field_disagreement_id) AS formula,         -- The formula every substrate was asked to compute, shown as evidence.
  calc_field_disagreements_substrate_label(t.field_disagreement_id) AS substrate_label,-- The substrate's short label.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM field_disagreements t;

-- ----------------------------------------------------------------------------
-- vw_cell_disagreements: Latest run only: one cell a substrate computed differently from the answer key, with both values verbatim. Sampled per field; see FieldDisagreements.IsFullySampled.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_cell_disagreements CASCADE;
CREATE VIEW vw_cell_disagreements WITH (security_invoker = ON) AS
SELECT
  t.cell_disagreement_id,                                                       -- Stored logical identifier: '<substrate>|<Table>.<Field>|<record id>'.
  calc_cell_disagreements_name(t.cell_disagreement_id) AS name,                 -- Human-readable calculated display alias.
  t.field_disagreement,                                                         -- The substrate-by-field disagreement this cell belongs to.
  t.record_id,                                                                  -- Primary key of the row whose cell disagreed.
  t.expected_value,                                                             -- The answer key's value, JSON-encoded so null, '', false and 0 stay distinguishable.
  t.actual_value,                                                               -- The substrate's value, JSON-encoded the same way.
  t.reason,                                                                     -- The harness's reason: 'wrong/null value', 'missing record' or 'missing entity file'.
  calc_cell_disagreements_substrate(t.cell_disagreement_id) AS substrate,       -- The substrate that produced ActualValue.
  calc_cell_disagreements_rulebook_field(t.cell_disagreement_id) AS rulebook_field,-- The field.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM cell_disagreements t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_methods: Named methods, techniques and methodologies for eliciting, analysing, modeling and governing process knowledge. A method is only evidence that the model uses it when a seeded row applies it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_methods CASCADE;
CREATE VIEW vw_knowledge_methods WITH (security_invoker = ON) AS
SELECT
  t.knowledge_method_id,                                                        -- Stored identifier; PascalCase method key.
  calc_knowledge_methods_name(t.knowledge_method_id) AS name,                   -- Display name.
  t.label,                                                                      -- Human-readable method name.
  t.method_family,                                                              -- Elicitation | Analysis | Modeling | Encoding | Governance.
  t.summary,                                                                    -- What the method does, paraphrased.
  t.origin_reference,                                                           -- Where the method comes from.
  calc_knowledge_methods_elicitation_use_count(t.knowledge_method_id) AS elicitation_use_count,-- Elicitation sessions run with this method.
  calc_knowledge_methods_application_count(t.knowledge_method_id) AS application_count,-- Recorded applications of this method to model artifacts.
  calc_knowledge_methods_usage_count(t.knowledge_method_id) AS usage_count,     -- Every recorded application of this method across the model.
  calc_knowledge_methods_is_applied(t.knowledge_method_id) AS is_applied,       -- TRUE when at least one seeded row applies this method.
  t.elicitation_tradeoff,                                                       -- What the method gives up (accuracy or depth) and what it gains (practicality or reach).
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_methods t;

-- ----------------------------------------------------------------------------
-- vw_source_articles: The articles this rulebook was bootstrapped from. Coverage of each is computed from its claims; the article text itself is never stored.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_source_articles CASCADE;
CREATE VIEW vw_source_articles WITH (security_invoker = ON) AS
SELECT
  t.source_article_id,                                                          -- Stored identifier.
  calc_source_articles_name(t.source_article_id) AS name,                       -- Display name.
  t.title,                                                                      -- Article title.
  t.author,                                                                     -- Article author.
  t.series,                                                                     -- Publication series.
  t.published_on,                                                               -- Publication date.
  t.local_file_name,                                                            -- File name under bootstrap/git-ignored-articles/ (never committed).
  t.thesis,                                                                     -- The article's thesis, paraphrased.
  calc_source_articles_claim_count(t.source_article_id) AS claim_count,         -- Claims inventoried from this article.
  calc_source_articles_covered_claim_count(t.source_article_id) AS covered_claim_count,-- Claims with at least one valid piece of evidence.
  calc_source_articles_agreed_claim_count(t.source_article_id) AS agreed_claim_count,-- Covered claims whose evidence every graded substrate agrees on.
  calc_source_articles_uncovered_claim_count(t.source_article_id) AS uncovered_claim_count,-- Claims with no valid evidence.
  calc_source_articles_coverage_percent(t.source_article_id) AS coverage_percent,-- Share of this article's claims that are covered.
  calc_source_articles_agreed_coverage_percent(t.source_article_id) AS agreed_coverage_percent,-- Share of claims covered by evidence no graded substrate disputes.
  calc_source_articles_is_fully_covered(t.source_article_id) AS is_fully_covered,-- TRUE when every claim in this article is covered.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM source_articles t;

-- ----------------------------------------------------------------------------
-- vw_article_claims: One row per thing a source article says a process-knowledge system must represent, do, answer or use. Paraphrased with a section reference; never quoted.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_article_claims CASCADE;
CREATE VIEW vw_article_claims WITH (security_invoker = ON) AS
SELECT
  t.article_claim_id,                                                           -- Stored identifier.
  calc_article_claims_name(t.article_claim_id) AS name,                         -- Display name.
  t.source_article,                                                             -- Article the claim comes from.
  t.claim_kind,                                                                 -- Concept | Prescription | CompetencyQuestion | Standard | Scenario | Illustration.
  t.section_ref,                                                                -- Section of the article where the claim is made.
  t.claim_text,                                                                 -- The claim, paraphrased.
  calc_article_claims_required_evidence(t.article_claim_id) AS required_evidence,-- The evidence this kind of claim demands, stated in words.
  calc_article_claims_evidence_count(t.article_claim_id) AS evidence_count,     -- Evidence rows offered for this claim.
  calc_article_claims_valid_evidence_count(t.article_claim_id) AS valid_evidence_count,-- Evidence rows that meet the bar for this claim's kind.
  calc_article_claims_agreed_evidence_count(t.article_claim_id) AS agreed_evidence_count,-- Valid evidence rows no graded substrate disputes.
  calc_article_claims_is_covered(t.article_claim_id) AS is_covered,             -- TRUE when at least one evidence row meets the bar.
  calc_article_claims_is_agreed(t.article_claim_id) AS is_agreed,               -- TRUE when at least one valid evidence row is undisputed by every graded substrate.
  calc_article_claims_has_rejected_evidence(t.article_claim_id) AS has_rejected_evidence,-- TRUE when evidence was offered and none of it meets the bar.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM article_claims t;

-- ----------------------------------------------------------------------------
-- vw_claim_evidence: A proposed piece of evidence that the model covers a claim, with the justification a skeptic can audit. Whether it counts is computed in IsValid from measured facts, never asserted.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_claim_evidence CASCADE;
CREATE VIEW vw_claim_evidence WITH (security_invoker = ON) AS
SELECT
  t.claim_evidence_id,                                                          -- Stored identifier.
  calc_claim_evidence_name(t.claim_evidence_id) AS name,                        -- Display name.
  t.article_claim,                                                              -- The claim this evidence supports.
  t.evidence_kind,                                                              -- Field | Table | RoleQuestion | OntologyProfile | KnowledgeMethod | Procedure.
  t.rulebook_field,                                                             -- Evidence field, when EvidenceKind is Field.
  t.rulebook_table,                                                             -- Evidence table, when EvidenceKind is Table.
  t.role_question,                                                              -- Evidence question, when EvidenceKind is RoleQuestion.
  t.ontology_profile,                                                           -- Evidence profile, when EvidenceKind is OntologyProfile.
  t.knowledge_method,                                                           -- Evidence method, when EvidenceKind is KnowledgeMethod.
  t.procedure,                                                                  -- Evidence procedure, when EvidenceKind is Procedure.
  t.justification,                                                              -- How this evidence answers the claim, in words a skeptic can check.
  calc_claim_evidence_claim_kind(t.claim_evidence_id) AS claim_kind,            -- Kind of the claim this evidence supports.
  calc_claim_evidence_field_catalog_name(t.claim_evidence_id) AS field_catalog_name,-- The evidence field's name as the catalog records it; blank when the field does not exist.
  calc_claim_evidence_field_is_witness(t.claim_evidence_id) AS field_is_witness,-- Whether the evidence field was invented for a role question.
  calc_claim_evidence_field_has_data(t.claim_evidence_id) AS field_has_data,    -- Whether Postgres holds data for the evidence field.
  calc_claim_evidence_field_is_discriminating(t.claim_evidence_id) AS field_is_discriminating,-- Whether the evidence field tells rows apart.
  calc_claim_evidence_field_is_contested(t.claim_evidence_id) AS field_is_contested,-- Whether a graded substrate disagrees on the evidence field.
  calc_claim_evidence_table_has_rows(t.claim_evidence_id) AS table_has_rows,    -- Whether Postgres holds rows of the evidence table.
  calc_claim_evidence_question_is_answered(t.claim_evidence_id) AS question_is_answered,-- Whether the evidence question has predicates.
  calc_claim_evidence_question_witnessed_answer(t.claim_evidence_id) AS question_witnessed_answer,-- The substrate-computed answer of the evidence question.
  calc_claim_evidence_profile_mapping_count(t.claim_evidence_id) AS profile_mapping_count,-- Semantic mappings using the evidence profile.
  calc_claim_evidence_method_is_applied(t.claim_evidence_id) AS method_is_applied,-- Whether a seeded row applies the evidence method.
  calc_claim_evidence_procedure_execution_count(t.claim_evidence_id) AS procedure_execution_count,-- Recorded executions of the evidence procedure.
  calc_claim_evidence_has_justification(t.claim_evidence_id) AS has_justification,-- TRUE when the justification is written.
  calc_claim_evidence_is_witness_proof(t.claim_evidence_id) AS is_witness_proof,-- Evidence is an existing field invented for a role question that discriminates.
  calc_claim_evidence_is_structural_proof(t.claim_evidence_id) AS is_structural_proof,-- Evidence is a table with rows or a field with data.
  calc_claim_evidence_is_question_proof(t.claim_evidence_id) AS is_question_proof,-- Evidence is an answered role question with a computed answer.
  calc_claim_evidence_is_standard_proof(t.claim_evidence_id) AS is_standard_proof,-- Evidence is a mapped ontology profile or an applied knowledge method.
  calc_claim_evidence_is_scenario_proof(t.claim_evidence_id) AS is_scenario_proof,-- Evidence is a procedure with recorded executions.
  calc_claim_evidence_is_valid(t.claim_evidence_id) AS is_valid,                -- TRUE when the evidence is justified and is the kind of proof this claim's kind demands.
  calc_claim_evidence_is_contested(t.claim_evidence_id) AS is_contested,        -- TRUE when the evidence field is disputed by a graded substrate.
  calc_claim_evidence_is_agreed_evidence(t.claim_evidence_id) AS is_agreed_evidence,-- TRUE when the evidence is valid and no graded substrate disputes it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM claim_evidence t;

-- ----------------------------------------------------------------------------
-- vw_method_applications: One recorded application of a knowledge method to a concrete artifact of this model. Themes add a relationship column here for the artifact table they apply a method to.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_method_applications CASCADE;
CREATE VIEW vw_method_applications WITH (security_invoker = ON) AS
SELECT
  t.method_application_id,                                                      -- Stored identifier.
  calc_method_applications_name(t.method_application_id) AS name,               -- Display name.
  t.knowledge_method,                                                           -- Method applied.
  t.applied_to,                                                                 -- The artifact the method was applied to, in words.
  t.applied_at,                                                                 -- When.
  t.applied_by_agent,                                                           -- Who applied it.
  t.applied_to_grounding_snapshot,                                              -- Grounding snapshot the method was applied to.
  t.identified_broker,                                                          -- A connector between groups that a network analysis identified.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM method_applications t;

-- ----------------------------------------------------------------------------
-- vw_lifecycle_statuses: Every status a procedure version or an execution can hold, as one controlled scheme. PKO 2.0.0 types procedure statuses and execution statuses as specializations of one general status.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_lifecycle_statuses CASCADE;
CREATE VIEW vw_lifecycle_statuses WITH (security_invoker = ON) AS
SELECT
  t.lifecycle_status_id,                                                        -- Stored identifier.
  calc_lifecycle_statuses_name(t.lifecycle_status_id) AS name,                  -- Display name.
  t.label,                                                                      -- Status label.
  t.status_scheme,                                                              -- ProcedureStatus or ProcedureExecutionStatus.
  t.broader_status,                                                             -- The general status concept this one specializes.
  t.is_pko_status,                                                              -- TRUE when PKO 2.0.0 defines this individual.
  t.pko_iri,                                                                    -- The PKO individual IRI, when there is one.
  calc_lifecycle_statuses_version_use_count(t.lifecycle_status_id) AS version_use_count,-- Procedure versions currently holding this status.
  calc_lifecycle_statuses_execution_use_count(t.lifecycle_status_id) AS execution_use_count,-- Procedure executions currently holding this status.
  calc_lifecycle_statuses_is_non_pko_status_in_use(t.lifecycle_status_id) AS is_non_pko_status_in_use,-- TRUE when a status PKO does not define is held by some version or execution.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.workflow_status_concept                                                     -- Concept of the controlled workflow-status scheme this status maps to.
FROM lifecycle_statuses t;

-- ----------------------------------------------------------------------------
-- vw_facilities: Sites, factories and areas where procedures run (pko-ind:Site, pko-ind:Factory, pko-ind:Area).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_facilities CASCADE;
CREATE VIEW vw_facilities WITH (security_invoker = ON) AS
SELECT
  t.facility_id,                                                                -- Stored identifier.
  calc_facilities_name(t.facility_id) AS name,                                  -- Display name.
  t.label,                                                                      -- Facility name.
  t.organization,                                                               -- Organization operating the facility.
  t.facility_kind,                                                              -- Site, Factory or Area.
  t.parent_facility,                                                            -- Facility this one is part of.
  calc_facilities_deviating_run_count(t.facility_id) AS deviating_run_count,    -- Procedure executions here with at least one step deviation.
  calc_facilities_clean_run_count(t.facility_id) AS clean_run_count,            -- Procedure executions here with no step deviation.
  calc_facilities_is_deviation_only_facility(t.facility_id) AS is_deviation_only_facility,-- TRUE when every recorded execution at this facility deviated, while the procedure is run cleanly elsewhere.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM facilities t;

-- ----------------------------------------------------------------------------
-- vw_machine_types: Kinds of machine (pko-ind:MachineType).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_machine_types CASCADE;
CREATE VIEW vw_machine_types WITH (security_invoker = ON) AS
SELECT
  t.machine_type_id,                                                            -- Stored identifier.
  calc_machine_types_name(t.machine_type_id) AS name,                           -- Display name.
  t.label,                                                                      -- Machine type.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM machine_types t;

-- ----------------------------------------------------------------------------
-- vw_energy_sources: Hazardous energy sources a machine carries (pko-ind:EnergySource individuals).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_energy_sources CASCADE;
CREATE VIEW vw_energy_sources WITH (security_invoker = ON) AS
SELECT
  t.energy_source_id,                                                           -- Stored identifier.
  calc_energy_sources_name(t.energy_source_id) AS name,                         -- Display name.
  t.label,                                                                      -- Energy source.
  t.pko_individual_iri,                                                         -- The PKO industry individual.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM energy_sources t;

-- ----------------------------------------------------------------------------
-- vw_machines: Machines procedures are executed on (pko-ind:Machine).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_machines CASCADE;
CREATE VIEW vw_machines WITH (security_invoker = ON) AS
SELECT
  t.machine_id,                                                                 -- Stored identifier.
  calc_machines_name(t.machine_id) AS name,                                     -- Display name.
  t.label,                                                                      -- Machine name.
  t.machine_type,                                                               -- Kind of machine (pko-ind:hasMachineType).
  t.facility,                                                                   -- Where the machine stands (pko-ind:hasSite / hasArea).
  t.manufactured_by,                                                            -- Manufacturer (pko-ind:wasManufacturedBy).
  t.configuration_kind,                                                         -- Standard, or NonStandard for a retrofitted or unusual configuration.
  t.governing_procedure_version,                                                -- The lockout procedure version that must isolate this machine.
  calc_machines_energy_source_count(t.machine_id) AS energy_source_count,       -- Energy sources this machine carries.
  calc_machines_unisolated_energy_source_count(t.machine_id) AS unisolated_energy_source_count,-- Energy sources the governing procedure has no isolation step for.
  calc_machines_is_non_standard_configuration(t.machine_id) AS is_non_standard_configuration,-- TRUE for an unusually configured machine.
  calc_machines_has_unisolated_energy_source(t.machine_id) AS has_unisolated_energy_source,-- TRUE when the governing lockout procedure cannot isolate every energy source this machine carries.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM machines t;

-- ----------------------------------------------------------------------------
-- vw_machine_energy_sources: Which energy sources each machine carries.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_machine_energy_sources CASCADE;
CREATE VIEW vw_machine_energy_sources WITH (security_invoker = ON) AS
SELECT
  t.machine_energy_source_id,                                                   -- Stored identifier.
  calc_machine_energy_sources_name(t.machine_energy_source_id) AS name,         -- Display name.
  t.machine,                                                                    -- Machine.
  t.energy_source,                                                              -- Energy source.
  calc_machine_energy_sources_machine_procedure_version(t.machine_energy_source_id) AS machine_procedure_version,-- The lockout procedure version governing the machine.
  calc_machine_energy_sources_isolation_step_count(t.machine_energy_source_id) AS isolation_step_count,-- Steps of the governing procedure version that isolate this energy source.
  calc_machine_energy_sources_is_unisolated_energy_source(t.machine_energy_source_id) AS is_unisolated_energy_source,-- TRUE when no step of the governing procedure isolates this energy source.
  calc_machine_energy_sources_unisolated_machine_key(t.machine_energy_source_id) AS unisolated_machine_key,-- Machine key when unisolated, else blank.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM machine_energy_sources t;

-- ----------------------------------------------------------------------------
-- vw_lock_devices: Lockout devices a step can require (pko-ind:Lock individuals).
