-- ----------------------------------------------------------------------------
-- vw_step_protective_equipment: Protective equipment a step requires (pko-ind:requiresPPE).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_protective_equipment CASCADE;
CREATE VIEW vw_step_protective_equipment WITH (security_invoker = ON) AS
SELECT
  t.step_protective_equipment_id,                                               -- Stored identifier.
  calc_step_protective_equipment_name(t.step_protective_equipment_id) AS name,  -- Display name.
  t.step,                                                                       -- Step.
  t.protective_equipment,                                                       -- Required equipment.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM step_protective_equipment t;

-- ----------------------------------------------------------------------------
-- vw_regulatory_frameworks: Regulatory frameworks that require procedures or controls (industry module).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_regulatory_frameworks CASCADE;
CREATE VIEW vw_regulatory_frameworks WITH (security_invoker = ON) AS
SELECT
  t.regulatory_framework_id,                                                    -- Stored identifier.
  calc_regulatory_frameworks_name(t.regulatory_framework_id) AS name,           -- Display name.
  t.label,                                                                      -- Framework name.
  t.jurisdiction,                                                               -- Where it applies.
  calc_regulatory_frameworks_requirement_count(t.regulatory_framework_id) AS requirement_count,-- Requirements this framework imposes.
  calc_regulatory_frameworks_required_procedure_count(t.regulatory_framework_id) AS required_procedure_count,-- Procedures this framework makes mandatory.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM regulatory_frameworks t;

-- ----------------------------------------------------------------------------
-- vw_procedure_targets: The things a procedure is about (pko:hasProcedureTarget).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_targets CASCADE;
CREATE VIEW vw_procedure_targets WITH (security_invoker = ON) AS
SELECT
  t.procedure_target_id,                                                        -- Stored identifier.
  calc_procedure_targets_name(t.procedure_target_id) AS name,                   -- Display name.
  t.procedure,                                                                  -- Procedure whose target this is.
  t.label,                                                                      -- Target.
  t.target_kind,                                                                -- Machine, DataSystem, Population or Service.
  t.machine,                                                                    -- The machine, when the target is one.
  calc_procedure_targets_machine_is_non_standard(t.procedure_target_id) AS machine_is_non_standard,-- Whether the target machine is unusually configured.
  calc_procedure_targets_handling_failure_mode_count(t.procedure_target_id) AS handling_failure_mode_count,-- Failure modes that give handling for this target.
  calc_procedure_targets_is_unhandled_non_standard_target(t.procedure_target_id) AS is_unhandled_non_standard_target,-- TRUE for an unusually configured machine target with no documented handling.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM procedure_targets t;

-- ----------------------------------------------------------------------------
-- vw_procedure_adoptions: Organizations that adopt a procedure, and how (pko:isAdoptedBy).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_adoptions CASCADE;
CREATE VIEW vw_procedure_adoptions WITH (security_invoker = ON) AS
SELECT
  t.procedure_adoption_id,                                                      -- Stored identifier.
  calc_procedure_adoptions_name(t.procedure_adoption_id) AS name,               -- Display name.
  t.procedure,                                                                  -- Adopted procedure.
  t.organization,                                                               -- Adopting organization.
  t.adopted_at,                                                                 -- When adopted.
  t.adoption_mode,                                                              -- AsIs, Extended, Reference, or blank when nobody recorded the choice.
  calc_procedure_adoptions_is_adoption_mode_unstated(t.procedure_adoption_id) AS is_adoption_mode_unstated,-- TRUE when an organization adopted the procedure without stating whether as is, extended or as a reference.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM procedure_adoptions t;

-- ----------------------------------------------------------------------------
-- vw_procedure_outcome_criteria: Criteria by which a procedure's outcome counts as success or failure.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_outcome_criteria CASCADE;
CREATE VIEW vw_procedure_outcome_criteria WITH (security_invoker = ON) AS
SELECT
  t.procedure_outcome_criterion_id,                                             -- Stored identifier.
  calc_procedure_outcome_criteria_name(t.procedure_outcome_criterion_id) AS name,-- Display name.
  t.procedure,                                                                  -- Procedure.
  t.polarity,                                                                   -- Success or Failure.
  t.statement,                                                                  -- The criterion.
  calc_procedure_outcome_criteria_failure_procedure_key(t.procedure_outcome_criterion_id) AS failure_procedure_key,-- Procedure key for a failure criterion.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM procedure_outcome_criteria t;

-- ----------------------------------------------------------------------------
-- vw_relation_types: The defined relationship types process elements may be linked by.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_relation_types CASCADE;
CREATE VIEW vw_relation_types WITH (security_invoker = ON) AS
SELECT
  t.relation_type_id,                                                           -- Stored identifier.
  calc_relation_types_name(t.relation_type_id) AS name,                         -- Display name.
  t.label,                                                                      -- Relation.
  t.family,                                                                     -- Temporal, Compositional, Causal or Role.
  t.inverse_label,                                                              -- The inverse reading.
  t.is_defined,                                                                 -- TRUE once ratified; FALSE for a proposed type.
  t.realized_by,                                                                -- Where the model realizes this relation when it is not an ActivityRelations row.
  calc_relation_types_usage_count(t.relation_type_id) AS usage_count,           -- Activity relations of this type.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM relation_types t;

-- ----------------------------------------------------------------------------
-- vw_activity_relations: Temporal and causal relations between steps beyond simple sequence.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_activity_relations CASCADE;
CREATE VIEW vw_activity_relations WITH (security_invoker = ON) AS
SELECT
  t.activity_relation_id,                                                       -- Stored identifier.
  calc_activity_relations_name(t.activity_relation_id) AS name,                 -- Display name.
  t.from_step,                                                                  -- Subject step.
  t.relation_type,                                                              -- Relation.
  t.to_step,                                                                    -- Object step.
  t.rationale,                                                                  -- Why the relation holds.
  calc_activity_relations_relation_type_is_defined(t.activity_relation_id) AS relation_type_is_defined,-- Whether the relation type has been ratified.
  calc_activity_relations_uses_undefined_relation_type(t.activity_relation_id) AS uses_undefined_relation_type,-- TRUE when two steps are linked by a relation type nobody has defined.
  calc_activity_relations_from_step_version(t.activity_relation_id) AS from_step_version,-- Version of the subject step.
  calc_activity_relations_overlaps_version_key(t.activity_relation_id) AS overlaps_version_key,-- Version key for an overlaps relation.
  calc_activity_relations_enables_version_key(t.activity_relation_id) AS enables_version_key,-- Version key for an enables relation.
  calc_activity_relations_prevents_version_key(t.activity_relation_id) AS prevents_version_key,-- Version key for a prevents relation.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM activity_relations t;

-- ----------------------------------------------------------------------------
-- vw_step_variables: Input and output variables a step declares (pplan:Variable, pplan:hasInputVar / hasOutputVar).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_variables CASCADE;
CREATE VIEW vw_step_variables WITH (security_invoker = ON) AS
SELECT
  t.step_variable_id,                                                           -- Stored identifier.
  calc_step_variables_name(t.step_variable_id) AS name,                         -- Display name.
  t.step,                                                                       -- Declaring step.
  t.direction,                                                                  -- Input or Output.
  t.label,                                                                      -- Variable name.
  t.datatype,                                                                   -- What kind of thing the variable holds.
  t.source_variable,                                                            -- For an input, the output variable of an earlier step that feeds it.
  t.is_external_input,                                                          -- TRUE for an input supplied from outside the procedure.
  calc_step_variables_source_direction(t.step_variable_id) AS source_direction, -- Direction of the feeding variable.
  calc_step_variables_source_step(t.step_variable_id) AS source_step,           -- Step that produces the feeding variable.
  calc_step_variables_is_dangling_input(t.step_variable_id) AS is_dangling_input,-- TRUE for an input no earlier step produces and nobody declared as external: the step cannot be run as specified.
  calc_step_variables_is_miswired_source(t.step_variable_id) AS is_miswired_source,-- TRUE when an input is fed from a variable that is not an output.
  calc_step_variables_consumer_count(t.step_variable_id) AS consumer_count,     -- Inputs this variable feeds.
  calc_step_variables_input_step_key(t.step_variable_id) AS input_step_key,     -- Step key for an input variable.
  calc_step_variables_output_step_key(t.step_variable_id) AS output_step_key,   -- Step key for an output variable.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.expected_format,                                                            -- Media type the variable's value must have.
  calc_step_variables_step_accountable_agent(t.step_variable_id) AS step_accountable_agent,-- Agent accountable for the declaring step.
  calc_step_variables_step_agent_kind(t.step_variable_id) AS step_agent_kind,   -- Kind of that agent.
  calc_step_variables_consumer_role(t.step_variable_id) AS consumer_role,       -- Role responsible for the declaring step.
  calc_step_variables_consumer_workflow(t.step_variable_id) AS consumer_workflow,-- Procedure version containing the declaring step.
  calc_step_variables_source_step_agent(t.step_variable_id) AS source_step_agent,-- Agent accountable for the step producing the feeding variable.
  calc_step_variables_source_step_agent_kind(t.step_variable_id) AS source_step_agent_kind,-- Kind of that agent.
  calc_step_variables_is_input_from_ai_artifact(t.step_variable_id) AS is_input_from_ai_artifact,-- TRUE for an input fed by an artifact that a step held by an AI agent produces.
  calc_step_variables_ai_artifact_consumer_has_no_accountable_age(t.step_variable_id) AS ai_artifact_consumer_has_no_accountable_agent,-- TRUE when a step consuming an AI agent's artifact has nobody holding its role.
  calc_step_variables_ai_blast_radius_path(t.step_variable_id) AS ai_blast_radius_path-- For an input fed by an AI agent's artifact: the agent, the artifact, the consuming step, its role, its agent and its workflow.
FROM step_variables t;

-- ----------------------------------------------------------------------------
-- vw_execution_entities: Entities a step execution used or generated (prov:used, prov:wasGeneratedBy, pplan:correspondsToVariable).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_execution_entities CASCADE;
CREATE VIEW vw_execution_entities WITH (security_invoker = ON) AS
SELECT
  t.execution_entity_id,                                                        -- Stored identifier.
  calc_execution_entities_name(t.execution_entity_id) AS name,                  -- Display name.
  t.step_execution,                                                             -- Step execution.
  t.step_variable,                                                              -- Declared variable the entity corresponds to.
  t.usage,                                                                      -- Used or Generated.
  t.entity_label,                                                               -- The entity.
  t.entity_uri,                                                                 -- Where the entity lives.
  calc_execution_entities_variable_direction(t.execution_entity_id) AS variable_direction,-- Direction of the declared variable.
  calc_execution_entities_variable_step(t.execution_entity_id) AS variable_step,-- Step that declares the variable.
  calc_execution_entities_executed_step(t.execution_entity_id) AS executed_step,-- Step the execution executed.
  calc_execution_entities_is_usage_direction_mismatch(t.execution_entity_id) AS is_usage_direction_mismatch,-- TRUE when a used entity maps to an output or a generated entity maps to an input.
  calc_execution_entities_is_foreign_variable(t.execution_entity_id) AS is_foreign_variable,-- TRUE when the entity corresponds to a variable another step declares.
  calc_execution_entities_used_execution_key(t.execution_entity_id) AS used_execution_key,-- Step execution key for a used entity.
  calc_execution_entities_generated_execution_key(t.execution_entity_id) AS generated_execution_key,-- Step execution key for a generated entity.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.recorded_datatype,                                                          -- Datatype of the entity actually recorded.
  t.recorded_format,                                                            -- Media type of the entity actually recorded.
  calc_execution_entities_variable_datatype(t.execution_entity_id) AS variable_datatype,-- Datatype the variable declares.
  calc_execution_entities_variable_expected_format(t.execution_entity_id) AS variable_expected_format,-- Format the variable declares.
  calc_execution_entities_violates_declared_datatype_or_format(t.execution_entity_id) AS violates_declared_datatype_or_format,-- TRUE when a recorded value's datatype or format differs from what its variable declares.
  calc_execution_entities_generating_agent(t.execution_entity_id) AS generating_agent,-- Agent that executed the step execution.
  calc_execution_entities_attributed_to_agent(t.execution_entity_id) AS attributed_to_agent-- For a generated entity, the agent it is attributed to (prov:wasAttributedTo).
FROM execution_entities t;

-- ----------------------------------------------------------------------------
-- vw_step_conditions: Pre-conditions, post-conditions and invariants of a step.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_conditions CASCADE;
CREATE VIEW vw_step_conditions WITH (security_invoker = ON) AS
SELECT
  t.step_condition_id,                                                          -- Stored identifier.
  calc_step_conditions_name(t.step_condition_id) AS name,                       -- Display name.
  t.step,                                                                       -- Step.
  t.condition_kind,                                                             -- Precondition, Postcondition or Invariant.
  t.statement,                                                                  -- The condition.
  t.is_safety_critical,                                                         -- TRUE when breaking it endangers people.
  calc_step_conditions_check_count(t.step_condition_id) AS check_count,         -- Times the condition was checked.
  calc_step_conditions_is_never_checked(t.step_condition_id) AS is_never_checked,-- TRUE for a condition no execution has ever checked.
  calc_step_conditions_precondition_step_key(t.step_condition_id) AS precondition_step_key,-- Step key for a precondition.
  calc_step_conditions_postcondition_step_key(t.step_condition_id) AS postcondition_step_key,-- Step key for a postcondition.
  calc_step_conditions_invariant_step_key(t.step_condition_id) AS invariant_step_key,-- Step key for an invariant.
  calc_step_conditions_safety_critical_step_key(t.step_condition_id) AS safety_critical_step_key,-- Step key for a safety-critical condition.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.machine_expression,                                                         -- The condition as an expression an agent or constraint engine can evaluate.
  calc_step_conditions_is_machine_parseable(t.step_condition_id) AS is_machine_parseable,-- TRUE when the condition is stored as an expression, not only prose.
  t.enforces_requirement,                                                       -- The blocking requirement this condition is the physical check of, when it is one. A failed check of the condition is then a failure of that requirement.
  calc_step_conditions_enforced_requirement_is_computed(t.step_condition_id) AS enforced_requirement_is_computed,-- Whether the requirement this condition enforces has a computed witness (loop 18): a failed check of it is then a breach the register counts on its own.
  calc_step_conditions_enforced_requirement_statement(t.step_condition_id) AS enforced_requirement_statement-- The statement of the requirement this condition enforces, for the desk that shows a breach.
FROM step_conditions t;

-- ----------------------------------------------------------------------------
-- vw_condition_checks: A step condition checked during a step execution.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_condition_checks CASCADE;
CREATE VIEW vw_condition_checks WITH (security_invoker = ON) AS
SELECT
  t.condition_check_id,                                                         -- Stored identifier.
  calc_condition_checks_name(t.condition_check_id) AS name,                     -- Display name.
  t.step_execution,                                                             -- Step execution.
  t.step_condition,                                                             -- Condition checked.
  t.held,                                                                       -- Whether the condition held.
  t.checked_at,                                                                 -- When checked.
  t.checked_by_agent,                                                           -- Who checked.
  calc_condition_checks_condition_kind(t.condition_check_id) AS condition_kind, -- Kind of the checked condition.
  calc_condition_checks_is_failed_precondition(t.condition_check_id) AS is_failed_precondition,-- TRUE when a precondition did not hold.
  calc_condition_checks_is_violated_invariant(t.condition_check_id) AS is_violated_invariant,-- TRUE when an invariant did not hold.
  calc_condition_checks_failed_precondition_execution_key(t.condition_check_id) AS failed_precondition_execution_key,-- Step execution key when a precondition failed.
  calc_condition_checks_violated_invariant_execution_key(t.condition_check_id) AS violated_invariant_execution_key,-- Step execution key when an invariant failed.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  calc_condition_checks_enforced_requirement(t.condition_check_id) AS enforced_requirement,-- The requirement the checked condition enforces, copied from the condition.
  calc_condition_checks_failed_check_requirement_key(t.condition_check_id) AS failed_check_requirement_key,-- Echoes the enforced requirement's id when this check recorded that the condition did not hold; blank otherwise.
  calc_condition_checks_enforced_requirement_is_computed(t.condition_check_id) AS enforced_requirement_is_computed,-- Copied from the checked condition: the rule it enforces has a computed witness.
  calc_condition_checks_enforced_requirement_statement(t.condition_check_id) AS enforced_requirement_statement,-- Copied from the checked condition: the rule it enforces, in its own words.
  calc_condition_checks_is_scored_breach(t.condition_check_id) AS is_scored_breach-- This check recorded that the condition did not hold, and the rule it enforces is computed by the register: a breach counted by the register itself, not by a person looking.
FROM condition_checks t;

-- ----------------------------------------------------------------------------
-- vw_failure_modes: Ways a step can fail and the response to each.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_failure_modes CASCADE;
CREATE VIEW vw_failure_modes WITH (security_invoker = ON) AS
SELECT
  t.failure_mode_id,                                                            -- Stored identifier.
  calc_failure_modes_name(t.failure_mode_id) AS name,                           -- Display name.
  t.step,                                                                       -- Step that can fail this way.
  t.procedure_target,                                                           -- Target this handling applies to, for unusually configured equipment.
  t.description,                                                                -- What goes wrong.
  t.response,                                                                   -- What to do.
  t.requires_escalation,                                                        -- TRUE when the response is to escalate at once.
  t.escalate_to_role,                                                           -- Role that receives the escalation.
  calc_failure_modes_escalation_role_has_no_holder(t.failure_mode_id) AS escalation_role_has_no_holder,-- Whether the escalation role is currently unfilled.
  calc_failure_modes_escalates_to_vacant_role(t.failure_mode_id) AS escalates_to_vacant_role,-- TRUE when a failure that must be escalated goes to a role nobody holds.
  calc_failure_modes_has_no_response(t.failure_mode_id) AS has_no_response,     -- TRUE when a failure mode names no response.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM failure_modes t;

-- ----------------------------------------------------------------------------
-- vw_step_cues: Indicators, sounds and confirmations a practitioner reads during a step; some are danger cues.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_cues CASCADE;
CREATE VIEW vw_step_cues WITH (security_invoker = ON) AS
SELECT
  t.step_cue_id,                                                                -- Stored identifier.
  calc_step_cues_name(t.step_cue_id) AS name,                                   -- Display name.
  t.step,                                                                       -- Step.
  t.cue_kind,                                                                   -- Indicator, Sound, Visual or Confirmation.
  t.description,                                                                -- What the practitioner looks, listens or checks for.
  t.signals_incomplete_step,                                                    -- TRUE when the cue shows the step did not fully take effect.
  t.requires_escalation,                                                        -- TRUE for a danger cue that calls for escalating at once.
  t.escalate_to_role,                                                           -- Role the cue is escalated to.
  calc_step_cues_observation_count(t.step_cue_id) AS observation_count,         -- Times the cue was observed.
  calc_step_cues_unescalated_observation_count(t.step_cue_id) AS unescalated_observation_count,-- Observations of this danger cue that were not escalated.
  calc_step_cues_danger_cue_step_key(t.step_cue_id) AS danger_cue_step_key,     -- Step key for a danger cue.
  calc_step_cues_incomplete_cue_step_key(t.step_cue_id) AS incomplete_cue_step_key,-- Step key for a cue that shows the step did not take effect.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.operator_question,                                                          -- How a technician on the floor would ask about this warning sign. The assistant offers it verbatim.
  t.signals_failure_mode,                                                       -- The failure mode this warning sign is evidence of. Its recorded response is the assistant's answer.
  calc_step_cues_failure_mode_response(t.step_cue_id) AS failure_mode_response, -- What to do, from the failure mode this sign points at.
  calc_step_cues_is_unanswerable_sign(t.step_cue_id) AS is_unanswerable_sign    -- A sign that means 'not finished' but points at no failure mode, so neither the runner nor the assistant can say what to do about it.
FROM step_cues t;

-- ----------------------------------------------------------------------------
-- vw_cue_observations: A cue observed during a step execution.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_cue_observations CASCADE;
CREATE VIEW vw_cue_observations WITH (security_invoker = ON) AS
SELECT
  t.cue_observation_id,                                                         -- Stored identifier.
  calc_cue_observations_name(t.cue_observation_id) AS name,                     -- Display name.
  t.step_execution,                                                             -- Step execution.
  t.step_cue,                                                                   -- Cue observed.
  t.observed_at,                                                                -- When observed.
  t.observed_by_agent,                                                          -- Who observed it.
  t.was_escalated,                                                              -- Whether it was escalated.
  t.escalated_to_agent,                                                         -- Who received the escalation.
  calc_cue_observations_cue_requires_escalation(t.cue_observation_id) AS cue_requires_escalation,-- Whether the cue is a danger cue.
  calc_cue_observations_is_unescalated_danger_cue(t.cue_observation_id) AS is_unescalated_danger_cue,-- TRUE when a danger cue was seen and nobody escalated it.
  calc_cue_observations_unescalated_cue_key(t.cue_observation_id) AS unescalated_cue_key,-- Cue key when unescalated.
  calc_cue_observations_unescalated_execution_key(t.cue_observation_id) AS unescalated_execution_key,-- Step execution key when unescalated.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  calc_cue_observations_owner_organization(t.cue_observation_id) AS owner_organization,-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
  calc_cue_observations_cue_signals_incomplete_step(t.cue_observation_id) AS cue_signals_incomplete_step,-- Whether the observed warning sign means the step is not finished.
  t.acknowledged_at,                                                            -- When the person it was escalated to acknowledged it. Blank until they do.
  calc_cue_observations_is_awaiting_acknowledgement(t.cue_observation_id) AS is_awaiting_acknowledgement-- Escalated to someone who has not acknowledged it yet: the safety desk's inbox.
FROM cue_observations t;

-- ----------------------------------------------------------------------------
-- vw_decision_points: Choice points and the factors that decide them (dmn:Decision).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_decision_points CASCADE;
CREATE VIEW vw_decision_points WITH (security_invoker = ON) AS
SELECT
  t.decision_point_id,                                                          -- Stored identifier.
  calc_decision_points_name(t.decision_point_id) AS name,                       -- Display name.
  t.step,                                                                       -- Step where the decision is made.
  t.governing_transition,                                                       -- The branch the decision selects.
  t.question,                                                                   -- The decision.
  t.deciding_factors,                                                           -- Factors that decide it.
  t.default_outcome,                                                            -- Outcome when nothing unusual is observed.
  t.dmn_decision_key,                                                           -- Key of the DMN decision.
  calc_decision_points_has_no_deciding_factors(t.decision_point_id) AS has_no_deciding_factors,-- TRUE when a decision names no factors.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  calc_decision_points_is_dmn_encoded(t.decision_point_id) AS is_dmn_encoded    -- TRUE when the decision is encoded as a DMN decision.
FROM decision_points t;

-- ----------------------------------------------------------------------------
-- vw_execution_participants: Agents associated with a procedure execution besides its executor (prov:wasAssociatedWith).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_execution_participants CASCADE;
CREATE VIEW vw_execution_participants WITH (security_invoker = ON) AS
SELECT
  t.execution_participant_id,                                                   -- Stored identifier.
  calc_execution_participants_name(t.execution_participant_id) AS name,         -- Display name.
  t.procedure_execution,                                                        -- Execution.
  t.agent,                                                                      -- Participant.
  t.participation_role,                                                         -- Verifier, Observer, Trainee or Supervisor.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM execution_participants t;

-- ----------------------------------------------------------------------------
-- vw_step_resources: Resources a step relies on (dct:references).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_resources CASCADE;
CREATE VIEW vw_step_resources WITH (security_invoker = ON) AS
SELECT
  t.step_resource_id,                                                           -- Stored identifier.
  calc_step_resources_name(t.step_resource_id) AS name,                         -- Display name.
  t.step,                                                                       -- Step.
  t.resource,                                                                   -- Resource.
  t.relation,                                                                   -- How the step uses it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM step_resources t;

-- ----------------------------------------------------------------------------
-- vw_faq_categories: FAQ categories (pko:FAQCategory).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_faq_categories CASCADE;
CREATE VIEW vw_faq_categories WITH (security_invoker = ON) AS
SELECT
  t.faq_category_id,                                                            -- Stored identifier.
  calc_faq_categories_name(t.faq_category_id) AS name,                          -- Display name.
  t.label,                                                                      -- Category.
  calc_faq_categories_faq_count(t.faq_category_id) AS faq_count,                -- FAQs in the category.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM faq_categories t;

-- ----------------------------------------------------------------------------
-- vw_faq_targets: What an FAQ is about (pko:FAQTarget).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_faq_targets CASCADE;
CREATE VIEW vw_faq_targets WITH (security_invoker = ON) AS
SELECT
  t.faq_target_id,                                                              -- Stored identifier.
  calc_faq_targets_name(t.faq_target_id) AS name,                               -- Display name.
  t.label,                                                                      -- Target.
  calc_faq_targets_faq_count(t.faq_target_id) AS faq_count,                     -- FAQs with this target.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM faq_targets t;

-- ----------------------------------------------------------------------------
-- vw_authoring_submissions: Procedures submitted through the no-code capture form, validated against the PKO profile.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_authoring_submissions CASCADE;
CREATE VIEW vw_authoring_submissions WITH (security_invoker = ON) AS
SELECT
  t.authoring_submission_id,                                                    -- Stored identifier.
  calc_authoring_submissions_name(t.authoring_submission_id) AS name,           -- Display name.
  t.procedure_version,                                                          -- Version the submission authors.
  t.submitted_by_agent,                                                         -- Who submitted it.
  t.submitted_at,                                                               -- When.
  t.authoring_tool,                                                             -- Tool used.
  t.submitter_expertise,                                                        -- DomainExpert or KnowledgeEngineer.
  t.step_count,                                                                 -- Steps authored.
  t.profile_validation_passed,                                                  -- Whether it validated against the PKO profile.
  t.validation_error_count,                                                     -- Profile violations found.
  t.was_accepted,                                                               -- Whether it was accepted into the rulebook.
  calc_authoring_submissions_is_expert_authored_conforming(t.authoring_submission_id) AS is_expert_authored_conforming,-- TRUE when a domain expert with no ontology training produced a submission that conforms to the profile.
  calc_authoring_submissions_is_non_conforming_accepted(t.authoring_submission_id) AS is_non_conforming_accepted,-- TRUE when a submission that failed profile validation was accepted anyway.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM authoring_submissions t;

-- ----------------------------------------------------------------------------
-- vw_process_knowledge_levels: The operational, tactical and strategic levels at which process knowledge is held.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_knowledge_levels CASCADE;
CREATE VIEW vw_process_knowledge_levels WITH (security_invoker = ON) AS
SELECT
  t.process_knowledge_level_id,                                                 -- Stored identifier.
  calc_process_knowledge_levels_name(t.process_knowledge_level_id) AS name,     -- Display name.
  t.label,                                                                      -- Level name.
  t.planning_horizon,                                                           -- The horizon the level plans over.
  calc_process_knowledge_levels_tacit_strategy_count(t.process_knowledge_level_id) AS tacit_strategy_count,-- Capture strategies for tacit knowledge at this level.
  calc_process_knowledge_levels_explicit_strategy_count(t.process_knowledge_level_id) AS explicit_strategy_count,-- Capture strategies for explicit knowledge at this level.
  calc_process_knowledge_levels_lacks_capture_strategy_for_either(t.process_knowledge_level_id) AS lacks_capture_strategy_for_either_form,-- TRUE when the level has no strategy for capturing its tacit knowledge, or none for its explicit knowledge.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_knowledge_levels t;

-- ----------------------------------------------------------------------------
-- vw_level_capture_strategies: How the tacit or explicit knowledge of one level is captured and passed on.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_level_capture_strategies CASCADE;
CREATE VIEW vw_level_capture_strategies WITH (security_invoker = ON) AS
SELECT
  t.level_capture_strategy_id,                                                  -- Stored identifier.
  calc_level_capture_strategies_name(t.level_capture_strategy_id) AS name,      -- Display name.
  t.level,                                                                      -- Level the strategy serves.
  t.knowledge_form,                                                             -- Tacit (experiential) or Explicit (codifiable).
  t.knowledge_method,                                                           -- Method the strategy uses.
  t.transfer_mode,                                                              -- InPerson (apprenticeship, shadowing) or Codified (stored document or data).
  t.description,                                                                -- The strategy.
  calc_level_capture_strategies_contradicts_knowledge_form(t.level_capture_strategy_id) AS contradicts_knowledge_form,-- TRUE when tacit knowledge is to be passed on only as a stored document, or explicit knowledge only in person.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM level_capture_strategies t;

-- ----------------------------------------------------------------------------
-- vw_level_pyramid_questions: The planning pyramid: which questions each level answers (strategic who and why, tactical what, operational how and where).
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_level_pyramid_questions CASCADE;
CREATE VIEW vw_level_pyramid_questions WITH (security_invoker = ON) AS
SELECT
  t.level_pyramid_question_id,                                                  -- Stored identifier.
  calc_level_pyramid_questions_name(t.level_pyramid_question_id) AS name,       -- Display name.
  t.level,                                                                      -- Level.
  t.question_kind,                                                              -- who, why, what, how or where.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM level_pyramid_questions t;

-- ----------------------------------------------------------------------------
-- vw_process_level_statements: Statements about a procedure, filed at a level of the planning pyramid.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_level_statements CASCADE;
CREATE VIEW vw_process_level_statements WITH (security_invoker = ON) AS
SELECT
  t.process_level_statement_id,                                                 -- Stored identifier.
  calc_process_level_statements_name(t.process_level_statement_id) AS name,     -- Display name.
  t.procedure,                                                                  -- Procedure the statement is about.
  t.level,                                                                      -- Level it is filed at.
  t.question_kind,                                                              -- The question the statement answers: who, why, what, how or where.
  t.statement,                                                                  -- The statement.
  calc_process_level_statements_level_question_key(t.process_level_statement_id) AS level_question_key,-- Level and question kind, as the pyramid keys them.
  calc_process_level_statements_pyramid_match_count(t.process_level_statement_id) AS pyramid_match_count,-- Pyramid rows saying this level answers this kind of question.
  calc_process_level_statements_is_filed_at_wrong_level(t.process_level_statement_id) AS is_filed_at_wrong_level,-- TRUE when a statement answers a question its level does not answer in the pyramid.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_level_statements t;

-- ----------------------------------------------------------------------------
-- vw_tactical_resource_allocations: Tactical knowledge: resources allocated to a step, the demand on them, and the adjustment decided.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_tactical_resource_allocations CASCADE;
CREATE VIEW vw_tactical_resource_allocations WITH (security_invoker = ON) AS
SELECT
  t.tactical_resource_allocation_id,                                            -- Stored identifier.
  calc_tactical_resource_allocations_name(t.tactical_resource_allocation_id) AS name,-- Display name.
  t.step,                                                                       -- Step the resource serves.
  t.facility,                                                                   -- Where the resource is allocated.
  t.resource_label,                                                             -- The resource.
  t.resource_kind,                                                              -- People, Equipment or Tooling.
  t.available_units_per_week,                                                   -- Capacity allocated per week.
  t.demanded_units_per_week,                                                    -- Demand on it per week.
  t.adjustment_decision,                                                        -- How the process is being adjusted.
  calc_tactical_resource_allocations_utilization_percent(t.tactical_resource_allocation_id) AS utilization_percent,-- Demand as a percentage of capacity.
  calc_tactical_resource_allocations_is_bottleneck(t.tactical_resource_allocation_id) AS is_bottleneck,-- TRUE when demand on the resource exceeds the capacity allocated to it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM tactical_resource_allocations t;

-- ----------------------------------------------------------------------------
-- vw_process_strategic_alignments: Strategic knowledge: why a procedure exists, the mission it serves, the value it creates and the trade-offs it makes.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_strategic_alignments CASCADE;
CREATE VIEW vw_process_strategic_alignments WITH (security_invoker = ON) AS
SELECT
  t.process_strategic_alignment_id,                                             -- Stored identifier.
  calc_process_strategic_alignments_name(t.process_strategic_alignment_id) AS name,-- Display name.
  t.procedure,                                                                  -- Procedure.
  t.organization,                                                               -- Organization whose mission it serves.
  t.mission_statement,                                                          -- The mission.
  t.rationale,                                                                  -- Why the procedure exists.
  t.value_created,                                                              -- Value it creates.
  t.trade_offs,                                                                 -- What it costs or gives up.
  calc_process_strategic_alignments_states_no_trade_off(t.process_strategic_alignment_id) AS states_no_trade_off,-- TRUE when a strategic alignment names no trade-off.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_strategic_alignments t;

-- ----------------------------------------------------------------------------
-- vw_business_outcomes: Results the business cares about, owned by an executive or manager.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_business_outcomes CASCADE;
CREATE VIEW vw_business_outcomes WITH (security_invoker = ON) AS
SELECT
  t.business_outcome_id,                                                        -- Stored identifier.
  calc_business_outcomes_name(t.business_outcome_id) AS name,                   -- Display name.
  t.label,                                                                      -- Outcome.
  t.owner_role,                                                                 -- Role accountable for the outcome.
  t.strategic_objective,                                                        -- The objective it serves.
  calc_business_outcomes_linked_measure_count(t.business_outcome_id) AS linked_measure_count,-- Process measures linked to the outcome.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM business_outcomes t;

-- ----------------------------------------------------------------------------
-- vw_process_outcome_measures: Measured outcomes of a procedure, and the business outcome each links to.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_outcome_measures CASCADE;
CREATE VIEW vw_process_outcome_measures WITH (security_invoker = ON) AS
SELECT
  t.process_outcome_measure_id,                                                 -- Stored identifier.
  calc_process_outcome_measures_name(t.process_outcome_measure_id) AS name,     -- Display name.
  t.procedure,                                                                  -- Procedure measured.
  t.label,                                                                      -- Measure.
  t.unit,                                                                       -- Unit.
  t.target_value,                                                               -- Target.
  t.observed_value,                                                             -- Observed value over the period.
  t.measured_over_period,                                                       -- Period.
  t.business_outcome,                                                           -- Business outcome the measure drives.
  t.link_rationale,                                                             -- How the measure moves the business outcome.
  calc_process_outcome_measures_is_unlinked_to_business_outcome(t.process_outcome_measure_id) AS is_unlinked_to_business_outcome,-- TRUE when a process measure is tied to no business outcome.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_outcome_measures t;

-- ----------------------------------------------------------------------------
-- vw_process_stages: Stages that group a procedure version's steps, each with an owning role.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_stages CASCADE;
CREATE VIEW vw_process_stages WITH (security_invoker = ON) AS
SELECT
  t.process_stage_id,                                                           -- Stored identifier.
  calc_process_stages_name(t.process_stage_id) AS name,                         -- Display name.
  t.procedure_version,                                                          -- Version the stage belongs to.
  t.label,                                                                      -- Stage.
  t.sequence,                                                                   -- Order of the stage.
  t.owner_role,                                                                 -- Stakeholder role that owns the stage.
  calc_process_stages_step_count(t.process_stage_id) AS step_count,             -- Steps grouped in the stage.
  calc_process_stages_owner_has_no_holder(t.process_stage_id) AS owner_has_no_holder,-- Whether nobody currently holds the owning role.
  calc_process_stages_is_unowned_or_empty_stage(t.process_stage_id) AS is_unowned_or_empty_stage,-- TRUE when a stage has no owner, an owner role nobody holds, or no steps.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_stages t;

-- ----------------------------------------------------------------------------
-- vw_process_interdependencies: How one operation helps, hinders or requires another.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_interdependencies CASCADE;
CREATE VIEW vw_process_interdependencies WITH (security_invoker = ON) AS
SELECT
  t.process_interdependency_id,                                                 -- Stored identifier.
  calc_process_interdependencies_name(t.process_interdependency_id) AS name,    -- Display name.
  t.from_procedure,                                                             -- Operation that has the effect.
  t.to_procedure,                                                               -- Operation affected.
  t.effect,                                                                     -- Helps, Hinders or Requires.
  t.mechanism,                                                                  -- How the effect arises.
  t.evidence_note,                                                              -- Where the effect was observed.
  calc_process_interdependencies_is_hindering_dependency(t.process_interdependency_id) AS is_hindering_dependency,-- TRUE when one operation works against another.
  calc_process_interdependencies_hindered_procedure_key(t.process_interdependency_id) AS hindered_procedure_key,-- Procedure key when hindered.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_interdependencies t;

-- ----------------------------------------------------------------------------
-- vw_stakeholder_lenses: The perspectives from which one procedure is read, what each needs, and at what granularity and form.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_stakeholder_lenses CASCADE;
CREATE VIEW vw_stakeholder_lenses WITH (security_invoker = ON) AS
SELECT
  t.stakeholder_lens_id,                                                        -- Stored identifier.
  calc_stakeholder_lenses_name(t.stakeholder_lens_id) AS name,                  -- Display name.
  t.label,                                                                      -- Lens.
  t.exemplar_role,                                                              -- Role that reads the procedure this way.
  t.needs_step_guidance,                                                        -- Needs step-by-step guidance.
  t.needs_metrics,                                                              -- Needs metrics.
  t.needs_exception_handling,                                                   -- Needs exception handling.
  t.needs_compliance_evidence,                                                  -- Needs compliance evidence.
  t.needs_structured_constraints,                                               -- Needs structured, machine-readable constraints.
  t.required_granularity,                                                       -- Step, Stage or Category.
  t.preferred_form,                                                             -- Prose, Diagram, Table or MachineReadable.
  calc_stakeholder_lenses_granularity_rank(t.stakeholder_lens_id) AS granularity_rank,-- 3 for step level, 2 for stage level, 1 for category level.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM stakeholder_lenses t;

-- ----------------------------------------------------------------------------
-- vw_procedure_lens_views: A view of one procedure for one stakeholder lens, projected from a procedure version.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_lens_views CASCADE;
CREATE VIEW vw_procedure_lens_views WITH (security_invoker = ON) AS
SELECT
  t.procedure_lens_view_id,                                                     -- Stored identifier.
  calc_procedure_lens_views_name(t.procedure_lens_view_id) AS name,             -- Display name.
  t.procedure,                                                                  -- Procedure viewed.
  t.stakeholder_lens,                                                           -- Lens served.
  t.projects_version,                                                           -- Version the view is projected from; blank for a free-standing document.
  t.granularity,                                                                -- Step, Stage or Category.
  t.form,                                                                       -- Prose, Diagram, Table or MachineReadable.
  calc_procedure_lens_views_procedure_current_version(t.procedure_lens_view_id) AS procedure_current_version,-- The procedure's current version.
  calc_procedure_lens_views_lens_granularity_rank(t.procedure_lens_view_id) AS lens_granularity_rank,-- Granularity the lens requires.
  calc_procedure_lens_views_view_granularity_rank(t.procedure_lens_view_id) AS view_granularity_rank,-- Granularity the view delivers.
  calc_procedure_lens_views_is_granularity_misfit(t.procedure_lens_view_id) AS is_granularity_misfit,-- TRUE when a view is coarser or finer than its lens's use requires.
  calc_procedure_lens_views_is_disconnected_silo(t.procedure_lens_view_id) AS is_disconnected_silo,-- TRUE when a view is not projected from the procedure's current version: a free-standing copy that will drift apart.
  calc_procedure_lens_views_step_level_procedure_key(t.procedure_lens_view_id) AS step_level_procedure_key,-- Procedure key when the lens needs step-level detail.
  calc_procedure_lens_views_category_level_procedure_key(t.procedure_lens_view_id) AS category_level_procedure_key,-- Procedure key when the lens needs only the category.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM procedure_lens_views t;

-- ----------------------------------------------------------------------------
-- vw_applicability_scopes: Where a piece of process knowledge applies: business unit, geography, customer segment, regulatory regime, conditions, and the named graph holding it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_applicability_scopes CASCADE;
CREATE VIEW vw_applicability_scopes WITH (security_invoker = ON) AS
SELECT
  t.applicability_scope_id,                                                     -- Stored identifier.
  calc_applicability_scopes_name(t.applicability_scope_id) AS name,             -- Display name.
  t.label,                                                                      -- Scope.
  t.business_unit,                                                              -- Business unit.
  t.geography,                                                                  -- Geography (ISO region code).
  t.customer_segment,                                                           -- Customer segment.
  t.regulatory_regime,                                                          -- Regulatory regime.
  t.applies_when,                                                               -- Condition under which the knowledge holds.
  t.exclusion_condition,                                                        -- Scoping annotation: where the knowledge stops applying.
  t.named_graph_iri,                                                            -- Named graph that holds the knowledge scoped here.
  calc_applicability_scopes_dimension_count(t.applicability_scope_id) AS dimension_count,-- Context dimensions the scope names.
  calc_applicability_scopes_states_conditions(t.applicability_scope_id) AS states_conditions,-- TRUE when the scope says when the knowledge applies or where it stops.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM applicability_scopes t;

-- ----------------------------------------------------------------------------
-- vw_step_context_sensitivities: How a step's significance changes with the performer, the resources on hand or outside circumstances.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_context_sensitivities CASCADE;
CREATE VIEW vw_step_context_sensitivities WITH (security_invoker = ON) AS
SELECT
  t.step_context_sensitivity_id,                                                -- Stored identifier.
  calc_step_context_sensitivities_name(t.step_context_sensitivity_id) AS name,  -- Display name.
  t.step,                                                                       -- Step.
  t.context_factor,                                                             -- Performer, Resource or Circumstance.
  t.description,                                                                -- The context.
  t.effect_on_significance,                                                     -- How the step's significance changes.
  t.applicability_scope,                                                        -- Scope stating where this holds.
  calc_step_context_sensitivities_unscoped_step_key(t.step_context_sensitivity_id) AS unscoped_step_key,-- Step key when no scope is stated.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM step_context_sensitivities t;

-- ----------------------------------------------------------------------------
-- vw_situational_variants: How experts adapt a standard procedure to the situation in front of them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_situational_variants CASCADE;
CREATE VIEW vw_situational_variants WITH (security_invoker = ON) AS
SELECT
  t.situational_variant_id,                                                     -- Stored identifier.
  calc_situational_variants_name(t.situational_variant_id) AS name,             -- Display name.
  t.procedure,                                                                  -- Standard procedure adapted.
  t.label,                                                                      -- Variant.
  t.situation,                                                                  -- The situation.
  t.adaptation,                                                                 -- What the expert does differently.
  t.applicability_scope,                                                        -- Where the variant applies.
  t.expert_agent,                                                               -- Expert the variant came from.
  calc_situational_variants_scope_dimension_count(t.situational_variant_id) AS scope_dimension_count,-- Context dimensions the scope names.
  calc_situational_variants_scope_states_conditions(t.situational_variant_id) AS scope_states_conditions,-- Whether the scope states its conditions.
  calc_situational_variants_has_no_applicability_dimension(t.situational_variant_id) AS has_no_applicability_dimension,-- TRUE when nothing says under which business unit, geography, segment or regime the variant applies.
  calc_situational_variants_diverges_without_stated_conditions(t.situational_variant_id) AS diverges_without_stated_conditions,-- TRUE when a variant departs from the standard with no stated condition for when it applies or stops.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM situational_variants t;

-- ----------------------------------------------------------------------------
-- vw_collected_source_materials: Raw material collection produced, and when it was organized into a scheme and encoded into a procedure version.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_collected_source_materials CASCADE;
CREATE VIEW vw_collected_source_materials WITH (security_invoker = ON) AS
SELECT
  t.collected_source_material_id,                                               -- Stored identifier.
  calc_collected_source_materials_name(t.collected_source_material_id) AS name, -- Display name.
  t.label,                                                                      -- Material.
  t.material_kind,                                                              -- Transcript, FieldNotes, ProcessMap, MinedEventTrace or DocumentExcerpt.
  t.procedure,                                                                  -- Procedure the material is about.
  t.collected_at,                                                               -- When collected.
  t.organized_into_scheme,                                                      -- Scheme the material was organized into.
  t.organized_at,                                                               -- When it was organized.
  t.encoded_into_version,                                                       -- Version it was modeled into.
  t.encoded_at,                                                                 -- When it was modeled.
  calc_collected_source_materials_is_modeled_before_organized(t.collected_source_material_id) AS is_modeled_before_organized,-- TRUE when material was encoded into a procedure version before it was organized, or without ever being organized.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.source_document,                                                            -- The existing document the material was excerpted from.
  calc_collected_source_materials_source_document_revised_at(t.collected_source_material_id) AS source_document_revised_at,-- Last revision of that document.
  calc_collected_source_materials_is_document_source(t.collected_source_material_id) AS is_document_source,-- TRUE for an excerpt of existing written material.
  calc_collected_source_materials_is_people_capture(t.collected_source_material_id) AS is_people_capture,-- TRUE for material captured from people: a transcript or field notes.
  calc_collected_source_materials_is_practice_evidence(t.collected_source_material_id) AS is_practice_evidence,-- TRUE for material that records the work as performed: field notes or a mined event trace.
  t.holds_reasoning_or_tacit_knowledge,                                         -- TRUE when the material holds the reasoning or tacit knowledge behind the actions, not only the actions.
  t.complements_mining_run,                                                     -- The mining run whose findings this capture from people explains.
  t.captured_during_execution,                                                  -- The execution during which the material was captured, when captured in the course of work.
  calc_collected_source_materials_is_captured_in_flow_of_work(t.collected_source_material_id) AS is_captured_in_flow_of_work,-- TRUE when the material was captured while the work was being done.
  t.collected_at_occasion,                                                      -- The recurring occasion at which the material was collected.
  t.prompted_by_feedback,                                                       -- The practitioner feedback that prompted this collection.
  t.produced_by_method_application,                                             -- The method application that produced the material.
  t.contributing_expert,                                                        -- The domain expert whose time the capture consumed.
  t.expert_effort_hours,                                                        -- Hours of expert time the capture consumed.
  calc_collected_source_materials_dependent_trace_count(t.collected_source_material_id) AS dependent_trace_count,-- Organized knowledge traced to this material.
  calc_collected_source_materials_is_dependency_invisible_to_chan(t.collected_source_material_id) AS is_dependency_invisible_to_change,-- TRUE when the material was encoded into a model but no trace records what rests on it, so a change to it reveals nothing.
  calc_collected_source_materials_changed_dependent_count(t.collected_source_material_id) AS changed_dependent_count,-- Traced knowledge taken before the source document was last revised.
  calc_collected_source_materials_has_knowledge_affected_by_sourc(t.collected_source_material_id) AS has_knowledge_affected_by_source_change-- TRUE when a revision of the source affects organized knowledge taken from it.
FROM collected_source_materials t;

-- ----------------------------------------------------------------------------
-- vw_scheme_refinements: A change to an organizing scheme made because collection showed how practitioners think about the work.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_scheme_refinements CASCADE;
CREATE VIEW vw_scheme_refinements WITH (security_invoker = ON) AS
SELECT
  t.scheme_refinement_id,                                                       -- Stored identifier.
  calc_scheme_refinements_name(t.scheme_refinement_id) AS name,                 -- Display name.
  t.vocabulary,                                                                 -- Scheme refined.
  t.refined_at,                                                                 -- When.
  t.triggered_by_material,                                                      -- Material that prompted it.
  t.change_summary,                                                             -- What changed.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM scheme_refinements t;

-- ----------------------------------------------------------------------------
-- vw_term_label_variants: Preferred and alternative labels of a controlled concept, one row per wording, so variant wordings can be matched.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_term_label_variants CASCADE;
CREATE VIEW vw_term_label_variants WITH (security_invoker = ON) AS
SELECT
  t.term_label_variant_id,                                                      -- Stored identifier.
  calc_term_label_variants_name(t.term_label_variant_id) AS name,               -- Display name.
  t.vocabulary_term,                                                            -- Concept labeled.
  t.label_kind,                                                                 -- pref (skos:prefLabel) or alt (skos:altLabel).
  t.wording,                                                                    -- The wording, lower case.
  calc_term_label_variants_term_scheme(t.term_label_variant_id) AS term_scheme, -- Scheme the concept belongs to.
  calc_term_label_variants_term_pref_label(t.term_label_variant_id) AS term_pref_label,-- The preferred label of the concept this wording belongs to. What a vocabulary search answers with, whichever wording was typed.
  calc_term_label_variants_wording_key(t.term_label_variant_id) AS wording_key, -- Scheme and wording.
  calc_term_label_variants_pref_wording_key(t.term_label_variant_id) AS pref_wording_key,-- Scheme and wording for a preferred label.
  calc_term_label_variants_concepts_sharing_wording(t.term_label_variant_id) AS concepts_sharing_wording,-- Labels in the same scheme with this exact wording.
  calc_term_label_variants_is_ambiguous_label(t.term_label_variant_id) AS is_ambiguous_label,-- TRUE when one wording is a label of more than one concept in the scheme, so it cannot normalize to one canonical concept.
  calc_term_label_variants_practitioner_mention_count(t.term_label_variant_id) AS practitioner_mention_count,-- Practitioner mentions using this wording in this scheme.
  calc_term_label_variants_pref_wording(t.term_label_variant_id) AS pref_wording,-- Wording of a preferred label, regardless of scheme.
  calc_term_label_variants_same_pref_wording_count(t.term_label_variant_id) AS same_pref_wording_count,-- Preferred labels in any scheme with this wording.
  calc_term_label_variants_is_cross_scheme_duplicate_pref(t.term_label_variant_id) AS is_cross_scheme_duplicate_pref,-- TRUE when the same concern is defined as a separate preferred concept in more than one scheme instead of being shared.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM term_label_variants t;

-- ----------------------------------------------------------------------------
-- vw_ai_labeling_runs: A run in which an AI model assigned controlled values, with or without a grounding scheme.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_labeling_runs CASCADE;
CREATE VIEW vw_ai_labeling_runs WITH (security_invoker = ON) AS
SELECT
  t.ai_labeling_run_id,                                                         -- Stored identifier.
  calc_ai_labeling_runs_name(t.ai_labeling_run_id) AS name,                     -- Display name.
  t.agent,                                                                      -- Model that labeled.
  t.grounding_scheme,                                                           -- Scheme supplied as grounding; blank when ungrounded.
  t.run_at,                                                                     -- When.
  t.task_description,                                                           -- What it labeled.
  calc_ai_labeling_runs_output_count(t.ai_labeling_run_id) AS output_count,     -- Values produced.
  calc_ai_labeling_runs_non_canonical_output_count(t.ai_labeling_run_id) AS non_canonical_output_count,-- Values that are not a preferred label.
  calc_ai_labeling_runs_grounding_scheme_is_machine_accessible(t.ai_labeling_run_id) AS grounding_scheme_is_machine_accessible,-- Whether the grounding scheme is published formally.
  calc_ai_labeling_runs_is_ungrounded_synonym_sprawl(t.ai_labeling_run_id) AS is_ungrounded_synonym_sprawl,-- TRUE when an ungrounded run produced values outside the canonical scheme.
  calc_ai_labeling_runs_grounded_in_non_machine_readable_scheme(t.ai_labeling_run_id) AS grounded_in_non_machine_readable_scheme,-- TRUE when a run was grounded in a vocabulary that is not formal and machine-accessible.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_labeling_runs t;

-- ----------------------------------------------------------------------------
-- vw_source_term_mentions: A wording found in collected material or produced by an AI run, and the concept a knowledge engineer judged it to mean.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_source_term_mentions CASCADE;
CREATE VIEW vw_source_term_mentions WITH (security_invoker = ON) AS
SELECT
  t.source_term_mention_id,                                                     -- Stored identifier.
  calc_source_term_mentions_name(t.source_term_mention_id) AS name,             -- Display name.
  t.source_material,                                                            -- Material the wording came from.
  t.ai_labeling_run,                                                            -- AI run that produced the wording.
  t.concept_scheme,                                                             -- Scheme the wording should resolve in.
  t.wording,                                                                    -- The wording as found, lower case.
  t.mention_origin,                                                             -- Practitioner, OfficialDocument, SystemLog or AIGenerated.
  t.intended_term,                                                              -- Concept the knowledge engineer judged the wording to mean.
  calc_source_term_mentions_wording_key(t.source_term_mention_id) AS wording_key,-- Scheme and wording.
  calc_source_term_mentions_matching_label_count(t.source_term_mention_id) AS matching_label_count,-- Labels in the scheme with this wording.
  calc_source_term_mentions_matching_pref_label_count(t.source_term_mention_id) AS matching_pref_label_count,-- Preferred labels in the scheme with this wording.
  calc_source_term_mentions_is_uncontrolled_wording(t.source_term_mention_id) AS is_uncontrolled_wording,-- TRUE when a wording resolves to no concept label in its scheme.
  calc_source_term_mentions_is_non_canonical_generated_value(t.source_term_mention_id) AS is_non_canonical_generated_value,-- TRUE when an AI-generated value is not a preferred label of the governed scheme.
  calc_source_term_mentions_intended_term_role(t.source_term_mention_id) AS intended_term_role,-- Role the intended concept stands for.
  calc_source_term_mentions_unresolved_intended_term_key(t.source_term_mention_id) AS unresolved_intended_term_key,-- Intended concept key when the wording does not resolve.
  calc_source_term_mentions_unresolved_role_key(t.source_term_mention_id) AS unresolved_role_key,-- Role key when a role wording does not resolve.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM source_term_mentions t;

-- ----------------------------------------------------------------------------
-- vw_term_relations: SKOS semantic relations between concepts beyond the primary broader link: associative (related) and additional broader links.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_term_relations CASCADE;
CREATE VIEW vw_term_relations WITH (security_invoker = ON) AS
SELECT
  t.term_relation_id,                                                           -- Stored identifier.
  calc_term_relations_name(t.term_relation_id) AS name,                         -- Display name.
  t.from_term,                                                                  -- Subject concept.
  t.relation_kind,                                                              -- broader (direct) or related (associative).
  t.to_term,                                                                    -- Object concept.
  t.note,                                                                       -- Why the relation holds.
  calc_term_relations_from_term_grandparent(t.term_relation_id) AS from_term_grandparent,-- Broader concept of the subject's broader concept.
  calc_term_relations_asserts_indirect_link_as_direct(t.term_relation_id) AS asserts_indirect_link_as_direct,-- TRUE when a direct broader link is asserted to a concept the subject only reaches through an intermediate concept.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM term_relations t;

-- ----------------------------------------------------------------------------
-- vw_term_meaning_changes: A change in what the organization means by a controlled term.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_term_meaning_changes CASCADE;
CREATE VIEW vw_term_meaning_changes WITH (security_invoker = ON) AS
SELECT
  t.term_meaning_change_id,                                                     -- Stored identifier.
  calc_term_meaning_changes_name(t.term_meaning_change_id) AS name,             -- Display name.
  t.vocabulary_term,                                                            -- Term.
  t.prior_meaning_since,                                                        -- Since when the prior meaning held.
  t.changed_at,                                                                 -- When the organization's meaning changed.
  t.prior_meaning,                                                              -- What it used to mean.
  t.new_meaning,                                                                -- What it means now.
  t.is_structural_change,                                                       -- TRUE when the thing referred to changed shape, not just wording.
  t.recorded_by_agent,                                                          -- Who recorded it.
  calc_term_meaning_changes_span_days(t.term_meaning_change_id) AS span_days,   -- Days the prior meaning held.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM term_meaning_changes t;

-- ----------------------------------------------------------------------------
-- vw_external_standard_terms: Terms the model reuses from external standards, whether the source deprecated them, and how the model responded.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_external_standard_terms CASCADE;
CREATE VIEW vw_external_standard_terms WITH (security_invoker = ON) AS
SELECT
  t.external_standard_term_id,                                                  -- Stored identifier.
  calc_external_standard_terms_name(t.external_standard_term_id) AS name,       -- Display name.
  t.ontology_profile,                                                           -- Standard the term comes from.
  t.term_iri,                                                                   -- The term's current IRI.
  t.previous_term_iri,                                                          -- The IRI before the standard changed its prefix or identifier.
  t.evaluation_context,                                                         -- Instant the model is judged against.
  calc_external_standard_terms_as_of_instant(t.external_standard_term_id) AS as_of_instant,-- Judgment instant.
  t.deprecated_by_source,                                                       -- TRUE when the source standard marks the term deprecated.
  t.deprecated_at,                                                              -- When the source deprecated it.
  t.still_resolves,                                                             -- TRUE when the deprecated IRI still dereferences.
  t.alignment_updated_at,                                                       -- When our mappings and documentation for the term were last updated.
  t.model_still_needs_term,                                                     -- TRUE when the model still needs the concept.
  t.rehomed_as_term,                                                            -- Local concept the term was taken into.
  calc_external_standard_terms_rehomed_term_same_as(t.external_standard_term_id) AS rehomed_term_same_as,-- Identity link the local concept carries.
  calc_external_standard_terms_rehomed_term_namespace(t.external_standard_term_id) AS rehomed_term_namespace,-- Namespace of the local concept.
  calc_external_standard_terms_rehomed_term_release_issued_at(t.external_standard_term_id) AS rehomed_term_release_issued_at,-- When the model release introducing the local concept was issued.
  calc_external_standard_terms_profile_namespace_iri(t.external_standard_term_id) AS profile_namespace_iri,-- Namespace of the external standard.
  calc_external_standard_terms_days_since_deprecated(t.external_standard_term_id) AS days_since_deprecated,-- Days since the source deprecated the term.
  calc_external_standard_terms_is_recent_deprecation(t.external_standard_term_id) AS is_recent_deprecation,-- TRUE when the source deprecated the term within the last two years.
  calc_external_standard_terms_using_mapping_count(t.external_standard_term_id) AS using_mapping_count,-- Semantic mappings that target the term's current IRI.
  calc_external_standard_terms_stale_identifier_mapping_count(t.external_standard_term_id) AS stale_identifier_mapping_count,-- Semantic mappings still targeting the term's previous IRI.
  calc_external_standard_terms_is_adopted_but_deprecated(t.external_standard_term_id) AS is_adopted_but_deprecated,-- TRUE when a term the model adopted (mapped or re-homed) has been deprecated by its source.
  calc_external_standard_terms_is_alignment_stale_after_deprecati(t.external_standard_term_id) AS is_alignment_stale_after_deprecation,-- TRUE when the source deprecated the term and our alignment and documentation were not updated afterwards.
  calc_external_standard_terms_is_needed_deprecated_term_not_reho(t.external_standard_term_id) AS is_needed_deprecated_term_not_rehomed,-- TRUE when the model still needs a deprecated external term and has not taken it into the local namespace.
  calc_external_standard_terms_is_rehomed_without_identity_link(t.external_standard_term_id) AS is_rehomed_without_identity_link,-- TRUE when a re-homed local concept does not assert identity with the external original.
  calc_external_standard_terms_is_rehomed_without_new_release(t.external_standard_term_id) AS is_rehomed_without_new_release,-- TRUE when a term was re-homed without a model release issued after the deprecation that introduced it.
  calc_external_standard_terms_has_unpropagated_identifier_change(t.external_standard_term_id) AS has_unpropagated_identifier_change,-- TRUE when a standard changed the term's prefix or identifier and some mapping still uses the old one.
  calc_external_standard_terms_rehoming_kept_external_namespace(t.external_standard_term_id) AS rehoming_kept_external_namespace,-- TRUE when a term said to be re-homed still sits in the external standard's namespace.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM external_standard_terms t;

-- ----------------------------------------------------------------------------
-- vw_role_capability_tags: Capability tags a role carries, drawn from a controlled capability scheme.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_capability_tags CASCADE;
CREATE VIEW vw_role_capability_tags WITH (security_invoker = ON) AS
SELECT
  t.role_capability_tag_id,                                                     -- Stored identifier.
  calc_role_capability_tags_name(t.role_capability_tag_id) AS name,             -- Display name.
  t.role,                                                                       -- Role tagged.
  t.capability_term,                                                            -- Capability concept.
  calc_role_capability_tags_capability_scheme_dimension(t.role_capability_tag_id) AS capability_scheme_dimension,-- What the tag's scheme governs.
  calc_role_capability_tags_is_tag_outside_capability_scheme(t.role_capability_tag_id) AS is_tag_outside_capability_scheme,-- TRUE when a capability tag is drawn from a scheme that does not govern agent capabilities.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM role_capability_tags t;

-- ----------------------------------------------------------------------------
-- vw_classification_facets: Independent dimensions along which procedures are classified.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_classification_facets CASCADE;
CREATE VIEW vw_classification_facets WITH (security_invoker = ON) AS
SELECT
  t.classification_facet_id,                                                    -- Stored identifier.
  calc_classification_facets_name(t.classification_facet_id) AS name,           -- Display name.
  t.label,                                                                      -- Facet.
  t.dimension_description,                                                      -- What the facet distinguishes.
  calc_classification_facets_assignment_count(t.classification_facet_id) AS assignment_count,-- Procedures classified along the facet.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM classification_facets t;

-- ----------------------------------------------------------------------------
-- vw_procedure_facet_assignments: A procedure's value along one classification facet.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_procedure_facet_assignments CASCADE;
CREATE VIEW vw_procedure_facet_assignments WITH (security_invoker = ON) AS
SELECT
  t.procedure_facet_assignment_id,                                              -- Stored identifier.
  calc_procedure_facet_assignments_name(t.procedure_facet_assignment_id) AS name,-- Display name.
  t.procedure,                                                                  -- Procedure.
  t.facet,                                                                      -- Facet.
  t.facet_value,                                                                -- Value.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM procedure_facet_assignments t;

-- ----------------------------------------------------------------------------
-- vw_encoding_lifecycle_stages: The stages that carry process knowledge to AI and reuse: collect, store, document, codify, encode, operationalize.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_encoding_lifecycle_stages CASCADE;
CREATE VIEW vw_encoding_lifecycle_stages WITH (security_invoker = ON) AS
SELECT
  t.encoding_lifecycle_stage_id,                                                -- Stored identifier.
  calc_encoding_lifecycle_stages_name(t.encoding_lifecycle_stage_id) AS name,   -- Display name.
  t.label,                                                                      -- Stage name.
  t.stage_order,                                                                -- Position in the lifecycle.
  t.activity,                                                                   -- What happens to knowledge at this stage.
  calc_encoding_lifecycle_stages_annotation_count(t.encoding_lifecycle_stage_id) AS annotation_count,-- Practitioner annotations and feedback recorded against this stage.
  calc_encoding_lifecycle_stages_is_stage_without_feedback(t.encoding_lifecycle_stage_id) AS is_stage_without_feedback,-- TRUE for a lifecycle stage from which no feedback at all has come back.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM encoding_lifecycle_stages t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_consumer_systems: Systems that hold or consume process knowledge: content management, process modeling tools, semantic repositories, knowledge graph platforms, AI platforms and field apps.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_consumer_systems CASCADE;
CREATE VIEW vw_knowledge_consumer_systems WITH (security_invoker = ON) AS
SELECT
  t.knowledge_consumer_system_id,                                               -- Stored identifier.
  calc_knowledge_consumer_systems_name(t.knowledge_consumer_system_id) AS name, -- Display name.
  t.label,                                                                      -- System name.
  t.system_kind,                                                                -- ContentManagement, ProcessModelingTool, SemanticRepository, KnowledgeGraphPlatform, AIPlatform or FieldApp.
  t.organization,                                                               -- Operating organization.
  t.audience,                                                                   -- Human, AI or Both: who reads knowledge through this system.
  t.holds_procedure_knowledge,                                                  -- TRUE when procedures live in this system.
  t.exports_standard_format,                                                    -- TRUE when the system can export its knowledge in an open standard.
  t.export_format,                                                              -- The export format.
  t.has_reasoner,                                                               -- Has a reasoner.
  t.has_semantic_storage,                                                       -- Has semantic (triple) storage.
  t.has_graph_algorithms,                                                       -- Has graph algorithms.
  t.has_machine_learning,                                                       -- Has machine learning.
  t.has_taxonomy,                                                               -- Holds a taxonomy.
  t.has_thesaurus,                                                              -- Holds a thesaurus.
  t.has_ontology,                                                               -- Holds an ontology.
  t.has_metadata_schema,                                                        -- Holds metadata schemas.
  calc_knowledge_consumer_systems_model_sync_count(t.knowledge_consumer_system_id) AS model_sync_count,-- Procedure versions this system holds, synced from the shared model.
  calc_knowledge_consumer_systems_integration_count(t.knowledge_consumer_system_id) AS integration_count,-- AI agent integrations that read knowledge through this system.
  calc_knowledge_consumer_systems_is_knowledge_silo(t.knowledge_consumer_system_id) AS is_knowledge_silo,-- TRUE for a system holding procedures that exports no open format and receives nothing from the shared model.
  calc_knowledge_consumer_systems_is_unlinked_toolchain_component(t.knowledge_consumer_system_id) AS is_unlinked_toolchain_component,-- TRUE for a process modeling tool, semantic repository or AI platform linked to neither the model nor any AI integration.
  calc_knowledge_consumer_systems_semantic_layer_component_count(t.knowledge_consumer_system_id) AS semantic_layer_component_count,-- How many of taxonomy, thesaurus, ontology, metadata schemas and reasoner the system combines.
  calc_knowledge_consumer_systems_platform_capability_count(t.knowledge_consumer_system_id) AS platform_capability_count,-- How many of reasoner, semantic storage, graph algorithms and machine learning the system has.
  calc_knowledge_consumer_systems_is_immature_graph_platform(t.knowledge_consumer_system_id) AS is_immature_graph_platform,-- TRUE for a knowledge graph platform that lacks one of reasoner, semantic storage, graph algorithms or machine learning.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.is_computationally_queryable,                                               -- Whether the procedure knowledge this system holds can be queried structurally, rather than only opened and read by a person.
  t.is_computationally_validatable,                                             -- Whether the procedure knowledge this system holds can be checked automatically against rules.
  calc_knowledge_consumer_systems_holds_computationally_encoded_p(t.knowledge_consumer_system_id) AS holds_computationally_encoded_procedure_knowledge,-- The system holds procedure knowledge in a form that can be queried, validated and reasoned over computationally -- the shift that encoded representations made possible.
  calc_knowledge_consumer_systems_stores_procedure_knowledge_with(t.knowledge_consumer_system_id) AS stores_procedure_knowledge_without_computational_access-- The system holds procedure knowledge that no machine can query, validate or reason over: storage without encoding.
FROM knowledge_consumer_systems t;

-- ----------------------------------------------------------------------------
-- vw_consumer_system_syncs: Which procedure version a consuming system currently holds, from what source, and when it was synced.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_consumer_system_syncs CASCADE;
CREATE VIEW vw_consumer_system_syncs WITH (security_invoker = ON) AS
SELECT
  t.consumer_system_sync_id,                                                    -- Stored identifier.
  calc_consumer_system_syncs_name(t.consumer_system_sync_id) AS name,           -- Display name.
  t.consumer_system,                                                            -- Consuming system.
  t.loaded_version,                                                             -- Procedure version the system holds.
  t.synced_at,                                                                  -- When the system last took the version.
  t.source_resource,                                                            -- A document the system was fed from instead of the shared model; blank when fed from the model.
  t.carries_provenance,                                                         -- TRUE when the system's copy kept who authored the knowledge and where it came from.
  calc_consumer_system_syncs_system_audience(t.consumer_system_sync_id) AS system_audience,-- Who reads through the system.
  calc_consumer_system_syncs_loaded_procedure(t.consumer_system_sync_id) AS loaded_procedure,-- Procedure of the loaded version.
  calc_consumer_system_syncs_canonical_version(t.consumer_system_sync_id) AS canonical_version,-- The procedure's current version in the model.
  calc_consumer_system_syncs_canonical_version_modified_at(t.consumer_system_sync_id) AS canonical_version_modified_at,-- When the current version last changed.
  calc_consumer_system_syncs_loaded_version_creator(t.consumer_system_sync_id) AS loaded_version_creator,-- Who authored the loaded version.
  calc_consumer_system_syncs_is_behind_canonical_version(t.consumer_system_sync_id) AS is_behind_canonical_version,-- TRUE when a consuming system holds a different version from the one the model says is current.
  calc_consumer_system_syncs_predates_version_change(t.consumer_system_sync_id) AS predates_version_change,-- TRUE when the system holds the current version but took it before that version last changed.
  calc_consumer_system_syncs_is_ai_fed_from_forked_copy(t.consumer_system_sync_id) AS is_ai_fed_from_forked_copy,-- TRUE when a system read by AI is fed from a separate document rather than the shared model humans use.
  calc_consumer_system_syncs_drops_provenance_in_transit(t.consumer_system_sync_id) AS drops_provenance_in_transit,-- TRUE when the version had an author on record and the system's copy dropped the provenance.
  calc_consumer_system_syncs_reaches_humans(t.consumer_system_sync_id) AS reaches_humans,-- TRUE when the system is read by people.
  calc_consumer_system_syncs_reaches_machines(t.consumer_system_sync_id) AS reaches_machines,-- TRUE when the system is read by AI.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM consumer_system_syncs t;

-- ----------------------------------------------------------------------------
-- vw_integration_pathways: Shared pathways agents reach knowledge through (a Model Context Protocol server, an agent-to-agent gateway) versus one-off connections.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_integration_pathways CASCADE;
CREATE VIEW vw_integration_pathways WITH (security_invoker = ON) AS
SELECT
  t.integration_pathway_id,                                                     -- Stored identifier.
  calc_integration_pathways_name(t.integration_pathway_id) AS name,             -- Display name.
  t.label,                                                                      -- Pathway.
  t.protocol,                                                                   -- MCP, A2A, custom or none.
  calc_integration_pathways_integration_count_on_pathway(t.integration_pathway_id) AS integration_count_on_pathway,-- Agent integrations that use this pathway.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM integration_pathways t;

-- ----------------------------------------------------------------------------
-- vw_agent_integrations: The central registry of AI agent integrations: which agent reads which knowledge system, over which pathway, served which graph.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_agent_integrations CASCADE;
CREATE VIEW vw_agent_integrations WITH (security_invoker = ON) AS
SELECT
  t.agent_integration_id,                                                       -- Stored identifier.
  calc_agent_integrations_name(t.agent_integration_id) AS name,                 -- Display name.
  t.agent,                                                                      -- Integrated AI agent.
  t.knowledge_system,                                                           -- System it reads knowledge from.
  t.pathway,                                                                    -- Pathway used.
  t.serves_snapshot,                                                            -- Graph snapshot the integration serves the agent.
  t.delivery_mode,                                                              -- Runtime (retrieved when the agent acts) or BakedIn (copied into a prompt or model once).
  t.registry_entry_key,                                                         -- Entry in the central integration registry; blank when never registered.
  t.connected_at,                                                               -- When connected.
  calc_agent_integrations_pathway_integration_count(t.agent_integration_id) AS pathway_integration_count,-- Integrations sharing this pathway.
  calc_agent_integrations_observed_answer_count(t.agent_integration_id) AS observed_answer_count,-- Assistant answers delivered through this integration.
  calc_agent_integrations_is_shadow_integration(t.agent_integration_id) AS is_shadow_integration,-- TRUE when an integration is in live use but has no entry in the central registry.
  calc_agent_integrations_is_one_off_connection(t.agent_integration_id) AS is_one_off_connection,-- TRUE when no other integration shares the pathway this one uses.
  calc_agent_integrations_snapshot_is_governed(t.agent_integration_id) AS snapshot_is_governed,-- Whether the served snapshot is governed.
  calc_agent_integrations_is_deployed_on_ungoverned_graph(t.agent_integration_id) AS is_deployed_on_ungoverned_graph,-- TRUE when an AI agent is deployed against a graph snapshot nobody governs.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM agent_integrations t;

-- ----------------------------------------------------------------------------
-- vw_grounding_snapshots: A snapshot of the knowledge graph as it is served to retrieval and AI context, with its reasoning and governance record.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_grounding_snapshots CASCADE;
CREATE VIEW vw_grounding_snapshots WITH (security_invoker = ON) AS
SELECT
  t.grounding_snapshot_id,                                                      -- Stored identifier.
  calc_grounding_snapshots_name(t.grounding_snapshot_id) AS name,               -- Display name.
  t.label,                                                                      -- Snapshot.
  t.built_at,                                                                   -- When built.
  t.served_from,                                                                -- When retrieval began serving it.
  t.served_to,                                                                  -- When it stopped being served.
  t.steward_role,                                                               -- Role that stewards the served graph.
  t.governance_reviewed_at,                                                     -- When the steward last reviewed the graph for serving.
  calc_grounding_snapshots_is_governed(t.grounding_snapshot_id) AS is_governed, -- TRUE when the snapshot has a steward and was reviewed before it was served.
  calc_grounding_snapshots_reasoner_run_count(t.grounding_snapshot_id) AS reasoner_run_count,-- Reasoner runs over the snapshot.
  calc_grounding_snapshots_consistent_reasoner_run_count(t.grounding_snapshot_id) AS consistent_reasoner_run_count,-- Reasoner runs that found the snapshot consistent.
  calc_grounding_snapshots_latest_materialized_at(t.grounding_snapshot_id) AS latest_materialized_at,-- When a reasoner last materialized the snapshot's entailments.
  calc_grounding_snapshots_served_without_consistency_check(t.grounding_snapshot_id) AS served_without_consistency_check,-- TRUE when a snapshot was served to AI with no reasoner run finding it consistent.
  calc_grounding_snapshots_served_before_materialization(t.grounding_snapshot_id) AS served_before_materialization,-- TRUE when a snapshot was served before a reasoner materialized what its assertions entail.
  calc_grounding_snapshots_assertion_count(t.grounding_snapshot_id) AS assertion_count,-- Assertions served.
  calc_grounding_snapshots_stale_assignment_assertion_count(t.grounding_snapshot_id) AS stale_assignment_assertion_count,-- Served assertions resting on a role assignment that is no longer current.
  calc_grounding_snapshots_serves_stale_role_assignments(t.grounding_snapshot_id) AS serves_stale_role_assignments,-- TRUE when retrieval serves an assertion about a role assignment that has ended.
  calc_grounding_snapshots_deprecated_as_current_count(t.grounding_snapshot_id) AS deprecated_as_current_count,-- Served assertions presenting a deprecated or archived version as current.
  calc_grounding_snapshots_serves_deprecated_as_current(t.grounding_snapshot_id) AS serves_deprecated_as_current,-- TRUE when retrieval presents a deprecated workflow individual as current.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM grounding_snapshots t;

-- ----------------------------------------------------------------------------
-- vw_reasoner_runs: One reasoner run over a grounding snapshot: consistency, materialization, budget and dropped axioms.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_reasoner_runs CASCADE;
CREATE VIEW vw_reasoner_runs WITH (security_invoker = ON) AS
SELECT
  t.reasoner_run_id,                                                            -- Stored identifier.
  calc_reasoner_runs_name(t.reasoner_run_id) AS name,                           -- Display name.
  t.snapshot,                                                                   -- Snapshot reasoned over.
  t.reasoner_profile,                                                           -- OWL 2 RL, OWL 2 DL or RDFS.
  t.ran_at,                                                                     -- When run.
  t.materialized_at,                                                            -- When entailments were written into the snapshot; blank if not.
  t.is_consistent,                                                              -- Whether the reasoner found the snapshot consistent.
  t.inferred_triple_count,                                                      -- Triples inferred.
  t.duration_seconds,                                                           -- Run time.
  t.time_budget_seconds,                                                        -- Time allowed before serving.
  t.dropped_axiom_count,                                                        -- Axioms the profile could not express and dropped.
  t.schema_validation_passed,                                                   -- Whether the export passed plain schema (shape of the tables) validation.
  calc_reasoner_runs_is_richness_tractability_failure(t.reasoner_run_id) AS is_richness_tractability_failure,-- TRUE when a run either blew its reasoning budget or kept to budget only by dropping axioms.
  calc_reasoner_runs_passes_schema_but_fails_reasoner(t.reasoner_run_id) AS passes_schema_but_fails_reasoner,-- TRUE when an export that validates as a table design is found inconsistent by the reasoner.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM reasoner_runs t;

-- ----------------------------------------------------------------------------
-- vw_snapshot_assertions: One typed assertion served to retrieval in a snapshot, with its provenance and Dublin Core labels.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_snapshot_assertions CASCADE;
CREATE VIEW vw_snapshot_assertions WITH (security_invoker = ON) AS
SELECT
  t.snapshot_assertion_id,                                                      -- Stored identifier.
  calc_snapshot_assertions_name(t.snapshot_assertion_id) AS name,               -- Display name.
  t.snapshot,                                                                   -- Snapshot.
  t.subject_identifier,                                                         -- Identifier of the subject individual.
  t.predicate,                                                                  -- Predicate.
  t.object_value,                                                               -- Object.
  t.is_inferred,                                                                -- TRUE when the reasoner inferred the assertion.
  t.source_procedure_version,                                                   -- Procedure version the assertion came from.
  t.source_step,                                                                -- Step the assertion came from.
  t.source_role_assignment,                                                     -- Role assignment the assertion came from.
  t.about_agent,                                                                -- Agent the assertion is about, for accountability and category assertions.
  t.provenance_uri,                                                             -- Where the assertion came from.
  t.dc_title,                                                                   -- dcterms:title of the subject.
  t.dc_description,                                                             -- dcterms:description of the subject.
  t.presented_status,                                                           -- Status the assertion presents the subject as: Current or Deprecated.
  calc_snapshot_assertions_source_version_status(t.snapshot_assertion_id) AS source_version_status,-- Status of the source version.
  calc_snapshot_assertions_source_assignment_is_current(t.snapshot_assertion_id) AS source_assignment_is_current,-- Whether the source role assignment is current.
  calc_snapshot_assertions_snapshot_consistent_run_count(t.snapshot_assertion_id) AS snapshot_consistent_run_count,-- Consistent reasoner runs over the snapshot.
  calc_snapshot_assertions_snapshot_is_reasoned(t.snapshot_assertion_id) AS snapshot_is_reasoned,-- TRUE when the assertion sits in a snapshot a reasoner found consistent.
  calc_snapshot_assertions_is_stale_role_assertion(t.snapshot_assertion_id) AS is_stale_role_assertion,-- TRUE when the assertion rests on a role assignment that is no longer current.
  calc_snapshot_assertions_presents_deprecated_as_current(t.snapshot_assertion_id) AS presents_deprecated_as_current,-- TRUE when the assertion presents a deprecated or archived version as current.
  calc_snapshot_assertions_lacks_provenance(t.snapshot_assertion_id) AS lacks_provenance,-- TRUE when a served assertion links back to nothing: no provenance URI, version, step or assignment.
  calc_snapshot_assertions_has_opaque_identifier(t.snapshot_assertion_id) AS has_opaque_identifier,-- TRUE when the subject identifier is a UUID URN or blank node a person or model cannot read or cite.
  calc_snapshot_assertions_lacks_dublin_core(t.snapshot_assertion_id) AS lacks_dublin_core,-- TRUE when the subject carries no Dublin Core title or no description.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM snapshot_assertions t;

-- ----------------------------------------------------------------------------
-- vw_retrieval_segments: Retrieval segments of process knowledge, with their boundary, position, applicability and links.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_retrieval_segments CASCADE;
CREATE VIEW vw_retrieval_segments WITH (security_invoker = ON) AS
SELECT
  t.retrieval_segment_id,                                                       -- Stored identifier.
  calc_retrieval_segments_name(t.retrieval_segment_id) AS name,                 -- Display name.
  t.procedure_version,                                                          -- Version the segment is cut from.
  t.step,                                                                       -- Activity the segment covers.
  t.decision_point,                                                             -- Decision point the segment covers.
  t.boundary_kind,                                                              -- Activity, DecisionPoint, or CharacterWindow for a chunk cut by length.
  t.character_count,                                                            -- Length.
  t.position_in_process,                                                        -- Where the segment sits in the larger process.
  t.applicability_condition,                                                    -- When the segment applies.
  t.related_segment,                                                            -- A related segment.
  t.source_resource,                                                            -- Where the text came from.
  t.segment_text,                                                               -- Segment text.
  t.is_indexed,                                                                 -- TRUE when retrieval serves the segment.
  t.authored_by_agent,                                                          -- Who wrote the segment.
  t.accountable_role,                                                           -- Role accountable for the segment's content.
  t.contradicts_segment,                                                        -- A segment this one logically contradicts, as found by the consistency check.
  calc_retrieval_segments_author_agent_kind(t.retrieval_segment_id) AS author_agent_kind,-- Kind of author.
  calc_retrieval_segments_related_from_count(t.retrieval_segment_id) AS related_from_count,-- Segments that link to this one.
  calc_retrieval_segments_is_isolated_chunk(t.retrieval_segment_id) AS is_isolated_chunk,-- TRUE for a segment with no position, no applicability and no link to or from any other segment.
  calc_retrieval_segments_contradicted_is_indexed(t.retrieval_segment_id) AS contradicted_is_indexed,-- Whether the contradicted segment is served too.
  calc_retrieval_segments_is_inconsistent_grounding(t.retrieval_segment_id) AS is_inconsistent_grounding,-- TRUE when retrieval serves two segments that contradict each other.
  calc_retrieval_segments_is_machine_held_knowledge(t.retrieval_segment_id) AS is_machine_held_knowledge,-- TRUE for knowledge written by software with no human role accountable for it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM retrieval_segments t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_query_definitions: Structured queries (SPARQL or SQL) run over the knowledge, with the layers and sources they touch.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_query_definitions CASCADE;
CREATE VIEW vw_knowledge_query_definitions WITH (security_invoker = ON) AS
SELECT
  t.knowledge_query_definition_id,                                              -- Stored identifier.
  calc_knowledge_query_definitions_name(t.knowledge_query_definition_id) AS name,-- Display name.
  t.label,                                                                      -- The question the query answers.
  t.query_language,                                                             -- SPARQL or SQL.
  t.query_text,                                                                 -- The query, abridged.
  t.target_procedure_version,                                                   -- Version queried.
  t.needs_ontology_and_instances,                                               -- TRUE when the question can only be answered by combining class definitions with instance data.
  t.traverses_ontology_layer,                                                   -- TRUE when the query walks class or property definitions.
  t.traverses_instance_layer,                                                   -- TRUE when the query walks instance data.
  t.ran_over_consolidated_copy,                                                 -- TRUE when the sources were first copied into one store to run the query.
  t.last_run_at,                                                                -- When last run.
  calc_knowledge_query_definitions_source_system_count(t.knowledge_query_definition_id) AS source_system_count,-- Knowledge systems the query reads.
  calc_knowledge_query_definitions_misses_a_layer(t.knowledge_query_definition_id) AS misses_a_layer,-- TRUE when a question that needs ontology and instances together is answered by a query that walks only one of them.
  calc_knowledge_query_definitions_consolidated_distributed_sourc(t.knowledge_query_definition_id) AS consolidated_distributed_sources,-- TRUE when a query over several knowledge systems only ran after copying them into one store.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_query_definitions t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_query_sources: The knowledge systems one structured query reads.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_query_sources CASCADE;
CREATE VIEW vw_knowledge_query_sources WITH (security_invoker = ON) AS
SELECT
  t.knowledge_query_source_id,                                                  -- Stored identifier.
  calc_knowledge_query_sources_name(t.knowledge_query_source_id) AS name,       -- Display name.
  t.query_definition,                                                           -- Query.
  t.consumer_system,                                                            -- System read.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_query_sources t;

-- ----------------------------------------------------------------------------
-- vw_assistant_answers: One answer, guidance or recommendation an AI assistant delivered, recorded with its context and review. The model does not run the AI; it records what it said.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assistant_answers CASCADE;
CREATE VIEW vw_assistant_answers WITH (security_invoker = ON) AS
SELECT
  t.assistant_answer_id,                                                        -- Stored identifier.
  calc_assistant_answers_name(t.assistant_answer_id) AS name,                   -- Display name.
  t.answering_agent,                                                            -- AI agent that answered.
  t.asked_by_agent,                                                             -- Who asked.
  t.via_integration,                                                            -- Integration the answer came through.
  t.step_execution,                                                             -- Step execution under way when the question was asked.
  t.asked_at,                                                                   -- When asked.
  t.answered_at,                                                                -- When answered.
  t.answer_kind,                                                                -- Guidance, Recommendation or Lookup.
  t.question_topic,                                                             -- Authority, Safety, Sequence, Scheduling or General.
  t.question_text,                                                              -- The question.
  t.answer_text,                                                                -- The answer.
  t.retrieval_mode,                                                             -- StructuredQuery, DocumentPassage or None.
  t.derivation_performed_by,                                                    -- Reasoner, StructuredQuery or LanguageModel: what produced the logic of the answer.
  t.needs_inference,                                                            -- TRUE when the answer requires deriving something not stated outright.
  t.assumed_current_step,                                                       -- Step the assistant believed the execution was at.
  t.asserted_next_step,                                                         -- Step the assistant said comes next.
  t.recommended_step,                                                           -- Step a recommendation acts on.
  t.raised_safety_concern,                                                      -- TRUE when the answer raised a possible safety problem.
  t.delivery_disposition,                                                       -- Delivered or Withheld.
  t.was_acted_on,                                                               -- TRUE when someone acted on the answer.
  t.human_reviewed_by,                                                          -- Expert who reviewed the answer before it was used.
  t.reviewed_for_initiative,                                                    -- Automation pilot whose output this expert review belongs to.
  t.was_correct,                                                                -- Expert verdict on the answer.
  t.documented_inaccuracy,                                                      -- What was wrong, as documented.
  t.task_outcome,                                                               -- Completed, Failed or Abandoned.
  calc_assistant_answers_grounding_count(t.assistant_answer_id) AS grounding_count,-- Groundings of the answer.
  calc_assistant_answers_own_knowledge_grounding_count(t.assistant_answer_id) AS own_knowledge_grounding_count,-- Groundings in the organization's own assertions or segments.
  calc_assistant_answers_cited_grounding_count(t.assistant_answer_id) AS cited_grounding_count,-- Groundings shown to the person as citations.
  calc_assistant_answers_stale_grounding_count(t.assistant_answer_id) AS stale_grounding_count,-- Groundings on stale or deprecated assertions.
  calc_assistant_answers_is_not_from_own_knowledge(t.assistant_answer_id) AS is_not_from_own_knowledge,-- TRUE when a delivered answer rests on nothing from the organization's own procedural knowledge.
  calc_assistant_answers_is_untraceable_to_source(t.assistant_answer_id) AS is_untraceable_to_source,-- TRUE when a delivered answer was grounded but showed the person none of its sources.
  calc_assistant_answers_context_unescalated_danger_cue_count(t.assistant_answer_id) AS context_unescalated_danger_cue_count,-- Danger cues seen and not escalated on the step under way.
  calc_assistant_answers_stayed_silent_on_safety_problem(t.assistant_answer_id) AS stayed_silent_on_safety_problem,-- TRUE when an unescalated danger cue was on record for the step and the answer raised no safety concern.
  calc_assistant_answers_context_step_ended_at(t.assistant_answer_id) AS context_step_ended_at,-- When the step under way ended.
  calc_assistant_answers_arrived_after_step_ended(t.assistant_answer_id) AS arrived_after_step_ended,-- TRUE when guidance for a step arrived after the step had already ended.
  calc_assistant_answers_execution_of_context(t.assistant_answer_id) AS execution_of_context,-- Procedure execution under way.
  calc_assistant_answers_context_step(t.assistant_answer_id) AS context_step,   -- Step under way.
  calc_assistant_answers_assumed_step_completed_count(t.assistant_answer_id) AS assumed_step_completed_count,-- Completed runs, in the same execution, of the step the assistant believed it was at.
  calc_assistant_answers_lost_track_of_state(t.assistant_answer_id) AS lost_track_of_state,-- TRUE when the assistant acted as if a step were done that the execution record shows never completed.
  calc_assistant_answers_specified_transition_count(t.assistant_answer_id) AS specified_transition_count,-- Transitions the model allows from the assumed step to the asserted next step.
  calc_assistant_answers_contradicts_shared_model(t.assistant_answer_id) AS contradicts_shared_model,-- TRUE when the assistant asserted a next step the procedure's transition graph does not allow.
  calc_assistant_answers_is_explicitly_grounded_recommendation(t.assistant_answer_id) AS is_explicitly_grounded_recommendation,-- TRUE for a recommendation that names at least one piece of the organization's explicit process knowledge.
  calc_assistant_answers_recommendation_rests_on_nothing_explicit(t.assistant_answer_id) AS recommendation_rests_on_nothing_explicit,-- TRUE for a recommendation traceable to no explicit process knowledge.
  calc_assistant_answers_recommended_step_regulatory_count(t.assistant_answer_id) AS recommended_step_regulatory_count,-- Regulatory requirements on the recommended step.
  calc_assistant_answers_requirement_check_count(t.assistant_answer_id) AS requirement_check_count,-- Requirement checks run on the answer.
  calc_assistant_answers_conflict_count(t.assistant_answer_id) AS conflict_count,-- Checks that found a conflict.
  calc_assistant_answers_conflicts_with_regulation(t.assistant_answer_id) AS conflicts_with_regulation,-- TRUE when a check found the recommended action conflicts with an applicable requirement.
  calc_assistant_answers_is_unchecked_regulated_recommendation(t.assistant_answer_id) AS is_unchecked_regulated_recommendation,-- TRUE for a recommendation on a regulated step that was never checked against its requirements.
  calc_assistant_answers_delivered_despite_conflict(t.assistant_answer_id) AS delivered_despite_conflict,-- TRUE when the check found a regulatory conflict and the recommendation was delivered anyway.
  calc_assistant_answers_recommended_step_needs_human(t.assistant_answer_id) AS recommended_step_needs_human,-- Whether the recommended step requires human confirmation.
  calc_assistant_answers_acted_on_without_human_judgment(t.assistant_answer_id) AS acted_on_without_human_judgment,-- TRUE when an AI recommendation on a step that requires human judgment was acted on with no expert review.
  calc_assistant_answers_answered_compliance_question_from_docume(t.assistant_answer_id) AS answered_compliance_question_from_documents,-- TRUE when an authority or safety question was answered from document passages rather than a structured query.
  calc_assistant_answers_document_interpretation_erred(t.assistant_answer_id) AS document_interpretation_erred,-- TRUE when an authority question answered by interpreting a document passage came back wrong.
  calc_assistant_answers_model_did_the_reasoning(t.assistant_answer_id) AS model_did_the_reasoning,-- TRUE when an answer that needed inference had its logic produced by the language model, not a reasoner or query.
  calc_assistant_answers_wrong_because_graph_was_stale(t.assistant_answer_id) AS wrong_because_graph_was_stale,-- TRUE when a graph-grounded answer was wrong and rested on a stale or deprecated assertion.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  calc_assistant_answers_owner_organization(t.assistant_answer_id) AS owner_organization,-- The organization that owns the procedure this row belongs to, one hop at a time from Procedures.OwnerOrganization. A row policy compares it to the caller's organization, so a plant sign-in never sees the finance close.
  calc_assistant_answers_model_reasoned_and_task_failed(t.assistant_answer_id) AS model_reasoned_and_task_failed-- The language model did the reasoning for this answer itself, and the task it was asked about ended in failure.
FROM assistant_answers t;

-- ----------------------------------------------------------------------------
-- vw_answer_groundings: Which served assertion, segment or external source grounded an assistant answer, and whether it was cited.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_answer_groundings CASCADE;
CREATE VIEW vw_answer_groundings WITH (security_invoker = ON) AS
SELECT
  t.answer_grounding_id,                                                        -- Stored identifier.
  calc_answer_groundings_name(t.answer_grounding_id) AS name,                   -- Display name.
  t.assistant_answer,                                                           -- Answer.
  t.snapshot_assertion,                                                         -- Served assertion.
  t.retrieval_segment,                                                          -- Retrieved segment.
  t.external_source_uri,                                                        -- External content outside the organization's knowledge.
  t.cited_to_user,                                                              -- TRUE when shown to the person as a citation.
  calc_answer_groundings_is_from_own_knowledge(t.answer_grounding_id) AS is_from_own_knowledge,-- TRUE when the grounding is the organization's own assertion or segment.
  calc_answer_groundings_assertion_is_stale(t.answer_grounding_id) AS assertion_is_stale,-- Whether the assertion rests on an ended role assignment.
  calc_answer_groundings_assertion_presents_deprecated(t.answer_grounding_id) AS assertion_presents_deprecated,-- Whether the assertion presents a deprecated version as current.
  calc_answer_groundings_grounds_on_stale_assertion(t.answer_grounding_id) AS grounds_on_stale_assertion,-- TRUE when the grounding assertion is stale or deprecated.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM answer_groundings t;

-- ----------------------------------------------------------------------------
-- vw_answer_requirement_checks: A check of an AI recommendation against a requirement, and its verdict.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_answer_requirement_checks CASCADE;
CREATE VIEW vw_answer_requirement_checks WITH (security_invoker = ON) AS
SELECT
  t.answer_requirement_check_id,                                                -- Stored identifier.
  calc_answer_requirement_checks_name(t.answer_requirement_check_id) AS name,   -- Display name.
  t.assistant_answer,                                                           -- Recommendation checked.
  t.requirement,                                                                -- Requirement.
  t.verdict,                                                                    -- Complies or Conflicts.
  t.checked_at,                                                                 -- When.
  t.checked_by_agent,                                                           -- Who or what checked.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM answer_requirement_checks t;

-- ----------------------------------------------------------------------------
-- vw_ai_tool_invocations: A tool or function an AI agent invoked during a step execution, with the inputs it supplied.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_tool_invocations CASCADE;
CREATE VIEW vw_ai_tool_invocations WITH (security_invoker = ON) AS
SELECT
  t.ai_tool_invocation_id,                                                      -- Stored identifier.
  calc_ai_tool_invocations_name(t.ai_tool_invocation_id) AS name,               -- Display name.
  t.invoking_agent,                                                             -- AI agent.
  t.step_execution,                                                             -- Step execution.
  t.function,                                                                   -- Function invoked.
  t.invoked_at,                                                                 -- When.
  t.supplied_input_count,                                                       -- Declared inputs the agent actually supplied.
  calc_ai_tool_invocations_executed_step(t.ai_tool_invocation_id) AS executed_step,-- Step being executed.
  calc_ai_tool_invocations_declared_function_count(t.ai_tool_invocation_id) AS declared_function_count,-- Declarations of this function on the executed step.
  calc_ai_tool_invocations_is_undeclared_tool_use(t.ai_tool_invocation_id) AS is_undeclared_tool_use,-- TRUE when an AI agent used a tool the process graph does not declare on that step.
  calc_ai_tool_invocations_declared_input_count(t.ai_tool_invocation_id) AS declared_input_count,-- Inputs the step declares.
  calc_ai_tool_invocations_acted_without_declared_context(t.ai_tool_invocation_id) AS acted_without_declared_context,-- TRUE when the agent acted with fewer of the step's declared inputs than the step needs.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_tool_invocations t;

-- ----------------------------------------------------------------------------
-- vw_embedding_probes: Recorded similarity of process-vocabulary term pairs under an embedding model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_embedding_probes CASCADE;
CREATE VIEW vw_embedding_probes WITH (security_invoker = ON) AS
SELECT
  t.embedding_probe_id,                                                         -- Stored identifier.
  calc_embedding_probes_name(t.embedding_probe_id) AS name,                     -- Display name.
  t.term_a,                                                                     -- First term.
  t.term_b,                                                                     -- Second term.
  t.expected_relation,                                                          -- NearSynonym or Opposite in the process domain.
  t.embedding_model,                                                            -- Embedding model probed.
  t.cosine_similarity,                                                          -- Measured cosine similarity.
  t.probed_at,                                                                  -- When.
  calc_embedding_probes_synonyms_not_similar(t.embedding_probe_id) AS synonyms_not_similar,-- TRUE when the model places near-synonyms of the process domain below 0.7 similarity.
  calc_embedding_probes_opposites_not_opposed(t.embedding_probe_id) AS opposites_not_opposed,-- TRUE when the model places opposites of the process domain above 0.3 similarity.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM embedding_probes t;

-- ----------------------------------------------------------------------------
-- vw_prompt_templates: Prompts and system instructions that carry process knowledge to AI, layered and kept in a library.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_prompt_templates CASCADE;
CREATE VIEW vw_prompt_templates WITH (security_invoker = ON) AS
SELECT
  t.prompt_template_id,                                                         -- Stored identifier.
  calc_prompt_templates_name(t.prompt_template_id) AS name,                     -- Display name.
  t.label,                                                                      -- Prompt.
  t.layer,                                                                      -- Framework, ProcedureDetail or AdHocContext.
  t.parent_template,                                                            -- The framework layer this detail layer is pulled into.
  t.source_procedure_version,                                                   -- Procedure version the prompt's knowledge was drawn from.
  t.library_status,                                                             -- Maintained or Unmanaged.
  t.maintained_by_role,                                                         -- Role maintaining the prompt.
  t.used_by_agent,                                                              -- AI agent using the prompt.
  t.carries_procedure_instructions,                                             -- TRUE when the prompt tells the AI how to carry out a procedure.
  t.includes_rare_detail,                                                       -- TRUE when the prompt inlines detail needed only in rare cases.
  t.token_budget,                                                               -- Tokens allowed.
  t.estimated_tokens,                                                           -- Tokens used.
  t.source_token_count,                                                         -- Tokens in the source knowledge the prompt was made from.
  calc_prompt_templates_child_template_count(t.prompt_template_id) AS child_template_count,-- Detail layers pulled into this one.
  calc_prompt_templates_is_disconnected_prompt_knowledge(t.prompt_template_id) AS is_disconnected_prompt_knowledge,-- TRUE when a prompt carries procedure instructions that exist in no procedure version of the model.
  calc_prompt_templates_is_unmanaged_prompt_in_use(t.prompt_template_id) AS is_unmanaged_prompt_in_use,-- TRUE when an agent uses a prompt nobody maintains in the library.
  calc_prompt_templates_spends_budget_on_rare_detail(t.prompt_template_id) AS spends_budget_on_rare_detail,-- TRUE when a prompt inlines rarely needed detail and so exceeds its token budget.
  calc_prompt_templates_condensation_percent(t.prompt_template_id) AS condensation_percent,-- Prompt size as a share of the source knowledge.
  calc_prompt_templates_is_verbatim_dump(t.prompt_template_id) AS is_verbatim_dump,-- TRUE when a prompt pastes its source at 90% or more of its size instead of codifying and condensing it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM prompt_templates t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_projections: Diagrams and narrative documents that present a procedure version to people, and whether they were generated from the model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_projections CASCADE;
CREATE VIEW vw_knowledge_projections WITH (security_invoker = ON) AS
SELECT
  t.knowledge_projection_id,                                                    -- Stored identifier.
  calc_knowledge_projections_name(t.knowledge_projection_id) AS name,           -- Display name.
  t.label,                                                                      -- Projection.
  t.projection_kind,                                                            -- Narrative or Diagram.
  t.notation,                                                                   -- BPMN 2.0, Mermaid flowchart, Visio flowchart, Markdown prose or RuleSpeak HTML.
  t.procedure_version,                                                          -- Version presented.
  t.output_path,                                                                -- Where the artifact lives.
  t.generated_by_tool,                                                          -- Generator that produced it from the model; blank when made by hand.
  t.generated_at,                                                               -- When generated.
  t.published_uri,                                                              -- Where stakeholders can open it; blank when unpublished.
  t.audience_role,                                                              -- Intended audience.
  calc_knowledge_projections_version_modified_at(t.knowledge_projection_id) AS version_modified_at,-- When the presented version last changed.
  calc_knowledge_projections_open_count(t.knowledge_projection_id) AS open_count,-- Times someone opened it from a search.
  calc_knowledge_projections_diagram_can_diverge_from_model(t.knowledge_projection_id) AS diagram_can_diverge_from_model,-- TRUE for a diagram drawn by hand or generated before the version last changed.
  calc_knowledge_projections_narrative_not_generated_from_model(t.knowledge_projection_id) AS narrative_not_generated_from_model,-- TRUE for narrative documentation written by hand or generated before the version last changed.
  calc_knowledge_projections_narrative_unreachable(t.knowledge_projection_id) AS narrative_unreachable,-- TRUE for narrative documentation that is published nowhere and has never been opened.
  calc_knowledge_projections_is_published(t.knowledge_projection_id) AS is_published,-- TRUE when stakeholders can open the projection.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_projections t;

-- ----------------------------------------------------------------------------
-- vw_model_annotations: Comments, questions, suggestions, alternative interpretations, outdated flags and new or missing knowledge practitioners attach to the model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_annotations CASCADE;
CREATE VIEW vw_model_annotations WITH (security_invoker = ON) AS
SELECT
  t.model_annotation_id,                                                        -- Stored identifier.
  calc_model_annotations_name(t.model_annotation_id) AS name,                   -- Display name.
  t.procedure_version,                                                          -- Version annotated.
  t.step,                                                                       -- Step annotated.
  t.annotated_by_agent,                                                         -- Who annotated.
  t.annotated_at,                                                               -- When.
  t.annotation_kind,                                                            -- Comment, Question, Suggestion, AlternativeInterpretation, FlagOutdated, NewKnowledge or MissingKnowledge.
  t.body,                                                                       -- The annotation.
  t.status,                                                                     -- Open, Accepted or Declined.
  t.entered_through,                                                            -- AnnotationPanel or EmailToSteward.
  t.stored_in,                                                                  -- AnnotationLayer or AuthoritativeRulebook.
  t.lifecycle_stage,                                                            -- Lifecycle stage the feedback concerns.
  t.promoted_to_fragment,                                                       -- Knowledge fragment new knowledge became.
  t.raised_knowledge_gap,                                                       -- Knowledge gap a missing-knowledge report became.
  calc_model_annotations_is_discussion_in_authoritative_model(t.model_annotation_id) AS is_discussion_in_authoritative_model,-- TRUE when a comment, question, suggestion or alternative reading was written into the authoritative rulebook.
  calc_model_annotations_flag_bypassed_annotation_interface(t.model_annotation_id) AS flag_bypassed_annotation_interface,-- TRUE when a practitioner had to flag outdated guidance outside the annotation interface.
  calc_model_annotations_is_lost_new_knowledge(t.model_annotation_id) AS is_lost_new_knowledge,-- TRUE when new knowledge a practitioner added was not declined and never became a knowledge fragment.
  calc_model_annotations_is_friction_without_gap(t.model_annotation_id) AS is_friction_without_gap,-- TRUE when friction from missing knowledge was reported and never recorded as a knowledge gap.
  calc_model_annotations_is_open_outdated_flag(t.model_annotation_id) AS is_open_outdated_flag,-- TRUE for guidance a practitioner flagged as outdated that is still open.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_annotations t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_search_events: Searches and retrievals against the knowledge, by people and AI, with what they found and when they gave up.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_search_events CASCADE;
CREATE VIEW vw_knowledge_search_events WITH (security_invoker = ON) AS
SELECT
  t.knowledge_search_event_id,                                                  -- Stored identifier.
  calc_knowledge_search_events_name(t.knowledge_search_event_id) AS name,       -- Display name.
  t.searched_by_agent,                                                          -- Who searched.
  t.searched_at,                                                                -- When.
  t.channel,                                                                    -- RegisterSearch, TabletSearch or AssistantRetrieval.
  t.query_text,                                                                 -- What was searched for.
  t.sought_procedure_version,                                                   -- Version the searcher was working with.
  t.result_count,                                                               -- Results returned.
  t.opened_segment,                                                             -- Segment opened.
  t.opened_projection,                                                          -- Document or diagram opened.
  t.was_abandoned,                                                              -- TRUE when the searcher gave up.
  t.seconds_before_abandoning,                                                  -- Seconds before giving up.
  t.dwell_seconds,                                                              -- Time spent with what was found.
  t.linked_knowledge_gap,                                                       -- Knowledge gap the failed search was linked to.
  t.linked_usability_barrier,                                                   -- Usability barrier the failed search was linked to.
  calc_knowledge_search_events_found_nothing_useful(t.knowledge_search_event_id) AS found_nothing_useful,-- TRUE when a search returned nothing or nothing was opened.
  calc_knowledge_search_events_gave_up_after_seeing_results(t.knowledge_search_event_id) AS gave_up_after_seeing_results,-- TRUE when the searcher abandoned the query after results came back.
  calc_knowledge_search_events_is_unlinked_failed_search(t.knowledge_search_event_id) AS is_unlinked_failed_search,-- TRUE when a search that found nothing useful is linked to no knowledge gap and no usability barrier.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_search_events t;

-- ----------------------------------------------------------------------------
-- vw_ai_adoption_initiatives: AI initiatives: the agent, the process and procedure it works on, the automation level, and what came of it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_ai_adoption_initiatives: AI initiatives: the agent, the process and procedure it works on, the automation level, and what came of it.
-- SELF-REFERENTIAL SETTLE: AiAdoptionInitiatives has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: reviewed_output_count. Drivers: preceding_initiative.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_adoption_initiatives CASCADE;
CREATE VIEW vw_ai_adoption_initiatives WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.ai_adoption_initiative_id, jsonb_build_object(
      'reviewed_output_count', (SELECT COUNT(*) FROM assistant_answers WHERE reviewed_for_initiative = (SELECT NULLIF(t.ai_adoption_initiative_id::text,'')))
    ))
    FROM ai_adoption_initiatives t WHERE NULLIF(t.preceding_initiative,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.ai_adoption_initiative_id, jsonb_build_object(
      'reviewed_output_count', (SELECT COUNT(*) FROM assistant_answers WHERE reviewed_for_initiative = (SELECT NULLIF(t.ai_adoption_initiative_id::text,'')))
    ))
    FROM ai_adoption_initiatives t
    WHERE NOT (a.settled ? t.ai_adoption_initiative_id) AND NOT (NULLIF(t.preceding_initiative,'') IS NULL) AND (NULLIF(t.preceding_initiative,'') IS NULL OR a.settled ? t.preceding_initiative)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM ai_adoption_initiatives t
    WHERE NOT (a.settled ? t.ai_adoption_initiative_id) AND NOT (NULLIF(t.preceding_initiative,'') IS NULL) AND (NULLIF(t.preceding_initiative,'') IS NULL OR a.settled ? t.preceding_initiative))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.ai_adoption_initiative_id,                                                  -- Stored identifier.
  calc_ai_adoption_initiatives_name(t.ai_adoption_initiative_id) AS name,       -- Display name.
  t.label,                                                                      -- Initiative.
  t.organization,                                                               -- Sponsoring organization.
  t.agent,                                                                      -- AI agent.
  t.target_procedure,                                                           -- Procedure the AI works on.
  t.target_version,                                                             -- Version the AI works from.
  t.approach,                                                                   -- GroundedAgent, Assistant or PromptOnly.
  t.automation_level,                                                           -- Assist, Partial or Full.
  t.is_agentic,                                                                 -- TRUE when the AI takes actions in the workflow, not just answers.
  t.task_is_multi_step,                                                         -- TRUE when the AI's task follows ordered steps.
  t.depends_on_organizational_knowledge,                                        -- TRUE when the task depends on this organization's own knowledge.
  t.preceding_initiative,                                                       -- The partial-automation stage this initiative follows.
  t.status,                                                                     -- Proposed, Pilot, InProduction or Retired.
  t.outcome,                                                                    -- Succeeded, Failed, Pending or NoMeasurableResult.
  t.redesign_started_at,                                                        -- When the workflow redesign for AI began.
  t.connected_to_ai_at,                                                         -- When knowledge was connected to the AI.
  t.model_layer_budget,                                                         -- Spend on models.
  t.knowledge_layer_budget,                                                     -- Spend on eliciting, encoding and governing knowledge.
  t.measured_bottom_line_impact,                                                -- Measured bottom-line result.
  t.evaluation_context,                                                         -- Instant judged against.
  calc_ai_adoption_initiatives_as_of_instant(t.ai_adoption_initiative_id) AS as_of_instant,-- Evaluation instant.
  calc_ai_adoption_initiatives_target_has_no_explicit_steps(t.ai_adoption_initiative_id) AS target_has_no_explicit_steps,-- Whether the procedure exists only as title and documents.
  calc_ai_adoption_initiatives_target_version_issued_at(t.ai_adoption_initiative_id) AS target_version_issued_at,-- When the target version was issued.
  calc_ai_adoption_initiatives_target_version_under_specified(t.ai_adoption_initiative_id) AS target_version_under_specified,-- Whether the version lacks conditions or exception handling.
  calc_ai_adoption_initiatives_target_version_notation_only(t.ai_adoption_initiative_id) AS target_version_notation_only,-- Whether the version's steps carry no ontology type.
  calc_ai_adoption_initiatives_target_elicitation_evidence_count(t.ai_adoption_initiative_id) AS target_elicitation_evidence_count,-- Elicitation evidence behind the version.
  (SELECT settled #>> ARRAY[t.ai_adoption_initiative_id::text, 'reviewed_output_count'] FROM settled)::integer AS reviewed_output_count,-- AI outputs experts reviewed during this initiative.
  (SELECT settled #>> ARRAY[NULLIF(t.preceding_initiative,''), 'reviewed_output_count'] FROM settled)::integer AS preceding_reviewed_output_count,-- Expert-reviewed outputs of the preceding stage.
  calc_ai_adoption_initiatives_last_outcome_measured_at(t.ai_adoption_initiative_id) AS last_outcome_measured_at,-- When an outcome was last measured.
  calc_ai_adoption_initiatives_days_since_outcome_measured(t.ai_adoption_initiative_id) AS days_since_outcome_measured,-- Days since the last outcome measurement.
  calc_ai_adoption_initiatives_ai_insight_count(t.ai_adoption_initiative_id) AS ai_insight_count,-- Insights the initiative folded back as proposals.
  calc_ai_adoption_initiatives_hands_tacit_procedure_to_agent(t.ai_adoption_initiative_id) AS hands_tacit_procedure_to_agent,-- TRUE when an agent is assigned a procedure that exists only as tacit knowledge and documents.
  calc_ai_adoption_initiatives_agent_on_under_specified_procedure(t.ai_adoption_initiative_id) AS agent_on_under_specified_procedure,-- TRUE when an agent runs a version that does not specify conditions or exception handling.
  calc_ai_adoption_initiatives_agent_on_notation_only_procedure(t.ai_adoption_initiative_id) AS agent_on_notation_only_procedure,-- TRUE when an agent runs a version whose steps carry no ontology type.
  calc_ai_adoption_initiatives_calls_for_process_knowledge_framew(t.ai_adoption_initiative_id) AS calls_for_process_knowledge_framework,-- TRUE when the AI task follows ordered steps and depends on organizational knowledge.
  calc_ai_adoption_initiatives_redesigned_before_documented(t.ai_adoption_initiative_id) AS redesigned_before_documented,-- TRUE when a workflow redesign for AI began before the workflow was documented as a version.
  calc_ai_adoption_initiatives_breaks_elicit_encode_connect_order(t.ai_adoption_initiative_id) AS breaks_elicit_encode_connect_order,-- TRUE when knowledge was connected to AI with no elicitation behind it, or before it was encoded.
  calc_ai_adoption_initiatives_went_full_without_reviewed_partial(t.ai_adoption_initiative_id) AS went_full_without_reviewed_partial_stage,-- TRUE for full automation with no preceding partial stage whose output experts reviewed.
  calc_ai_adoption_initiatives_underinvests_knowledge_layer(t.ai_adoption_initiative_id) AS underinvests_knowledge_layer,-- TRUE when the knowledge layer gets less investment than the model layer.
  calc_ai_adoption_initiatives_not_anchored_in_process_knowledge(t.ai_adoption_initiative_id) AS not_anchored_in_process_knowledge,-- TRUE for an AI initiative past proposal that is anchored to no modeled procedure.
  calc_ai_adoption_initiatives_agentic_without_knowledge_capture(t.ai_adoption_initiative_id) AS agentic_without_knowledge_capture,-- TRUE for an agentic system past proposal that has produced no procedural knowledge back.
  calc_ai_adoption_initiatives_is_ai_outcome_unmeasured(t.ai_adoption_initiative_id) AS is_ai_outcome_unmeasured,-- TRUE for a pilot or production AI never measured, or not measured in over 30 days.
  calc_ai_adoption_initiatives_adopted_without_bottom_line_result(t.ai_adoption_initiative_id) AS adopted_without_bottom_line_result,-- TRUE for AI in production with no measured bottom-line result.
  calc_ai_adoption_initiatives_failed_without_formalized_knowledg(t.ai_adoption_initiative_id) AS failed_without_formalized_knowledge,-- TRUE when prompting a model about work with no formalized steps -- no procedure, or one with no steps -- failed.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_adoption_initiatives t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_outcome_measurements: Operational outcomes measured for a team or AI initiative, alongside how well it can reach the process knowledge.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_outcome_measurements CASCADE;
CREATE VIEW vw_knowledge_outcome_measurements WITH (security_invoker = ON) AS
SELECT
  t.knowledge_outcome_measurement_id,                                           -- Stored identifier.
  calc_knowledge_outcome_measurements_name(t.knowledge_outcome_measurement_id) AS name,-- Display name.
  t.label,                                                                      -- Measurement.
  t.measured_group,                                                             -- Team measured.
  t.facility,                                                                   -- Where.
  t.procedure_version,                                                          -- Knowledge the outcome is linked to.
  t.ai_initiative,                                                              -- AI initiative measured.
  t.knowledge_scope,                                                            -- Procedural, or ProductQuality for knowledge about products rather than procedures.
  t.measured_at,                                                                -- When.
  t.knowledge_access_score,                                                     -- Access to process knowledge, 0 to 100.
  t.error_rate_percent,                                                         -- Error rate.
  t.minutes_per_run,                                                            -- Efficiency: minutes per run.
  t.satisfaction_score,                                                         -- Customer satisfaction, 1 to 5.
  t.efficiency_gain_percent,                                                    -- Measured efficiency gain.
  t.target_error_rate_percent,                                                  -- Tolerated error rate.
  t.informed_change_request,                                                    -- Change request the measurement fed.
  t.informed_investment_decision,                                               -- Investment decision the measurement fed.
  t.comparison_baseline,                                                        -- The lower-access team this is compared with.
  calc_knowledge_outcome_measurements_baseline_access_score(t.knowledge_outcome_measurement_id) AS baseline_access_score,-- Baseline access.
  calc_knowledge_outcome_measurements_baseline_error_rate(t.knowledge_outcome_measurement_id) AS baseline_error_rate,-- Baseline error rate.
  calc_knowledge_outcome_measurements_baseline_minutes_per_run(t.knowledge_outcome_measurement_id) AS baseline_minutes_per_run,-- Baseline minutes per run.
  calc_knowledge_outcome_measurements_baseline_satisfaction(t.knowledge_outcome_measurement_id) AS baseline_satisfaction,-- Baseline satisfaction.
  calc_knowledge_outcome_measurements_higher_access_fewer_errors(t.knowledge_outcome_measurement_id) AS higher_access_fewer_errors,-- TRUE when this team has better access to process knowledge than its baseline and fewer errors.
  calc_knowledge_outcome_measurements_higher_access_more_efficien(t.knowledge_outcome_measurement_id) AS higher_access_more_efficient,-- TRUE when this team has better access than its baseline and takes fewer minutes per run.
  calc_knowledge_outcome_measurements_higher_access_more_satisfie(t.knowledge_outcome_measurement_id) AS higher_access_more_satisfied,-- TRUE when this team has better access than its baseline and higher satisfaction.
  calc_knowledge_outcome_measurements_is_unacted_adverse_outcome(t.knowledge_outcome_measurement_id) AS is_unacted_adverse_outcome,-- TRUE when an outcome worse than tolerated fed no change request and no investment decision.
  calc_knowledge_outcome_measurements_is_gain_outside_procedural_(t.knowledge_outcome_measurement_id) AS is_gain_outside_procedural_scope,-- TRUE for an efficiency gain measured on knowledge that is not about procedures.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_outcome_measurements t;

-- ----------------------------------------------------------------------------
-- vw_ai_insight_proposals: Insight an AI produced about a process, and whether it was validated and folded back into the knowledge base.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_insight_proposals CASCADE;
CREATE VIEW vw_ai_insight_proposals WITH (security_invoker = ON) AS
SELECT
  t.ai_insight_proposal_id,                                                     -- Stored identifier.
  calc_ai_insight_proposals_name(t.ai_insight_proposal_id) AS name,             -- Display name.
  t.proposing_agent,                                                            -- AI agent.
  t.source_initiative,                                                          -- Initiative that produced it.
  t.target_procedure_version,                                                   -- Version it concerns; blank for a wholly new model element.
  t.insight_kind,                                                               -- DeviationPattern, ProposedStep or ModelExtension.
  t.statement,                                                                  -- The insight.
  t.proposed_at,                                                                -- When.
  t.validated_by_agent,                                                         -- Who validated it.
  t.validation_verdict,                                                         -- Valid, Invalid, or blank while pending.
  t.folded_into_change_request,                                                 -- Change request that carries it into the model.
  calc_ai_insight_proposals_target_creator_kind(t.ai_insight_proposal_id) AS target_creator_kind,-- Kind of agent that created the target version.
  calc_ai_insight_proposals_is_unvalidated_or_stranded_insight(t.ai_insight_proposal_id) AS is_unvalidated_or_stranded_insight,-- TRUE when an AI insight was folded in without validation, or validated and never folded back.
  calc_ai_insight_proposals_grew_model_without_human_seed(t.ai_insight_proposal_id) AS grew_model_without_human_seed,-- TRUE when an AI proposed extending the model where no human-authored seed version exists.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_insight_proposals t;

-- ----------------------------------------------------------------------------
-- vw_assistant_benchmarks: Recorded accuracy of an AI assistant on a task family with and without graph grounding.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assistant_benchmarks CASCADE;
CREATE VIEW vw_assistant_benchmarks WITH (security_invoker = ON) AS
SELECT
  t.assistant_benchmark_id,                                                     -- Stored identifier.
  calc_assistant_benchmarks_name(t.assistant_benchmark_id) AS name,             -- Display name.
  t.label,                                                                      -- Benchmark.
  t.task_family,                                                                -- Spatial, Geospatial or Procedural.
  t.agent,                                                                      -- Assistant.
  t.grounding_snapshot,                                                         -- Graph used by the grounded arm.
  t.generates_database_queries,                                                 -- TRUE when the grounded arm writes structured queries against the graph.
  t.ungrounded_accuracy_percent,                                                -- Accuracy without the graph.
  t.graph_grounded_accuracy_percent,                                            -- Accuracy with the graph.
  t.ran_at,                                                                     -- When.
  calc_assistant_benchmarks_accuracy_lift_points(t.assistant_benchmark_id) AS accuracy_lift_points,-- Accuracy points gained by grounding.
  calc_assistant_benchmarks_shows_spatial_lift_from_graph_queries(t.assistant_benchmark_id) AS shows_spatial_lift_from_graph_queries,-- TRUE when a spatial task gained 20 or more points once the assistant queried the graph.
  calc_assistant_benchmarks_shows_geospatial_retrieval_lift(t.assistant_benchmark_id) AS shows_geospatial_retrieval_lift,-- TRUE when geospatial retrieval gained 20 or more points once linked to the graph.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM assistant_benchmarks t;

-- ----------------------------------------------------------------------------
-- vw_governed_models: Everything under governance: this rulebook as an ontology, each procedure family, and each governed vocabulary.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_governed_models CASCADE;
CREATE VIEW vw_governed_models WITH (security_invoker = ON) AS
SELECT
  t.governed_model_id,                                                          -- Stored identifier.
  calc_governed_models_name(t.governed_model_id) AS name,                       -- Display name.
  t.label,                                                                      -- What is governed.
  t.model_kind,                                                                 -- Ontology, ProcedureFamily or Vocabulary.
  t.procedure,                                                                  -- For a procedure family, the procedure.
  t.domain_owning_organization,                                                 -- The function that owns the domain being modeled.
  t.tooling_owner_role,                                                         -- Role that owns the knowledge-infrastructure tooling the model is built and published with.
  t.organization_headcount,                                                     -- Headcount of the organization governing the model.
  t.requirements_purpose,                                                       -- Requirements specification: the model's purpose.
  t.intended_users,                                                             -- Requirements specification: the model's intended users.
  t.registered_at,                                                              -- When the model came under management.
  t.first_control_adopted_at,                                                   -- When the first governance control other than ownership was adopted.
  t.current_charter,                                                            -- Key of the charter currently in force, blank when none.
  t.current_release,                                                            -- Key of the release the model is currently declared at.
  t.evaluation_context,                                                         -- Evaluation context.
  calc_governed_models_as_of_instant(t.governed_model_id) AS as_of_instant,     -- The modeled instant this row is judged against.
  calc_governed_models_days_since_registered(t.governed_model_id) AS days_since_registered,-- Days under management.
  calc_governed_models_charter_count(t.governed_model_id) AS charter_count,     -- Charters ever recorded.
  calc_governed_models_current_charter_count(t.governed_model_id) AS current_charter_count,-- Charters in force now.
  calc_governed_models_current_steward_role(t.governed_model_id) AS current_steward_role,-- Steward role of the charter in force.
  calc_governed_models_current_steward_agent(t.governed_model_id) AS current_steward_agent,-- Person holding the steward role now.
  calc_governed_models_current_authority_role(t.governed_model_id) AS current_authority_role,-- Authority role of the charter in force.
  calc_governed_models_current_authority_agent(t.governed_model_id) AS current_authority_agent,-- Person holding the authority role now.
  calc_governed_models_is_ownerless(t.governed_model_id) AS is_ownerless,       -- TRUE when no ownership charter is in force.
  calc_governed_models_is_ownerless_past_a_year(t.governed_model_id) AS is_ownerless_past_a_year,-- TRUE for a model that has been under management for more than a year with nobody owning it.
  calc_governed_models_governance_lapsed(t.governed_model_id) AS governance_lapsed,-- TRUE when a model was once chartered and its governance has since lapsed: management stopped rather than continuing as a standing capability.
  calc_governed_models_has_no_current_steward(t.governed_model_id) AS has_no_current_steward,-- TRUE when nobody holds the steward role for the model now.
  calc_governed_models_has_no_current_authority(t.governed_model_id) AS has_no_current_authority,-- TRUE when nobody holds authority over the model now.
  calc_governed_models_is_procedure_without_change_authority(t.governed_model_id) AS is_procedure_without_change_authority,-- TRUE for a procedure family where nobody currently holds authority to create, change or retire its definition.
  calc_governed_models_last_steward_activity_at(t.governed_model_id) AS last_steward_activity_at,-- Most recent recorded steward activity on the model.
  calc_governed_models_days_since_steward_activity(t.governed_model_id) AS days_since_steward_activity,-- Days since any steward activity, or since registration when there was none.
  calc_governed_models_is_unmaintained(t.governed_model_id) AS is_unmaintained, -- TRUE when no maintenance activity touched the model for more than ninety days.
  calc_governed_models_documents_behind_count(t.governed_model_id) AS documents_behind_count,-- Model documents describing an older release than the current one.
  calc_governed_models_is_not_kept_current(t.governed_model_id) AS is_not_kept_current,-- TRUE when the model is unmaintained or its documentation describes a release it is no longer at.
  calc_governed_models_open_practice_drift_count(t.governed_model_id) AS open_practice_drift_count,-- Open observations that the encoded knowledge no longer matches practice.
  calc_governed_models_has_open_practice_drift(t.governed_model_id) AS has_open_practice_drift,-- TRUE when knowledge that no longer matches practice has been detected and is still open.
  calc_governed_models_is_neglected_and_drifting(t.governed_model_id) AS is_neglected_and_drifting,-- TRUE when an unmaintained model carries open drift from practice: a representation degrading into something nobody can rely on.
  calc_governed_models_expert_found_drift_count(t.governed_model_id) AS expert_found_drift_count,-- Drift found only because a domain expert noticed a wrong answer.
  calc_governed_models_cq_review_count(t.governed_model_id) AS cq_review_count, -- Competency question set reviews held.
  calc_governed_models_last_cq_review_at(t.governed_model_id) AS last_cq_review_at,-- Most recent competency question set review.
  calc_governed_models_days_since_cq_review(t.governed_model_id) AS days_since_cq_review,-- Days since the question set was last reviewed, or since registration.
  calc_governed_models_cq_review_overdue(t.governed_model_id) AS cq_review_overdue,-- TRUE when the competency question set has gone more than a quarter (92 days) without review.
  calc_governed_models_degradation_hidden_until_wrong_answer(t.governed_model_id) AS degradation_hidden_until_wrong_answer,-- TRUE when drift surfaced only through an expert noticing a wrong answer on a model whose questions were never periodically reviewed.
  calc_governed_models_baseline_question_count(t.governed_model_id) AS baseline_question_count,-- Original competency questions recorded for the model.
  calc_governed_models_requirements_spec_incomplete(t.governed_model_id) AS requirements_spec_incomplete,-- TRUE when the requirements specification lacks a purpose, intended users or competency questions.
  calc_governed_models_collection_control_count(t.governed_model_id) AS collection_control_count,-- Governance controls over the collection stage.
  calc_governed_models_stewardship_control_count(t.governed_model_id) AS stewardship_control_count,-- Governance controls over the stewardship stage.
  calc_governed_models_retrieval_control_count(t.governed_model_id) AS retrieval_control_count,-- Governance controls over the retrieval stage.
  calc_governed_models_use_control_count(t.governed_model_id) AS use_control_count,-- Governance controls over the use stage.
  calc_governed_models_continuous_pipeline_stage_count(t.governed_model_id) AS continuous_pipeline_stage_count,-- Collection, organization and encoding stages that run continuously.
  calc_governed_models_lacks_lifecycle_stage_control(t.governed_model_id) AS lacks_lifecycle_stage_control,-- TRUE for a procedure family with no governance control over capture, stewardship, retrieval or use.
  calc_governed_models_pipeline_not_continuous(t.governed_model_id) AS pipeline_not_continuous,-- TRUE for a procedure family whose collection, organization and encoding do not all run continuously.
  calc_governed_models_procedure_has_no_explicit_steps(t.governed_model_id) AS procedure_has_no_explicit_steps,-- Whether the procedure exists only as a title and documents.
  calc_governed_models_is_unmanageable_undocumented_work(t.governed_model_id) AS is_unmanageable_undocumented_work,-- TRUE for a procedure family whose work was never documented into the knowledge system, so it cannot be managed.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  t.originating_use_case,                                                       -- The concrete use case the model was started from.
  calc_governed_models_is_without_originating_use_case(t.governed_model_id) AS is_without_originating_use_case,-- TRUE when a procedure family or ontology was modeled with no concrete use case behind it.
  calc_governed_models_pilot_count(t.governed_model_id) AS pilot_count,         -- Pilot implementations of the model.
  calc_governed_models_is_adopted_without_pilot(t.governed_model_id) AS is_adopted_without_pilot,-- TRUE when a procedure family or ontology was adopted without ever being refined through a pilot.
  calc_governed_models_requirements_expert_count(t.governed_model_id) AS requirements_expert_count,-- Experts in requirements specification.
  calc_governed_models_implementation_expert_count(t.governed_model_id) AS implementation_expert_count,-- Experts in implementation.
  calc_governed_models_publication_expert_count(t.governed_model_id) AS publication_expert_count,-- Experts in publication.
  calc_governed_models_maintenance_expert_count(t.governed_model_id) AS maintenance_expert_count,-- Experts in maintenance.
  calc_governed_models_experts_not_involved_throughout(t.governed_model_id) AS experts_not_involved_throughout,-- TRUE when some LOT activity of a procedure family or ontology ran with no domain expert taking part.
  calc_governed_models_real_data_mapping_run_count(t.governed_model_id) AS real_data_mapping_run_count,-- Runs that mapped the organization's real records into RDF.
  calc_governed_models_is_implemented_without_real_data(t.governed_model_id) AS is_implemented_without_real_data-- TRUE when a procedure family or ontology was never implemented by mapping the organization's real data into RDF.
FROM governed_models t;

-- ----------------------------------------------------------------------------
-- vw_model_charters: Ownership charters: who stewards a governed model and who holds authority over it, with written responsibilities, for a period.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_charters CASCADE;
CREATE VIEW vw_model_charters WITH (security_invoker = ON) AS
SELECT
  t.model_charter_id,                                                           -- Stored identifier.
  calc_model_charters_name(t.model_charter_id) AS name,                         -- Display name.
  t.governed_model,                                                             -- Model chartered.
  t.steward_role,                                                               -- Role responsible for the model's health.
  t.authority_role,                                                             -- Role empowered to approve changes.
  t.steward_responsibilities,                                                   -- The steward's written responsibilities.
  t.authority_approval_scope,                                                   -- What the authority approves, stated.
  t.charter_template,                                                           -- Corporate charter template this charter was drawn from, if any.
  t.local_adaptation,                                                           -- How this organization fitted the template to its own procedures, systems and constraints.
  t.valid_from,                                                                 -- Charter start.
  t.valid_to,                                                                   -- Charter end.
  t.supersedes_charter,                                                         -- Charter this one replaced.
  t.evaluation_context,                                                         -- Evaluation context.
  calc_model_charters_as_of_instant(t.model_charter_id) AS as_of_instant,       -- The modeled instant this row is judged against.
  calc_model_charters_is_current(t.model_charter_id) AS is_current,             -- TRUE when the charter is in force at the modeled instant.
  calc_model_charters_steward_agent(t.model_charter_id) AS steward_agent,       -- Who holds the steward role.
  calc_model_charters_authority_agent(t.model_charter_id) AS authority_agent,   -- Who holds the authority role.
  calc_model_charters_authority_organization(t.model_charter_id) AS authority_organization,-- Organization the authority role belongs to.
  calc_model_charters_model_kind(t.model_charter_id) AS model_kind,             -- Kind of model chartered.
  calc_model_charters_model_domain_owner(t.model_charter_id) AS model_domain_owner,-- Function owning the modeled domain.
  calc_model_charters_model_headcount(t.model_charter_id) AS model_headcount,   -- Headcount of the governing organization.
  calc_model_charters_model_tooling_owner_role(t.model_charter_id) AS model_tooling_owner_role,-- Role owning the model's tooling.
  calc_model_charters_model_first_control_adopted_at(t.model_charter_id) AS model_first_control_adopted_at,-- When the model's first non-ownership control was adopted.
  calc_model_charters_is_steward_unwritten(t.model_charter_id) AS is_steward_unwritten,-- TRUE when no steward is named or the steward has no written responsibilities.
  calc_model_charters_is_authority_scope_unstated(t.model_charter_id) AS is_authority_scope_unstated,-- TRUE when no authority is named or nothing states what it approves.
  calc_model_charters_conflates_steward_and_authority(t.model_charter_id) AS conflates_steward_and_authority,-- TRUE when one role is chartered as both steward and authority, so the two responsibilities are never defined apart.
  calc_model_charters_is_sanctioned_dual_holding(t.model_charter_id) AS is_sanctioned_dual_holding,-- TRUE when one person holds two distinct steward and authority roles in an organization of fifty or fewer, which needs no committee.
  calc_model_charters_is_authority_outside_domain_owner(t.model_charter_id) AS is_authority_outside_domain_owner,-- TRUE when authority over the model rests with a function other than the one that owns the domain.
  calc_model_charters_controls_precede_ownership(t.model_charter_id) AS controls_precede_ownership,-- TRUE when governance controls were adopted before the model's first owner was named.
  calc_model_charters_steward_activity_count(t.model_charter_id) AS steward_activity_count,-- Steward activities recorded under the charter.
  calc_model_charters_last_drift_watch_at(t.model_charter_id) AS last_drift_watch_at,-- Most recent drift watch under the charter.
  calc_model_charters_days_since_drift_watch(t.model_charter_id) AS days_since_drift_watch,-- Days since the steward last watched for drift, or since the charter began.
  calc_model_charters_is_drift_watch_lapsed(t.model_charter_id) AS is_drift_watch_lapsed,-- TRUE when the steward of a charter in force has not watched for drift in more than ninety days.
  calc_model_charters_procedure_decision_count(t.model_charter_id) AS procedure_decision_count,-- Procedure change requests the authority role has decided.
  calc_model_charters_model_review_count(t.model_charter_id) AS model_review_count,-- Model change requests that received authority review.
  calc_model_charters_is_named_but_unexercised(t.model_charter_id) AS is_named_but_unexercised,-- TRUE when a charter in force names a steward who has done nothing or an authority that has decided nothing.
  calc_model_charters_steward_is_outside_tooling(t.model_charter_id) AS steward_is_outside_tooling,-- TRUE when an ontology's steward is not the role that owns the tooling it is built and published with.
  calc_model_charters_adopted_template_without_adaptation(t.model_charter_id) AS adopted_template_without_adaptation,-- TRUE when a charter copied a corporate template without fitting it to the organization's own procedures and constraints.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_charters t;

-- ----------------------------------------------------------------------------
-- vw_steward_activities: Recorded steward duties: drift watches, dependency tracking, documentation and validation-suite upkeep.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_steward_activities CASCADE;
CREATE VIEW vw_steward_activities WITH (security_invoker = ON) AS
SELECT
  t.steward_activity_id,                                                        -- Stored identifier.
  calc_steward_activities_name(t.steward_activity_id) AS name,                  -- Display name.
  t.model_charter,                                                              -- Charter the duty was performed under.
  t.duty_kind,                                                                  -- DriftWatch, DependencyTracking, UserQuestion, DocumentationUpdate or ValidationSuiteUpdate.
  t.performed_at,                                                               -- When.
  t.performed_by_agent,                                                         -- Who.
  t.subject,                                                                    -- What was looked at or changed.
  t.release,                                                                    -- Release the activity kept in step, when there is one.
  calc_steward_activities_activity_model(t.steward_activity_id) AS activity_model,-- Model the charter governs.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM steward_activities t;

-- ----------------------------------------------------------------------------
-- vw_model_change_requests: Requests to change a governed model, each begun from a stated need and tied to the competency question that motivates it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_change_requests CASCADE;
CREATE VIEW vw_model_change_requests WITH (security_invoker = ON) AS
SELECT
  t.model_change_request_id,                                                    -- Stored identifier.
  calc_model_change_requests_name(t.model_change_request_id) AS name,           -- Display name.
  t.governed_model,                                                             -- Model to change.
  t.title,                                                                      -- Change.
  t.stated_need,                                                                -- The need the request starts from.
  t.requested_by_agent,                                                         -- Requester.
  t.requested_at,                                                               -- When requested.
  t.motivating_question,                                                        -- Competency question that motivates the change.
  t.motivation_kind,                                                            -- ExistingQuestionNowFails or NewQuestionNeeded.
  t.change_layer,                                                               -- Schema, Instance, Vocabulary or Documentation.
  t.change_operation,                                                           -- AddClass, AddProperty, RenameClass, RemoveClass, ChangeDomainRange, AddDisjointness, AddVocabularyTerm, AddInstances, ReassignAgent, MoveStepToHuman, CreateDefinition, RetireDefinition.
  t.classification,                                                             -- DataOperation or ModelingChange.
  t.route,                                                                      -- DataOperations or Governance: the process the request actually went through.
  t.declared_scale,                                                             -- Patch, Minor or Major as the proposer declared it.
  t.status,                                                                     -- Submitted, ReturnedForClarification, UnderImpactAssessment, Approved, Rejected or Deployed.
  t.impact_assessment,                                                          -- Impact assessment summary.
  t.coverage_checked_at,                                                        -- When the vocabulary layer and domain coverage model were checked against the change.
  t.authority_reviewed_at,                                                      -- When the authority reviewed the change.
  t.approved_by_agent,                                                          -- Who approved it.
  t.decided_at,                                                                 -- When decided.
  t.implementation_placement,                                                   -- How and where the change is made in the model.
  t.placement_decided_by_agent,                                                 -- Who decided how and where.
  t.target_release,                                                             -- Release the change ships in.
  t.compliance_impact,                                                          -- Compliance consequences recorded for moving work between AI and human execution.
  t.effective_at,                                                               -- When a reassignment took effect.
  calc_model_change_requests_steward_agent(t.model_change_request_id) AS steward_agent,-- Steward of the model now.
  calc_model_change_requests_authority_agent(t.model_change_request_id) AS authority_agent,-- Authority over the model now.
  calc_model_change_requests_rule_key(t.model_change_request_id) AS rule_key,   -- Key of the change-authority rule for this model and layer.
  calc_model_change_requests_required_route(t.model_change_request_id) AS required_route,-- Process the rule requires for this layer.
  calc_model_change_requests_is_accepted(t.model_change_request_id) AS is_accepted,-- TRUE once approved or deployed.
  calc_model_change_requests_is_modeling_change(t.model_change_request_id) AS is_modeling_change,-- TRUE for a modeling change rather than a data operation.
  calc_model_change_requests_is_schema_change(t.model_change_request_id) AS is_schema_change,-- TRUE for a change to the schema layer.
  calc_model_change_requests_has_authority_review(t.model_change_request_id) AS has_authority_review,-- TRUE when the authority reviewed the change.
  calc_model_change_requests_requires_authority_review(t.model_change_request_id) AS requires_authority_review,-- TRUE when the change alters or retires existing elements or vocabularies, adds disjointness, or is major.
  calc_model_change_requests_is_minor_scope(t.model_change_request_id) AS is_minor_scope,-- TRUE for a change the steward may approve and deploy alone.
  calc_model_change_requests_steward_own_change_unreviewed(t.model_change_request_id) AS steward_own_change_unreviewed,-- TRUE when the steward raised a change beyond minor scope and the authority never reviewed it.
  calc_model_change_requests_steward_approval_out_of_bounds(t.model_change_request_id) AS steward_approval_out_of_bounds,-- TRUE when a steward who is not also the authority approved a change beyond the minor changes a steward is authorized to approve.
  calc_model_change_requests_authority_review_skipped(t.model_change_request_id) AS authority_review_skipped,-- TRUE when a change that alters existing elements or vocabularies, or adds disjointness, was accepted without authority review.
  calc_model_change_requests_placement_not_decided_by_authority(t.model_change_request_id) AS placement_not_decided_by_authority,-- TRUE when someone other than the authority decided how and where a change is made.
  calc_model_change_requests_is_misrouted(t.model_change_request_id) AS is_misrouted,-- TRUE when a change went through a different process than the rule for its layer requires.
  calc_model_change_requests_lacks_motivating_question(t.model_change_request_id) AS lacks_motivating_question,-- TRUE when the request names no competency question.
  calc_model_change_requests_unmotivated_and_not_returned(t.model_change_request_id) AS unmotivated_and_not_returned,-- TRUE when a request with no competency question went forward instead of being returned for clarification.
  calc_model_change_requests_motivated_by_failing_question(t.model_change_request_id) AS motivated_by_failing_question,-- TRUE when the change exists because a question the model used to answer now fails.
  calc_model_change_requests_is_accepted_without_named_approver(t.model_change_request_id) AS is_accepted_without_named_approver,-- TRUE when an accepted change names nobody as approver.
  calc_model_change_requests_deployed_without_target_release(t.model_change_request_id) AS deployed_without_target_release,-- TRUE when a deployed schema change names no release.
  calc_model_change_requests_is_misclassified_agent_swap(t.model_change_request_id) AS is_misclassified_agent_swap,-- TRUE when swapping which agent fills a role was handled as a modeling change.
  calc_model_change_requests_ai_to_human_move_without_compliance_(t.model_change_request_id) AS ai_to_human_move_without_compliance_review,-- TRUE when a step moved from AI to human execution with no compliance consequences recorded.
  calc_model_change_requests_ai_to_human_move_unaudited(t.model_change_request_id) AS ai_to_human_move_unaudited,-- TRUE when a move from AI to human execution does not record when it took effect or why.
  calc_model_change_requests_is_ai_to_human_move(t.model_change_request_id) AS is_ai_to_human_move,-- TRUE for a recorded move of a step from AI to human execution with its effective date.
  calc_model_change_requests_lifecycle_change_by_unauthorized_age(t.model_change_request_id) AS lifecycle_change_by_unauthorized_agent,-- TRUE when a definition was created, modified or retired on the approval of someone who is neither steward nor authority.
  calc_model_change_requests_assessed_inconsistent_count(t.model_change_request_id) AS assessed_inconsistent_count,-- Instance data the impact assessment found the change would make inconsistent.
  calc_model_change_requests_post_deploy_inconsistent_count(t.model_change_request_id) AS post_deploy_inconsistent_count,-- Inconsistent instance data found only after deployment.
  calc_model_change_requests_assessed_inference_count(t.model_change_request_id) AS assessed_inference_count,-- Inferences the assessment found the change would alter.
  calc_model_change_requests_post_deploy_inference_count(t.model_change_request_id) AS post_deploy_inference_count,-- Altered inferences found only after deployment.
  calc_model_change_requests_assessed_query_result_count(t.model_change_request_id) AS assessed_query_result_count,-- Query results the assessment found the change would alter.
  calc_model_change_requests_post_deploy_query_result_count(t.model_change_request_id) AS post_deploy_query_result_count,-- Altered query results found only after deployment.
  calc_model_change_requests_assessed_coverage_gap_count(t.model_change_request_id) AS assessed_coverage_gap_count,-- Vocabulary or coverage-model gaps the assessment found the change would leave.
  calc_model_change_requests_would_make_instances_inconsistent(t.model_change_request_id) AS would_make_instances_inconsistent,-- TRUE when the assessment found existing instance data the change would make inconsistent.
  calc_model_change_requests_would_alter_inferences(t.model_change_request_id) AS would_alter_inferences,-- TRUE when the assessment found inferences the change would alter.
  calc_model_change_requests_would_alter_query_results(t.model_change_request_id) AS would_alter_query_results,-- TRUE when the assessment found query results the change would alter.
  calc_model_change_requests_would_leave_coverage_incomplete(t.model_change_request_id) AS would_leave_coverage_incomplete,-- TRUE when the assessment found the change would leave the vocabulary layer or coverage model incomplete.
  calc_model_change_requests_missed_inconsistent_instances(t.model_change_request_id) AS missed_inconsistent_instances,-- TRUE when instance data became inconsistent after deployment and the impact assessment had identified none.
  calc_model_change_requests_missed_altered_inferences(t.model_change_request_id) AS missed_altered_inferences,-- TRUE when inferences changed after deployment and the impact assessment had identified none.
  calc_model_change_requests_missed_altered_query_results(t.model_change_request_id) AS missed_altered_query_results,-- TRUE when query results changed after deployment and the impact assessment had identified none.
  calc_model_change_requests_leaves_coverage_unchecked(t.model_change_request_id) AS leaves_coverage_unchecked,-- TRUE when an accepted modeling change was never checked against the vocabulary layer and domain coverage model.
  calc_model_change_requests_domain_change_spread_wrong_inference(t.model_change_request_id) AS domain_change_spread_wrong_inferences,-- TRUE when a domain or range change produced altered inferences in deployment.
  calc_model_change_requests_intuitive_disjointness_broke_individ(t.model_change_request_id) AS intuitive_disjointness_broke_individuals,-- TRUE when a disjointness axiom added with no motivating question made individuals inconsistent.
  calc_model_change_requests_validation_run_count(t.model_change_request_id) AS validation_run_count,-- Validation suite runs with the change applied.
  calc_model_change_requests_acceptance_failure_total(t.model_change_request_id) AS acceptance_failure_total,-- Failures in acceptance runs of the full suite with the change applied.
  calc_model_change_requests_structural_pass_count(t.model_change_request_id) AS structural_pass_count,-- Runs whose automated structural consistency check passed.
  calc_model_change_requests_vocabulary_pass_count(t.model_change_request_id) AS vocabulary_pass_count,-- Runs whose automated approved-vocabulary check passed.
  calc_model_change_requests_accepted_without_test_run(t.model_change_request_id) AS accepted_without_test_run,-- TRUE when a modeling change was accepted without ever running the validation suite with it applied.
  calc_model_change_requests_accepted_with_failing_suite(t.model_change_request_id) AS accepted_with_failing_suite,-- TRUE when a change was accepted although the full suite failed with it applied.
  calc_model_change_requests_accepted_without_structural_check(t.model_change_request_id) AS accepted_without_structural_check,-- TRUE when a modeling change was accepted with no passing automated structural consistency check.
  calc_model_change_requests_accepted_without_vocabulary_check(t.model_change_request_id) AS accepted_without_vocabulary_check,-- TRUE when a modeling change was accepted with no passing automated check that it uses only approved vocabulary.
  calc_model_change_requests_integrity_check_count(t.model_change_request_id) AS integrity_check_count,-- Integrity review checks.
  calc_model_change_requests_human_integrity_check_count(t.model_change_request_id) AS human_integrity_check_count,-- Integrity checks a person performed.
  calc_model_change_requests_disjointness_check_count(t.model_change_request_id) AS disjointness_check_count,-- Disjointness integrity checks.
  calc_model_change_requests_domain_inference_check_count(t.model_change_request_id) AS domain_inference_check_count,-- DomainInference integrity checks.
  calc_model_change_requests_range_consistency_check_count(t.model_change_request_id) AS range_consistency_check_count,-- RangeConsistency integrity checks.
  calc_model_change_requests_integrity_decided_without_human(t.model_change_request_id) AS integrity_decided_without_human,-- TRUE when an accepted schema change's integrity was judged only by software.
  calc_model_change_requests_skipped_disjointness_review(t.model_change_request_id) AS skipped_disjointness_review,-- TRUE when an accepted schema change was never checked for disjointness violations.
  calc_model_change_requests_skipped_domain_inference_review(t.model_change_request_id) AS skipped_domain_inference_review,-- TRUE when an accepted schema change was never checked for unintended domain inferences.
  calc_model_change_requests_skipped_range_review(t.model_change_request_id) AS skipped_range_review,-- TRUE when an accepted schema change was never checked for property range inconsistencies.
  calc_model_change_requests_unresolved_objection_count(t.model_change_request_id) AS unresolved_objection_count,-- Stakeholder objections still unresolved.
  calc_model_change_requests_approved_over_unresolved_objection(t.model_change_request_id) AS approved_over_unresolved_objection,-- TRUE when a change was accepted while a stakeholder objection remained unresolved.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_change_requests t;

-- ----------------------------------------------------------------------------
-- vw_change_authority_rules: Which role may change which layer of a model, who approves, through which process, and the response when a change breaks the model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_authority_rules CASCADE;
CREATE VIEW vw_change_authority_rules WITH (security_invoker = ON) AS
SELECT
  t.change_authority_rule_id,                                                   -- Stored identifier.
  calc_change_authority_rules_name(t.change_authority_rule_id) AS name,         -- Display name.
  t.governed_model,                                                             -- Model.
  t.change_layer,                                                               -- Layer the rule governs.
  t.permitted_role,                                                             -- Role that may make the change.
  t.approval_role,                                                              -- Role that approves it.
  t.required_route,                                                             -- DataOperations or Governance.
  t.when_permitted,                                                             -- When such changes may be made.
  t.breakage_response,                                                          -- What happens when a change of this kind breaks the model.
  calc_change_authority_rules_misrouted_request_count(t.change_authority_rule_id) AS misrouted_request_count,-- Requests under this rule that went through the wrong process.
  calc_change_authority_rules_is_rule_bypassed(t.change_authority_rule_id) AS is_rule_bypassed,-- TRUE when at least one change went around this rule's required process.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM change_authority_rules t;

-- ----------------------------------------------------------------------------
-- vw_change_impact_findings: What an impact assessment (or, too late, deployment) found a change does to instance data, inferences, query results and coverage.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_impact_findings CASCADE;
CREATE VIEW vw_change_impact_findings WITH (security_invoker = ON) AS
SELECT
  t.change_impact_finding_id,                                                   -- Stored identifier.
  calc_change_impact_findings_name(t.change_impact_finding_id) AS name,         -- Display name.
  t.model_change_request,                                                       -- Change.
  t.finding_kind,                                                               -- InconsistentInstance, AlteredInference, AlteredQueryResult or CoverageGap.
  t.finding_stage,                                                              -- Assessment or PostDeployment.
  t.affected_table,                                                             -- Table affected.
  t.affected_row_key,                                                           -- Row or query affected.
  t.description,                                                                -- What was found.
  t.detected_by_query,                                                          -- The query that found it.
  t.query_language,                                                             -- SPARQL or SQL.
  t.found_by_agent,                                                             -- Who found it.
  t.found_at,                                                                   -- When.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM change_impact_findings t;

-- ----------------------------------------------------------------------------
-- vw_change_integrity_checks: Integrity review of a schema change: disjointness, domain inference and range consistency.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_integrity_checks CASCADE;
CREATE VIEW vw_change_integrity_checks WITH (security_invoker = ON) AS
SELECT
  t.change_integrity_check_id,                                                  -- Stored identifier.
  calc_change_integrity_checks_name(t.change_integrity_check_id) AS name,       -- Display name.
  t.model_change_request,                                                       -- Change.
  t.check_kind,                                                                 -- Disjointness, DomainInference or RangeConsistency.
  t.checked_by_agent,                                                           -- Who checked.
  calc_change_integrity_checks_checker_kind(t.change_integrity_check_id) AS checker_kind,-- Human or software checker.
  t.checked_at,                                                                 -- When.
  t.result,                                                                     -- Clean or ViolationFound.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM change_integrity_checks t;

-- ----------------------------------------------------------------------------
-- vw_change_objections: Stakeholder objections to a change and how they were resolved.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_objections CASCADE;
CREATE VIEW vw_change_objections WITH (security_invoker = ON) AS
SELECT
  t.change_objection_id,                                                        -- Stored identifier.
  calc_change_objections_name(t.change_objection_id) AS name,                   -- Display name.
  t.model_change_request,                                                       -- Change.
  t.raised_by_agent,                                                            -- Objector.
  t.raised_at,                                                                  -- When.
  t.objection,                                                                  -- The objection.
  t.resolved_at,                                                                -- When resolved.
  t.resolved_by_agent,                                                          -- Who resolved it.
  t.resolution,                                                                 -- How.
  calc_change_objections_is_unresolved(t.change_objection_id) AS is_unresolved, -- TRUE while the objection has no resolution.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM change_objections t;

-- ----------------------------------------------------------------------------
-- vw_change_validation_runs: The validation suite run with a proposed change applied.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_change_validation_runs CASCADE;
CREATE VIEW vw_change_validation_runs WITH (security_invoker = ON) AS
SELECT
  t.change_validation_run_id,                                                   -- Stored identifier.
  calc_change_validation_runs_name(t.change_validation_run_id) AS name,         -- Display name.
  t.model_change_request,                                                       -- Change applied in the run.
  t.test_suite,                                                                 -- Suite run.
  t.run_purpose,                                                                -- Exploratory or Acceptance.
  t.ran_at,                                                                     -- When.
  t.test_count,                                                                 -- Tests run.
  t.failure_count,                                                              -- Tests failed.
  t.failures_inspected_at,                                                      -- When someone inspected the failures.
  t.consistency_check_outcome,                                                  -- Consistent, Inconsistent, or blank when no logical consistency check ran.
  t.structural_check_outcome,                                                   -- Pass, Fail, or blank when not run.
  t.vocabulary_check_outcome,                                                   -- Pass, Fail, or blank when not run.
  calc_change_validation_runs_release(t.change_validation_run_id) AS release,   -- Release the change targets.
  calc_change_validation_runs_expected_chain_count(t.change_validation_run_id) AS expected_chain_count,-- Expected inference chains checked.
  calc_change_validation_runs_unproduced_chain_count(t.change_validation_run_id) AS unproduced_chain_count,-- Expected inference chains the model did not produce.
  calc_change_validation_runs_has_uninspected_failures(t.change_validation_run_id) AS has_uninspected_failures,-- TRUE when a run failed tests and nobody inspected the failures.
  calc_change_validation_runs_is_unconfirmed_consistency(t.change_validation_run_id) AS is_unconfirmed_consistency,-- TRUE when a run did not confirm the model free of logical inconsistency.
  calc_change_validation_runs_misses_expected_inference(t.change_validation_run_id) AS misses_expected_inference,-- TRUE when an expected inference chain was not produced in the run.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM change_validation_runs t;

-- ----------------------------------------------------------------------------
-- vw_expected_inference_checks: Expected logical consequences the validation suite checks: an inference chain and the value it must land.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_expected_inference_checks CASCADE;
CREATE VIEW vw_expected_inference_checks WITH (security_invoker = ON) AS
SELECT
  t.expected_inference_check_id,                                                -- Stored identifier.
  calc_expected_inference_checks_name(t.expected_inference_check_id) AS name,   -- Display name.
  t.change_validation_run,                                                      -- Run.
  t.chain_description,                                                          -- The inference chain.
  t.expected_field,                                                             -- Field the chain lands in.
  t.expected_value,                                                             -- Value expected.
  t.produced_value,                                                             -- Value produced.
  calc_expected_inference_checks_is_unproduced(t.expected_inference_check_id) AS is_unproduced,-- TRUE when the produced value is not the expected one.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM expected_inference_checks t;

-- ----------------------------------------------------------------------------
-- vw_model_consumers: Systems and agents that consume a governed model and must be updated when it changes.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_consumers CASCADE;
CREATE VIEW vw_model_consumers WITH (security_invoker = ON) AS
SELECT
  t.model_consumer_id,                                                          -- Stored identifier.
  calc_model_consumers_name(t.model_consumer_id) AS name,                       -- Display name.
  t.label,                                                                      -- Consumer.
  t.consumer_kind,                                                              -- Substrate, Application or AIAgent.
  t.depends_on_model,                                                           -- Model consumed.
  t.conformance_substrate,                                                      -- Substrate, when it is one.
  t.owner_role,                                                                 -- Role owning the consumer.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_consumers t;

-- ----------------------------------------------------------------------------
-- vw_consumer_revalidations: Per release and consumer: was the consumer told, and re-validated against the release.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_consumer_revalidations CASCADE;
CREATE VIEW vw_consumer_revalidations WITH (security_invoker = ON) AS
SELECT
  t.consumer_revalidation_id,                                                   -- Stored identifier.
  calc_consumer_revalidations_name(t.consumer_revalidation_id) AS name,         -- Display name.
  t.rulebook_release,                                                           -- Release.
  t.model_consumer,                                                             -- Consumer.
  t.was_notified,                                                               -- Whether the consumer's owner was told of the release.
  t.notified_at,                                                                -- When.
  t.passed_revalidation,                                                        -- Whether the consumer was updated and re-validated against the release.
  t.revalidated_at,                                                             -- When.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM consumer_revalidations t;

-- ----------------------------------------------------------------------------
-- vw_model_documents: The model's development materials: requirements, version notes, documentation and evaluation materials.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_documents CASCADE;
CREATE VIEW vw_model_documents WITH (security_invoker = ON) AS
SELECT
  t.model_document_id,                                                          -- Stored identifier.
  calc_model_documents_name(t.model_document_id) AS name,                       -- Display name.
  t.governed_model,                                                             -- Model documented.
  t.title,                                                                      -- Document.
  t.document_kind,                                                              -- Requirements, VersionNotes, Documentation or Evaluation.
  t.documented_release,                                                         -- Release the document describes.
  t.last_updated_at,                                                            -- When last updated.
  calc_model_documents_model_current_release(t.model_document_id) AS model_current_release,-- Release the model is at now.
  calc_model_documents_is_behind_current_release(t.model_document_id) AS is_behind_current_release,-- TRUE when the document still describes an older release than the one the model is at.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_documents t;

-- ----------------------------------------------------------------------------
-- vw_staleness_query_runs: Periodic runs of the staleness query over workflow last-modified dates, and whether the results reached the steward.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_staleness_query_runs CASCADE;
CREATE VIEW vw_staleness_query_runs WITH (security_invoker = ON) AS
SELECT
  t.staleness_query_run_id,                                                     -- Stored identifier.
  calc_staleness_query_runs_name(t.staleness_query_run_id) AS name,             -- Display name.
  t.governed_model,                                                             -- Model queried.
  t.ran_at,                                                                     -- When.
  t.ran_by_agent,                                                               -- Who or what ran it.
  calc_staleness_query_runs_runner_kind(t.staleness_query_run_id) AS runner_kind,-- Human or software runner.
  t.threshold_days,                                                             -- Days without modification that count as stale.
  t.query_text,                                                                 -- The query.
  t.stale_workflow_count,                                                       -- Workflows the run found stale.
  t.surfaced_to_steward_at,                                                     -- When the results were put in front of the steward.
  calc_staleness_query_runs_not_surfaced_to_steward(t.staleness_query_run_id) AS not_surfaced_to_steward,-- TRUE when a staleness run found stale workflows and the results never reached the steward.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM staleness_query_runs t;

-- ----------------------------------------------------------------------------
-- vw_external_dependency_revisions: Revisions and deprecations published by external standards the model reuses.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_external_dependency_revisions CASCADE;
CREATE VIEW vw_external_dependency_revisions WITH (security_invoker = ON) AS
SELECT
  t.external_dependency_revision_id,                                            -- Stored identifier.
  calc_external_dependency_revisions_name(t.external_dependency_revision_id) AS name,-- Display name.
  t.ontology_profile,                                                           -- Reused standard that changed.
  t.revision_label,                                                             -- Revision.
  t.revision_kind,                                                              -- TermRevision, Deprecation or Errata.
  t.published_at,                                                               -- When the standard published it.
  calc_external_dependency_revisions_affected_mapping_count(t.external_dependency_revision_id) AS affected_mapping_count,-- Mappings in this model that use the standard.
  t.tracked_at,                                                                 -- When the steward reviewed the revision against the model.
  t.tracked_by_agent,                                                           -- Who.
  t.evaluation_context,                                                         -- Evaluation context.
  calc_external_dependency_revisions_as_of_instant(t.external_dependency_revision_id) AS as_of_instant,-- The modeled instant this row is judged against.
  calc_external_dependency_revisions_days_since_published(t.external_dependency_revision_id) AS days_since_published,-- Days since the revision was published.
  calc_external_dependency_revisions_is_untracked_revision(t.external_dependency_revision_id) AS is_untracked_revision,-- TRUE when a revision to a standard the model maps to has gone untracked for more than thirty days.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM external_dependency_revisions t;

-- ----------------------------------------------------------------------------
-- vw_stakeholder_questions: Questions users and stakeholders bring to a model through its issue channel, whether the model answers them, and how the unanswerable ones were triaged.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_stakeholder_questions CASCADE;
CREATE VIEW vw_stakeholder_questions WITH (security_invoker = ON) AS
SELECT
  t.stakeholder_question_id,                                                    -- Stored identifier.
  calc_stakeholder_questions_name(t.stakeholder_question_id) AS name,           -- Display name.
  t.governed_model,                                                             -- Model asked.
  t.channel,                                                                    -- Where it was raised.
  t.use_case,                                                                   -- The adopter's use case.
  t.question_text,                                                              -- The question.
  t.asked_by_agent,                                                             -- Who asked.
  t.asked_at,                                                                   -- When.
  t.answering_role_question,                                                    -- The competency question whose witnesses answer it; blank when the model cannot.
  t.answered_by_agent,                                                          -- Who responded.
  t.answered_at,                                                                -- When responded.
  t.triage_outcome,                                                             -- MoreData, MinorSchemaExtension or StructuralChange for an unanswerable question.
  t.triaged_by_agent,                                                           -- Who triaged.
  calc_stakeholder_questions_triager_kind(t.stakeholder_question_id) AS triager_kind,-- Human or software triager.
  t.resulting_change_request,                                                   -- Change request the triage raised.
  calc_stakeholder_questions_result_route(t.stakeholder_question_id) AS result_route,-- Process the resulting change went through.
  t.evaluation_context,                                                         -- Evaluation context.
  calc_stakeholder_questions_as_of_instant(t.stakeholder_question_id) AS as_of_instant,-- The modeled instant this row is judged against.
  calc_stakeholder_questions_days_open(t.stakeholder_question_id) AS days_open, -- Days from asking to response, or to now when unanswered.
  calc_stakeholder_questions_is_unanswered_past_due(t.stakeholder_question_id) AS is_unanswered_past_due,-- TRUE when a user's question has gone more than fourteen days with no response.
  calc_stakeholder_questions_is_unanswerable_today(t.stakeholder_question_id) AS is_unanswerable_today,-- TRUE when no competency question of the model answers the stakeholder's question.
  calc_stakeholder_questions_is_untriaged_unanswerable(t.stakeholder_question_id) AS is_untriaged_unanswerable,-- TRUE for an unanswerable question nobody has triaged.
  calc_stakeholder_questions_needs_structural_change(t.stakeholder_question_id) AS needs_structural_change,-- TRUE when triage found the fix is a structural change to the model.
  calc_stakeholder_questions_unanswerable_without_scope_request(t.stakeholder_question_id) AS unanswerable_without_scope_request,-- TRUE when a question the model cannot answer never became a scope change request.
  calc_stakeholder_questions_is_misrouted_after_triage(t.stakeholder_question_id) AS is_misrouted_after_triage,-- TRUE when the change raised from triage went through a different process than the triage outcome calls for.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM stakeholder_questions t;

-- ----------------------------------------------------------------------------
-- vw_model_expansion_requests: Requests to model new workflows with an existing model, and the governance decision on whether they fit.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_expansion_requests CASCADE;
CREATE VIEW vw_model_expansion_requests WITH (security_invoker = ON) AS
SELECT
  t.model_expansion_request_id,                                                 -- Stored identifier.
  calc_model_expansion_requests_name(t.model_expansion_request_id) AS name,     -- Display name.
  t.governed_model,                                                             -- Model to expand.
  t.requesting_organization,                                                    -- Requesting function.
  t.requested_by_agent,                                                         -- Requester.
  t.workflow_description,                                                       -- Workflows to model.
  t.requested_at,                                                               -- When.
  t.fit_decision,                                                               -- FitsExistingSchema, NeedsNewTerms or NeedsModifiedTerms.
  t.decided_by_agent,                                                           -- Who decided.
  t.decided_at,                                                                 -- When.
  calc_model_expansion_requests_model_domain_owner(t.model_expansion_request_id) AS model_domain_owner,-- Function owning the model's domain.
  calc_model_expansion_requests_concept_count(t.model_expansion_request_id) AS concept_count,-- Concepts the workflows need.
  calc_model_expansion_requests_uncovered_concept_count(t.model_expansion_request_id) AS uncovered_concept_count,-- Concepts no existing table covers.
  calc_model_expansion_requests_is_cross_function_expansion(t.model_expansion_request_id) AS is_cross_function_expansion,-- TRUE when a function other than the domain owner wants its workflows in the model.
  calc_model_expansion_requests_requires_schema_extension(t.model_expansion_request_id) AS requires_schema_extension,-- TRUE when the workflows need concepts the schema has no table for.
  calc_model_expansion_requests_fit_decision_contradicts_concept_(t.model_expansion_request_id) AS fit_decision_contradicts_concept_fit,-- TRUE when governance decided new workflows fit the existing schema although some of their concepts have no home in it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_expansion_requests t;

-- ----------------------------------------------------------------------------
-- vw_expansion_concept_fits: Each concept a proposed workflow needs, and the existing table that covers it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_expansion_concept_fits CASCADE;
CREATE VIEW vw_expansion_concept_fits WITH (security_invoker = ON) AS
SELECT
  t.expansion_concept_fit_id,                                                   -- Stored identifier.
  calc_expansion_concept_fits_name(t.expansion_concept_fit_id) AS name,         -- Display name.
  t.model_expansion_request,                                                    -- Expansion.
  t.concept_label,                                                              -- Concept.
  t.covering_table,                                                             -- Existing table covering it; blank when none.
  calc_expansion_concept_fits_is_uncovered(t.expansion_concept_fit_id) AS is_uncovered,-- TRUE when no existing table covers the concept.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM expansion_concept_fits t;

-- ----------------------------------------------------------------------------
-- vw_competency_question_set_entries: The competency question set of each governed model, with the original baseline kept apart from later additions.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_competency_question_set_entries CASCADE;
CREATE VIEW vw_competency_question_set_entries WITH (security_invoker = ON) AS
SELECT
  t.competency_question_set_entry_id,                                           -- Stored identifier.
  calc_competency_question_set_entries_name(t.competency_question_set_entry_id) AS name,-- Display name.
  t.governed_model,                                                             -- Model.
  t.role_question,                                                              -- Question.
  t.is_original_baseline,                                                       -- TRUE for a question in the original set the model was built against.
  t.added_at,                                                                   -- When added.
  t.status,                                                                     -- Active, DeprecationCandidate or Deprecated.
  t.relevance_verdict,                                                          -- Relevant or NoLongerRelevant, from the latest review.
  t.used_for_scoping,                                                           -- Used to scope the model.
  t.used_as_acceptance_criterion,                                               -- Used as an acceptance criterion.
  t.used_as_test_driver,                                                        -- Drives validation tests.
  t.used_for_governance,                                                        -- Reviewed as a governance instrument.
  t.evaluation_context,                                                         -- Evaluation context.
  calc_competency_question_set_entries_as_of_instant(t.competency_question_set_entry_id) AS as_of_instant,-- The modeled instant this row is judged against.
  calc_competency_question_set_entries_days_since_added(t.competency_question_set_entry_id) AS days_since_added,-- Days in the set.
  calc_competency_question_set_entries_is_outgrown_baseline_quest(t.competency_question_set_entry_id) AS is_outgrown_baseline_question,-- TRUE for an original question that after more than a year of operation no longer fits what the organization needs.
  calc_competency_question_set_entries_irrelevant_but_still_activ(t.competency_question_set_entry_id) AS irrelevant_but_still_active,-- TRUE when review found a question no longer relevant and it was not made a deprecation candidate.
  calc_competency_question_set_entries_governance_use_count(t.competency_question_set_entry_id) AS governance_use_count,-- How many of the four roles (scoping, acceptance, test driver, governance) the question serves.
  calc_competency_question_set_entries_serves_every_governance_us(t.competency_question_set_entry_id) AS serves_every_governance_use,-- TRUE when one question served in turn as scoping tool, acceptance criterion, test driver and governance instrument.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM competency_question_set_entries t;

-- ----------------------------------------------------------------------------
-- vw_competency_question_runs: Each competency question run as a task against a release: answerable, and answered correctly.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_competency_question_runs CASCADE;
CREATE VIEW vw_competency_question_runs WITH (security_invoker = ON) AS
SELECT
  t.competency_question_run_id,                                                 -- Stored identifier.
  calc_competency_question_runs_name(t.competency_question_run_id) AS name,     -- Display name.
  t.cq_set_entry,                                                               -- Question.
  t.rulebook_release,                                                           -- Release.
  t.prior_run,                                                                  -- Run of the same question against the previous release.
  t.ran_at,                                                                     -- When.
  t.was_answerable,                                                             -- Whether the release could answer the question.
  t.answer_outcome,                                                             -- Correct or Wrong.
  t.defect_change_request,                                                      -- Change request raised to fix a wrong answer.
  calc_competency_question_runs_entry_is_original(t.competency_question_run_id) AS entry_is_original,-- Whether the question is in the original baseline.
  calc_competency_question_runs_prior_was_answerable(t.competency_question_run_id) AS prior_was_answerable,-- Whether the previous release answered it.
  calc_competency_question_runs_is_baseline_regression(t.competency_question_run_id) AS is_baseline_regression,-- TRUE when an original question the previous release answered can no longer be answered.
  calc_competency_question_runs_is_unfixed_wrong_answer(t.competency_question_run_id) AS is_unfixed_wrong_answer,-- TRUE when a question the model should answer came back wrong and no defect was raised to fix it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM competency_question_runs t;

-- ----------------------------------------------------------------------------
-- vw_competency_question_reviews: Periodic reviews of a model's competency question set.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_competency_question_reviews CASCADE;
CREATE VIEW vw_competency_question_reviews WITH (security_invoker = ON) AS
SELECT
  t.competency_question_review_id,                                              -- Stored identifier.
  calc_competency_question_reviews_name(t.competency_question_review_id) AS name,-- Display name.
  t.governed_model,                                                             -- Model.
  t.reviewed_at,                                                                -- When.
  t.reviewed_by_agent,                                                          -- Who.
  t.outcome,                                                                    -- What the review concluded.
  t.questions_added,                                                            -- New questions added.
  t.deprecation_candidates_raised,                                              -- Questions marked deprecation candidates.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM competency_question_reviews t;

-- ----------------------------------------------------------------------------
-- vw_quality_criteria: Stated quality criteria an ontology release is scored against.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_quality_criteria CASCADE;
CREATE VIEW vw_quality_criteria WITH (security_invoker = ON) AS
SELECT
  t.quality_criterion_id,                                                       -- Stored identifier.
  calc_quality_criteria_name(t.quality_criterion_id) AS name,                   -- Display name.
  t.label,                                                                      -- Criterion.
  t.definition,                                                                 -- What it means.
  t.is_stated,                                                                  -- Part of the stated criteria.
  calc_quality_criteria_assessment_count(t.quality_criterion_id) AS assessment_count,-- Scores recorded.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM quality_criteria t;

-- ----------------------------------------------------------------------------
-- vw_quality_assessments: A release scored against one quality criterion.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_quality_assessments CASCADE;
CREATE VIEW vw_quality_assessments WITH (security_invoker = ON) AS
SELECT
  t.quality_assessment_id,                                                      -- Stored identifier.
  calc_quality_assessments_name(t.quality_assessment_id) AS name,               -- Display name.
  t.rulebook_release,                                                           -- Release.
  t.quality_criterion,                                                          -- Criterion.
  t.score,                                                                      -- 1 to 5.
  t.method,                                                                     -- How scored.
  t.assessed_by_agent,                                                          -- Who.
  t.assessed_at,                                                                -- When.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM quality_assessments t;

-- ----------------------------------------------------------------------------
-- vw_term_definitions: Class definitions: what a class includes, excludes, and where it sits among neighboring terms, with who drafted and revised them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_term_definitions CASCADE;
CREATE VIEW vw_term_definitions WITH (security_invoker = ON) AS
SELECT
  t.term_definition_id,                                                         -- Stored identifier.
  calc_term_definitions_name(t.term_definition_id) AS name,                     -- Display name.
  t.rulebook_table,                                                             -- Class defined.
  t.includes,                                                                   -- What the class includes.
  t.excludes,                                                                   -- What it excludes.
  t.neighboring_terms,                                                          -- Where it sits among neighbors.
  t.drafted_by_agent,                                                           -- Drafter.
  calc_term_definitions_drafter_kind(t.term_definition_id) AS drafter_kind,     -- Human or AI drafter.
  t.drafted_at,                                                                 -- When drafted.
  t.revised_by_agent,                                                           -- Person who critically revised the draft.
  t.revised_at,                                                                 -- When revised.
  calc_term_definitions_ai_draft_adopted_unrevised(t.term_definition_id) AS ai_draft_adopted_unrevised,-- TRUE when an AI-drafted definition stands with no person having revised it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM term_definitions t;

-- ----------------------------------------------------------------------------
-- vw_model_proposals: Candidate contributions to a model (questions, labels, alignments, axioms, instance data) and the human review and commitment behind each.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_proposals CASCADE;
CREATE VIEW vw_model_proposals WITH (security_invoker = ON) AS
SELECT
  t.model_proposal_id,                                                          -- Stored identifier.
  calc_model_proposals_name(t.model_proposal_id) AS name,                       -- Display name.
  t.governed_model,                                                             -- Model.
  t.proposal_kind,                                                              -- CompetencyQuestion, Label, Definition, Alignment, Axiom, Disjointness, DomainRange or InstanceData.
  t.proposed_by_agent,                                                          -- Proposer.
  t.proposed_at,                                                                -- When.
  t.source_document,                                                            -- Document the candidate was drawn from.
  t.content,                                                                    -- The candidate.
  t.quality_check_outcome,                                                      -- Pass, Fail, or blank when never checked against quality standards.
  t.reviewed_by_agent,                                                          -- Expert reviewer.
  t.reviewed_at,                                                                -- When reviewed.
  t.review_outcome,                                                             -- Adopted, Revised or Rejected.
  t.committed_at,                                                               -- When it entered the model as authoritative.
  t.committed_by_agent,                                                         -- Who committed it.
  t.adopted_in_release,                                                         -- Schema release it was adopted in.
  t.adopted_in_data_version,                                                    -- Instance data version it was loaded in.
  calc_model_proposals_proposer_kind(t.model_proposal_id) AS proposer_kind,     -- Proposer kind.
  calc_model_proposals_reviewer_kind(t.model_proposal_id) AS reviewer_kind,     -- Reviewer kind.
  calc_model_proposals_committer_kind(t.model_proposal_id) AS committer_kind,   -- Committer kind.
  calc_model_proposals_model_steward_agent(t.model_proposal_id) AS model_steward_agent,-- Steward of the model now.
  calc_model_proposals_is_ai_candidate(t.model_proposal_id) AS is_ai_candidate, -- TRUE for a candidate an AI agent produced, as opposed to a human commitment.
  calc_model_proposals_is_only_proposed(t.model_proposal_id) AS is_only_proposed,-- TRUE for knowledge that is proposed but not yet approved into the model.
  calc_model_proposals_committed_without_expert_review(t.model_proposal_id) AS committed_without_expert_review,-- TRUE when a candidate became authoritative without review by a human expert.
  calc_model_proposals_entered_without_quality_check(t.model_proposal_id) AS entered_without_quality_check,-- TRUE when a candidate entered the model without passing the quality standards check.
  calc_model_proposals_approver_unknown(t.model_proposal_id) AS approver_unknown,-- TRUE when committed knowledge names no approver.
  calc_model_proposals_committed_outside_any_version(t.model_proposal_id) AS committed_outside_any_version,-- TRUE when committed knowledge cannot be tied to the release or data version it was approved in.
  calc_model_proposals_ai_question_adopted_unvetted(t.model_proposal_id) AS ai_question_adopted_unvetted,-- TRUE when an AI-proposed competency question was adopted without an engineer vetting it.
  calc_model_proposals_ai_alignment_decided_by_ai(t.model_proposal_id) AS ai_alignment_decided_by_ai,-- TRUE when an AI-suggested alignment to an external standard was committed by software rather than a person.
  calc_model_proposals_ai_axiom_without_human_review(t.model_proposal_id) AS ai_axiom_without_human_review,-- TRUE when an AI-proposed axiom, disjointness or domain/range commitment entered the model without human review.
  calc_model_proposals_adoption_not_answered_by_person(t.model_proposal_id) AS adoption_not_answered_by_person,-- TRUE when AI output was adopted by software, so no person answers for the adoption.
  calc_model_proposals_has_no_human_touchpoint(t.model_proposal_id) AS has_no_human_touchpoint,-- TRUE when a contribution was proposed, reviewed and committed with no person at any stage.
  calc_model_proposals_ai_instance_data_loaded_without_steward(t.model_proposal_id) AS ai_instance_data_loaded_without_steward,-- TRUE when AI-extracted instance data was loaded without the steward reviewing it.
  calc_model_proposals_awaits_engineer_vetting(t.model_proposal_id) AS awaits_engineer_vetting,-- TRUE for an AI-proposed competency question drawn from a document that no engineer has vetted yet.
  calc_model_proposals_is_pending_alignment_decision(t.model_proposal_id) AS is_pending_alignment_decision,-- TRUE for a suggested alignment waiting on a person's modeling decision.
  calc_model_proposals_awaits_steward_approval(t.model_proposal_id) AS awaits_steward_approval,-- TRUE for extracted instance assertions not yet reviewed or loaded.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_proposals t;

-- ----------------------------------------------------------------------------
-- vw_assignment_instant_checks: Point-in-time audit of which role assignment, and which agent version, held a step at a past instant.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assignment_instant_checks CASCADE;
CREATE VIEW vw_assignment_instant_checks WITH (security_invoker = ON) AS
SELECT
  t.assignment_instant_check_id,                                                -- Stored identifier.
  calc_assignment_instant_checks_name(t.assignment_instant_check_id) AS name,   -- Display name.
  t.audit_question,                                                             -- What the auditor asked.
  t.step,                                                                       -- Step.
  t.audit_instant,                                                              -- Past instant.
  t.role_assignment,                                                            -- Candidate assignment.
  calc_assignment_instant_checks_step_role(t.assignment_instant_check_id) AS step_role,-- Role accountable for the step.
  calc_assignment_instant_checks_assignment_role(t.assignment_instant_check_id) AS assignment_role,-- Role of the assignment.
  calc_assignment_instant_checks_assignment_valid_from(t.assignment_instant_check_id) AS assignment_valid_from,-- Assignment start.
  calc_assignment_instant_checks_assignment_valid_to(t.assignment_instant_check_id) AS assignment_valid_to,-- Assignment end.
  calc_assignment_instant_checks_assignment_agent(t.assignment_instant_check_id) AS assignment_agent,-- Agent assigned.
  calc_assignment_instant_checks_assignment_agent_version(t.assignment_instant_check_id) AS assignment_agent_version,-- Model version of that agent.
  calc_assignment_instant_checks_held_step_at_instant(t.assignment_instant_check_id) AS held_step_at_instant,-- TRUE when this assignment held the step's role at the audited instant.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM assignment_instant_checks t;

-- ----------------------------------------------------------------------------
-- vw_instance_data_versions: Versions of a model's instance data, kept separately from schema releases.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_instance_data_versions CASCADE;
CREATE VIEW vw_instance_data_versions WITH (security_invoker = ON) AS
SELECT
  t.instance_data_version_id,                                                   -- Stored identifier.
  calc_instance_data_versions_name(t.instance_data_version_id) AS name,         -- Display name.
  t.governed_model,                                                             -- Model.
  t.data_version_label,                                                         -- Data version.
  t.snapshot_at,                                                                -- When.
  t.conforms_to_release,                                                        -- Schema release the data conforms to.
  calc_instance_data_versions_logged_change_count(t.instance_data_version_id) AS logged_change_count,-- Logged instance changes in this version.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM instance_data_versions t;

-- ----------------------------------------------------------------------------
-- vw_domain_coverage_areas: The domain coverage model: areas a model must cover and the table that covers each.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_domain_coverage_areas CASCADE;
CREATE VIEW vw_domain_coverage_areas WITH (security_invoker = ON) AS
SELECT
  t.domain_coverage_area_id,                                                    -- Stored identifier.
  calc_domain_coverage_areas_name(t.domain_coverage_area_id) AS name,           -- Display name.
  t.governed_model,                                                             -- Model.
  t.area_label,                                                                 -- Area.
  t.required_concept,                                                           -- What must be representable.
  t.covering_table,                                                             -- Table covering it.
  calc_domain_coverage_areas_is_uncovered_area(t.domain_coverage_area_id) AS is_uncovered_area,-- TRUE when no table covers a required area.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM domain_coverage_areas t;

-- ----------------------------------------------------------------------------
-- vw_governance_stage_controls: The governance control over each stage of a procedure family's knowledge lifecycle.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_governance_stage_controls CASCADE;
CREATE VIEW vw_governance_stage_controls WITH (security_invoker = ON) AS
SELECT
  t.governance_stage_control_id,                                                -- Stored identifier.
  calc_governance_stage_controls_name(t.governance_stage_control_id) AS name,   -- Display name.
  t.governed_model,                                                             -- Model.
  t.stage,                                                                      -- Collection, Organization, Encoding, Stewardship, Retrieval or Use.
  t.control,                                                                    -- The control.
  t.is_continuous,                                                              -- Runs continuously rather than as a one-off or batch.
  calc_governance_stage_controls_is_continuous_pipeline_stage(t.governance_stage_control_id) AS is_continuous_pipeline_stage,-- TRUE for a collection, organization or encoding stage that runs continuously.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM governance_stage_controls t;

-- ----------------------------------------------------------------------------
-- vw_process_design_decisions: Design decisions behind a procedure's commitments, recorded alongside the procedure with their rationale.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_process_design_decisions CASCADE;
CREATE VIEW vw_process_design_decisions WITH (security_invoker = ON) AS
SELECT
  t.process_design_decision_id,                                                 -- Stored identifier.
  calc_process_design_decisions_name(t.process_design_decision_id) AS name,     -- Display name.
  t.procedure_version,                                                          -- Version.
  t.step,                                                                       -- Step the commitment is on.
  t.decision,                                                                   -- The commitment.
  t.rationale,                                                                  -- Why.
  t.decided_by_agent,                                                           -- Who decided.
  t.decided_at,                                                                 -- When decided.
  t.recorded_at,                                                                -- When written down.
  calc_process_design_decisions_is_commitment_without_rationale(t.process_design_decision_id) AS is_commitment_without_rationale,-- TRUE when a procedure commitment was recorded with no reason behind it.
  calc_process_design_decisions_days_before_recorded(t.process_design_decision_id) AS days_before_recorded,-- Days between deciding and writing the decision down.
  calc_process_design_decisions_is_recorded_after_the_fact(t.process_design_decision_id) AS is_recorded_after_the_fact,-- TRUE when a decision was written down more than thirty days after it was made, so its why was reconstructed from memory.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM process_design_decisions t;

-- ----------------------------------------------------------------------------
-- vw_model_change_log_entries: The change log: every schema and instance modification, its rationale, motivating question, terms affected, version and date.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_change_log_entries CASCADE;
CREATE VIEW vw_model_change_log_entries WITH (security_invoker = ON) AS
SELECT
  t.model_change_log_entry_id,                                                  -- Stored identifier.
  calc_model_change_log_entries_name(t.model_change_log_entry_id) AS name,      -- Display name.
  t.governed_model,                                                             -- Model.
  t.model_change_request,                                                       -- Change request behind the entry.
  t.release,                                                                    -- Schema release it shipped in.
  t.instance_data_version,                                                      -- Data version it shipped in.
  t.change_layer,                                                               -- Schema, Instance, Vocabulary or Documentation.
  t.change_operation,                                                           -- Operation.
  t.change_summary,                                                             -- The change.
  t.rationale,                                                                  -- Why.
  t.terms_affected,                                                             -- Terms affected.
  t.affected_table,                                                             -- Table affected.
  t.invalidates_instances,                                                      -- Whether existing instance assertions become invalid or inconsistent.
  t.logged_at,                                                                  -- When.
  t.changed_by_agent,                                                           -- Who.
  t.prior_state_commit,                                                         -- Version-control commit of the state before the change.
  t.reverts_entry,                                                              -- Entry this one rolls back.
  calc_model_change_log_entries_motivating_question(t.model_change_log_entry_id) AS motivating_question,-- Question motivating the change.
  calc_model_change_log_entries_release_version(t.model_change_log_entry_id) AS release_version,-- Version number shipped in.
  calc_model_change_log_entries_release_decision_undocumented(t.model_change_log_entry_id) AS release_decision_undocumented,-- Whether the release's versioning decision was left undocumented.
  calc_model_change_log_entries_alters_logical_model(t.model_change_log_entry_id) AS alters_logical_model,-- TRUE for a schema or vocabulary change, as opposed to documentation or instance data.
  calc_model_change_log_entries_is_class_removal_or_rename(t.model_change_log_entry_id) AS is_class_removal_or_rename,-- TRUE when a class is removed or renamed.
  calc_model_change_log_entries_is_invalidating_domain_range_chan(t.model_change_log_entry_id) AS is_invalidating_domain_range_change,-- TRUE for a domain or range change that invalidates existing assertions.
  calc_model_change_log_entries_is_inconsistent_disjointness(t.model_change_log_entry_id) AS is_inconsistent_disjointness,-- TRUE for a disjointness axiom that makes existing individuals inconsistent.
  calc_model_change_log_entries_is_backward_incompatible(t.model_change_log_entry_id) AS is_backward_incompatible,-- TRUE when the change breaks existing data or queries.
  calc_model_change_log_entries_is_additive_schema_change(t.model_change_log_entry_id) AS is_additive_schema_change,-- TRUE for a purely additive schema change.
  calc_model_change_log_entries_is_unexplained_modification(t.model_change_log_entry_id) AS is_unexplained_modification,-- TRUE when a schema or instance modification is logged with no rationale.
  calc_model_change_log_entries_rationale_without_question(t.model_change_log_entry_id) AS rationale_without_question,-- TRUE when a rationale was recorded but no competency question stands behind it.
  calc_model_change_log_entries_is_schema_change_without_incremen(t.model_change_log_entry_id) AS is_schema_change_without_increment,-- TRUE when a schema change shipped in no versioned release.
  calc_model_change_log_entries_is_instance_change_in_schema_rele(t.model_change_log_entry_id) AS is_instance_change_in_schema_release,-- TRUE when an instance data change was versioned as a schema release instead of a data version.
  calc_model_change_log_entries_schema_change_without_request(t.model_change_log_entry_id) AS schema_change_without_request,-- TRUE when a schema change was made outside the change process, with no change request.
  calc_model_change_log_entries_cannot_be_audited(t.model_change_log_entry_id) AS cannot_be_audited,-- TRUE when a change names nobody who made it or no version it belongs to.
  calc_model_change_log_entries_cannot_be_rolled_back(t.model_change_log_entry_id) AS cannot_be_rolled_back,-- TRUE when no prior-state commit is recorded, so the change cannot be rolled back.
  calc_model_change_log_entries_is_untraceable_breaking_change(t.model_change_log_entry_id) AS is_untraceable_breaking_change,-- TRUE when a breaking change cannot be traced to a documented versioning decision.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_change_log_entries t;

-- ----------------------------------------------------------------------------
-- vw_drift_observations: Observed drift: places where a model no longer matches the organization it describes, how each was detected, and what drove it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_drift_observations CASCADE;
CREATE VIEW vw_drift_observations WITH (security_invoker = ON) AS
SELECT
  t.drift_observation_id,                                                       -- Stored identifier.
  calc_drift_observations_name(t.drift_observation_id) AS name,                 -- Display name.
  t.governed_model,                                                             -- Model that drifted.
  t.procedure_version,                                                          -- Representation that no longer matches, when one.
  t.observed_at,                                                                -- When observed.
  t.observed_by_agent,                                                          -- Who observed it.
  t.detected_by,                                                                -- StewardReview, StalenessQuery, ValidationSuite or ExpertWrongAnswer.
  t.drift_kind,                                                                 -- PracticeMismatch, ScopeExpansion or DependencyChange.
  t.drift_cause,                                                                -- ShiftingRequirement, NewTechnology or CompetitivePressure.
  t.description,                                                                -- What no longer matches.
  t.since_release,                                                              -- Release the model was at when the drift began.
  t.resolved_at,                                                                -- When resolved.
  calc_drift_observations_release_passed_validation(t.drift_observation_id) AS release_passed_validation,-- Whether that release passed every acceptance validation.
  calc_drift_observations_release_issued_at(t.drift_observation_id) AS release_issued_at,-- When that release was issued.
  calc_drift_observations_is_open_practice_mismatch(t.drift_observation_id) AS is_open_practice_mismatch,-- TRUE for an unresolved observation that a representation no longer matches how the process runs.
  calc_drift_observations_went_undetected_by_passing_suite(t.drift_observation_id) AS went_undetected_by_passing_suite,-- TRUE when drift on a release that passed its validation was found by something other than the validation suite.
  calc_drift_observations_drift_follows_clean_release(t.drift_observation_id) AS drift_follows_clean_release,-- TRUE when a release that passed all its validation drifted afterwards anyway.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM drift_observations t;

-- ----------------------------------------------------------------------------
-- vw_sourcing_functions: Business functions an organization classifies as retained core or sends out for execution, with who executes them and who holds the knowledge of what is built and of how it is built.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_sourcing_functions CASCADE;
CREATE VIEW vw_sourcing_functions WITH (security_invoker = ON) AS
SELECT
  t.sourcing_function_id,                                                       -- Stored identifier.
  calc_sourcing_functions_name(t.sourcing_function_id) AS name,                 -- Display name.
  t.label,                                                                      -- The function.
  t.client_organization,                                                        -- The organization whose function this is.
  t.procedure,                                                                  -- The modeled procedure that carries the function, when there is one.
  t.sourcing_class,                                                             -- RetainedCore, or SentOutExecution for a function classified as execution to be sent out.
  t.work_nature,                                                                -- Transactional (routine) or ExpertiseHeavy (analytical, design or engineering judgment).
  t.is_strategically_vital,                                                     -- TRUE when the organization cannot deliver its strategy without the function.
  t.delivers_own_product,                                                       -- TRUE when the function is part of delivering the organization's own products.
  t.executing_organization,                                                     -- The organization that actually performs the work.
  t.specification_holder,                                                       -- The party that holds what is to be built or delivered.
  t.method_holder,                                                              -- The party that holds how it is built or performed.
  t.sourced_since,                                                              -- When the current execution arrangement began.
  t.sourcing_rationale,                                                         -- Why the function was placed where it is (CoreCompetencyFocus, CostReduction, Capability).
  calc_sourcing_functions_is_outsourced(t.sourcing_function_id) AS is_outsourced,-- TRUE when an organization other than the client performs the work.
  calc_sourcing_functions_is_business_process_outsourcing(t.sourcing_function_id) AS is_business_process_outsourcing,-- TRUE for routine transactional work performed by a provider.
  calc_sourcing_functions_is_knowledge_process_outsourcing(t.sourcing_function_id) AS is_knowledge_process_outsourcing,-- TRUE for expertise-heavy work performed by a provider, the kind that builds deep process knowledge.
  calc_sourcing_functions_is_vital_expertise_classed_non_core(t.sourcing_function_id) AS is_vital_expertise_classed_non_core,-- TRUE when strategically vital, expertise-heavy work is classified as execution to send out rather than retained core.
  calc_sourcing_functions_is_what_how_split(t.sourcing_function_id) AS is_what_how_split,-- TRUE when different parties hold what is to be built and how it is built.
  calc_sourcing_functions_is_method_knowledge_held_outside(t.sourcing_function_id) AS is_method_knowledge_held_outside,-- TRUE when the knowledge of how the work is really performed is held by a party other than the client.
  calc_sourcing_functions_claims_how_without_doing(t.sourcing_function_id) AS claims_how_without_doing,-- TRUE when the client declares it holds the method knowledge of a function a provider executes.
  calc_sourcing_functions_is_vital_expertise_process(t.sourcing_function_id) AS is_vital_expertise_process,-- TRUE for a strategically vital, expertise-heavy function.
  calc_sourcing_functions_is_outsourced_vital_expertise_process(t.sourcing_function_id) AS is_outsourced_vital_expertise_process,-- TRUE for a strategically vital, expertise-heavy function a provider performs.
  calc_sourcing_functions_audit_item_count(t.sourcing_function_id) AS audit_item_count,-- Audit items comparing held and needed knowledge for this function.
  calc_sourcing_functions_dependency_count(t.sourcing_function_id) AS dependency_count,-- Audit items that found knowledge the client relies on a provider for.
  calc_sourcing_functions_coverage_gap_count(t.sourcing_function_id) AS coverage_gap_count,-- Audit items that found knowledge nobody available to the client holds.
  calc_sourcing_functions_specification_audit_count(t.sourcing_function_id) AS specification_audit_count,-- Audit items about specification knowledge.
  calc_sourcing_functions_specification_shortfall_count(t.sourcing_function_id) AS specification_shortfall_count,-- Specification items where the client holds less than it needs.
  calc_sourcing_functions_method_shortfall_count(t.sourcing_function_id) AS method_shortfall_count,-- Method items where the client holds less than it needs.
  calc_sourcing_functions_provider_ip_documentation_count(t.sourcing_function_id) AS provider_ip_documentation_count,-- Engagements for this function whose documentation stays the provider's property.
  calc_sourcing_functions_designs_what_it_cannot_build(t.sourcing_function_id) AS designs_what_it_cannot_build,-- TRUE when a product-delivering function is performed by a provider that keeps the documentation, the client's audited specification knowledge is complete, and its method knowledge falls short.
  calc_sourcing_functions_is_unaudited_function(t.sourcing_function_id) AS is_unaudited_function,-- TRUE when an outsourced or strategically vital function has never been audited for held against needed knowledge.
  calc_sourcing_functions_capture_initiative_count(t.sourcing_function_id) AS capture_initiative_count,-- Deliberate knowledge capture initiatives for this function.
  calc_sourcing_functions_is_uncaptured_priority_process(t.sourcing_function_id) AS is_uncaptured_priority_process,-- TRUE for a vital, expertise-heavy function that is outsourced or has a coverage gap and has no deliberate capture initiative.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM sourcing_functions t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_audits: Audits of the procedural knowledge an organization holds against what it needs.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_audits CASCADE;
CREATE VIEW vw_knowledge_audits WITH (security_invoker = ON) AS
SELECT
  t.knowledge_audit_id,                                                         -- Stored identifier.
  calc_knowledge_audits_name(t.knowledge_audit_id) AS name,                     -- Display name.
  t.organization,                                                               -- Audited organization.
  t.title,                                                                      -- Audit title.
  t.conducted_at,                                                               -- When the audit was concluded.
  t.conducted_by_agent,                                                         -- Who led it.
  t.problem_framing,                                                            -- How the audit states its problem: KnowledgeDeficit, or CostEfficiency.
  calc_knowledge_audits_finding_count(t.knowledge_audit_id) AS finding_count,   -- Items where held knowledge falls short of what is needed.
  calc_knowledge_audits_treats_deficit_as_cost_problem(t.knowledge_audit_id) AS treats_deficit_as_cost_problem,-- TRUE when an audit finds knowledge shortfalls but frames them as a cost or efficiency problem instead of acknowledging a knowledge deficit.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_audits t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_audit_items: One knowledge area an audit assessed: the level needed, the level the client holds, and any provider that holds it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_audit_items CASCADE;
CREATE VIEW vw_knowledge_audit_items WITH (security_invoker = ON) AS
SELECT
  t.knowledge_audit_item_id,                                                    -- Stored identifier.
  calc_knowledge_audit_items_name(t.knowledge_audit_item_id) AS name,           -- Display name.
  t.knowledge_audit,                                                            -- Audit.
  t.sourcing_function,                                                          -- Function the knowledge belongs to.
  t.knowledge_area,                                                             -- What must be known.
  t.knowledge_kind,                                                             -- Specification (what is built) or Method (how it is built).
  t.needed_level,                                                               -- Level needed: 0 none, 1 aware, 2 can perform with help, 3 can perform and teach.
  t.held_internal_level,                                                        -- Level the client's own people hold, on the same scale.
  t.provider_holding_knowledge,                                                 -- Provider that holds the knowledge, when one does.
  t.provider_held_level,                                                        -- Level the provider holds.
  t.internal_holding_team_count,                                                -- Internal teams that hold the knowledge at the needed level.
  t.named_knowledge_gap,                                                        -- The knowledge gap row that names this finding.
  calc_knowledge_audit_items_client_organization(t.knowledge_audit_item_id) AS client_organization,-- The audited organization.
  calc_knowledge_audit_items_has_internal_shortfall(t.knowledge_audit_item_id) AS has_internal_shortfall,-- TRUE when the client holds less than it needs.
  calc_knowledge_audit_items_is_knowledge_dependency(t.knowledge_audit_item_id) AS is_knowledge_dependency,-- TRUE when the client falls short and relies on a provider that holds the knowledge at the needed level.
  calc_knowledge_audit_items_is_coverage_gap(t.knowledge_audit_item_id) AS is_coverage_gap,-- TRUE when the client falls short and no provider available to it holds the knowledge either.
  calc_knowledge_audit_items_is_unnamed_finding(t.knowledge_audit_item_id) AS is_unnamed_finding,-- TRUE when an audit found a gap or dependency and nobody recorded it as a named knowledge gap.
  calc_knowledge_audit_items_is_single_team_silo(t.knowledge_audit_item_id) AS is_single_team_silo,-- TRUE when knowledge the client does hold sits with exactly one internal team.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_audit_items t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_capture_initiatives: Deliberate efforts to capture the knowledge of a function, with the method used.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_capture_initiatives CASCADE;
CREATE VIEW vw_knowledge_capture_initiatives WITH (security_invoker = ON) AS
SELECT
  t.knowledge_capture_initiative_id,                                            -- Stored identifier.
  calc_knowledge_capture_initiatives_name(t.knowledge_capture_initiative_id) AS name,-- Display name.
  t.sourcing_function,                                                          -- Function whose knowledge is captured.
  t.knowledge_method,                                                           -- Capture method.
  t.lead_agent,                                                                 -- Who leads it.
  t.started_at,                                                                 -- When it started.
  t.status,                                                                     -- Planned, Active or Completed.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_capture_initiatives t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_workforce_positions: Dedicated knowledge engineering, information architecture and ontology positions an organization budgets.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_workforce_positions CASCADE;
CREATE VIEW vw_knowledge_workforce_positions WITH (security_invoker = ON) AS
SELECT
  t.knowledge_workforce_position_id,                                            -- Stored identifier.
  calc_knowledge_workforce_positions_name(t.knowledge_workforce_position_id) AS name,-- Display name.
  t.organization,                                                               -- Organization whose knowledge the position works on.
  t.discipline,                                                                 -- KnowledgeEngineer, InformationArchitect or Ontologist.
  t.role,                                                                       -- The modeled role, when there is one.
  t.status,                                                                     -- Filled, Open or NotBudgeted.
  t.opened_at,                                                                  -- When the position was opened.
  t.filled_by_agent,                                                            -- Who holds it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_workforce_positions t;

-- ----------------------------------------------------------------------------
-- vw_provider_engagements: A client's relationship with a provider for one function, with the knowledge terms it carries.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_provider_engagements CASCADE;
CREATE VIEW vw_provider_engagements WITH (security_invoker = ON) AS
SELECT
  t.provider_engagement_id,                                                     -- Stored identifier.
  calc_provider_engagements_name(t.provider_engagement_id) AS name,             -- Display name.
  t.client_organization,                                                        -- Client.
  t.provider,                                                                   -- Provider.
  t.sourcing_function,                                                          -- Function the provider performs.
  t.started_at,                                                                 -- When the engagement started.
  t.term_months,                                                                -- Contract term in months.
  t.status,                                                                     -- Active or Ended.
  t.documentation_ownership,                                                    -- ProviderIP when the documentation the provider produces stays its intellectual property; ClientOwned or Joint otherwise.
  t.knowledge_duty_terms,                                                       -- Any duty the provider carries to build up the client's knowledge; blank when there is none.
  t.provider_treats_know_how_as_differentiator,                                 -- TRUE when the provider positions its procedural know-how as its competitive differentiator.
  t.has_knowledge_access_clause,                                                -- TRUE when the contract gives the client access to the process knowledge needed to run the operation.
  t.knowledge_return_plan,                                                      -- How the knowledge comes back to the client; blank when nobody planned it.
  calc_provider_engagements_is_active(t.provider_engagement_id) AS is_active,   -- TRUE for a running engagement.
  calc_provider_engagements_relied_dependency_count(t.provider_engagement_id) AS relied_dependency_count,-- Audit findings where the client relies on this provider's knowledge.
  calc_provider_engagements_is_unplanned_knowledge_return(t.provider_engagement_id) AS is_unplanned_knowledge_return,-- TRUE when the client relies on a provider's knowledge, the provider keeps the documentation as its property, and nobody planned how the knowledge comes back.
  calc_provider_engagements_is_knowledge_access_unsecured(t.provider_engagement_id) AS is_knowledge_access_unsecured,-- TRUE when a running engagement is a knowledge dependency and the client has no contractual access to that knowledge.
  calc_provider_engagements_required_deliverable_count(t.provider_engagement_id) AS required_deliverable_count,-- Knowledge deliverables the engagement requires.
  calc_provider_engagements_to_client_required_count(t.provider_engagement_id) AS to_client_required_count,-- Deliverables that move knowledge from the provider to the client.
  calc_provider_engagements_to_client_delivered_count(t.provider_engagement_id) AS to_client_delivered_count,-- Delivered knowledge moving from provider to client.
  calc_provider_engagements_to_provider_delivered_count(t.provider_engagement_id) AS to_provider_delivered_count,-- Delivered knowledge moving from client to provider.
  calc_provider_engagements_joint_deliverable_count(t.provider_engagement_id) AS joint_deliverable_count,-- Knowledge assets the client and provider build jointly.
  calc_provider_engagements_lacks_knowledge_deliverables(t.provider_engagement_id) AS lacks_knowledge_deliverables,-- TRUE when a running engagement requires no knowledge deliverable at all.
  calc_provider_engagements_is_one_way_learning(t.provider_engagement_id) AS is_one_way_learning,-- TRUE when a running engagement has knowledge deliverables but knowledge has actually moved in only one direction.
  calc_provider_engagements_is_short_term_without_joint_knowledge(t.provider_engagement_id) AS is_short_term_without_joint_knowledge,-- TRUE when a running engagement is contracted for under three years and builds no knowledge jointly.
  calc_provider_engagements_obliges_knowledge_flow_back(t.provider_engagement_id) AS obliges_knowledge_flow_back,-- TRUE when the engagement requires knowledge deliverables to the client and plans how the knowledge comes back.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM provider_engagements t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_deliverables: Explicit knowledge management deliverables an engagement requires, and the direction knowledge moves.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_deliverables CASCADE;
CREATE VIEW vw_knowledge_deliverables WITH (security_invoker = ON) AS
SELECT
  t.knowledge_deliverable_id,                                                   -- Stored identifier.
  calc_knowledge_deliverables_name(t.knowledge_deliverable_id) AS name,         -- Display name.
  t.provider_engagement,                                                        -- Engagement.
  t.direction,                                                                  -- ToClient, ToProvider or Joint.
  t.title,                                                                      -- Deliverable.
  t.due_at,                                                                     -- When due.
  t.delivered_at,                                                               -- When delivered; blank when not.
  calc_knowledge_deliverables_is_delivered(t.knowledge_deliverable_id) AS is_delivered,-- TRUE once delivered.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_deliverables t;

-- ----------------------------------------------------------------------------
-- vw_corporate_governance_programs: Governance programmes an organization runs, who sponsors them, and what their scope covers.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_corporate_governance_programs CASCADE;
CREATE VIEW vw_corporate_governance_programs WITH (security_invoker = ON) AS
SELECT
  t.corporate_governance_program_id,                                            -- Stored identifier.
  calc_corporate_governance_programs_name(t.corporate_governance_program_id) AS name,-- Display name.
  t.organization,                                                               -- Organization.
  t.label,                                                                      -- Programme.
  t.sponsor_discipline,                                                         -- The leadership discipline sponsoring it: Engineering or Legal.
  t.launched_at,                                                                -- When launched.
  t.covers_compliance,                                                          -- Scope includes regulatory compliance and legal risk.
  t.covers_data_quality,                                                        -- Scope includes data quality.
  t.covers_information_management,                                              -- Scope includes information management.
  t.covers_knowledge_management,                                                -- Scope includes knowledge management.
  calc_corporate_governance_programs_is_compliance_only(t.corporate_governance_program_id) AS is_compliance_only,-- TRUE when a programme's scope is compliance and nothing else.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM corporate_governance_programs t;

-- ----------------------------------------------------------------------------
-- vw_records_retention_policies: Retention rules for classes of records, with what drives the retention period.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_records_retention_policies CASCADE;
CREATE VIEW vw_records_retention_policies WITH (security_invoker = ON) AS
SELECT
  t.records_retention_policy_id,                                                -- Stored identifier.
  calc_records_retention_policies_name(t.records_retention_policy_id) AS name,  -- Display name.
  t.governance_program,                                                         -- Programme that set the rule.
  t.record_class,                                                               -- Records the rule applies to.
  t.retention_driver,                                                           -- ComplianceRisk (keep only as long as legal exposure requires) or KnowledgeValue.
  t.retention_years,                                                            -- Years records are kept.
  t.knowledge_useful_life_years,                                                -- Years the knowledge in those records stays in use (for example the service life of the product they describe).
  calc_records_retention_policies_program_sponsor_discipline(t.records_retention_policy_id) AS program_sponsor_discipline,-- Discipline sponsoring the programme.
  calc_records_retention_policies_is_legal_led_knowledge_destruct(t.records_retention_policy_id) AS is_legal_led_knowledge_destruction,-- TRUE when a legally sponsored programme sets a risk-driven retention period that destroys records while their knowledge is still in use.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM records_retention_policies t;

-- ----------------------------------------------------------------------------
-- vw_ai_registry_model_versions: Model versions supplied by the external AI system registry feed, described in Dublin Core terms.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_registry_model_versions CASCADE;
CREATE VIEW vw_ai_registry_model_versions WITH (security_invoker = ON) AS
SELECT
  t.ai_registry_model_version_id,                                               -- Stored identifier.
  calc_ai_registry_model_versions_name(t.ai_registry_model_version_id) AS name, -- Display name.
  t.registry_system,                                                            -- The registry the record came from.
  t.dc_identifier,                                                              -- dct:identifier: the identifier the graph uses for the agent individual.
  t.dc_title,                                                                   -- dct:title.
  t.dc_creator,                                                                 -- dct:creator.
  t.dc_date,                                                                    -- dct:date the version was issued.
  t.dc_has_version,                                                             -- dct:hasVersion.
  t.dc_description,                                                             -- dct:description.
  t.feed_received_at,                                                           -- When the feed delivered the record.
  calc_ai_registry_model_versions_graph_individual_count(t.ai_registry_model_version_id) AS graph_individual_count,-- Agent individuals in the graph carrying the registry identifier.
  calc_ai_registry_model_versions_live_production_deployment_coun(t.ai_registry_model_version_id) AS live_production_deployment_count,-- Deployments of this version live in production.
  calc_ai_registry_model_versions_is_live_but_unregistered_in_gra(t.ai_registry_model_version_id) AS is_live_but_unregistered_in_graph,-- TRUE when a model version runs in production and no agent individual in the graph represents it.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_registry_model_versions t;

-- ----------------------------------------------------------------------------
-- vw_ai_model_deployments: Deployment records for AI system versions, from the registry feed.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_model_deployments CASCADE;
CREATE VIEW vw_ai_model_deployments WITH (security_invoker = ON) AS
SELECT
  t.ai_model_deployment_id,                                                     -- Stored identifier.
  calc_ai_model_deployments_name(t.ai_model_deployment_id) AS name,             -- Display name.
  t.model_version,                                                              -- Deployed version.
  t.environment,                                                                -- Production or Staging.
  t.deployed_at,                                                                -- When deployed.
  t.retired_at,                                                                 -- When retired; blank while running.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_ai_model_deployments_as_of_instant(t.ai_model_deployment_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_ai_model_deployments_is_live_in_production(t.ai_model_deployment_id) AS is_live_in_production,-- TRUE for a production deployment running at the evaluation instant.
  calc_ai_model_deployments_agent_identifier(t.ai_model_deployment_id) AS agent_identifier,-- Graph identifier of the deployed version.
  calc_ai_model_deployments_assignment_link_count(t.ai_model_deployment_id) AS assignment_link_count,-- Role assignments in the graph filled by that agent.
  calc_ai_model_deployments_artifact_link_count(t.ai_model_deployment_id) AS artifact_link_count,-- Artifacts in the graph attributed to that agent.
  calc_ai_model_deployments_is_isolated_registry_fact(t.ai_model_deployment_id) AS is_isolated_registry_fact,-- TRUE for a live production deployment whose agent fills no role and has produced no artifact the graph knows: a registry row with no context.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_model_deployments t;

-- ----------------------------------------------------------------------------
-- vw_ai_model_evaluations: Evaluation results for AI system versions, from the registry feed.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_model_evaluations CASCADE;
CREATE VIEW vw_ai_model_evaluations WITH (security_invoker = ON) AS
SELECT
  t.ai_model_evaluation_id,                                                     -- Stored identifier.
  calc_ai_model_evaluations_name(t.ai_model_evaluation_id) AS name,             -- Display name.
  t.model_version,                                                              -- Evaluated version.
  t.evaluated_at,                                                               -- When evaluated.
  t.evaluation_suite,                                                           -- Suite or dataset.
  t.metric,                                                                     -- Metric.
  t.score,                                                                      -- Score.
  t.pass_threshold,                                                             -- Score needed to pass.
  calc_ai_model_evaluations_passed(t.ai_model_evaluation_id) AS passed,         -- TRUE when the score meets the threshold.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_model_evaluations t;

-- ----------------------------------------------------------------------------
-- vw_ai_agent_accountabilities: The human person accountable for an AI agent, with a validity period.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ai_agent_accountabilities CASCADE;
CREATE VIEW vw_ai_agent_accountabilities WITH (security_invoker = ON) AS
SELECT
  t.ai_agent_accountability_id,                                                 -- Stored identifier.
  calc_ai_agent_accountabilities_name(t.ai_agent_accountability_id) AS name,    -- Display name.
  t.ai_agent,                                                                   -- AI agent.
  t.accountable_agent,                                                          -- Agent accountable for it (prov:actedOnBehalfOf).
  t.valid_from,                                                                 -- From.
  t.valid_to,                                                                   -- To; blank while in force.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_ai_agent_accountabilities_as_of_instant(t.ai_agent_accountability_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_ai_agent_accountabilities_is_current(t.ai_agent_accountability_id) AS is_current,-- TRUE while in force at the evaluation instant.
  calc_ai_agent_accountabilities_accountable_agent_kind(t.ai_agent_accountability_id) AS accountable_agent_kind,-- Kind of the accountable agent.
  calc_ai_agent_accountabilities_is_accountable_to_non_person(t.ai_agent_accountability_id) AS is_accountable_to_non_person,-- TRUE when an AI agent is recorded as accountable to something that is not a human person.
  calc_ai_agent_accountabilities_is_current_human_accountability(t.ai_agent_accountability_id) AS is_current_human_accountability,-- TRUE for an accountability in force that names a human person.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM ai_agent_accountabilities t;

-- ----------------------------------------------------------------------------
-- vw_agent_upgrade_assessments: Impact assessments of moving an agent to a newer model version, as listed by whoever assessed it and as traversed in the graph.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_agent_upgrade_assessments CASCADE;
CREATE VIEW vw_agent_upgrade_assessments WITH (security_invoker = ON) AS
SELECT
  t.agent_upgrade_assessment_id,                                                -- Stored identifier.
  calc_agent_upgrade_assessments_name(t.agent_upgrade_assessment_id) AS name,   -- Display name.
  t.current_agent,                                                              -- Agent being replaced.
  t.candidate_agent,                                                            -- Candidate version.
  t.assessed_at,                                                                -- When assessed.
  t.assessment_method,                                                          -- ChangeTicket (listed by hand) or GraphTraversal.
  t.assessed_by_agent,                                                          -- Who assessed it.
  t.listed_affected_step_count,                                                 -- Downstream steps the assessment listed as affected.
  t.listed_affected_steps_note,                                                 -- What the assessment listed.
  calc_agent_upgrade_assessments_attributed_artifact_count(t.agent_upgrade_assessment_id) AS attributed_artifact_count,-- Artifacts attributed to the current agent.
  calc_agent_upgrade_assessments_traversed_downstream_step_count(t.agent_upgrade_assessment_id) AS traversed_downstream_step_count,-- Steps downstream of the current agent's artifacts, found by traversing the artifact-flow closure.
  calc_agent_upgrade_assessments_missed_traversed_impact(t.agent_upgrade_assessment_id) AS missed_traversed_impact,-- TRUE when an assessment listed fewer affected steps than traversal of the artifact flow finds.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM agent_upgrade_assessments t;

-- ----------------------------------------------------------------------------
-- vw_assignment_update_policies: Governance for updating role assignments once operational systems read them: who triggers the update and the service level for completing it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assignment_update_policies CASCADE;
CREATE VIEW vw_assignment_update_policies WITH (security_invoker = ON) AS
SELECT
  t.assignment_update_policy_id,                                                -- Stored identifier.
  calc_assignment_update_policies_name(t.assignment_update_policy_id) AS name,  -- Display name.
  t.label,                                                                      -- Policy.
  t.trigger_owner_role,                                                         -- Role responsible for triggering an assignment update; blank when governance names nobody.
  t.update_sla_hours,                                                           -- Hours within which an update must be completed; 0 when no service level is defined.
  t.model_drives_routing,                                                       -- TRUE when operational systems route work from the assignments this policy covers.
  t.adopted_at,                                                                 -- When adopted.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM assignment_update_policies t;

-- ----------------------------------------------------------------------------
-- vw_role_assignment_update_tasks: The audit record of one change to who fills a role: what triggered it, who triggered it, when it was completed, and the run that depended on it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_role_assignment_update_tasks CASCADE;
CREATE VIEW vw_role_assignment_update_tasks WITH (security_invoker = ON) AS
SELECT
  t.role_assignment_update_task_id,                                             -- Stored identifier.
  calc_role_assignment_update_tasks_name(t.role_assignment_update_task_id) AS name,-- Display name.
  t.role,                                                                       -- Role whose filler changes.
  t.governing_policy,                                                           -- Policy governing the update.
  t.trigger_event,                                                              -- Departure, ModelUpgrade, AiToHumanHandover or HumanToAutomationHandover.
  t.reason,                                                                     -- Why the change was made.
  t.trigger_occurred_at,                                                        -- When the triggering event happened.
  t.triggered_at,                                                               -- When someone triggered the update; blank when nobody did.
  t.triggered_by_agent,                                                         -- Who triggered it.
  t.completed_at,                                                               -- When the assignment change was recorded in the model; blank when not yet.
  t.ending_assignment,                                                          -- Assignment that ends.
  t.replacement_assignment,                                                     -- Assignment that replaces it, when there is one.
  t.dependent_execution,                                                        -- The first procedure run after the trigger that needed the role.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_role_assignment_update_tasks_as_of_instant(t.role_assignment_update_task_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_role_assignment_update_tasks_policy_trigger_owner_role(t.role_assignment_update_task_id) AS policy_trigger_owner_role,-- Role the policy makes responsible for triggering.
  calc_role_assignment_update_tasks_trigger_owner_cover_count(t.role_assignment_update_task_id) AS trigger_owner_cover_count,-- Assignments currently covering that role.
  calc_role_assignment_update_tasks_lacks_named_trigger_owner(t.role_assignment_update_task_id) AS lacks_named_trigger_owner,-- TRUE when governance names no role responsible for triggering the update, or names one nobody holds.
  calc_role_assignment_update_tasks_policy_sla_hours(t.role_assignment_update_task_id) AS policy_sla_hours,-- Service level in hours.
  calc_role_assignment_update_tasks_elapsed_minutes(t.role_assignment_update_task_id) AS elapsed_minutes,-- Minutes from the trigger to completion, or to the evaluation instant while incomplete.
  calc_role_assignment_update_tasks_exceeded_update_sla(t.role_assignment_update_task_id) AS exceeded_update_sla,-- TRUE when no service level is defined, or the update took longer than it allows.
  calc_role_assignment_update_tasks_ending_role(t.role_assignment_update_task_id) AS ending_role,-- Role of the ending assignment.
  calc_role_assignment_update_tasks_replacement_role(t.role_assignment_update_task_id) AS replacement_role,-- Role of the replacement assignment.
  calc_role_assignment_update_tasks_changed_role_instead_of_assig(t.role_assignment_update_task_id) AS changed_role_instead_of_assignment,-- TRUE when a change of who does the work was made by moving it to a different role, so the steps bound to the old role had to be re-pointed.
  calc_role_assignment_update_tasks_dependent_run_version(t.role_assignment_update_task_id) AS dependent_run_version,-- Version the dependent run enacted.
  calc_role_assignment_update_tasks_dependent_run_started_at(t.role_assignment_update_task_id) AS dependent_run_started_at,-- When the dependent run started.
  calc_role_assignment_update_tasks_dependent_run_role_step_count(t.role_assignment_update_task_id) AS dependent_run_role_step_count,-- Steps of the dependent run's version assigned to the role.
  calc_role_assignment_update_tasks_missed_next_dependent_run(t.role_assignment_update_task_id) AS missed_next_dependent_run,-- TRUE when a run that needs the role started after the trigger and before the assignment change was recorded.
  calc_role_assignment_update_tasks_failed_notice_count(t.role_assignment_update_task_id) AS failed_notice_count,-- Notices for the role in the dependent run that reached the wrong person or nobody.
  calc_role_assignment_update_tasks_stale_assignment_broke_routin(t.role_assignment_update_task_id) AS stale_assignment_broke_routing,-- TRUE when the assignment was still stale at a run that needed it and that run's notice for the role reached the wrong person or nobody.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM role_assignment_update_tasks t;

-- ----------------------------------------------------------------------------
-- vw_assignment_routed_notices: Approval and verification notices a deployment pipeline sent for a run, where it read the recipient from, and who received it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_assignment_routed_notices CASCADE;
CREATE VIEW vw_assignment_routed_notices WITH (security_invoker = ON) AS
SELECT
  t.assignment_routed_notice_id,                                                -- Stored identifier.
  calc_assignment_routed_notices_name(t.assignment_routed_notice_id) AS name,   -- Display name.
  t.procedure_execution,                                                        -- Run the notice belongs to.
  t.notice_step,                                                                -- Step the notice asks someone to act on.
  t.notice_kind,                                                                -- ReleaseApproval or HealthVerification.
  t.sent_at,                                                                    -- When sent.
  t.routing_source,                                                             -- RoleAssignments (read from the model) or OpsSpreadsheet (a separately maintained list).
  t.routed_to_agent,                                                            -- Who received it; blank when nobody did.
  calc_assignment_routed_notices_notice_role(t.assignment_routed_notice_id) AS notice_role,-- Role assigned to the step.
  calc_assignment_routed_notices_recipient_role_key(t.assignment_routed_notice_id) AS recipient_role_key,-- Recipient and role, as one key.
  calc_assignment_routed_notices_recipient_pair_assignment_count(t.assignment_routed_notice_id) AS recipient_pair_assignment_count,-- Assignments of the recipient to the role, at any time.
  calc_assignment_routed_notices_recipient_valid_from(t.assignment_routed_notice_id) AS recipient_valid_from,-- Start of the recipient's assignment to the role.
  calc_assignment_routed_notices_recipient_latest_valid_to(t.assignment_routed_notice_id) AS recipient_latest_valid_to,-- End of the recipient's assignment to the role.
  calc_assignment_routed_notices_recipient_open_ended_count(t.assignment_routed_notice_id) AS recipient_open_ended_count,-- Open-ended assignments of the recipient to the role.
  calc_assignment_routed_notices_recipient_held_role_when_sent(t.assignment_routed_notice_id) AS recipient_held_role_when_sent,-- TRUE when the recipient's assignment to the step's role was valid at the moment the notice was sent.
  calc_assignment_routed_notices_reached_wrong_person_or_nobody(t.assignment_routed_notice_id) AS reached_wrong_person_or_nobody,-- TRUE when a notice went to someone who did not hold the step's role when it was sent, or to nobody.
  calc_assignment_routed_notices_routed_around_model(t.assignment_routed_notice_id) AS routed_around_model,-- TRUE when a notice was routed from a separately maintained list and reached someone the model's assignments did not name for the role.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM assignment_routed_notices t;

-- ----------------------------------------------------------------------------
-- vw_practitioner_expertise: Expertise a practitioner demonstrably holds, with the basis they could not put into words recorded as a property of that knowledge source.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_practitioner_expertise CASCADE;
CREATE VIEW vw_practitioner_expertise WITH (security_invoker = ON) AS
SELECT
  t.practitioner_expertise_id,                                                  -- Stored identifier.
  calc_practitioner_expertise_name(t.practitioner_expertise_id) AS name,        -- Display name.
  t.agent,                                                                      -- The practitioner who holds the expertise.
  t.procedure,                                                                  -- The procedure the expertise is exercised in.
  t.step,                                                                       -- The step the expertise is exercised at.
  t.elicitation_session,                                                        -- The session in which the expertise was probed.
  t.expert_kind,                                                                -- Detection (sensing a condition in the moment) or DesignForesight (sensing a future cost).
  t.cue,                                                                        -- What the practitioner senses or judges.
  t.unstated_basis,                                                             -- The basis the practitioner could not articulate, in the elicitor's words; blank when the basis was stated.
  t.reliable_call_count,                                                        -- Observed occasions on which the practitioner's call proved right.
  t.foresight_confirmed,                                                        -- For design foresight: TRUE when later experience confirmed the call.
  calc_practitioner_expertise_knows_more_than_can_say(t.practitioner_expertise_id) AS knows_more_than_can_say,-- TRUE when a practitioner reliably detects a condition whose basis they cannot state.
  calc_practitioner_expertise_is_unexplained_foresight(t.practitioner_expertise_id) AS is_unexplained_foresight,-- TRUE when a design judgment later proved right although its holder could not say why.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM practitioner_expertise t;

-- ----------------------------------------------------------------------------
-- vw_critical_incidents: Specific past episodes of a procedure that went well, went badly or needed improvising, collected with the critical incident technique, each linked to the judgment call it brought out.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_critical_incidents CASCADE;
CREATE VIEW vw_critical_incidents WITH (security_invoker = ON) AS
SELECT
  t.critical_incident_id,                                                       -- Stored identifier.
  calc_critical_incidents_name(t.critical_incident_id) AS name,                 -- Display name.
  t.procedure_version,                                                          -- The version the episode is elicited for.
  t.step,                                                                       -- The step where the episode turned.
  t.elicitation_session,                                                        -- The critical incident session that collected it.
  t.narrator,                                                                   -- The practitioner who recounted the episode.
  t.occurred_at,                                                                -- When the episode happened.
  t.outcome,                                                                    -- WentWell, WentBadly or Improvised.
  t.account,                                                                    -- The practitioner's account of the episode.
  t.revealed_judgment,                                                          -- The judgment call the episode brought out that the written procedure hides; blank when none.
  t.judgment_fragment,                                                          -- The knowledge fragment the revealed judgment was recorded as.
  calc_critical_incidents_is_adverse_or_improvised(t.critical_incident_id) AS is_adverse_or_improvised,-- TRUE for an episode that went badly or had to be improvised.
  calc_critical_incidents_has_surfaced_judgment(t.critical_incident_id) AS has_surfaced_judgment,-- TRUE when the episode revealed a judgment call.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM critical_incidents t;

-- ----------------------------------------------------------------------------
-- vw_interview_probes: Questions put in an elicitation interview, typed by what they probe: why a choice is made, what the practitioner would do if a condition changed, or what happens when the procedure falls short.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_interview_probes CASCADE;
CREATE VIEW vw_interview_probes WITH (security_invoker = ON) AS
SELECT
  t.interview_probe_id,                                                         -- Stored identifier.
  calc_interview_probes_name(t.interview_probe_id) AS name,                     -- Display name.
  t.elicitation_session,                                                        -- The interview the probe was asked in.
  t.step,                                                                       -- The step the probe is about.
  t.probe_kind,                                                                 -- Why, WhatIf or ProcedureFallsShort.
  t.prompt,                                                                     -- The question asked.
  t.answer,                                                                     -- The practitioner's answer.
  calc_interview_probes_why_answer(t.interview_probe_id) AS why_answer,         -- The reason a practitioner gave for a choice.
  calc_interview_probes_shortfall_answer(t.interview_probe_id) AS shortfall_answer,-- What the practitioner does when the standard procedure proves insufficient.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM interview_probes t;

-- ----------------------------------------------------------------------------
-- vw_observed_actions: Actions an observer saw during shadowing or observation, typed as small choices, unofficial workarounds, steps omitted from the practitioner's own account, or documented steps, with the reason given when the observer asked.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_observed_actions CASCADE;
CREATE VIEW vw_observed_actions WITH (security_invoker = ON) AS
SELECT
  t.observed_action_id,                                                         -- Stored identifier.
  calc_observed_actions_name(t.observed_action_id) AS name,                     -- Display name.
  t.elicitation_session,                                                        -- The observation session.
  t.step,                                                                       -- The step the action belongs to.
  t.practitioner,                                                               -- The practitioner observed.
  t.action_description,                                                         -- What the observer saw.
  t.action_kind,                                                                -- SmallChoice, Workaround, OmittedObviousStep or DocumentedStep.
  t.mentioned_in_own_account,                                                   -- TRUE when the practitioner's own interview account included the action.
  t.stated_reason,                                                              -- The reason the practitioner gave when the observer asked; blank when nobody asked.
  t.counterfactual_condition,                                                   -- The different condition the observer asked about.
  t.counterfactual_answer,                                                      -- What the practitioner said they would do under that condition.
  t.captured_as_fragment,                                                       -- The knowledge fragment the action was captured as.
  calc_observed_actions_is_small_choice(t.observed_action_id) AS is_small_choice,-- TRUE for a small choice made during actual practice.
  calc_observed_actions_is_unofficial_workaround(t.observed_action_id) AS is_unofficial_workaround,-- TRUE for an unofficial workaround.
  calc_observed_actions_is_omitted_from_own_account(t.observed_action_id) AS is_omitted_from_own_account,-- TRUE when observation saw an action the practitioner's own account left out.
  calc_observed_actions_is_missed_step_left_uncaptured(t.observed_action_id) AS is_missed_step_left_uncaptured,-- TRUE when an action the interview missed was observed but never captured as knowledge.
  calc_observed_actions_is_watched_not_questioned(t.observed_action_id) AS is_watched_not_questioned,-- TRUE when a small choice or workaround was watched but no reason was asked for and recorded.
  calc_observed_actions_has_recorded_reason(t.observed_action_id) AS has_recorded_reason,-- TRUE when a reason is recorded against the observed action.
  calc_observed_actions_has_counterfactual_answer(t.observed_action_id) AS has_counterfactual_answer,-- TRUE when the practitioner said what they would do if a condition were different.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM observed_actions t;

-- ----------------------------------------------------------------------------
-- vw_elicitation_participants: Who took part in an elicitation session: their part in the session, whether they produce or consume the knowledge, their stake in the process, and whether people in their position are normally invited.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_elicitation_participants CASCADE;
CREATE VIEW vw_elicitation_participants WITH (security_invoker = ON) AS
SELECT
  t.elicitation_participant_id,                                                 -- Stored identifier.
  calc_elicitation_participants_name(t.elicitation_participant_id) AS name,     -- Display name.
  t.elicitation_session,                                                        -- The session.
  t.agent,                                                                      -- The participant.
  t.participation_role,                                                         -- Practitioner, SubjectMatterExpert or KnowledgeEngineer.
  t.knowledge_flow,                                                             -- Producer, Consumer or Both.
  t.process_stake,                                                              -- Initiates, Executes or DependsOnResults; blank for a facilitator with no stake.
  t.is_usually_invited,                                                         -- FALSE for a participant whose position is normally left out of such sessions.
  calc_elicitation_participants_is_practitioner(t.elicitation_participant_id) AS is_practitioner,-- TRUE for a practitioner who holds process knowledge.
  calc_elicitation_participants_is_subject_matter_expert(t.elicitation_participant_id) AS is_subject_matter_expert,-- TRUE for a subject matter expert.
  calc_elicitation_participants_is_knowledge_engineer(t.elicitation_participant_id) AS is_knowledge_engineer,-- TRUE for the knowledge engineer collecting the knowledge.
  calc_elicitation_participants_is_knowledge_producer(t.elicitation_participant_id) AS is_knowledge_producer,-- TRUE for a participant who produces the knowledge.
  calc_elicitation_participants_is_knowledge_consumer(t.elicitation_participant_id) AS is_knowledge_consumer,-- TRUE for a participant who consumes the knowledge.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM elicitation_participants t;

-- ----------------------------------------------------------------------------
-- vw_representation_reviews: Expert reviews of a procedure version: approval of the process representation itself, or evaluation of AI output built on it, with whether the reviewer is a subject matter expert whose work the procedure affects.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_representation_reviews CASCADE;
CREATE VIEW vw_representation_reviews WITH (security_invoker = ON) AS
SELECT
  t.representation_review_id,                                                   -- Stored identifier.
  calc_representation_reviews_name(t.representation_review_id) AS name,         -- Display name.
  t.procedure_version,                                                          -- The version reviewed.
  t.reviewer_agent,                                                             -- The reviewer.
  t.review_purpose,                                                             -- RepresentationApproval or AiEvaluation.
  t.reviewer_is_affected_sme,                                                   -- TRUE when the reviewer is a subject matter expert whose work the procedure affects.
  t.decision,                                                                   -- Approved, Rejected or Pending.
  t.reviewed_at,                                                                -- When the review was given.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM representation_reviews t;

-- ----------------------------------------------------------------------------
-- vw_workflow_view_divergences: Differing views of how work flows, brought into the open in an elicitation session, and the reconciled account when one was reached.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_workflow_view_divergences CASCADE;
CREATE VIEW vw_workflow_view_divergences WITH (security_invoker = ON) AS
SELECT
  t.workflow_view_divergence_id,                                                -- Stored identifier.
  calc_workflow_view_divergences_name(t.workflow_view_divergence_id) AS name,   -- Display name.
  t.elicitation_session,                                                        -- The session where the views surfaced.
  t.procedure_version,                                                          -- The version the divergence is about.
  t.step,                                                                       -- The step the views differ on.
  t.view_a,                                                                     -- One account of how the work flows.
  t.holder_a,                                                                   -- Who holds the first account.
  t.view_b,                                                                     -- The differing account.
  t.holder_b,                                                                   -- Who holds the second account.
  t.reconciled_statement,                                                       -- The account the participants settled on; blank while unsettled.
  t.reconciled_at,                                                              -- When it was settled.
  t.reconciled_into_fragment,                                                   -- The fragment recording the settled account.
  calc_workflow_view_divergences_is_reconciled(t.workflow_view_divergence_id) AS is_reconciled,-- TRUE when a settled account is recorded.
  calc_workflow_view_divergences_is_surfaced_but_unreconciled(t.workflow_view_divergence_id) AS is_surfaced_but_unreconciled,-- TRUE when two differing views were brought into the open but never reconciled.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM workflow_view_divergences t;

-- ----------------------------------------------------------------------------
-- vw_expert_cognitions: Mental models and decision heuristics experts apply, drawn out by protocols and incident interviews, with any exceptions the expert stated and whether the capture kept them.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_expert_cognitions CASCADE;
CREATE VIEW vw_expert_cognitions WITH (security_invoker = ON) AS
SELECT
  t.expert_cognition_id,                                                        -- Stored identifier.
  calc_expert_cognitions_name(t.expert_cognition_id) AS name,                   -- Display name.
  t.agent,                                                                      -- The expert.
  t.step,                                                                       -- The step the cognition is applied at.
  t.elicitation_session,                                                        -- The session that drew it out.
  t.cognition_kind,                                                             -- MentalModel or DecisionHeuristic.
  t.statement,                                                                  -- The model or heuristic as captured.
  t.applied_automatically,                                                      -- TRUE when the expert applies it without deliberating.
  t.expert_stated_exceptions,                                                   -- TRUE when the expert said when the heuristic does not hold.
  t.captured_exceptions,                                                        -- The exceptions as captured; blank when the capture dropped them.
  calc_expert_cognitions_is_mental_model(t.expert_cognition_id) AS is_mental_model,-- TRUE for a mental model an expert applies.
  calc_expert_cognitions_is_automatic_heuristic(t.expert_cognition_id) AS is_automatic_heuristic,-- TRUE for a decision heuristic the expert applies automatically.
  calc_expert_cognitions_is_heuristic_oversimplified(t.expert_cognition_id) AS is_heuristic_oversimplified,-- TRUE when an expert stated when a heuristic does not hold and the capture kept only the bare rule.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM expert_cognitions t;

-- ----------------------------------------------------------------------------
-- vw_concept_ladder_rungs: Rungs of a concept ladder built around a concrete action: positive levels climb by asking why to the goals and values it serves, negative levels descend by asking how to its subprocesses and conditions.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_concept_ladder_rungs CASCADE;
CREATE VIEW vw_concept_ladder_rungs WITH (security_invoker = ON) AS
SELECT
  t.concept_ladder_rung_id,                                                     -- Stored identifier.
  calc_concept_ladder_rungs_name(t.concept_ladder_rung_id) AS name,             -- Display name.
  t.elicitation_session,                                                        -- The laddering session.
  t.step,                                                                       -- The concrete action the ladder starts from.
  t.ladder_level,                                                               -- Rung height: positive above the action, negative below.
  t.rung_kind,                                                                  -- Goal, Value, Subprocess or Condition.
  t.statement,                                                                  -- The practitioner's answer at this rung.
  calc_concept_ladder_rungs_step_top_level(t.concept_ladder_rung_id) AS step_top_level,-- The highest rung laddered from the same action.
  calc_concept_ladder_rungs_is_ultimate_goal(t.concept_ladder_rung_id) AS is_ultimate_goal,-- TRUE for the top rung above an action: the goal or value it ultimately serves.
  calc_concept_ladder_rungs_is_decomposition_rung(t.concept_ladder_rung_id) AS is_decomposition_rung,-- TRUE for a rung below the action: a subprocess or condition that makes it up.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM concept_ladder_rungs t;

-- ----------------------------------------------------------------------------
-- vw_repertory_grid_constructs: Constructs elicited with a repertory grid: the bipolar dimensions an expert uses to tell compared situations apart.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_repertory_grid_constructs CASCADE;
CREATE VIEW vw_repertory_grid_constructs WITH (security_invoker = ON) AS
SELECT
  t.repertory_grid_construct_id,                                                -- Stored identifier.
  calc_repertory_grid_constructs_name(t.repertory_grid_construct_id) AS name,   -- Display name.
  t.elicitation_session,                                                        -- The repertory grid session.
  t.agent,                                                                      -- The expert.
  t.situations_compared,                                                        -- The situations laid side by side.
  t.pole_a,                                                                     -- One end of the dimension.
  t.pole_b,                                                                     -- The other end.
  t.was_stated_unprompted,                                                      -- TRUE when the expert named the dimension before the grid comparison.
  t.separates_situations,                                                       -- TRUE when rating the compared situations on the dimension actually split them.
  calc_repertory_grid_constructs_dimension(t.repertory_grid_construct_id) AS dimension,-- The dimension as recorded.
  calc_repertory_grid_constructs_is_never_stated_dimension(t.repertory_grid_construct_id) AS is_never_stated_dimension,-- TRUE for a dimension the expert uses but only the grid comparison brought out.
  calc_repertory_grid_constructs_is_recorded_discriminating_dimen(t.repertory_grid_construct_id) AS is_recorded_discriminating_dimension,-- TRUE for a recorded dimension that tells the compared situations apart.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM repertory_grid_constructs t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_conversions: Recorded shifts of process knowledge between tacit and explicit form, typed by SECI conversion mode.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_conversions CASCADE;
CREATE VIEW vw_knowledge_conversions WITH (security_invoker = ON) AS
SELECT
  t.knowledge_conversion_id,                                                    -- Stored identifier.
  calc_knowledge_conversions_name(t.knowledge_conversion_id) AS name,           -- Display name.
  t.elicitation_session,                                                        -- The session in which the conversion happened, when there was one.
  t.result_fragment,                                                            -- The fragment the conversion produced or used.
  t.conversion_mode,                                                            -- Socialization, Externalization, Combination or Internalization.
  t.from_form,                                                                  -- Tacit or Explicit.
  t.to_form,                                                                    -- Tacit or Explicit.
  t.description,                                                                -- What moved and how.
  t.occurred_at,                                                                -- When.
  calc_knowledge_conversions_is_mode_inconsistent_with_forms(t.knowledge_conversion_id) AS is_mode_inconsistent_with_forms,-- TRUE when the recorded SECI mode does not match the forms it converts between (socialization tacit to tacit, externalization tacit to explicit, combination explicit to explicit, internalization explicit to tacit).
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_conversions t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_holdings: Where a piece of a procedure's knowledge lives at one point in time (before and after encoding): operators' memory, formal documents, notes in outdated manuals, the memory of staff who may leave, unspoken crew agreements, or the procedure rulebook.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_holdings CASCADE;
CREATE VIEW vw_knowledge_holdings WITH (security_invoker = ON) AS
SELECT
  t.knowledge_holding_id,                                                       -- Stored identifier.
  calc_knowledge_holdings_name(t.knowledge_holding_id) AS name,                 -- Display name.
  t.procedure_version,                                                          -- The version whose knowledge this is.
  t.step,                                                                       -- The step it concerns.
  t.snapshot,                                                                   -- Before or After encoding.
  t.knowledge_form,                                                             -- Tacit or Explicit.
  t.carrier,                                                                    -- OperatorMemory, FormalDocument, OutdatedManualNote, DepartingStaffMemory, UnspokenCrewAgreement or ProcedureRulebook.
  t.holder_agent,                                                               -- The person who holds it, when a person does.
  t.statement,                                                                  -- What is held.
  t.is_unsaid_in_sop,                                                           -- TRUE when the written SOP says nothing about it.
  t.holder_is_veteran,                                                          -- TRUE when the holder is a long-tenured practitioner.
  t.handles_exception_or_discretion,                                            -- TRUE when the knowledge resolves an exception or a discretionary decision.
  t.formalized_as,                                                              -- The fragment it was formalized into, once formalized.
  calc_knowledge_holdings_formalized_fragment_session(t.knowledge_holding_id) AS formalized_fragment_session,-- The elicitation session that produced the formalizing fragment.
  calc_knowledge_holdings_is_unformalized_process_knowledge(t.knowledge_holding_id) AS is_unformalized_process_knowledge,-- TRUE for lived, unformalized knowledge of how the work gets done.
  calc_knowledge_holdings_is_procedural_knowledge(t.knowledge_holding_id) AS is_procedural_knowledge,-- TRUE once the knowledge is formalized as a typed fragment of the procedure ontology.
  calc_knowledge_holdings_is_judgment_outside_document(t.knowledge_holding_id) AS is_judgment_outside_document,-- TRUE for unformalized knowledge the written SOP says nothing about.
  calc_knowledge_holdings_is_veteran_discretion(t.knowledge_holding_id) AS is_veteran_discretion,-- TRUE when a veteran resolves an exception or discretionary decision that nothing written encodes.
  calc_knowledge_holdings_is_formalized_without_elicitation_work(t.knowledge_holding_id) AS is_formalized_without_elicitation_work,-- TRUE when knowledge was formalized into a fragment that no observation, interview or other elicitation produced.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_holdings t;

-- ----------------------------------------------------------------------------
-- vw_fragment_corroborations: Independent data points (another session or another practitioner) that bear on a knowledge fragment.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_fragment_corroborations CASCADE;
CREATE VIEW vw_fragment_corroborations WITH (security_invoker = ON) AS
SELECT
  t.fragment_corroboration_id,                                                  -- Stored identifier.
  calc_fragment_corroborations_name(t.fragment_corroboration_id) AS name,       -- Display name.
  t.knowledge_fragment,                                                         -- The fragment.
  t.elicitation_session,                                                        -- The corroborating session.
  t.agent,                                                                      -- The corroborating practitioner.
  t.agrees,                                                                     -- TRUE when the data point supports the fragment.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM fragment_corroborations t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_test_outcomes: Outcomes a process knowledge test programme is expected to improve, measured before and after testing.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_test_outcomes CASCADE;
CREATE VIEW vw_knowledge_test_outcomes WITH (security_invoker = ON) AS
SELECT
  t.knowledge_test_outcome_id,                                                  -- Stored identifier.
  calc_knowledge_test_outcomes_name(t.knowledge_test_outcome_id) AS name,       -- Display name.
  t.procedure,                                                                  -- The procedure tested.
  t.outcome_area,                                                               -- CompetencyGaps, ProcessQuality, Efficiency, JobSatisfaction or Consistency.
  t.measure,                                                                    -- What was measured.
  t.baseline_value,                                                             -- Measured before the tests.
  t.after_test_value,                                                           -- Measured after the tests.
  t.higher_is_better,                                                           -- TRUE when a higher value is an improvement.
  calc_knowledge_test_outcomes_is_improved(t.knowledge_test_outcome_id) AS is_improved,-- TRUE when the outcome moved in the better direction after testing.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_test_outcomes t;

-- ----------------------------------------------------------------------------
-- vw_know_how_carriers: One piece of an organization's process know-how and what carries it: a person, a facility or a system, with the community it belongs to, the forms it is held in, and how long it took to build.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_know_how_carriers CASCADE;
CREATE VIEW vw_know_how_carriers WITH (security_invoker = ON) AS
SELECT
  t.know_how_carrier_id,                                                        -- Stored identifier.
  calc_know_how_carriers_name(t.know_how_carrier_id) AS name,                   -- Display name.
  t.topic,                                                                      -- What the know-how is about.
  t.organization,                                                               -- The organization whose know-how this is.
  t.procedure,                                                                  -- The procedure the know-how serves.
  t.community_of_practice,                                                      -- The community in which the know-how circulates.
  t.carrier_kind,                                                               -- Person, Facility or System.
  t.holder_agent,                                                               -- The person who carries it, when the carrier is a person.
  t.holder_facility,                                                            -- The plant that carries it in its layout and equipment, when the carrier is a facility.
  t.know_how_kind,                                                              -- WhatFails, Diagnosis, Improvisation or Refinement: the kind of practitioner know-how.
  t.is_in_written_procedure,                                                    -- TRUE when the know-how is written into a procedure.
  t.is_trained_skill,                                                           -- TRUE when the know-how is carried as trained skill of seasoned workers.
  t.work_medium,                                                                -- Physical or Digital work.
  t.held_since,                                                                 -- When the carrier began to hold the know-how.
  t.builds_on_know_how,                                                         -- Know-how about a related component or system this know-how depends on.
  t.is_in_public_references,                                                    -- TRUE when the know-how can be found in public references.
  t.replacement_plan,                                                           -- How the organization plans to replace the know-how if lost: PublicReference, AiGeneration, Apprenticeship, or blank.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_know_how_carriers_as_of_instant(t.know_how_carrier_id) AS as_of_instant, -- The modeled evaluation instant.
  calc_know_how_carriers_holder_is_still_engaged(t.know_how_carrier_id) AS holder_is_still_engaged,-- Whether the holding person still holds a current role.
  calc_know_how_carriers_holder_service_started_at(t.know_how_carrier_id) AS holder_service_started_at,-- When the holder began service.
  calc_know_how_carriers_holder_departure_at(t.know_how_carrier_id) AS holder_departure_at,-- The holder's planned or actual departure.
  calc_know_how_carriers_days_until_holder_departure(t.know_how_carrier_id) AS days_until_holder_departure,-- Days from the evaluation instant to the holder's departure; negative once gone.
  calc_know_how_carriers_days_served_to_as_of(t.know_how_carrier_id) AS days_served_to_as_of,-- Days of service up to the evaluation instant.
  calc_know_how_carriers_days_served_to_departure(t.know_how_carrier_id) AS days_served_to_departure,-- Days of service up to departure.
  calc_know_how_carriers_holder_tenure_years(t.know_how_carrier_id) AS holder_tenure_years,-- Years the holder practised: to departure when gone, else to the evaluation instant.
  calc_know_how_carriers_is_veteran_held(t.know_how_carrier_id) AS is_veteran_held,-- TRUE when a person with ten or more years of practice carries the know-how.
  calc_know_how_carriers_is_holder_leaving_soon(t.know_how_carrier_id) AS is_holder_leaving_soon,-- TRUE when the holder leaves within 120 days of the evaluation instant.
  calc_know_how_carriers_transfer_count(t.know_how_carrier_id) AS transfer_count,-- Recorded transfers of this know-how to someone else.
  calc_know_how_carriers_repository_entry_count(t.know_how_carrier_id) AS repository_entry_count,-- Repository entries that capture this know-how.
  calc_know_how_carriers_source_relationship_count(t.know_how_carrier_id) AS source_relationship_count,-- Collection relationships with this holder on this procedure.
  calc_know_how_carriers_is_held_in_both_forms(t.know_how_carrier_id) AS is_held_in_both_forms,-- TRUE when the know-how is at once a written procedure and trained skill.
  calc_know_how_carriers_is_held_by_current_practitioner(t.know_how_carrier_id) AS is_held_by_current_practitioner,-- TRUE when a person who still holds a role carries the know-how.
  calc_know_how_carriers_is_untransferred_veteran_know_how(t.know_how_carrier_id) AS is_untransferred_veteran_know_how,-- TRUE when a serving veteran carries know-how never transferred or captured.
  calc_know_how_carriers_is_at_risk_of_imminent_loss(t.know_how_carrier_id) AS is_at_risk_of_imminent_loss,-- TRUE when untransferred veteran know-how belongs to someone leaving within 120 days.
  calc_know_how_carriers_is_held_only_by_departed(t.know_how_carrier_id) AS is_held_only_by_departed,-- TRUE when the only carrier has left and the know-how was neither transferred nor captured.
  calc_know_how_carriers_is_held_by_departed_holder(t.know_how_carrier_id) AS is_held_by_departed_holder,-- TRUE when the person who carried the know-how has left.
  calc_know_how_carriers_is_captured(t.know_how_carrier_id) AS is_captured,     -- TRUE when a repository entry captures the know-how.
  calc_know_how_carriers_must_be_relearned_if_holder_leaves(t.know_how_carrier_id) AS must_be_relearned_if_holder_leaves,-- TRUE when a serving holder's know-how has nothing captured for a successor.
  calc_know_how_carriers_is_overlooked_living_holder(t.know_how_carrier_id) AS is_overlooked_living_holder,-- TRUE when uncaptured know-how has a serving holder no collection relationship has approached.
  calc_know_how_carriers_transfer_stops_without_veteran(t.know_how_carrier_id) AS transfer_stops_without_veteran,-- TRUE when veteran know-how has only been passed person to person with nothing captured, so the next newcomer still needs the veteran.
  calc_know_how_carriers_dependency_community(t.know_how_carrier_id) AS dependency_community,-- The community of the know-how this builds on.
  calc_know_how_carriers_builds_on_same_community_know_how(t.know_how_carrier_id) AS builds_on_same_community_know_how,-- TRUE when the know-how depends on related know-how concentrated in the same community.
  calc_know_how_carriers_lost_accumulation_years(t.know_how_carrier_id) AS lost_accumulation_years,-- Years of practice lost with a departed sole carrier; zero otherwise.
  calc_know_how_carriers_is_delegated_to_unfit_source(t.know_how_carrier_id) AS is_delegated_to_unfit_source,-- TRUE when the plan is to replace the know-how from public references or AI generation although it is not in public references.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM know_how_carriers t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_transfers: One occasion on which know-how passed from one person to another, and the channel it travelled through.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_transfers CASCADE;
CREATE VIEW vw_knowledge_transfers WITH (security_invoker = ON) AS
SELECT
  t.knowledge_transfer_id,                                                      -- Stored identifier.
  calc_knowledge_transfers_name(t.knowledge_transfer_id) AS name,               -- Display name.
  t.know_how,                                                                   -- The know-how that passed.
  t.from_agent,                                                                 -- Who passed it on.
  t.recipient_agent,                                                            -- Who received it, when one person did.
  t.channel,                                                                    -- Document, TrainingProgram, Mentoring, PersonalRelationship, Collaboration, DesignProductionIteration, EmployerChange or AmbientExposure.
  t.community_of_practice,                                                      -- The community the transfer took place in.
  t.occurred_at,                                                                -- When the transfer took place.
  t.on_allocated_time,                                                          -- TRUE when the transfer was done on time the organization allotted for it.
  calc_knowledge_transfers_from_organization(t.knowledge_transfer_id) AS from_organization,-- The giver's organization.
  calc_knowledge_transfers_recipient_role_count(t.knowledge_transfer_id) AS recipient_role_count,-- Current role assignments the recipient holds.
  calc_knowledge_transfers_is_traditional_channel(t.knowledge_transfer_id) AS is_traditional_channel,-- TRUE for the traditional channels: documents, training programs and mentoring.
  calc_knowledge_transfers_is_social_network_channel(t.knowledge_transfer_id) AS is_social_network_channel,-- TRUE for relationships, collaboration, design-production iteration and people changing employers.
  calc_knowledge_transfers_is_ambient_absorption_by_non_practitio(t.knowledge_transfer_id) AS is_ambient_absorption_by_non_practitioner,-- TRUE when someone holding no role absorbed the know-how by living among the trade.
  t.semantic_type_iri,                                                          -- Semantic type IRI.
  calc_knowledge_transfers_know_how_topic(t.knowledge_transfer_id) AS know_how_topic-- What was handed over, in words: the topic of the know-how.
FROM knowledge_transfers t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_repository_entries: Captured procedural knowledge kept in a repository: who wrote it, whose know-how it records, for whom, whether it came back from executing the work, and whether it is kept current.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_repository_entries CASCADE;
CREATE VIEW vw_knowledge_repository_entries WITH (security_invoker = ON) AS
SELECT
  t.knowledge_repository_entry_id,                                              -- Stored identifier.
  calc_knowledge_repository_entries_name(t.knowledge_repository_entry_id) AS name,-- Display name.
  t.title,                                                                      -- Entry title.
  t.procedure,                                                                  -- The procedure the entry documents.
  t.know_how,                                                                   -- The know-how the entry captures, when it captures a recorded carrier's know-how.
  t.author_agent,                                                               -- Who wrote the entry.
  t.source_expert,                                                              -- Whose expertise the entry records.
  t.credits_source_expert,                                                      -- TRUE when the entry names and credits the source expert.
  t.written_for_audience,                                                       -- LaterColleagues (written as part of the craft) or ComplianceAudit.
  t.authored_on_allocated_time,                                                 -- TRUE when the writing was done on time the organization allotted for it.
  t.fed_from_execution,                                                         -- The execution whose experience the entry wrote back.
  t.created_at,                                                                 -- When the entry was created.
  t.last_updated_at,                                                            -- When the entry was last revised.
  t.review_interval_days,                                                       -- How often the entry must be revised to stay current.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_knowledge_repository_entries_as_of_instant(t.knowledge_repository_entry_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_knowledge_repository_entries_author_is_still_engaged(t.knowledge_repository_entry_id) AS author_is_still_engaged,-- Whether the author still holds a role.
  calc_knowledge_repository_entries_author_agent_kind(t.knowledge_repository_entry_id) AS author_agent_kind,-- The author's kind.
  calc_knowledge_repository_entries_owner_organization(t.knowledge_repository_entry_id) AS owner_organization,-- The organization that owns the procedure.
  calc_knowledge_repository_entries_days_since_updated(t.knowledge_repository_entry_id) AS days_since_updated,-- Days since the last revision.
  calc_knowledge_repository_entries_is_stale(t.knowledge_repository_entry_id) AS is_stale,-- TRUE when the entry has gone longer than its review interval without revision.
  calc_knowledge_repository_entries_is_execution_feedback(t.knowledge_repository_entry_id) AS is_execution_feedback,-- TRUE when the entry wrote back what an execution taught.
  calc_knowledge_repository_entries_is_machine_authored(t.knowledge_repository_entry_id) AS is_machine_authored,-- TRUE when an AI agent or pipeline wrote the entry.
  calc_knowledge_repository_entries_outlives_author_tenure(t.knowledge_repository_entry_id) AS outlives_author_tenure,-- TRUE when the entry is still current although its author has left.
  calc_knowledge_repository_entries_is_uncredited_expert_know_how(t.knowledge_repository_entry_id) AS is_uncredited_expert_know_how,-- TRUE when an entry records another person's expertise without crediting them.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_repository_entries t;

-- ----------------------------------------------------------------------------
-- vw_community_memberships: A person's membership of a community of practice, whether they belong to a different organization, and whether they are a specialist others consult.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_community_memberships CASCADE;
CREATE VIEW vw_community_memberships WITH (security_invoker = ON) AS
SELECT
  t.community_membership_id,                                                    -- Stored identifier.
  calc_community_memberships_name(t.community_membership_id) AS name,           -- Display name.
  t.community_of_practice,                                                      -- The community.
  t.agent,                                                                      -- The member.
  t.is_specialist,                                                              -- TRUE when the member is a specialist others in the community consult.
  t.joined_at,                                                                  -- When the member joined.
  calc_community_memberships_member_organization(t.community_membership_id) AS member_organization,-- The member's organization.
  calc_community_memberships_community_organization(t.community_membership_id) AS community_organization,-- The organization hosting the community.
  calc_community_memberships_is_external_member(t.community_membership_id) AS is_external_member,-- TRUE when the member works for a different organization than the community's host.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM community_memberships t;

-- ----------------------------------------------------------------------------
-- vw_source_relationships: The standing relationship between a knowledge engineer and a knowledge source on one procedure: the power dynamic, what was negotiated, the state of trust, and what the source withholds and why.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_source_relationships CASCADE;
CREATE VIEW vw_source_relationships WITH (security_invoker = ON) AS
SELECT
  t.source_relationship_id,                                                     -- Stored identifier.
  calc_source_relationships_name(t.source_relationship_id) AS name,             -- Display name.
  t.knowledge_engineer,                                                         -- The knowledge engineer collecting.
  t.source_agent,                                                               -- The knowledge source.
  t.procedure,                                                                  -- The procedure the knowledge serves.
  t.source_standing,                                                            -- The source's standing relative to the engineer (SeniorVeteran, Peer, Manager).
  t.power_dynamic,                                                              -- Balanced, SourceOutranksEngineer, SupervisorPresent or JobSecurityThreat.
  t.negotiated_agreement,                                                       -- What was negotiated with the source about how their knowledge is collected and used.
  t.trust_level,                                                                -- Low, Building or Established.
  t.trust_building_practice,                                                    -- What the engineer does to build trust with the source.
  t.withholding_observed,                                                       -- TRUE when the source was seen to hold information back.
  t.withholding_motive,                                                         -- Why the source holds information back (status, job security).
  t.started_at,                                                                 -- When the relationship began.
  calc_source_relationships_is_unnegotiated_power_gap(t.source_relationship_id) AS is_unnegotiated_power_gap,-- TRUE when a power imbalance shapes the relationship and nothing was negotiated.
  calc_source_relationships_is_extractive_relationship(t.source_relationship_id) AS is_extractive_relationship,-- TRUE when trust is not established and no trust-building practice is recorded.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM source_relationships t;

-- ----------------------------------------------------------------------------
-- vw_department_process_accounts: The account a stakeholder department gives of a process, the interest shaping it, any conflicting account from another department, and the practice used to resolve the disagreement.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_department_process_accounts CASCADE;
CREATE VIEW vw_department_process_accounts WITH (security_invoker = ON) AS
SELECT
  t.department_process_account_id,                                              -- Stored identifier.
  calc_department_process_accounts_name(t.department_process_account_id) AS name,-- Display name.
  t.procedure,                                                                  -- The process accounted for.
  t.department,                                                                 -- The stakeholder department.
  t.stakeholder_agent,                                                          -- Who speaks for the department.
  t.engaged_at,                                                                 -- When the department was engaged in shaping the process knowledge; blank if never.
  t.account_summary,                                                            -- The department's account of the process.
  t.shaping_interest,                                                           -- The departmental interest that shapes the account.
  t.conflicts_with_account,                                                     -- Another account of the same process this one contradicts.
  t.resolution_practice,                                                        -- The practice used to resolve the disagreement.
  t.resolved_at,                                                                -- When the disagreement was resolved.
  calc_department_process_accounts_conflicting_department(t.department_process_account_id) AS conflicting_department,-- The department giving the contradicting account.
  calc_department_process_accounts_is_awaiting_engagement(t.department_process_account_id) AS is_awaiting_engagement,-- TRUE when the stakeholder department has not been engaged.
  calc_department_process_accounts_is_conflicting_account(t.department_process_account_id) AS is_conflicting_account,-- TRUE when another department gives a contradicting account of the same process.
  calc_department_process_accounts_is_unresolved_disagreement(t.department_process_account_id) AS is_unresolved_disagreement,-- TRUE when a cross-department conflict has no resolution practice.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM department_process_accounts t;

-- ----------------------------------------------------------------------------
-- vw_problem_occurrences: One occurrence of a recurring work problem: who solved it, whether the solution was recorded, and the earlier occurrence of the same problem.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
-- ----------------------------------------------------------------------------
-- vw_problem_occurrences: One occurrence of a recurring work problem: who solved it, whether the solution was recorded, and the earlier occurrence of the same problem.
-- SELF-REFERENTIAL SETTLE: ProblemOccurrences has lookup field(s) reading a computed
-- column of its own table through a self-FK. Settled level-by-level (seeds first,
-- then each row once its drivers are settled) via a jsonb accumulator carried
-- through ONE recursive self-reference. No cache: re-settles on every read.
-- Settle targets: is_solved, solver_is_still_engaged. Drivers: prior_occurrence.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_problem_occurrences CASCADE;
CREATE VIEW vw_problem_occurrences WITH (security_invoker = ON) AS
WITH RECURSIVE acc AS (
  SELECT 1 AS step,
    COALESCE((SELECT jsonb_object_agg(t.problem_occurrence_id, jsonb_build_object(
      'is_solved', (SELECT (NULLIF(t.solved_at::text,''))::timestamptz) IS NOT NULL,
      'solver_is_still_engaged', ((SELECT calc_agents_is_still_engaged(agent_id) FROM agents WHERE agent_id = ((SELECT NULLIF(t.solved_by_agent::text,'')))::text))
    ))
    FROM problem_occurrences t WHERE NULLIF(t.prior_occurrence,'') IS NULL), '{}'::jsonb) AS settled
  UNION ALL
  SELECT a.step + 1, a.settled || COALESCE((
    SELECT jsonb_object_agg(t.problem_occurrence_id, jsonb_build_object(
      'is_solved', (SELECT (NULLIF(t.solved_at::text,''))::timestamptz) IS NOT NULL,
      'solver_is_still_engaged', ((SELECT calc_agents_is_still_engaged(agent_id) FROM agents WHERE agent_id = ((SELECT NULLIF(t.solved_by_agent::text,'')))::text))
    ))
    FROM problem_occurrences t
    WHERE NOT (a.settled ? t.problem_occurrence_id) AND NOT (NULLIF(t.prior_occurrence,'') IS NULL) AND (NULLIF(t.prior_occurrence,'') IS NULL OR a.settled ? t.prior_occurrence)
  ), '{}'::jsonb)
  FROM acc a
  WHERE EXISTS (SELECT 1 FROM problem_occurrences t
    WHERE NOT (a.settled ? t.problem_occurrence_id) AND NOT (NULLIF(t.prior_occurrence,'') IS NULL) AND (NULLIF(t.prior_occurrence,'') IS NULL OR a.settled ? t.prior_occurrence))
),
settled AS (SELECT s.settled FROM acc s ORDER BY s.step DESC LIMIT 1)
SELECT
  t.problem_occurrence_id,                                                      -- Stored identifier.
  calc_problem_occurrences_name(t.problem_occurrence_id) AS name,               -- Display name.
  t.problem_signature,                                                          -- The recognizable problem.
  t.procedure,                                                                  -- The procedure in which it occurred.
  t.occurred_at,                                                                -- When it occurred.
  t.solved_by_agent,                                                            -- Who solved it.
  t.solved_at,                                                                  -- When it was solved; blank while open.
  t.solution_entry,                                                             -- The repository entry recording the solution.
  t.prior_occurrence,                                                           -- The earlier occurrence of the same problem.
  (SELECT settled #>> ARRAY[t.problem_occurrence_id::text, 'solver_is_still_engaged'] FROM settled)::boolean AS solver_is_still_engaged,-- Whether the solver still holds a role.
  (SELECT settled #>> ARRAY[t.problem_occurrence_id::text, 'is_solved'] FROM settled)::boolean AS is_solved,-- TRUE once the occurrence was solved.
  (SELECT settled #>> ARRAY[NULLIF(t.prior_occurrence,''), 'is_solved'] FROM settled)::boolean AS prior_was_solved,-- Whether the earlier occurrence was solved.
  calc_problem_occurrences_prior_solution_entry(t.problem_occurrence_id) AS prior_solution_entry,-- The earlier occurrence's recorded solution.
  calc_problem_occurrences_prior_solver(t.problem_occurrence_id) AS prior_solver,-- Who solved the earlier occurrence.
  (SELECT settled #>> ARRAY[NULLIF(t.prior_occurrence,''), 'solver_is_still_engaged'] FROM settled)::boolean AS prior_solver_is_still_engaged,-- Whether the earlier solver still holds a role.
  calc_problem_occurrences_is_solved_without_recorded_solution(t.problem_occurrence_id) AS is_solved_without_recorded_solution,-- TRUE when the problem was solved and the solution was not recorded.
  calc_problem_occurrences_has_been_solved_before(t.problem_occurrence_id) AS has_been_solved_before,-- TRUE when an earlier occurrence of the same problem was solved.
  calc_problem_occurrences_has_consultable_specialist(t.problem_occurrence_id) AS has_consultable_specialist,-- TRUE when whoever solved the earlier occurrence still holds a role and can be consulted.
  calc_problem_occurrences_is_relearned_solved_problem(t.problem_occurrence_id) AS is_relearned_solved_problem,-- TRUE when a problem solved before came back and its earlier fix had not been recorded.
  calc_problem_occurrences_is_turnover_regression(t.problem_occurrence_id) AS is_turnover_regression,-- TRUE when an unrecorded fix came back after the person who made it left.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM problem_occurrences t;

-- ----------------------------------------------------------------------------
-- vw_onboarding_records: A new starter learning a procedure: when they started, when they reached proficiency, and whether they learned from captured, formalized knowledge.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_onboarding_records CASCADE;
CREATE VIEW vw_onboarding_records WITH (security_invoker = ON) AS
SELECT
  t.onboarding_record_id,                                                       -- Stored identifier.
  calc_onboarding_records_name(t.onboarding_record_id) AS name,                 -- Display name.
  t.new_starter,                                                                -- The new starter.
  t.procedure,                                                                  -- The procedure being learned.
  t.started_at,                                                                 -- When onboarding started.
  t.proficient_at,                                                              -- When the starter was signed off as proficient; blank while learning.
  t.used_captured_knowledge,                                                    -- TRUE when the starter learned from formalized repository knowledge.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_onboarding_records_as_of_instant(t.onboarding_record_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_onboarding_records_is_proficient(t.onboarding_record_id) AS is_proficient,-- TRUE once signed off.
  calc_onboarding_records_days_to_proficiency(t.onboarding_record_id) AS days_to_proficiency,-- Days from start to proficiency.
  calc_onboarding_records_days_since_start(t.onboarding_record_id) AS days_since_start,-- Days from start to the evaluation instant.
  calc_onboarding_records_is_recent_start(t.onboarding_record_id) AS is_recent_start,-- TRUE when the starter began within 180 days of the evaluation instant.
  calc_onboarding_records_procedure_repository_entry_count(t.onboarding_record_id) AS procedure_repository_entry_count,-- Repository entries for the procedure.
  calc_onboarding_records_procedure_departed_only_count(t.onboarding_record_id) AS procedure_departed_only_count,-- Know-how of the procedure held only by people who left.
  calc_onboarding_records_is_starting_from_nothing(t.onboarding_record_id) AS is_starting_from_nothing,-- TRUE when a newcomer joins a procedure whose previous holders left and nothing was captured.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM onboarding_records t;

-- ----------------------------------------------------------------------------
-- vw_sharing_recognitions: Incentives and credit an organization gives people for sharing process knowledge.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_sharing_recognitions CASCADE;
CREATE VIEW vw_sharing_recognitions WITH (security_invoker = ON) AS
SELECT
  t.sharing_recognition_id,                                                     -- Stored identifier.
  calc_sharing_recognitions_name(t.sharing_recognition_id) AS name,             -- Display name.
  t.recognized_agent,                                                           -- Who was recognized.
  t.organization,                                                               -- The organization giving the recognition.
  t.recognition_kind,                                                           -- TeachingAward, PeerAward, PromotionCredit or Bonus.
  t.for_contribution,                                                           -- The sharing that was rewarded.
  t.awarded_at,                                                                 -- When it was awarded.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM sharing_recognitions t;

-- ----------------------------------------------------------------------------
-- vw_capability_declines: When an organization's training-and-retention cycle began to decline at one stage (facility investment, engineer training, upkeep of how-to-make knowledge) and the decline of the stage before it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_capability_declines CASCADE;
CREATE VIEW vw_capability_declines WITH (security_invoker = ON) AS
SELECT
  t.capability_decline_id,                                                      -- Stored identifier.
  calc_capability_declines_name(t.capability_decline_id) AS name,               -- Display name.
  t.organization,                                                               -- The organization.
  t.stage,                                                                      -- FacilityInvestment, EngineerTraining or KnowHowUpkeep.
  t.decline_started_at,                                                         -- When the decline started.
  t.preceding_stage_decline,                                                    -- The decline of the stage that feeds this one.
  t.evidence,                                                                   -- What shows the decline.
  calc_capability_declines_preceding_stage(t.capability_decline_id) AS preceding_stage,-- The stage of the preceding decline.
  calc_capability_declines_preceding_decline_started_at(t.capability_decline_id) AS preceding_decline_started_at,-- When the preceding decline started.
  calc_capability_declines_follows_preceding_stage_decline(t.capability_decline_id) AS follows_preceding_stage_decline,-- TRUE when training declined after facility investment, or upkeep after training.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM capability_declines t;

-- ----------------------------------------------------------------------------
-- vw_knowledge_traces: One trace from a piece of organized knowledge (a process model, an activity definition or a constraint) to the collected material it rests on, with the role the material plays (origin, validation, extension, contradiction), how the knowledge was derived, and who confirmed it.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_knowledge_traces CASCADE;
CREATE VIEW vw_knowledge_traces WITH (security_invoker = ON) AS
SELECT
  t.knowledge_trace_id,                                                         -- Stored identifier.
  calc_knowledge_traces_name(t.knowledge_trace_id) AS name,                     -- Display name.
  t.target_kind,                                                                -- ProcessModel, ActivityDefinition or Constraint.
  t.procedure_version,                                                          -- The process model the traced knowledge belongs to.
  t.step,                                                                       -- The activity definition traced, when the target is a step.
  t.requirement,                                                                -- The constraint traced, when the target is a requirement.
  t.source_material,                                                            -- The collected material the knowledge traces to.
  t.trace_role,                                                                 -- Origin (knowledge was taken from it), Validates, Extends, or Contradicts.
  t.traced_aspect,                                                              -- What the source is cited for: Sequence, StepDescription, Workaround, ActualExecution or Constraint.
  t.source_statement,                                                           -- Paraphrase of what the source says about the target.
  t.derivation_route,                                                           -- How the knowledge was produced from the source.
  t.derived_by_agent,                                                           -- Who (or what) derived the knowledge from the source.
  t.validated_by_agent,                                                         -- Who confirmed the derived knowledge.
  t.validated_at,                                                               -- When it was confirmed.
  t.source_stated_duration_minutes,                                             -- Duration the source states for the traced step, when it states one.
  t.contradicted_document,                                                      -- For a contradiction: the document whose prescription practice departs from.
  calc_knowledge_traces_source_material_kind(t.knowledge_trace_id) AS source_material_kind,-- Kind of the source material.
  calc_knowledge_traces_source_collected_at(t.knowledge_trace_id) AS source_collected_at,-- When the knowledge was taken: the material's collection instant.
  calc_knowledge_traces_source_revised_at(t.knowledge_trace_id) AS source_revised_at,-- Last revision of the document the material was excerpted from.
  calc_knowledge_traces_source_is_document(t.knowledge_trace_id) AS source_is_document,-- TRUE when the source is an excerpt of an existing document.
  calc_knowledge_traces_source_is_people_capture(t.knowledge_trace_id) AS source_is_people_capture,-- TRUE when the source was captured from people (transcript or field notes).
  calc_knowledge_traces_source_is_practice_evidence(t.knowledge_trace_id) AS source_is_practice_evidence,-- TRUE when the source records work as performed (field notes or an event trace).
  calc_knowledge_traces_is_source_changed_since_taken(t.knowledge_trace_id) AS is_source_changed_since_taken,-- TRUE when the source document was revised after the knowledge was taken from it.
  calc_knowledge_traces_modeled_duration_minutes(t.knowledge_trace_id) AS modeled_duration_minutes,-- Duration the modeled step carries.
  calc_knowledge_traces_is_unfaithful_to_source(t.knowledge_trace_id) AS is_unfaithful_to_source,-- TRUE when the modeled step's duration differs from the duration its source states.
  calc_knowledge_traces_derived_by_agent_kind(t.knowledge_trace_id) AS derived_by_agent_kind,-- Kind of the deriving agent.
  calc_knowledge_traces_is_machine_derived(t.knowledge_trace_id) AS is_machine_derived,-- TRUE when a software or AI agent derived the knowledge from its source.
  calc_knowledge_traces_is_self_validated(t.knowledge_trace_id) AS is_self_validated,-- TRUE when the agent who derived the knowledge is the one who confirmed it.
  calc_knowledge_traces_has_incomplete_provenance(t.knowledge_trace_id) AS has_incomplete_provenance,-- TRUE when the origin, the derivation route or the confirmation is missing.
  calc_knowledge_traces_provenance_statement(t.knowledge_trace_id) AS provenance_statement,-- Origin, route and confirmation in one line.
  calc_knowledge_traces_is_aspect_unsupported_by_source_kind(t.knowledge_trace_id) AS is_aspect_unsupported_by_source_kind,-- TRUE when a workaround is cited to something other than observation notes, or actual execution to something other than an event trace.
  calc_knowledge_traces_is_document_origin(t.knowledge_trace_id) AS is_document_origin,-- TRUE when the knowledge was first taken from a document.
  calc_knowledge_traces_step_elicited_validation_count(t.knowledge_trace_id) AS step_elicited_validation_count,-- Validations of the traced step captured from people.
  calc_knowledge_traces_step_elicited_extension_count(t.knowledge_trace_id) AS step_elicited_extension_count,-- Extensions of the traced step captured from people.
  calc_knowledge_traces_is_document_start_never_validated(t.knowledge_trace_id) AS is_document_start_never_validated,-- TRUE when a step taken from a document has never been confirmed by capture from people.
  calc_knowledge_traces_is_document_start_never_extended(t.knowledge_trace_id) AS is_document_start_never_extended,-- TRUE when a step taken from a document has never been extended by capture from people.
  calc_knowledge_traces_contradicted_document_revised_at(t.knowledge_trace_id) AS contradicted_document_revised_at,-- Last revision of the contradicted document.
  calc_knowledge_traces_is_document_trailing_practice(t.knowledge_trace_id) AS is_document_trailing_practice,-- TRUE when practice evidence collected after the document's last revision contradicts it.
  calc_knowledge_traces_prescribed_versus_enacted(t.knowledge_trace_id) AS prescribed_versus_enacted,-- For a contradiction: what the document prescribes against what practice evidence shows.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM knowledge_traces t;

-- ----------------------------------------------------------------------------
-- vw_mined_flow_edges: One step-to-step hand-off reconstructed from a system event log by a process-mining run: how many cases took it, how long cases waited before the next step, and whether it is kept as observed behavior or recorded as intended logic.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_mined_flow_edges CASCADE;
CREATE VIEW vw_mined_flow_edges WITH (security_invoker = ON) AS
SELECT
  t.mined_flow_edge_id,                                                         -- Stored identifier.
  calc_mined_flow_edges_name(t.mined_flow_edge_id) AS name,                     -- Display name.
  t.process_mining_run,                                                         -- The mining run that reconstructed the hand-off.
  t.from_step,                                                                  -- Step the cases left.
  t.to_step,                                                                    -- Step the cases entered next.
  t.observed_case_count,                                                        -- Cases in the log that took this hand-off.
  t.median_wait_minutes,                                                        -- Median minutes between leaving FromStep and starting ToStep.
  t.recorded_stance,                                                            -- Observed (kept as mined behavior) or Intended (recorded as intended process logic).
  t.intent_decision_by,                                                         -- Who decided that mined behavior should become intended logic.
  calc_mined_flow_edges_documented_transition_count(t.mined_flow_edge_id) AS documented_transition_count,-- Documented transitions with the same origin and target.
  calc_mined_flow_edges_is_undocumented_path(t.mined_flow_edge_id) AS is_undocumented_path,-- TRUE when cases took a hand-off the documented model does not contain.
  calc_mined_flow_edges_to_step_expected_minutes(t.mined_flow_edge_id) AS to_step_expected_minutes,-- Documented duration of the step entered.
  calc_mined_flow_edges_is_bottleneck(t.mined_flow_edge_id) AS is_bottleneck,   -- TRUE when cases wait more than four times the entered step's documented duration.
  calc_mined_flow_edges_is_mined_path_recorded_as_intent_without_(t.mined_flow_edge_id) AS is_mined_path_recorded_as_intent_without_decision,-- TRUE when a mined hand-off is recorded as intended logic and nobody decided it should be.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM mined_flow_edges t;

-- ----------------------------------------------------------------------------
-- vw_collection_occasions: Recurring occasions at which process knowledge is collected: retrospectives, process reviews and improvement initiatives.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_collection_occasions CASCADE;
CREATE VIEW vw_collection_occasions WITH (security_invoker = ON) AS
SELECT
  t.collection_occasion_id,                                                     -- Stored identifier.
  calc_collection_occasions_name(t.collection_occasion_id) AS name,             -- Display name.
  t.label,                                                                      -- The occasion.
  t.occasion_kind,                                                              -- Retrospective, ProcessReview or ImprovementInitiative.
  t.procedure,                                                                  -- The procedure the occasion collects knowledge about.
  t.cadence_days,                                                               -- Days between occurrences.
  t.last_held_at,                                                               -- When it was last held.
  t.evaluation_context,                                                         -- The instant the row is judged against.
  calc_collection_occasions_as_of_instant(t.collection_occasion_id) AS as_of_instant,-- The modeled evaluation instant.
  calc_collection_occasions_days_since_held(t.collection_occasion_id) AS days_since_held,-- Days since the occasion was last held.
  calc_collection_occasions_is_lapsed(t.collection_occasion_id) AS is_lapsed,   -- TRUE when the occasion has not been held within its cadence.
  calc_collection_occasions_captured_material_count(t.collection_occasion_id) AS captured_material_count,-- Collected materials captured at the occasion.
  calc_collection_occasions_is_held_without_capture(t.collection_occasion_id) AS is_held_without_capture,-- TRUE when the occasion was held and nothing it surfaced was collected.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM collection_occasions t;

-- ----------------------------------------------------------------------------
-- vw_stakeholder_perspectives: One stakeholder's view of how a step should be performed, kept with the collected material it comes from and the perspective it conflicts with, rather than merged into a single agreed version.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_stakeholder_perspectives CASCADE;
CREATE VIEW vw_stakeholder_perspectives WITH (security_invoker = ON) AS
SELECT
  t.stakeholder_perspective_id,                                                 -- Stored identifier.
  calc_stakeholder_perspectives_name(t.stakeholder_perspective_id) AS name,     -- Display name.
  t.procedure_version,                                                          -- The process model the view is about.
  t.step,                                                                       -- The step the view is about.
  t.holder_role,                                                                -- The role whose view this is.
  t.position,                                                                   -- The view, paraphrased.
  t.source_material,                                                            -- The collected material the view comes from.
  t.conflicts_with_perspective,                                                 -- The perspective this one conflicts with.
  t.disposition,                                                                -- Retained (kept alongside the other views) or OverriddenByConsensus.
  calc_stakeholder_perspectives_source_material_kind(t.stakeholder_perspective_id) AS source_material_kind,-- Kind of material the view comes from.
  calc_stakeholder_perspectives_conflict_partner_count(t.stakeholder_perspective_id) AS conflict_partner_count,-- Perspectives that name this one as their conflict.
  calc_stakeholder_perspectives_is_in_conflict(t.stakeholder_perspective_id) AS is_in_conflict,-- TRUE when the perspective conflicts with another in either direction.
  calc_stakeholder_perspectives_is_dissenting_view_not_kept_with_(t.stakeholder_perspective_id) AS is_dissenting_view_not_kept_with_source,-- TRUE when a conflicting view was overridden into one version or kept without the source it comes from.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM stakeholder_perspectives t;

-- ----------------------------------------------------------------------------
-- vw_model_pilots: Pilot implementations a governed model was tried out in before or while it was adopted.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_pilots CASCADE;
CREATE VIEW vw_model_pilots WITH (security_invoker = ON) AS
SELECT
  t.model_pilot_id,                                                             -- Stored identifier.
  calc_model_pilots_name(t.model_pilot_id) AS name,                             -- Display name.
  t.governed_model,                                                             -- Model piloted.
  t.site,                                                                       -- Where the pilot ran.
  t.started_at,                                                                 -- When it started.
  t.finding,                                                                    -- What the pilot changed in the model.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_pilots t;

-- ----------------------------------------------------------------------------
-- vw_model_activity_experts: Domain experts taking part in one LOT activity of a governed model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_activity_experts CASCADE;
CREATE VIEW vw_model_activity_experts WITH (security_invoker = ON) AS
SELECT
  t.model_activity_expert_id,                                                   -- Stored identifier.
  calc_model_activity_experts_name(t.model_activity_expert_id) AS name,         -- Display name.
  t.governed_model,                                                             -- Model.
  t.lot_activity,                                                               -- RequirementsSpecification, Implementation, Publication or Maintenance.
  t.expert,                                                                     -- Domain expert taking part.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_activity_experts t;

-- ----------------------------------------------------------------------------
-- vw_model_data_mapping_runs: Runs that map instance data into RDF for a governed model.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_model_data_mapping_runs CASCADE;
CREATE VIEW vw_model_data_mapping_runs WITH (security_invoker = ON) AS
SELECT
  t.model_data_mapping_run_id,                                                  -- Stored identifier.
  calc_model_data_mapping_runs_name(t.model_data_mapping_run_id) AS name,       -- Display name.
  t.governed_model,                                                             -- Model implemented.
  t.data_origin,                                                                -- Real (the organization's own records) or Synthetic.
  t.triples_produced,                                                           -- Triples the run produced.
  t.ran_at,                                                                     -- When.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM model_data_mapping_runs t;

-- ----------------------------------------------------------------------------
-- vw_artifact_handoffs: One artifact passing from the step that produces it to a step that consumes it, asserted per declared input variable. The edge table the upgrade blast radius is traversed over.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_artifact_handoffs CASCADE;
CREATE VIEW vw_artifact_handoffs WITH (security_invoker = ON) AS
SELECT
  t.artifact_handoff_id,                                                        -- Stored identifier.
  calc_artifact_handoffs_name(t.artifact_handoff_id) AS name,                   -- Display name.
  t.step_variable,                                                              -- The consuming step's input variable this hand-off feeds.
  t.from_step,                                                                  -- Step that produces the artifact.
  t.to_step,                                                                    -- Step that consumes it.
  calc_artifact_handoffs_declared_source_step(t.artifact_handoff_id) AS declared_source_step,-- Producing step the input variable itself declares.
  calc_artifact_handoffs_declared_consumer_step(t.artifact_handoff_id) AS declared_consumer_step,-- Step that declares the input variable.
  calc_artifact_handoffs_disagrees_with_declared_variable(t.artifact_handoff_id) AS disagrees_with_declared_variable,-- TRUE when a recorded hand-off names different steps than the input variable it feeds declares, so traversal and declaration have drifted apart.
  t.semantic_type_iri                                                           -- Semantic type IRI.
FROM artifact_handoffs t;

-- ----------------------------------------------------------------------------
-- vw_app_actions: One row per thing a role may DO in the app: the base table it writes, the operation, the access policy that permits it, and the derived value the page highlights afterwards. The app has no per-action endpoint; it executes these rows.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_actions CASCADE;
CREATE VIEW vw_app_actions WITH (security_invoker = ON) AS
SELECT
  t.app_action_id,                                                              -- Stable key, e.g. act-tech-start-lockout.
  calc_app_actions_name(t.app_action_id) AS name,                               -- Display name.
  t.label,                                                                      -- The button's words.
  t.owning_role,                                                                -- The role that performs this action.
  t.route_path,                                                                 -- The app route the action appears on.
  t.target_table,                                                               -- The base table written.
  t.operation,                                                                  -- INSERT or UPDATE, spelled as the policy's Command is.
  t.policy,                                                                     -- The write policy that permits it. Blank means nothing permits it.
  t.watched_field,                                                              -- The derived value the page highlights after the write.
  t.story_episode,                                                              -- The episode of the video series that performs this action on camera.
  t.description,                                                                -- What the action means, in the role's words.
  calc_app_actions_policy_command(t.app_action_id) AS policy_command,           -- The permitting policy's SQL command.
  calc_app_actions_policy_denial_test_count(t.app_action_id) AS policy_denial_test_count,-- Denial tests that exercise the permitting policy.
  calc_app_actions_watched_field_is_witness(t.app_action_id) AS watched_field_is_witness,-- Whether the highlighted value is a boolean witness.
  calc_app_actions_input_field_count(t.app_action_id) AS input_field_count,     -- Fields this action writes.
  calc_app_actions_is_unpermitted(t.app_action_id) AS is_unpermitted,           -- No access policy permits this action, so the database would refuse it.
  calc_app_actions_policy_command_disagrees(t.app_action_id) AS policy_command_disagrees,-- The permitting policy is for a different SQL command than the action performs.
  calc_app_actions_is_unproven_write(t.app_action_id) AS is_unproven_write,     -- Permitted, but no denial test proves the policy refuses anyone else.
  t.semantic_type_iri                                                           -- Extension IRI.
FROM app_actions t;

-- ----------------------------------------------------------------------------
-- vw_app_action_fields: The fields one action writes, one row each, and where each value comes from: typed by the person, picked from a list, fixed by the action, or stamped by the server.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_app_action_fields CASCADE;
CREATE VIEW vw_app_action_fields WITH (security_invoker = ON) AS
SELECT
  t.app_action_field_id,                                                        -- Stable key.
  calc_app_action_fields_name(t.app_action_field_id) AS name,                   -- Display name.
  t.app_action,                                                                 -- The action.
  t.target_field,                                                               -- The field written.
  t.field_label,                                                                -- The label shown beside the input.
  t.input_kind,                                                                 -- text, longtext, note (a long text that may be left empty), choice, toggle, date, fixed, or server.
  t.fixed_value,                                                                -- For fixed: the value. For server: what is stamped (agent, instant, id, iri).
  t.choices_from,                                                               -- For choice: the table whose rows are offered.
  t.sort_order,                                                                 -- Position in the form.
  calc_app_action_fields_target_field_type(t.app_action_field_id) AS target_field_type,-- raw, relationship, calculated, lookup or aggregation.
  calc_app_action_fields_writes_derived_field(t.app_action_field_id) AS writes_derived_field,-- The action tries to write a value the model works out for itself. That is never allowed.
  t.semantic_type_iri                                                           -- Extension IRI.
FROM app_action_fields t;

-- ----------------------------------------------------------------------------
-- vw_abundant_knowledge_gaps: The kinds of knowledge that an abundance of information does not supply, each pointing at the table in this model that represents it. One row per kind named in the source material's 'paradox of abundant knowledge'.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_abundant_knowledge_gaps CASCADE;
CREATE VIEW vw_abundant_knowledge_gaps WITH (security_invoker = ON) AS
SELECT
  t.abundant_knowledge_gap_id,                                                  -- Readable key for the kind of knowledge.
  calc_abundant_knowledge_gaps_name(t.abundant_knowledge_gap_id) AS name,       -- Display name.
  t.label,                                                                      -- Short name of this kind of knowledge.
  t.gap_kind,                                                                   -- HumanJudgment | UndiscoveredTacitKnowledge | CuratedToUserAndUseCase.
  t.description,                                                                -- What this kind of knowledge is.
  t.why_abundance_does_not_supply_it,                                           -- Why having more information available does not produce this kind of knowledge.
  t.represented_by_table,                                                       -- The table in this model that holds this kind of knowledge.
  calc_abundant_knowledge_gaps_representing_table_row_count(t.abundant_knowledge_gap_id) AS representing_table_row_count,-- Rows measured in the representing table, from the field catalog. This is how much of this kind of knowledge the model actually holds; a kind that is named but held nowhere reads zero. Deliberately a count rather than a yes/no: all three kinds are represented here, so a boolean would be all-true and would state nothing, while the counts differ and say which kind is thinnest.
  t.semantic_type_iri                                                           -- Semantic type.
FROM abundant_knowledge_gaps t;

-- ----------------------------------------------------------------------------
-- vw_ontology_support_programmes: Funded research programmes that produced or supported the ontologies this model reuses. Recorded so the ontology authority can see what happens to a reused vocabulary when the programme behind it ends.
-- Combines base table columns with calculated/lookup/aggregation fields.
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_ontology_support_programmes CASCADE;
CREATE VIEW vw_ontology_support_programmes WITH (security_invoker = ON) AS
SELECT
  t.ontology_support_programme_id,                                              -- Readable key for the programme.
  calc_ontology_support_programmes_name(t.ontology_support_programme_id) AS name,-- Display name.
  t.label,                                                                      -- Full programme title.
  t.acronym,                                                                    -- Programme acronym.
  t.funder,                                                                     -- Body that funded the programme.
  t.grant_reference,                                                            -- Grant agreement number, as published by the funder.
  t.programme_iri,                                                              -- Public record of the programme.
  t.coordinator,                                                                -- Organization coordinating the programme.
  t.started_on,                                                                 -- Programme start date, as published by the funder.
  t.ends_on,                                                                    -- Programme end date, as published by the funder.
  t.is_industry_focused,                                                        -- Whether the programme's purpose is ontology development for industry.
  t.our_successor_steward,                                                      -- Who this organization relies on to maintain the terms it took from this programme once the programme ends. Blank means nobody has been named.
  t.why_recorded,                                                               -- Why the ontology authority tracks this programme, whether or not anything has been adopted from it yet.
  t.evaluation_context,                                                         -- The instant this row is judged against.
  calc_ontology_support_programmes_as_of_instant(t.ontology_support_programme_id) AS as_of_instant,-- The modelled instant.
  calc_ontology_support_programmes_supported_profile_count(t.ontology_support_programme_id) AS supported_profile_count,-- Ontology profiles in this model that name this programme.
  calc_ontology_support_programmes_has_ended(t.ontology_support_programme_id) AS has_ended,-- Whether the programme has ended as of the modelled instant.
  calc_ontology_support_programmes_days_until_programme_ends(t.ontology_support_programme_id) AS days_until_programme_ends,-- Days from the modelled instant to the programme's end date.
  calc_ontology_support_programmes_is_ended_with_no_steward_named(t.ontology_support_programme_id) AS is_ended_with_no_steward_named,-- The programme has ended and this organization has named nobody to maintain what it took from it.
  calc_ontology_support_programmes_is_ending_soon_with_no_steward(t.ontology_support_programme_id) AS is_ending_soon_with_no_steward_named,-- The programme has not ended yet, ends within six months of the modelled instant, and nobody here has been named to maintain what we took from it. This is the window in which something can still be done about it.
  t.semantic_type_iri                                                           -- Semantic type.
FROM ontology_support_programmes t;

-- ----------------------------------------------------------------------------
-- vw_step_transitions_closure: Transitive closure of the step graph (FromStep -> ToStep over every transition kind), materialized by each substrate as vw_step_transitions_closure: every (from, to) pair a procedure can lead to in one or more transitions. A step that lies on a cycle reaches itself.
-- Cycle-safe transitive closure of step_transitions(from_step -> to_step) [junction edge table].
-- Columns: from_id, to_id, hop_distance (shortest derivation), is_inferred
--          (TRUE iff no direct hop-1 edge asserts the pair).
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_transitions_closure CASCADE;
CREATE VIEW vw_step_transitions_closure WITH (security_invoker = ON) AS
WITH RECURSIVE edges AS (
    SELECT from_step AS from_id, to_step AS to_id
    FROM step_transitions
    -- Treat NULL and empty-string FKs as 'no edge' (the transpiler stores absent
    -- relationship values as '' rather than NULL, so both must be excluded).
    WHERE from_step IS NOT NULL AND from_step <> '' AND to_step IS NOT NULL AND to_step <> ''
),
closure AS (
    -- Base: the directly-asserted edges (hop 1).
    SELECT
        e.from_id,
        e.to_id,
        1 AS hop_distance,
        ARRAY[e.from_id, e.to_id] AS path
    FROM edges e
    UNION ALL
    -- Step: extend each path by one asserted edge. Interior nodes are never
    -- revisited, so cyclic edge sets terminate (cycle-safe). Returning to the
    -- path's own origin IS allowed, exactly once: it emits (x, x) for every x
    -- that lies on a cycle, which is what transitive closure means. A path that
    -- has closed back on its origin is complete and is not extended further.
    SELECT
        cl.from_id,
        e.to_id,
        cl.hop_distance + 1,
        cl.path || e.to_id
    FROM closure cl
    JOIN edges e ON e.from_id = cl.to_id
    WHERE cl.to_id <> cl.from_id
      AND NOT (e.to_id = ANY(cl.path[2:]))
)
SELECT
    cl.from_id,
    cl.to_id,
    MIN(cl.hop_distance) AS hop_distance,
    NOT EXISTS (
        SELECT 1 FROM edges e2
        WHERE e2.from_id = cl.from_id AND e2.to_id = cl.to_id
    ) AS is_inferred
FROM closure cl
GROUP BY cl.from_id, cl.to_id;


-- ----------------------------------------------------------------------------
-- vw_step_transitions_closure_where_avoids_human_approval_gate: Transitive closure of the step graph over only the transitions that avoid every human approval gate, materialized as vw_step_transitions_closure_where_avoids_human_approval_gate: every (from, to) pair a procedure can reach without passing a gate.
-- Cycle-safe transitive closure of step_transitions(from_step -> to_step) [junction edge table].
-- Columns: from_id, to_id, hop_distance (shortest derivation), is_inferred
--          (TRUE iff no direct hop-1 edge asserts the pair).
-- ----------------------------------------------------------------------------
DROP VIEW IF EXISTS vw_step_transitions_closure_where_avoids_human_approval_gate CASCADE;
CREATE VIEW vw_step_transitions_closure_where_avoids_human_approval_gate WITH (security_invoker = ON) AS
WITH RECURSIVE edges AS (
    SELECT from_step AS from_id, to_step AS to_id
    FROM vw_step_transitions
    -- Treat NULL and empty-string FKs as 'no edge' (the transpiler stores absent
    -- relationship values as '' rather than NULL, so both must be excluded).
    WHERE from_step IS NOT NULL AND from_step <> '' AND to_step IS NOT NULL AND to_step <> '' AND avoids_human_approval_gate IS TRUE
),
closure AS (
    -- Base: the directly-asserted edges (hop 1).
    SELECT
        e.from_id,
        e.to_id,
        1 AS hop_distance,
        ARRAY[e.from_id, e.to_id] AS path
    FROM edges e
    UNION ALL
    -- Step: extend each path by one asserted edge. Interior nodes are never
    -- revisited, so cyclic edge sets terminate (cycle-safe). Returning to the
    -- path's own origin IS allowed, exactly once: it emits (x, x) for every x
    -- that lies on a cycle, which is what transitive closure means. A path that
    -- has closed back on its origin is complete and is not extended further.
    SELECT
        cl.from_id,
        e.to_id,
        cl.hop_distance + 1,
        cl.path || e.to_id
    FROM closure cl
    JOIN edges e ON e.from_id = cl.to_id
    WHERE cl.to_id <> cl.from_id
      AND NOT (e.to_id = ANY(cl.path[2:]))
)
SELECT
    cl.from_id,
    cl.to_id,
    MIN(cl.hop_distance) AS hop_distance,
    NOT EXISTS (
        SELECT 1 FROM edges e2
        WHERE e2.from_id = cl.from_id AND e2.to_id = cl.to_id
    ) AS is_inferred
FROM closure cl
GROUP BY cl.from_id, cl.to_id;


